"test("open re-enables arming for a session that reuses the extension", () => {
	const scheduler = makeScheduler();
	const stops = [];
	const idleStop = createCamoufoxIdleStop({ timeoutMs: 5_000, scheduler, stop: () => stops.push(1) });
	idleStop.onCallSettled();
	idleStop.close();
	idleStop.onCallSettled();
