"test("concurrent runtime imports keep native constructors isolated", async (t) => {
	const first = fixture(t, { native: 'exports.Impit = class { identity = "first"; };' });
	const second = fixture(t, { native: 'exports.Impit = class { identity = "second"; };' });
	const [a, b, repeated] = await Promise.all([
		importJouzuCamoufoxModules(first.paths),
		importJouzuCamoufoxModules(second.paths),
		importJouzuCamoufoxModules(first.paths),
	]);
	assert.equal(new a.camoufoxJs.Impit().identity, "first");
	assert.equal(new b.camoufoxJs.Impit().identity, "second");
	assert.equal(repeated.camoufoxJs, a.camoufoxJs);
})"

"test("CLI starts without browser tools when the Camoufox idle delay is invalid", () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-camoufox-startup-"));
	try {
		const extension = join(root, "observe-tools.mjs");
		writeFileSync(
			extension,
			`export default function(pi) {
				pi.on("session_start", () => {
					console.error("registered-tools:" + JSON.stringify(pi.getAllTools().map(tool => tool.name)));
				});
			}`,
		);
		const environment = Object.fromEntries(
			Object.entries(process.env).filter(([key]) => !/^(JOUZU_|PI_|SHISA_|AI_AGENT|TEXTGUARD_)/u.test(key)),
		);
		for (const [label, value] of [
			["invalid", "soon"],
			["valid", "1000"],
			["unset", undefined],
		]) {
			const result = spawnSync(
				process.execPath,
				[
					resolve(import.meta.dirname, "../dist/cli.js"),
					"--jouzu-home",
					join(root, label),
					"--mode",
					"rpc",
					"--no-session",
					"--no-context-files",
					"--no-extensions",
					"--no-skills",
					"--extension",
					extension,
				],
				{
					cwd: root,
					env: {
						...environment,
						PI_OFFLINE: "1",
						JOUZU_NO_UPDATE: "1",
						...(value === undefined ? {} : { JOUZU_CAMOUFOX_IDLE_STOP_MS: value }),
					},
					encoding: "utf8",
					// Guards against a hung startup; a loaded runner can take more than 15 s to start the CLI.
					timeout: 60_000,
					input: '{"id":"state","type":"get_state"}\n',
				},
			);
			assert.equal(result.status, 0, `${label}: ${result.error ?? result.stderr}`);
			const response = result.stdout
				.split("\n")
				.filter((line) => line.startsWith("{"))
				.map((line) => JSON.parse(line))
				.find((message) => message.id === "state");
			assert.equal(response?.success, true, result.stdout);
			const toolsLine = result.stderr.split("\n").find((line) => line.startsWith("registered-tools:"));
			assert.ok(toolsLine, result.stderr);
			const tools = JSON.parse(toolsLine.slice("registered-tools:".length));
			for (const name of ["tff-fetch_url", "tff-search_web"]) {
				assert.equal(tools.includes(name), value !== "soon", `${label}: ${name}`);
			}
			assert.ok(tools.includes("web_fetch"), "static fetch must remain available");
			assert.ok(tools.includes("read"), "ordinary tools must remain available");
			const diagnostics = `${result.stdout}\n${result.stderr}`;
			if (value === "soon") {
				assert.match(diagnostics, /Optional extension jouzu-camoufox-adapter/u);
				assert.match(diagnostics, /JOUZU_CAMOUFOX_IDLE_STOP_MS.*soon/u);
			} else {
				assert.doesNotMatch(diagnostics, /Optional extension jouzu-camoufox-adapter/u);
			}
		}
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("Core capability routing corpus covers direct, context, web, and workflow choices", () => {
	assert.equal(corpus.schemaVersion, 1);
	assert.deepEqual(
		corpus.cases.map((entry) => entry.id),
		expectedCaseIds,
	);
	for (const entry of corpus.cases) {
		assert.equal(typeof entry.prompt, "string");
		assert.ok(entry.prompt.length > 0);
		for (const side of ["expect", "avoid"]) {
			assertStringArray(entry[side].skills, `${entry.id}.${side}.skills`);
			assertStringArray(entry[side].tools, `${entry.id}.${side}.tools`);
		}
		assertStringArray(entry.expect.behaviors, `${entry.id}.expect.behaviors`);
		assert.equal(
			entry.expect.skills.some((name) => entry.avoid.skills.includes(name)),
			false,
			`${entry.id} expects and avoids the same skill`,
		);
		assert.equal(
			entry.expect.tools.some((name) => entry.avoid.tools.includes(name)),
			false,
			`${entry.id} expects and avoids the same tool`,
		);
	}
})"

"test("Core keeps repository discipline inline and generates bounded decision-time routing", () => {
	assert.ok(JOUZU_DEFAULT_GUIDANCE.length <= corpus.budgets.defaultGuidanceCharacters);
	for (const phrase of [
		"Work directly by default",
		"Follow repository instructions and preserve user-owned work",
		"Inspect relevant files before editing",
		"Distinguish evidence from assumptions",
		"make the smallest coherent change",
		"run the narrowest deterministic check",
		"Report untested limitations honestly",
		"Use task tracking only for work with three or more distinct steps",
		"do not combine workflow systems",
		"exact listed `<location>` once",
		"never search guessed package paths",
		"If a skill file is unavailable, continue without it",
	]) {
		assert.match(JOUZU_DEFAULT_GUIDANCE, new RegExp(phrase));
	}
	assert.doesNotMatch(JOUZU_DEFAULT_GUIDANCE, /jouzu-core/);
	assert.doesNotMatch(JOUZU_DEFAULT_GUIDANCE, /\b(?:removed|retired|obsolete|superseded)\b/i);

	const routing = buildCapabilityRoutingGuidance({
		selectedTools: [
			"read",
			"grep",
			"find",
			"ls",
			"vcc_recall",
			"web_fetch",
			"batch_web_fetch",
			"tff-search_web",
			"tff-fetch_url",
			"TaskCreate",
			"get_goal",
			"update_goal",
			"multiloop_start",
			"bg_task",
			"schedule_prompt",
		],
		skills: [
			{ name: "jouzu-source-check" },
			{ name: "multiloop" },
			{ name: "jouzu-clear-writing" },
			{ name: "jouzu-anti-slop" },
		],
	});
	assert.doesNotMatch(routing, /Repository files and commands|`read`|`grep`|`find`|`ls`/);
	for (const phrase of [
		"vcc_recall",
		"web_fetch",
		"batch_web_fetch",
		"tff-search_web",
		"tff-fetch_url",
		"jouzu-source-check",
		"TaskCreate",
		"get_goal",
		"multiloop",
		"bg_task",
		"schedule_prompt",
		"jouzu-clear-writing",
		"jouzu-anti-slop",
	]) {
		assert.match(routing, new RegExp(phrase));
	}
	assert.match(routing, /read `jouzu-source-check` at its listed `<location>`/);
	assert.match(routing, /read `multiloop` at its listed `<location>`/);
	// The goal and measured-loop routes both come from the multiloop skill now.
	assert.match(routing, /One user-approved persistent objective/);
	assert.match(routing, /Repeated measured improvement/);
	assert.match(routing, /read `jouzu-clear-writing` at its listed `<location>`/);
	assert.match(routing, /read `jouzu-anti-slop` at its listed `<location>`/);
	assert.match(routing, /Existing prose needs a filler-removal pass/);
})"

"test("Jouzu product questions route to the reference only when the skill is bundled", () => {
	const skill = { name: "jouzu-reference" };
	const routing = buildCapabilityRoutingGuidance({ selectedTools: ["read"], skills: [skill] });
	assert.match(routing, /read `jouzu-reference` at its listed `<location>`/);
	assert.match(
		routing,
		/Jouzu configuration, language, model catalogs, profiles, session or trace files, controls, or troubleshooting/,
	);
	assert.match(routing, /Use the actual session tools for live state/);
	assert.match(routing, /slash commands are user actions/);
	assert.match(routing, /user-only settings and restart requirements/);
	// The route is generated routing, not part of the inline default guidance.
	assert.doesNotMatch(JOUZU_DEFAULT_GUIDANCE, /jouzu-reference/);
	assert.doesNotMatch(buildCapabilityRoutingGuidance({ selectedTools: ["read"], skills: [] }), /jouzu-reference/);
	assert.doesNotMatch(buildCapabilityRoutingGuidance({ selectedTools: ["read"] }), /jouzu-reference/);
	assert.doesNotMatch(
		buildCapabilityRoutingGuidance({ selectedTools: ["read"], skills: [{ name: "jouzu-clear-writing" }] }),
		/jouzu-reference/,
	);
})"

"test("delegation routes to the skill only when both tool and skill are available", () => {
	const skill = { name: "jouzu-delegation" };
	const routing = buildCapabilityRoutingGuidance({ selectedTools: ["subagent"], skills: [skill] });
	assert.match(routing, /read `jouzu-delegation` at its listed `<location>` once/);
	assert.match(routing, /Use the user's configured role model/);
	// The subagent integration states the assignment checklist once for every model.
	assert.doesNotMatch(routing, /acceptance checks/);
	assert.doesNotMatch(buildCapabilityRoutingGuidance({ selectedTools: ["subagent"] }), /jouzu-delegation/);
	assert.doesNotMatch(buildCapabilityRoutingGuidance({ selectedTools: ["read"], skills: [skill] }), /jouzu-delegation/);
})"

"test("asynchronous-work guidance appears once, from waits when they are active", () => {
	const plain = buildCapabilityRoutingGuidance({ selectedTools: ["bg_task", "TaskUpdate"] });
	assert.ok(plain.startsWith(`${JOUZU_ASYNC_WAIT_GUIDANCE}\n\n`));
	assert.doesNotMatch(plain, /`agent_wait`/);
	const waiting = buildCapabilityRoutingGuidance({
		selectedTools: ["bg_task", "TaskUpdate", "agent_wait", "schedule_prompt"],
	});
	// `agent_wait` registers the wait protocol as tool guidelines; routing repeats none of it.
	assert.doesNotMatch(waiting, /completion notifications|agent_wait|end the turn/);
	assert.match(waiting, /do not add timer-based polling/);
})"

"test("the untrusted-content rule is stated once per prompt", () => {
	const withBrowser = buildCapabilityRoutingGuidance({
		selectedTools: ["web_fetch", "batch_web_fetch", "tff-search_web", "tff-fetch_url"],
	});
	assert.doesNotMatch(withBrowser, /untrusted/i);
	const fetchOnly = buildCapabilityRoutingGuidance({ selectedTools: ["web_fetch", "batch_web_fetch"] });
	assert.equal(fetchOnly.match(/untrusted/g)?.length, 1);
	assert.equal(buildCapabilityRoutingGuidance({ selectedTools: ["batch_web_fetch"] }).match(/untrusted/g)?.length, 1);
})"

"test("writing routes name their triggers and distinguish drafting from a filler pass", () => {
	const routing = buildCapabilityRoutingGuidance({
		selectedTools: ["read"],
		skills: [{ name: "jouzu-clear-writing" }, { name: "jouzu-anti-slop" }],
