			assert.doesNotMatch(error.message, /fixture-secret|private details/u);
			return true;
		},
	)"

"test("catalog registry rejects unsafe files, labels, sources, and credential references", () => {
	const { root, paths, registryPath } = setup();
	try {
		mkdirSync(paths.configDir, { recursive: true });
		writeFileSync(registryPath, '{"schemaVersion":1,"sources":[],"sources":[]}');
		assert.throws(() => loadCatalogSourceRegistry(paths), /duplicate object key/u);
		writeFileSync(registryPath, '{"schemaVersion":1,"sources":[]}');
		const target = join(root, "target.json");
		writeFileSync(target, '{"schemaVersion":1,"sources":[]}');
		rmSync(registryPath);
		symlinkSync(target, registryPath);
		assert.throws(() => loadCatalogSourceRegistry(paths), /regular file/u);
		rmSync(registryPath);

		const store = new CatalogSourceStore(paths);
		assert.throws(
			() => store.add({ label: "bad\u001b", url: "https://example.test/catalog", auth: { type: "none" } }),
			CatalogSourceError,
		);
		assert.throws(
			() =>
				store.add({
					label: "Bad auth",
					url: "https://example.test/catalog",
					auth: { type: "bearer", credentialRef: "literal-secret" },
				}),
			/environment credential reference/u,
		);
		const cleartext = store.add({ label: "Cleartext", url: "http://example.test/catalog", auth: { type: "none" } });
		assert.equal(cleartext.url, "http://example.test/catalog");
		assert.match(catalogInsecureTransportWarning(cleartext.url), /plain text/u);
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("source URL validation rejects credentials, queries, and fragments", () => {
	for (const url of [
		"https://user:pass@example.test/catalog",
		"https://example.test/catalog?q=1",
		"https://example.test/catalog#part",
	]) {
		assert.throws(() => catalogEndpointCandidates(url), /credentials|query|fragment/);
	}
	assert.equal(catalogEndpointCandidates("http://localhost:8080/catalog")[0], "http://localhost:8080/catalog");
})"

"test("plain HTTP is allowed but flagged as an insecure transport", () => {
	assert.equal(catalogInsecureTransportWarning("https://example.test/catalog"), undefined);
	assert.equal(catalogInsecureTransportWarning("http://localhost:8080/catalog"), undefined);
	assert.equal(catalogInsecureTransportWarning("http://127.0.0.1:8989/v1/jouzu/model-catalog"), undefined);
	assert.match(catalogInsecureTransportWarning("http://example.test/catalog"), /plain text/u);
	assert.match(catalogInsecureTransportWarning("http://192.168.1.10:8080/v1/jouzu/model-catalog"), /plain text/u);
	assert.equal(catalogInsecureTransportWarning("not a url"), undefined);
})"

"test("saved tokens live in a private store and never in the registry", () => {
	const { root, paths } = setup();
	try {
		const store = new CatalogSourceStore(paths, { env: {} });
		const source = store.add({
			label: "Office pool",
			url: "https://catalog.example/v1/jouzu/model-catalog",
			auth: { type: "bearer", credentialRef: "env:OFFICE_POOL_TOKEN" },
		});
		const credentialsPath = join(paths.configDir, "catalog-credentials.json");
		assert.equal(existsSync(credentialsPath), false);

		setCatalogSourceToken(paths, source.id, "  sk-office-secret  ");
		assert.equal(getCatalogSourceToken(paths, source.id), "sk-office-secret");
		const bytes = readFileSync(credentialsPath, "utf8");
		assert.match(bytes, /sk-office-secret/u);
		assert.doesNotMatch(readFileSync(join(paths.configDir, "catalogs.json"), "utf8"), /sk-office-secret/u);
		assert.equal(JSON.parse(bytes).schemaVersion, 1);

		// Update, remove, and the empty store deletes its own file.
		setCatalogSourceToken(paths, source.id, "sk-rotated");
		assert.equal(getCatalogSourceToken(paths, source.id), "sk-rotated");
		removeCatalogSourceToken(paths, source.id);
		assert.equal(getCatalogSourceToken(paths, source.id), undefined);
		assert.equal(existsSync(credentialsPath), false);

		assert.throws(() => setCatalogSourceToken(paths, source.id, "no\nnewlines"), CatalogSourceError);
		assert.throws(() => setCatalogSourceToken(paths, source.id, " ".repeat(10)), CatalogSourceError);
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("bearer resolution prefers the environment over a saved token", () => {
	const { root, paths } = setup();
	try {
		const store = new CatalogSourceStore(paths, { env: {} });
		const source = store.add({
			label: "Office pool",
			url: "https://catalog.example/v1/jouzu/model-catalog",
			auth: { type: "bearer", credentialRef: "env:OFFICE_POOL_TOKEN" },
		});
		assert.throws(() => resolveCatalogBearer(source, {}, paths), /OFFICE_POOL_TOKEN is not set/u);
		assert.equal(catalogSourceCredentialAvailable(source, {}, paths), false);
		assert.deepEqual(catalogSourceCredentialState(source, {}, paths), {
			name: "OFFICE_POOL_TOKEN",
			envSet: false,
			stored: false,
		});

		setCatalogSourceToken(paths, source.id, "sk-saved");
		assert.equal(resolveCatalogBearer(source, {}, paths), "sk-saved");
		assert.equal(catalogSourceCredentialAvailable(source, {}, paths), true);
		assert.deepEqual(catalogSourceCredentialState(source, {}, paths), {
			name: "OFFICE_POOL_TOKEN",
			envSet: false,
			stored: true,
		});

		// The environment overrides the saved token.
		assert.equal(resolveCatalogBearer(source, { OFFICE_POOL_TOKEN: "sk-env" }, paths), "sk-env");
		// Without paths, only the environment is consulted.
		assert.equal(resolveCatalogBearer(source, { OFFICE_POOL_TOKEN: "sk-env" }), "sk-env");
		assert.throws(() => resolveCatalogBearer(source, {}), /OFFICE_POOL_TOKEN is not set/u);
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("removing a source or dropping bearer auth removes its saved token", () => {
	const { root, paths } = setup();
	try {
		const store = new CatalogSourceStore(paths, { env: {} });
		const source = store.add({
			label: "Office pool",
			url: "https://catalog.example/v1/jouzu/model-catalog",
			auth: { type: "bearer", credentialRef: "env:OFFICE_POOL_TOKEN" },
		});
		setCatalogSourceToken(paths, source.id, "sk-saved");
		assert.equal(Object.keys(loadCatalogSourceTokens(paths)).length, 1);

		store.update(source.id, {
			label: "Office pool",
			url: "https://catalog.example/v1/jouzu/model-catalog",
			auth: { type: "none" },
		});
		assert.equal(getCatalogSourceToken(paths, source.id), undefined);
		assert.equal(existsSync(join(paths.configDir, "catalog-credentials.json")), false);

		setCatalogSourceToken(paths, source.id, "sk-saved-again");
		store.remove(source.id);
		assert.equal(Object.keys(loadCatalogSourceTokens(paths)).length, 0);
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("Shisa catalog uses saved login after explicit credentials, without sharing it with other endpoints", () => {
	const { root, paths } = setup();
	try {
		mkdirSync(paths.agentDir, { recursive: true });
		const authPath = join(paths.agentDir, "auth.json");
		const save = (credential) => writeFileSync(authPath, JSON.stringify({ shisa: credential }), { mode: 0o600 });
		const source = SHISA_API_CATALOG_SOURCE;
		const login = { type: "oauth", access: "sk-login-fixture", refresh: "", expires: Number.MAX_SAFE_INTEGER };
		save(login);
		assert.equal(resolveCatalogBearer(source, {}, paths), login.access);
		assert.equal(catalogSourceCredentialAvailable(source, {}, paths), true);
		assert.equal(catalogSourceCredentialState(source, {}, paths).login, true);
		setCatalogSourceToken(paths, source.id, "sk-catalog-fixture");
		assert.equal(resolveCatalogBearer(source, {}, paths), "sk-catalog-fixture");
		assert.equal(resolveCatalogBearer(source, { SHISA_API_KEY: "sk-env-fixture" }, paths), "sk-env-fixture");
		removeCatalogSourceToken(paths, source.id);
		for (const other of [
			{ ...source, url: "https://unrelated.example/catalog" },
			{ ...source, url: `${source.url}?copy=1` },
			{ ...source, auth: { type: "bearer", credentialRef: "env:OTHER_KEY" } },
		])
			assert.throws(() => resolveCatalogBearer(other, {}, paths), /not set/);
		for (const invalid of [
			{ ...login, expires: 0 },
			{ ...login, access: "" },
			{ ...login, access: "bad\ntoken" },
			{ type: "oauth" },
		]) {
			save(invalid);
			assert.equal(catalogSourceCredentialAvailable(source, {}, paths), false);
			assert.throws(() => resolveCatalogBearer(source, {}, paths), /not set/);
		}
		save(login);
		assert.equal(resolveCatalogBearer(source, {}, paths), login.access);
		writeFileSync(authPath, "{}");
		assert.equal(catalogSourceCredentialAvailable(source, {}, paths), false, "logout is visible without restarting");
		writeFileSync(authPath, "invalid auth json");
		assert.equal(catalogSourceCredentialAvailable(source, {}, paths), false);
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

