"test("combining marks, full-width spaces, emoji, and variation selectors measure by display width", () => {
	// The product width helper delegates to Pi TUI's terminal-width
	// implementation: zero-width marks add nothing and wide glyphs count as two.
	assert.equal(terminalTextWidth("か\u3099"), 2);
	assert.equal(terminalTextWidth("\u3000"), 2);
	assert.equal(terminalTextWidth("🦁"), 2);
	assert.equal(terminalTextWidth("❤\ufe0f"), 2);
	assert.equal(terminalTextWidth("👨‍👩‍👧"), 2);
	assert.equal(terminalTextWidth("か\u3099\u3000🦁\ufe0f❤\ufe0f"), 8);
})"

"test("combining characters, full-width spaces, variant characters, and emoji keep a correct width", () => {
	// A combining mark adds no column to the character it modifies, whether the
	// base is a kana, a CJK ideograph, or a Latin letter.
	assert.equal(terminalTextWidth("か\u3099"), terminalTextWidth("か"));
	assert.equal(terminalTextWidth("は\u3099"), terminalTextWidth("は"));
	assert.equal(terminalTextWidth("e\u0301"), terminalTextWidth("e"));

	// A full-width space and a full-width letter are each two columns.
	assert.equal(terminalTextWidth("\u3000"), 2);
	assert.equal(terminalTextWidth("Ａ"), 2);

	// Variant characters: the CJK Compatibility Ideographs and the common
	// variant forms of a character are all wide, so replacing a character with
	// its variant never changes the column count.
	for (const variant of ["邊", "邉", "國", "国", "高", "髙", "斎", "齋", "\uF900", "\uFA0C"]) {
		assert.equal(terminalTextWidth(variant), 2, `variant ${JSON.stringify(variant)} is not two columns`);
	}

	// Emoji: a ZWJ sequence, a skin-tone modifier, a regional-indicator flag, a
	// keycap, and an emoji-presentation selector each stay one wide glyph, while
	// a text-presentation selector keeps the narrow base width.
	assert.equal(terminalTextWidth("👨‍👩‍👧"), 2, "a ZWJ sequence is one wide glyph");
	assert.equal(terminalTextWidth("👍🏽"), 2, "a skin-tone modifier adds no column");
	assert.equal(terminalTextWidth("🇯🇵"), 2, "a regional-indicator flag is one wide glyph");
	assert.equal(terminalTextWidth("1️⃣"), 2, "a keycap is one wide glyph");
	assert.equal(terminalTextWidth("❤\ufe0f"), 2, "an emoji-presentation selector is zero width");
	assert.equal(terminalTextWidth("❤\ufe0e"), 1, "a text-presentation selector keeps the narrow base");
})"

"test("fitting and padding keep every combining, full-width, variant, and emoji case inside its column", () => {
	// A wrong width shows up as a line that is short or over its column, so each
	// case is fitted and padded to every column from zero and the result must
	// land exactly on the column.
	const cases = [
		["combining mark", "か\u3099"],
		["full-width space", "\u3000"],
		["full-width letter", "Ａ"],
		["variant character", "邊"],
		["compatibility ideograph", "\uF900"],
		["emoji ZWJ sequence", "👨‍👩‍👧"],
		["emoji skin tone", "👍🏽"],
		["emoji flag", "🇯🇵"],
		["emoji keycap", "1️⃣"],
		["emoji variation selector", "❤\ufe0f"],
	];
	for (const [name, value] of cases) {
		for (let columns = 0; columns <= 12; columns += 1) {
			assert.ok(terminalTextWidth(fitTerminalText(value, columns)) <= columns, `${name} fit at ${columns}`);
			assert.equal(terminalTextWidth(padTerminalText(value, columns)), columns, `${name} pad at ${columns}`);
		}
	}
})"

"test("profile operations preserve CJK paths, normalization, BOM, CRLF, and user bytes", () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-cjk-"));
	try {
		const jouzuHome = join(root, "上手　home");
		const project = join(root, "日本語 project");
		const decomposedName = `は\u3099-${"仕様"}.txt`;
		mkdirSync(project, { recursive: true });
		writeFileSync(join(project, "要件　仕様.md"), readFileSync(fixture));
		writeFileSync(join(project, decomposedName), "結合文字を保持\n");
		writeFileSync(join(project, "BOM.txt"), Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from("日本語\n")]));
		writeFileSync(join(project, "CRLF.txt"), Buffer.from("一行目\r\n二行目\r\n"));
		mkdirSync(join(jouzuHome, "agent"), { recursive: true });
		writeFileSync(join(jouzuHome, "agent", "AGENTS.md"), "利用者所有の指示　🦁\r\n");

		const tracked = [
			join(project, "要件　仕様.md"),
			join(project, decomposedName),
			join(project, "BOM.txt"),
			join(project, "CRLF.txt"),
			join(jouzuHome, "agent", "AGENTS.md"),
		];
		const before = new Map(tracked.map((path) => [path, hash(readFileSync(path))]));
		applyProfile(loadBundledProfile("ja"), paths(jouzuHome), "0.1.0");
		const after = new Map(tracked.map((path) => [path, hash(readFileSync(path))]));
		assert.deepEqual(after, before);
		assert.ok(readdirSync(project).includes(decomposedName));
		assert.equal(readFileSync(join(project, "BOM.txt")).subarray(0, 3).toString("hex"), "efbbbf");
		assert.match(readFileSync(join(project, "CRLF.txt"), "utf8"), /一行目\r\n二行目\r\n/);
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("Unicode arguments and no-color diagnostics preserve exact text", () => {
	const args = ["--jouzu-home", "./上手　home", "pi", "@要件　仕様.md", "日本語で確認 🦁"];
	assert.deepEqual(parseJouzuArgs(args).args, ["@要件　仕様.md", "日本語で確認 🦁"]);

	const root = mkdtempSync(join(tmpdir(), "jouzu-cjk-terminal-"));
	try {
		const home = join(root, "端末　上手");
		const result = spawnSync(process.execPath, [cli, "--jouzu-home", home, "profile", "plan"], {
			encoding: "utf8",
			env: { ...process.env, NO_COLOR: "1", TERM: "dumb", PI_OFFLINE: "1" },
		});
		assert.equal(result.status, 0, result.stderr);
		assert.match(result.stdout, new RegExp(home.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")));
		assert.equal(result.stdout.includes("\u001b["), false);
		assert.equal(result.stdout.normalize("NFC").includes(home.normalize("NFC")), true);
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("receipt-sensitive tools require direct calls; ordinary tools remain callable", () => {
	for (const name of directTools) assert.equal(requiresDirectToolCall(name), true, name);
	for (const name of ["read", "write", "edit", "bash", "web_fetch", "mcp__docs__search", "codemode"])
		assert.equal(requiresDirectToolCall(name), false, name);
})"

"test(`nested ${name} is blocked before side effects, while a direct call executes`, async (t) => {
		let executions = 0;
		let nested;
		const { session } = await createFlowSession(t, {
			tools: ["fanout", name],
			extensions: [
				createDirectToolPolicyExtension(),
				(pi) => {
					pi.registerTool({
						name,
						label: name,
						description: "Fixture",
						parameters: { type: "object", properties: {} },
						execute: async () => {
							executions++;
							return { content: [{ type: "text", text: "observed directly" }], details: {} };
						},
					});
					pi.registerTool({
						name: "fanout",
						label: "fanout",
						description: "Fixture",
						parameters: { type: "object", properties: {} },
						execute: async (_id, _args, signal, _update, ctx) => {
							nested = await ctx.executeTool(name, {}, { signal });
							return { content: [{ type: "text", text: "fanout finished" }], details: {} };
						},
					});
				},
			],
		});
		let call;
		session.agent.streamFunction = async () => {
			const final = assistant();
			if (call) {
				final.content = [{ type: "toolCall", id: "outer", name: call, arguments: {} }];
				final.stopReason = "toolUse";
				call = undefined;
			}
			return {
				async *[Symbol.asyncIterator]() {
					yield { type: "done", partial: final };
				},
				result: async () => final,
			};
		};
		call = "fanout";
		await session.prompt("nested call");
		assert.equal(executions, 0);
		assert.equal(nested.isError, true);
		assert.match(nested.result.content[0].text, /Call .* directly/);
		assert.equal(
			session.messages.some((message) => message.role === "toolResult" && message.toolName === name),
			false,
		);
		call = name;
		await session.prompt("direct call");
		assert.equal(executions, 1);
		assert.ok(
			session.messages.some(
				(message) => message.role === "toolResult" && message.toolName === name && !message.isError,
			),
		);
	})"

"test(`a virtual selection is withheld before routing under ${guard} admission`, async (t) => {
		const { session, requests } = await createFlowSession(t, {
			model: { ...model, api: "pi-virtual" },
			...(guard === "flow"
				? { ingress: { version: 1, submit: (_input, dispatch) => dispatch() } }
				: {
						policy: {
							filterSkills: async (skills) => skills,
							readSkill: async () => undefined,
							shouldInspectTool: () => true,
							filterToolResult: async (event) => event.result,
							filterContext: async (messages) => messages,
						},
					}),
		});
		let routed = 0;
		session.modelRuntime.resolveModel = async () => {
			routed++;
			throw new Error("router must not run");
		};
		await session.prompt("route a request");
		assert.equal(routed, 0);
		assert.equal(requests.length, 0);
		assert.ok(
			session.messages.some(
				(message) => message.role === "assistant" && /physical model/.test(message.errorMessage ?? ""),
			),
		);
		await assert.rejects(session._getSummarizationRequestAuth(session.model), /physical model/);
		assert.equal(routed, 0);
	})"

"test("classic overrides keep codemode disabled and replace the MCP factory", async (t) => {
	let started = 0;
	const { session, requests } = await createFlowSession(t, {
		additionalExtensionPaths: ["builtin:mcp", "builtin:codemode"],
		extensions: [
			{
				name: "mcp",
				builtin: true,
				factory: () => {
					started++;
					throw new Error("native server must not start");
				},
			},
			{
				name: "codemode",
				builtin: true,
				factory: () => {
					started++;
					throw new Error("native script runtime must not start");
				},
			},
			...classicHostBuiltinOverrides(),
		],
	});
	await session.prompt("ordinary turn");
	assert.equal(started, 0);
	assert.equal(requests.length, 1);
	assert.ok(session.extensionRunner.getCommand("mcp"));
	assert.equal(
		session.getAllTools().some((tool) => tool.name.startsWith("mcp__") || tool.name === "codemode"),
		false,
	);
})"

"test("ACP CLI drives real Jouzu RPC tools and reloads persisted sessions", { timeout: 60_000 }, async () => {
	const root = await mkdtemp(join(tmpdir(), "jouzu-acp-cli-"));
	const home = join(root, "home");
	const workspace = join(root, "workspace");
	const cwd = join(root, "workspace-alias");
	await mkdir(join(home, "agent"), { recursive: true });
	await mkdir(workspace);
	await symlink(workspace, cwd, process.platform === "win32" ? "junction" : "dir");
	await writeFile(join(cwd, "evidence.txt"), "ACP_REAL_RPC_EVIDENCE");
	const requests = [];
	const server = createServer(async (req, res) => {
		const chunks = [];
		for await (const chunk of req) chunks.push(chunk);
		requests.push(JSON.parse(Buffer.concat(chunks).toString()));
		res.writeHead(200, { "Content-Type": "text/event-stream" });
		const first = requests.length === 1;
		const delta = first
			? {
					role: "assistant",
					tool_calls: [
						{
							index: 0,
							id: "acp-read",
							type: "function",
							function: { name: "read", arguments: JSON.stringify({ path: join(cwd, "evidence.txt") }) },
						},
					],
				}
			: { role: "assistant", content: "ACP answer: 日本語\u2028jouzu --session preserved." };
		res.write(`data: ${JSON.stringify({ id: "fixture", choices: [{ index: 0, delta, finish_reason: null }] })}\n\n`);
		res.write(
			`data: ${JSON.stringify({ id: "fixture", choices: [{ index: 0, delta: {}, finish_reason: first ? "tool_calls" : "stop" }], usage: { prompt_tokens: 10, completion_tokens: 5, total_tokens: 15 } })}\n\n`,
		);
		res.end("data: [DONE]\n\n");
	});
	server.listen(0, "127.0.0.1");
	await once(server, "listening");
	await writeFile(
		join(home, "agent", "models.json"),
		JSON.stringify({
			providers: {
				"acp-fixture": {
					baseUrl: `http://127.0.0.1:${server.address().port}/v1`,
					api: "openai-completions",
					apiKey: "fixture-only",
					models: [
						{
							id: "fixture",
							name: "ACP fixture",
							reasoning: false,
							input: ["text"],
							contextWindow: 32000,
							maxTokens: 512,
							cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
						},
					],
				},
			},
		}),
	);
	await writeFile(
		join(home, "agent", "settings.json"),
		JSON.stringify({ defaultProvider: "acp-fixture", defaultModel: "fixture", defaultThinkingLevel: "off" }),
	);
	const env = Object.fromEntries(
		Object.entries(process.env).filter(
			([key]) => !/^(JOUZU_|PI_|SHISA_|AI_AGENT|TEXTGUARD_|OPENAI_|ANTHROPIC_)/u.test(key),
		),
	);
	env.PI_OFFLINE = "1";
	const processes = [];
	async function connect() {
		// A relative override must stay anchored to the adapter launch directory,
		// not the workspace supplied by session/new.
		const child = spawn(process.execPath, [cli, "--jouzu-home", "home", "acp"], {
			cwd: root,
			env,
			stdio: ["pipe", "pipe", "pipe"],
		});
		const closed = once(child, "close");
		let stderr = "";
		child.stderr.setEncoding("utf8").on("data", (chunk) => {
			stderr += chunk;
		});
		const updates = [];
		const app = client().onNotification("session/update", ({ params }) => {
			updates.push(params);
		});
		const connection = app.connect(ndJsonStream(Writable.toWeb(child.stdin), Readable.toWeb(child.stdout)));
		const request = (method, params) =>
			within(connection.agent.request(method, params)).catch((error) => {
				throw new Error(`${method}: ${error.message}\n${stderr}`, { cause: error });
			});
		const entry = { child, closed, connection, updates, request };
		processes.push(entry);
		const initialized = await request("initialize", { protocolVersion: PROTOCOL_VERSION, clientCapabilities: {} });
		assert.equal(initialized.agentInfo.name.toLowerCase(), "jouzu");
		assert.equal(initialized.agentCapabilities.loadSession, true);
		return entry;
	}
	async function disconnect(entry) {
		entry.child.stdin.end();
		const [code, signal] = await within(entry.closed, 10_000);
		assert.equal(signal, null);
		assert.equal(code, 0);
	}
	try {
		const first = await connect();
		const session = await first.request("session/new", { cwd, mcpServers: [] });
		assert.ok(session.sessionId);
		const result = await first.request("session/prompt", {
			sessionId: session.sessionId,
			prompt: [{ type: "text", text: "Read evidence.txt, then report." }],
		});
		assert.equal(result.stopReason, "end_turn");
		assert.equal(requests.length, 2);
		assert.match(JSON.stringify(requests[1].messages), /ACP_REAL_RPC_EVIDENCE/u);
		assert.ok(first.updates.some(({ update }) => update.sessionUpdate === "tool_call"));
		assert.ok(
			first.updates.some(({ update }) => update.sessionUpdate === "tool_call_update" && update.status === "completed"),
		);
		const text = first.updates
			.filter(({ update }) => update.sessionUpdate === "agent_message_chunk")
			.map(({ update }) => update.content.text)
			.join("");
		assert.equal(text, "ACP answer: 日本語\u2028jouzu --session preserved.");
		await disconnect(first);
		const second = await connect();
		await assert.rejects(
			second.request("session/load", { sessionId: session.sessionId, cwd: root, mcpServers: [] }),
			/Session working directory does not match/u,
		);
		await second.request("session/load", { sessionId: session.sessionId, cwd, mcpServers: [] });
		assert.match(JSON.stringify(second.updates), /ACP answer/u);
		assert.equal(
			(
				await second.request("session/prompt", {
					sessionId: session.sessionId,
					prompt: [{ type: "text", text: "Continue." }],
				})
			).stopReason,
			"end_turn",
		);
		assert.match(JSON.stringify(requests.at(-1).messages), /ACP_REAL_RPC_EVIDENCE/u);
		await disconnect(second);
	} finally {
		for (const entry of processes) {
			entry.connection.close();
			if (entry.child.exitCode === null && entry.child.signalCode === null) entry.child.kill("SIGKILL");
			await entry.closed;
		}
		server.closeAllConnections();
		await new Promise((resolve) => server.close(resolve));
		await rm(root, { recursive: true, force: true });
	}
})"

