"test("Core loads the selected release-owned tool, command, and skill surfaces", () => {
	const temp = mkdtempSync(join(tmpdir(), "jouzu-release-surfaces-"));
	try {
		const probe = join(temp, "surface probe.js");
		writeFileSync(
			probe,
			`export default function (pi) {
				pi.registerCommand("jouzu-surface-probe", {
					handler: async () => {
						const tools = pi.getAllTools().map((tool) => tool.name).sort();
						const commands = pi.getCommands().map((command) => command.name).sort();
						process.stderr.write("JOUZU_SURFACE_PROBE=" + JSON.stringify({ tools, commands }) + "\\n");
					},
				});
			}
`,
		);
		const result = run(
			[
				"--jouzu-home",
				join(temp, "home"),
				"pi",
				"--extension",
				probe,
				"--mode",
				"rpc",
				"--no-session",
				"--no-context-files",
			],
			{
				input: `${JSON.stringify({ id: "probe", type: "prompt", message: "/jouzu-surface-probe" })}\n${JSON.stringify({ id: "commands", type: "get_commands" })}\n`,
			},
		);
		assert.equal(result.status, 0, result.stderr);
		const marker = result.stderr.split("\n").find((line) => line.startsWith("JOUZU_SURFACE_PROBE="));
		assert.ok(marker, result.stderr);
		const surfaces = JSON.parse(marker.slice("JOUZU_SURFACE_PROBE=".length));
		for (const tool of [
			"TaskCreate",
			"TaskList",
			"batch_web_fetch",
			"bg_task",
			"get_goal",
			"multiloop_start",
			"schedule_prompt",
			"tff-fetch_url",
			"tff-search_web",
			"update_goal",
			"vcc_recall",
			"web_fetch",
		]) {
			assert.ok(surfaces.tools.includes(tool), `missing tool ${tool}`);
		}
		for (const command of [
			"goal",
			"multiloop",
			"pi-vcc",
			"schedule-prompt",
			"skill:jouzu-anti-slop",
			"skill:jouzu-clear-writing",
			"skill:jouzu-delegation",
			"skill:jouzu-source-check",
			"skill:multiloop",
			"status",
			"tasks",
		]) {
			assert.ok(surfaces.commands.includes(command), `missing command ${command}`);
		}
		assert.equal(surfaces.commands.includes("skill:jouzu-core"), false);
		assert.equal(rpcResponse(result.stdout, "probe").success, true);
		assert.equal(rpcResponse(result.stdout, "commands").success, true);
	} finally {
		rmSync(temp, { recursive: true, force: true });
	}
})"

"test("a prompt sent with flow control keeps its acceptance when input ends at once", () => {
	const temp = mkdtempSync(join(tmpdir(), "jouzu-flow-rpc-shutdown-"));
	try {
		const probe = join(temp, "shutdown probe.js");
		writeFileSync(
			probe,
			`export default function (pi) {
				pi.registerCommand("jouzu-shutdown-probe", {
					handler: async () => {
						process.stderr.write("JOUZU_SHUTDOWN_PROBE=ran\\n");
					},
				});
			}
`,
		);
		// End-of-input starts shutdown. Admission adds latency the prompt has to survive, so with
		// flow control installed the command must still run and report the same result as without it.
		for (const flag of [undefined, "1", "0"]) {
			const result = run(
				[
					"--jouzu-home",
					join(temp, `home-${flag ?? "off"}`),
					"pi",
					"--extension",
					probe,
					"--mode",
					"rpc",
					"--no-session",
					"--no-context-files",
				],
				{
					input: `${JSON.stringify({ id: "probe", type: "prompt", message: "/jouzu-shutdown-probe" })}\n`,
					...(flag ? { env: { JOUZU_FLOW_CONTROL: flag } } : {}),
				},
			);
			// Unset now means enabled, so this covers the default path as well as both explicit values.
			const label = `JOUZU_FLOW_CONTROL=${flag ?? "unset"}`;
			assert.equal(result.status, 0, `${label}: ${result.stderr}`);
			assert.ok(result.stderr.includes("JOUZU_SHUTDOWN_PROBE=ran"), `${label}: the command never ran`);
			assert.deepEqual(rpcResponse(result.stdout, "probe"), {
				id: "probe",
				type: "response",
				command: "prompt",
				success: true,
				data: { disposition: "handled" },
			});
		}
	} finally {
		rmSync(temp, { recursive: true, force: true });
	}
})"

