		'{"schemaVersion":1,"mode":"other"}',
		'{"schemaVersion":1,"mode":"compact","extra":true}',
		'{"schemaVersion":1,"mode":"hidden","mode":"compact"}',
		" ".repeat(8193),
	]) {
		writeFileSync(dashboardPolicyPath(paths), content);
