"test("doctor reports a trusted project policy's fields and an invalid policy's reason", () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-doctor-language-policy-"));
	try {
		const trusted = render(
			createDoctorReport({
				...healthyContext(root),
				responseLanguage: { requested: "ja", effective: "ja", source: "config" },
				artifactPolicy: {
					requested: { documentation: "en" },
					effective: { comments: "preserve", documentation: "en", commits: "project", reviews: "project" },
					source: "project",
					fieldSources: { comments: "builtin", documentation: "project", commits: "builtin", reviews: "builtin" },
				},
				// A trusted policy renders the fields it supplied, so a reader can see
				// what crossed the trust boundary.
				projectPolicy: { status: "ok", artifactPolicy: { documentation: "en" } },
			}),
		);
		assertField(trusted, "Project language policy", "documentation=en");

		// An invalid file names the reason it was left untouched.
		const invalid = render(
			createDoctorReport({
				...healthyContext(root),
				responseLanguage: { requested: "auto", effective: "auto", source: "builtin" },
				artifactPolicy: {
					requested: {},
					effective: { comments: "preserve", documentation: "project", commits: "project", reviews: "project" },
					source: "builtin",
					fieldSources: {
						comments: "builtin",
						documentation: "builtin",
						commits: "builtin",
						reviews: "builtin",
					},
				},
				projectPolicy: { status: "invalid", reason: "the project policy is not a regular file" },
			}),
		);
		assertField(invalid, "Project language policy", "the project policy is not a regular file");
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("doctor keeps the UI locale and the response language on independent sources", () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-doctor-language-independent-"));
	try {
		// A Japanese UI locale must not move the response language, and vice versa.
		const result = createDoctorReport({
			...healthyContext(root),
			uiLocale: { requested: "ja", effective: "ja", source: "cli" },
			responseLanguage: { requested: "en", effective: "en", source: "config" },
			artifactPolicy: {
				requested: {},
				effective: { comments: "preserve", documentation: "project", commits: "project", reviews: "project" },
				source: "builtin",
				fieldSources: { comments: "builtin", documentation: "builtin", commits: "builtin", reviews: "builtin" },
			},
			projectPolicy: { status: "untrusted" },
		});
		const fieldValue = (id) => result.report.fields.find((field) => field.id === id)?.value;
		assert.equal(fieldValue("localization.effective"), "ja");
		assert.equal(fieldValue("localization.source"), "cli");
		assert.equal(fieldValue("language.responseLanguage.effective"), "en");
		assert.equal(fieldValue("language.responseLanguage.source"), "config");
		// Each setting keeps its own source, so neither is derived from the other.
		assert.notEqual(fieldValue("localization.source"), fieldValue("language.responseLanguage.source"));
		const text = render(result);
		assertField(text, "UI locale effective", "ja");
		assertField(text, "Response language effective", "en");
		assertField(text, "Response language source", "config");
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("doctor summarizes catalog gaps per source and points to the catalog detail", () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-doctor-catalog-"));
	rmSync(root, { recursive: true, force: true });
	const reportFor = (extra) =>
		createDoctorReport({
			metadata: metadata(),
			paths: paths(root),
			profile: { id: "core", source: "default" },
			piRuntimeVersion: "0.84.2",
			executable: "/opt/jouzu/node_modules/jouzu/dist/cli.js",
			env: { HOME: "/home/user", ANTHROPIC_API_KEY: "redacted" },
			platform: "linux",
			commandPaths: { git: "/usr/bin/git", bash: "/usr/bin/bash", npm: "/usr/bin/npm" },
			...extra,
		});
	const source = (overrides) => ({
		sourceId: "codex-pool",
		label: "codex-pool",
		offerings: 36,
		thinkingLevelGaps: [],
		registrationGaps: [],
		...overrides,
	});

	const complete = reportFor({ catalogSources: [source({})] });
	const completeText = render(complete);
	assertField(completeText, "Model registration", "complete");
	assertField(completeText, "Thinking levels", "complete");
	assertField(completeText, "codex-pool", "36 offerings · 36 can add a model · 0 without thinking levels");
	assert.doesNotMatch(completeText, /jz catalog status codex-pool/u);
	assert.equal(complete.healthy, true);

	const gaps = reportFor({
		catalogSources: [
			source({
				thinkingLevelGaps: [
					{ providerId: "aiand", modelId: "deepseek-ai/deepseek-v4-flash" },
					{ providerId: "aiand", modelId: "qwen/qwen3.6-27b" },
				],
			}),
			source({
				sourceId: "shisa-api",
				label: "Shisa API",
				offerings: 10,
				registrationGaps: Array.from({ length: 10 }, (_, index) => ({
					providerId: "shisa",
					modelId: `model-${index}`,
					missing:
						index < 4 ? ["textModality", "contextWindow", "maxOutputTokens"] : ["textModality", "maxOutputTokens"],
				})),
			}),
		],
	});
	const gapsText = render(gaps);
	assertField(gapsText, "Offerings", "46");
	assertField(gapsText, "Model registration", "36 of 46 offerings can add a model");
	assertField(gapsText, "Thinking levels", "2 of 46 offerings without declared levels");
	assertField(gapsText, "Shisa API", "10 offerings · 0 can add a model · 0 without thinking levels");
	// The source is the key column, so a reader sees which catalog to fix before reading the text.
	assert.match(
		flat(gapsText),
		/⚠ shisa-api 0 of 10 offerings carry the fields a new model needs \(10 no text input, 4 no context window, 10 no maximum output tokens\)/u,
	);
	assert.match(flat(gapsText), /never reaches the model list. Run "jz catalog status shisa-api" for the list/u);
	assert.match(flat(gapsText), /⚠ codex-pool 2 of 36 offerings declare no thinking levels/u);
	assert.equal(gaps.healthy, true, "a catalog gap is a warning, not a problem");

	const unconfigured = reportFor({ catalogSources: [] });
	assertField(render(unconfigured), "Model registration", "no active catalog");
	assertField(render(unconfigured), "Thinking levels", "no active catalog");

	const unavailable = reportFor({ catalogDiagnostic: "cached catalog digest mismatch" });
	const unavailableText = render(unavailable);
	assertField(unavailableText, "Model registration", "unavailable");
	assertField(unavailableText, "Thinking levels", "unavailable");
	assert.match(flat(unavailableText), /Catalog status is unavailable: cached catalog digest mismatch/u);

	assert.equal(rmSync(root, { recursive: true, force: true }), undefined);
})"

"test("doctor reports model picker counts and unreadable state without rewriting it", () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-doctor-model-picker-"));
	try {
