"test("lock field values render from the catalog in both locales", () => {
	const states = [
		[{ exists: false, status: "free", ageMs: null }, "free", "空き"],
		[
			{ exists: true, status: "held-live", ageMs: 12_000 },
			"held by a live process (12s)",
			"実行中のプロセスが保持しています（12s）",
		],
		[
			{ exists: true, status: "held-dead", ageMs: 12_000 },
			"left by a dead process (12s; recoverable after 30m 0s)",
			"終了したプロセスが残しています（12s、30m 0s 後に回復可能）",
		],
		[
			{ exists: true, status: "owner-unknown", ageMs: 12_000 },
			"owner unknown (12s; recoverable after 30m 0s)",
			"所有者を特定できません（12s、30m 0s 後に回復可能）",
		],
		[
			{ exists: true, status: "unreadable", ageMs: null },
			"unreadable (lock inspection failed)",
			"読み取れません（ロックの検査に失敗しました）",
		],
		[
			{ exists: true, status: "invalid", ageMs: null },
			"invalid (not a regular lock file)",
			"無効です（通常のロックファイルではありません）",
		],
	];
	const japaneseCatalog = loadCatalog("ja");
	for (const [inspection, english, japanese] of states) {
		const ref = stateLockValue(inspection, STATE_LOCK_STALE_MS);
		assert.equal(catalogMessageText(defaultCatalog(), ref), english, `${inspection.status} in en`);
		assert.equal(catalogMessageText(japaneseCatalog, ref), japanese, `${inspection.status} in ja`);
		assert.doesNotMatch(japanese, /[A-Za-z]{3,}/u, `${inspection.status} keeps an English word`);
	}
})"

"test("on/off is explicit, idempotent, persisted in the session, and independent of thinking", async () => {
	const h = harness();
	const payload = { model: model.id, reasoning: { effort: "high" }, input: [] };
	assert.equal(h.payload(payload), payload);
	await h.command();
	assert.match(h.notices.at(-1).message, /off/);
	assert.equal(h.entries.length, 0);
	await h.command("on");
	await h.command("on");
	assert.equal(h.entries.length, 1);
	assert.equal(h.statuses.get(FAST_MODE_STATUS), "on");
	assert.deepEqual(h.payload(payload), { ...payload, service_tier: "priority" });
	assert.equal(payload.service_tier, undefined);
	await h.command("off");
	assert.equal(h.statuses.has(FAST_MODE_STATUS), false);
	assert.equal(h.payload({ ...payload, service_tier: "priority" }).service_tier, "default");
	assert.deepEqual(
		h.entries.map((entry) => entry.data.enabled),
		[true, false],
	);
	assert.deepEqual(
		h.commands
			.get("fast")
			.getArgumentCompletions("o")
			.map((entry) => entry.value),
		["on", "off"],
	);
})"

"test("invalid arguments, unsupported selections, and busy sessions do not change the choice", async () => {
	const h = harness();
	for (const action of ["toggle", "on off", "yes"]) {
		await h.command(action);
		assert.equal(h.notices.at(-1).type, "warning");
	}
	h.ctx.isIdle = () => false;
	await h.command("on");
	assert.match(h.notices.at(-1).message, /Wait/);
	h.ctx.isIdle = () => true;
	for (const selection of [undefined, { ...model, api: "anthropic-messages" }, { ...model, id: "glm-5" }]) {
		h.ctx.model = selection;
		await h.command("on");
		assert.equal(h.notices.at(-1).type, "warning");
	}
	assert.equal(h.entries.length, 0);
	assert.equal(h.statuses.size, 0);
})"

"test("resume, branch navigation, model switches, and shutdown restore the indicator", async () => {
	const h = harness();
	await h.command("on");
	const enabled = structuredClone(h.entries);
	await h.command("off");
	h.entries.splice(0, h.entries.length, ...enabled);
	await h.handlers.get("session_tree")({}, h.ctx);
	assert.equal(h.statuses.get(FAST_MODE_STATUS), "on");
	h.ctx.model = { ...model, id: "claude-sonnet", api: "anthropic-messages" };
	await h.handlers.get("model_select")({}, h.ctx);
	assert.equal(h.statuses.has(FAST_MODE_STATUS), false);
	await h.command();
	assert.match(h.notices.at(-1).message, /inactive/);
	h.ctx.model = model;
	await h.handlers.get("model_select")({}, h.ctx);
	assert.equal(h.statuses.get(FAST_MODE_STATUS), "on");
	await h.handlers.get("session_shutdown")({}, h.ctx);
	assert.equal(h.statuses.size, 0);
	await h.handlers.get("session_start")({}, h.ctx);
	assert.equal(h.statuses.get(FAST_MODE_STATUS), "on");
	h.entries.length = 0;
	await h.handlers.get("session_start")({}, h.ctx);
	assert.equal(h.statuses.size, 0);
})"

