"test(`flow control keeps working across a ${reason} session replacement`, async (t) => {
		const root = await persistentRoot(t);
		const first = await assembledSession(t, { root, persist: true });
		await first.session.prompt("work in the first session");
		const before = first.ingress.branch();
		assert.equal((await before.attachment.submissions.snapshot()).length, 1);

		const next = await replacedSession(t, first, { reason, persist: true });
		assert.notEqual(next.ingress, first.ingress, "the replacement gets its own ingress");
		assert.notEqual(
			next.ingress.branch().scope.sessionId,
			before.scope.sessionId,
			"and its own session scope, so the two sessions never share retained state",
		);

		// The point of the whole exercise: input still reaches the provider afterwards.
		await next.session.prompt("work in the replacement session");
		const records = await next.ingress.branch().attachment.submissions.snapshot();
		assert.equal(records.length, 1, "the replacement starts with only its own input");
		assert.equal(records[0].dispatch.phase, "returned");
		assert.ok(
			JSON.stringify(next.bodies).includes("work in the replacement session"),
			"the prompt was transmitted, not held",
		);
		// The outgoing session is closed rather than left admitting in the background.
		assert.throws(() => first.ingress.releaseReady(), { code: "stale" });
	})"

"test("a replacement session accepts automated input once its own producers are ready", async (t) => {
	const root = await persistentRoot(t);
	const producers = await installedProducerExtensions();
	const first = await assembledSession(t, { root, persist: true, producerExtensions: producers });
	await first.session.prompt("work in the first session");

	const next = await replacedSession(t, first, { reason: "new", persist: true, producerExtensions: producers });
	// An extension follow-up is the shape a task list uses to hand back its next task. It must be
	// admitted in the new session, since the starvation gates are rebuilt along with the ingress.
	await next.session.sendUserMessage("Continue by working on the next task", { deliverAs: "followUp" });
	const automated = (await next.ingress.branch().attachment.submissions.snapshot()).find(
		(record) => record.submission.args[0] === "Continue by working on the next task",
	);
	assert.ok(automated, "the automated send was captured by the replacement's ingress");
	assert.ok(automated.dispatch, "and dispatched rather than held by state from the replaced session");
})"

"test("multiloop resumes at the next revision after all settled attempts are retired and the session reopens", async (t) => {
	const first = await attach(t, { persist: true });
	await first.host.transition(lane, "active");
	await continueOnce(first);
	await continueOnce(first);
	assert.equal(first.bodies.length, 2);
	const before = await first.ingress.branch().attachment.ledger.snapshot();
	assert.deepEqual(
		before.attempts.map((attempt) => attempt.admission.choice.intent.revision),
		["1", "2"],
	);
	first.host.changed([]);
	await first.ingress.wakeProducers();
	await first.ingress.retireLedgerHistory(0);
	assert.deepEqual((await first.ingress.branch().attachment.ledger.snapshot()).attempts, []);
	const history = first.sessionManager.getSessionFile();
	await first.shutdown("resume", history);
	const second = await attach(t, { root: first.root, persist: true, sessionManager: SessionManager.open(history) });
	await continueOnce(second);
	assert.equal(second.bodies.length, 1, "the next continuation is admitted, not fenced as an old revision");
	await second.ingress.wakeProducers();
	assert.equal(second.bodies.length, 1, "the new revision is itself fenced against duplicate admission");
	const after = await second.ingress.branch().attachment.ledger.snapshot();
	assert.equal(after.attempts[0].admission.choice.intent.revision, "3");
	assert.equal(after.attempts[0].outcome, "success");
	assert.deepEqual(first.errors, []);
	assert.deepEqual(second.errors, []);
})"

"test("the status command reads and repairs holds without reaching the model", async (t) => {
	const background = await controlledBackground(t);
	const f = await assembledSession(t, {
		producerExtensions: await installedProducerExtensions(),
		script: campaignScript({ command: background.command, goal: "Report status" }),
	});
	await f.session.prompt("start the sweep and wait");
	const wait = await liveWait(f.ingress, "the campaign leaves one live wait");
	const blocked = f.bodies.length;

	// Pi dispatches an extension command inside prompt, so this is the real user path.
	await f.session.prompt("/flow");
	await settle();
	assert.equal(f.bodies.length, blocked, "reading status sends no request and adds no model context");

	await f.session.prompt(`/flow cancel ${wait.token}`);
	const cancelled = (await f.ingress.branch().attachment.waits.snapshot()).find(
		(record) => record.token === wait.token,
	);
	assert.equal(cancelled?.state, "cancelled", "the wait is cancelled, with its reason recorded");
	assert.match(cancelled.cancellationReason ?? "", /\/flow/);
	await settle();
	assert.equal(f.bodies.length, blocked, "and cancelling it sends no request either");
	const live = (await f.ingress.branch().attachment.waits.snapshot()).filter((record) => record.state === "waiting");
	assert.deepEqual(live, [], "no live wait remains");

	// The campaign work outlives its wait: cancelling a gate does not complete or retire the work.
	const authority = await f.ingress.branch().attachment.waits.authoritySnapshot();
	assert.ok(
		authority.work.some((record) => record.id === wait.workId),
		"the owning work stays registered",
	);
	assert.deepEqual(f.errors, []);
})"

"test("/flow reset requires explicit confirmation before destructive recovery", async (t) => {
	const f = await assembledSession(t, { producerExtensions: await installedProducerExtensions() });
	const notices = capturedNotices(f.session);
	let resets = 0;
	const original = f.ingress.resetFlow.bind(f.ingress);
	f.ingress.resetFlow = async () => {
		resets++;
		return { kind: "inactive", attemptId: undefined, releasedRequests: 0, recoveryHeld: false };
	};
	try {
		await f.session.prompt("/flow reset");
		assert.equal(resets, 0);
		assert.match(
			notices.at(-1).text,
			/discards all queued messages.*Try \/flow clear first.*only if \/flow clear does not fix the problem.*\/flow reset confirm/,
		);
		for (const args of ["yes", "confirm extra"]) {
			await f.session.prompt(`/flow reset ${args}`);
			assert.equal(resets, 0);
		}
		await f.session.prompt("/flow reset confirm");
		await settle();
		assert.equal(resets, 1);
		assert.match(notices.at(-1).text, /Flow reset completed\. Destructive flow state was discarded/);
		assert.deepEqual(f.errors, []);
	} finally {
		f.ingress.resetFlow = original;
	}
})"

