"test(`compaction cannot excuse unverified omission: ${fault}, keepTail=${keepTail}`, () => {
			const f = fixture(keepTail);
			switch (fault) {
				case "invalid-boundary":
					f.manager.appendCompaction("Invalid boundary", "missing-entry", 6000);
					break;
				case "retained-frame":
					f.manager.appendCompaction("Keep work.", f.entryId, 5000);
					break;
				case "missing-history":
					f.attempt.history = [];
					break;
				case "changed-history":
					f.attempt.history[0].entryHash = "bad";
					break;
				case "changed-frame":
					f.attempt.members[0].contentHash = "bad";
					break;
				case "wrong-branch":
					f.manager.branch(f.entryId);
					break;
				case "missing-summary":
					f.input.sourceMessages = f.input.sourceMessages.filter((message) => message.role !== "compactionSummary");
					break;
				case "filtered-summary":
					f.input.modelMessages = f.input.modelMessages.filter((message) => message.role === "system");
					break;
				case "changed-summary":
					f.input.sourceMessages.find((message) => message.role === "compactionSummary").summary = "Altered summary";
					f.input.modelMessages = convertToLlm(f.input.sourceMessages);
					break;
				case "reinserted-source":
					f.input.sourceMessages.push({ role: "user", content: f.composition.content, timestamp: 1 });
					break;
			}
			assert.deepEqual(compactedFlowMembers(f.manager, f.attempt, f.input), []);
		})"

"test("continuous extension followups retire superseded receipts before capacity fails @endurance", {
	timeout: 120000,
}, async (t) => {
	let endings = 0;
	const done = deferred();
	const f = await assembledSession(t, {
		producerExtensions: [
			...(await installedProducerExtensions()),
			{
				name: "continuation-probe",
				factory(pi) {
					pi.on("agent_end", () => {
						endings++;
						if (endings < 160)
							pi.sendUserMessage(`Continue probe ${endings}: ${"x".repeat(14000)}`, { deliverAs: "followUp" });
					});
					pi.on("agent_settled", () => {
						if (endings >= 160) done.resolve();
					});
				},
			},
		],
	});
	await f.session.prompt("Start probe");
	await done.promise;
	await f.session.waitForIdle();
	const errors = f.sessionManager
		.getEntries()
		.filter((e) => e.type === "message" && e.message.errorMessage)
		.map((e) => e.message.errorMessage);
	assert.equal(f.bodies.length, 160);
	assert.deepEqual(errors, []);
	assert.deepEqual(f.errors, []);
	assert.ok((await f.ingress.branch().attachment.submissions.snapshot(false)).length <= 2);
	assert.equal((await f.ingress.branch().attachment.submissions.snapshot()).length, 160);
	assert.ok((await f.ingress.branch().attachment.nativeRequests.snapshot()).length <= 3);
})"

"test(`revocation during queue maintenance stays fenced until ${resume}`, { timeout: 5000 }, async (t) => {
		const f = await fixture(t, true);
		const input = FlowModelInput.compose(
			"revoked",
			[{ id: "work", revision: "1", kind: "work", text: "Must not run" }],
			4096,
		);
		await f.ledger.select(input.attemptId, input.members);
		await f.host.enqueue(input, async () => true);
		const entered = deferred(),
			release = deferred();
		const maintenance = f.host.atQueueMaintenance(async () => {
			entered.resolve();
			await release.promise;
		});
		await entered.promise;
		try {
			assert.doesNotThrow(() => f.host.invalidate());
			assert.equal(f.session.agent.inspectQueuedMessages().length, 1);
			await f.host.reconcile(input.attemptId);
			assert.equal((await f.ledger.snapshot()).activeAttemptId, input.attemptId);
		} finally {
			release.resolve();
			await maintenance;
		}
		if (resume === "claim") await f.host.run();
		await f.host.reconcile(input.attemptId);
		assert.equal(f.session.agent.inspectQueuedMessages().length, 0);
		assert.equal((await f.ledger.snapshot()).attempts[0].phase, "cancelled");
		assert.deepEqual(f.calls, []);
	})"

"test("Pi multiloop adapter holds three continuations and accounts once at native consumption", async (t) => {
	let adapter,
		admitted = 0,
		builds = 0;
	const f = await fixture(t, true, { consumedAttempt: (attempt) => adapter.admitted(attempt) });
	const work = await f.attachment.waits.registerWork("campaign", "multiloop", Date.now());
	const lane = { lane: "work", runTag: "run" };
	adapter = new MultiloopFlowProducer(
		f.attachment,
		async () => work,
		() => work.id,
		() => {},
	);
	afterCleanup(t, () => adapter.close());
	f.controller.register(adapter);
	const input = {
		lane,
		reason: "continue",
		build() {
			builds++;
			return "Resume the campaign";
		},
		admitted() {
			admitted++;
		},
	};
	f.policy.waitingWorkIds = [work.id];
	for (let i = 0; i < 3; i++) {
		adapter.submit(input);
		await f.controller.wake();
	}
	assert.deepEqual(f.calls, []);
	assert.equal(builds, 0);
	assert.equal(admitted, 0);
	assert.equal((await adapter.snapshot(new AbortController().signal)).length, 1);
	f.policy.waitingWorkIds = [];
	await f.controller.wake();
	assert.equal(f.calls.length, 1);
	assert.equal(builds, 1);
	assert.equal(admitted, 1);
	await f.controller.wake();
	assert.equal(f.calls.length, 1);
	adapter.submit(input);
	await f.controller.wake();
	assert.equal(f.calls.length, 2);
	assert.equal(admitted, 2);
	adapter.lanesChanged([]);
	await f.controller.wake();
	assert.equal(f.calls.length, 2);
})"

"test(`multiloop continuation submitted before settlement advances: early snapshot=${earlySnapshot}`, async (t) => {
		let adapter,
			submitted = false;
		const f = await fixture(t, true, {
			consumedAttempt: (attempt) => adapter.admitted(attempt),
			extensions: [
				{
					name: "next-loop-continuation",
					factory(pi) {
						pi.on("agent_end", async () => {
							if (submitted) return;
							submitted = true;
							adapter.submit(input);
							// History retention can inspect descriptors before the controller settles this turn.
							if (earlySnapshot) await f.controller.retentionReferences();
						});
					},
				},
			],
		});
		const work = await f.attachment.waits.registerWork("campaign", "multiloop", Date.now());
		const lane = { lane: "work", runTag: "run" };
		let admitted = 0;
		const input = { lane, reason: "continue", build: () => "Continue campaign", admitted: () => admitted++ };
		adapter = new MultiloopFlowProducer(
			f.attachment,
			async () => work,
			() => work.id,
			() => {},
		);
		afterCleanup(t, () => adapter.close());
		f.controller.register(adapter);
		await f.session.bindExtensions({
			onError: (error) => {
				throw error;
			},
		});
		adapter.submit(input);
		await f.controller.wake();
		assert.equal(f.calls.length, 2, "the next continuation runs without another external wake");
		assert.equal(admitted, 2);
		assert.equal(adapter.retained(lane), false);
		assert.deepEqual(
			(await f.ledger.snapshot()).attempts.map((attempt) => attempt.admission.choice.intent.revision),
			["1", "2"],
		);
		await f.controller.wake();
		assert.equal(f.calls.length, 2, "consumed continuations do not replay");
		await f.ledger.retire(0);
		adapter.submit(input);
		const [next] = await adapter.snapshot(new AbortController().signal);
		assert.equal(next.revision, "3", "successful retirement preserves numbering");
		await f.controller.wake();
		assert.equal(f.calls.length, 3);
	})"

"test("an early observed multiloop successor stays blocked after predecessor failure and retirement", async (t) => {
	let adapter;
	const f = await fixture(t, true, {
		fetch: async () => new Response("unavailable", { status: 400 }),
		consumedAttempt: (attempt) => adapter.admitted(attempt),
		extensions: [
			{
				name: "observe-before-failure-settlement",
				factory(pi) {
					pi.on("agent_end", async () => {
						adapter.submit(input);
						await f.controller.retentionReferences();
					});
				},
			},
		],
	});
	const work = await f.attachment.waits.registerWork("campaign", "multiloop", Date.now());
	const input = { lane: { lane: "work", runTag: "run" }, reason: "continue", build: () => "Continue", admitted() {} };
	adapter = new MultiloopFlowProducer(
		f.attachment,
		async () => work,
		() => work.id,
		() => {},
	);
	afterCleanup(t, () => adapter.close());
	f.controller.register(adapter);
	await f.session.bindExtensions({
		onError: (error) => {
			throw error;
		},
	});
	adapter.submit(input);
	await f.controller.wake();
	const snapshot = () => adapter.snapshot(new AbortController().signal);
	assert.equal((await f.ledger.snapshot()).attempts[0].outcome, "failure");
	// A pending successor keeps the failed predecessor's identity until a success advances it,
	// so the failure receipt fences it instead of pinning a reservation above the failure.
	assert.equal((await snapshot())[0].revision, "1");
	assert.equal((await snapshot())[0].runnable, false);
	await f.ledger.retire(0);
	assert.equal((await f.ledger.snapshot()).attempts.length, 0, "the failure is represented by retired receipts");
	assert.equal((await snapshot())[0].revision, "1", "retirement preserves the failed identity");
	assert.equal((await snapshot())[0].runnable, false, "retirement cannot authorize the fenced successor");
	await f.controller.wake();
	assert.equal((await f.ledger.snapshot()).attempts.length, 0);
})"

"test("a retained multiloop continuation with a consumed identity exposes a recoverable hold", async (t) => {
	const f = await fixture(t, true);
	const work = await f.attachment.waits.registerWork("campaign", "multiloop", Date.now());
	const lane = { lane: "work", runTag: "run" };
	const adapter = new MultiloopFlowProducer(
		f.attachment,
		async () => work,
		() => work.id,
		() => {},
	);
	afterCleanup(t, () => adapter.close());
	const registration = f.controller.register(adapter);
	const input = { lane, reason: "continue", build: () => "Continue", admitted() {} };
	// Omit the consumption callback to model a retained entry whose identity has already run.
	adapter.submit(input);
	await f.controller.wake();
	assert.equal(adapter.retained(lane), true);
	assert.equal(f.calls.length, 1);
	assert.match(f.controller.view().held[0].reason, /reuses consumed input.*Resume the loop/);
	adapter.submit(input);
	await registration.changed();
	assert.equal(f.calls.length, 2, "an explicit replacement obtains a fresh revision");
})"

"test("a synthetic second producer drives one owner-scoped binding campaign through the shared controller", async (t) => {
	const f = await fixture(t, true, {});
	const binding = { producer: "sweep", key: ["nightly", "scan"] };
	const campaign = await f.attachment.waits.activateWorkBinding(binding, Date.now(), ["bg"]);
	assert.deepEqual(campaign.participants, ["sweep", "bg"], "a bound campaign shares work like a lane campaign");
	const handle = { producer: "sweep", handle: "scan", execution: "exec-1" };
	await f.attachment.waits.registerExecution(
		{ ...handle, workId: campaign.id, revision: 1, predicates: [{ until: "done", state: "pending" }] },
		campaign.revision,
		Date.now(),
	);
	await f.attachment.waits.declareOwned(
		"sweep",
		campaign.revision,
		{
			scope: f.ledger.scope,
			workId: campaign.id,
			token: "sweep-wait",
			reason: "scan done",
			mode: "all",
			on: [{ ...handle, until: "done" }],
			expiresAt: Date.now() + 60000,
		},
		Date.now(),
		60000,
	);
	let builds = 0;
	const sweep = {
		version: 1,
		namespace: "sweep",
		async snapshot() {
			const work = f.attachment.waits.boundWork(binding);
			return work
				? [
						{
							id: `sweep:${work.id}`,
							revision: "1",
							producer: "sweep",
							sequence: 0,
							rank: 4,
							workId: work.id,
							workRevision: `${work.revision}:1`,
							independent: false,
							runnable: (work.lifecycle?.state ?? "active") === "active",
						},
					]
				: [];
		},
		async build(intent) {
			builds++;
			return { id: intent.id, revision: intent.revision, kind: "work", text: "Continue the nightly sweep" };
		},
	};
	f.controller.register(sweep);
	f.policy.waitingWorkIds = [campaign.id];
	await f.controller.wake();
	assert.deepEqual(f.calls, [], "a live wait holds the campaign's intent");
	assert.equal(builds, 0);
	f.policy.waitingWorkIds = [];
	await f.controller.wake();
	assert.deepEqual(f.calls, [`sweep:${campaign.id}`]);
	assert.equal(builds, 1);
	await f.controller.wake();
	assert.equal(builds, 1, "a settled descriptor revision does not replay");
	// Stopping the campaign ends the binding, so the producer withdraws its intent for good.
	await f.attachment.waits.changeWork(campaign.id, "sweep", campaign.revision, "stopped", "operator stop", Date.now());
	assert.equal(f.attachment.waits.boundWork(binding), undefined);
	await f.controller.wake();
	assert.equal(builds, 1);
	assert.equal((await f.ledger.snapshot()).attempts.length, 1);
})"

