	await f.session.prompt("/goal stop missing/run");
	assert.match(notices.at(-1).text, /Could not select a goal/);
	assert.equal(f.bodies.length, 0);
	assert.deepEqual(f.errors, []);
})"

"test("goal commands filter measured runs and hand ambiguous resume requests to the agent", async (t) => {
	const f = await assembledSession(t, {
		producerExtensions: await installedProducerExtensions({
			freshMultiloop: true,
		}),
	});
	f.ingress.pauseAutomated("Hold dispatch");
	const notices = capturedNotices(f.session);
	await f.session.prompt("/goal Finish the first objective");
	const target = notices.find((n) => n.text.startsWith("Goal started:"))?.text.match(/Goal started: (\S+)/)?.[1];
	await f.session.prompt("/goal clear");
	const registryPath = join(f.root, ".multiloop/registry.json");
	const registry = JSON.parse(await readFile(registryPath, "utf8"));
	const original = JSON.parse(await readFile(join(f.root, ".multiloop/active", target, "state.json"), "utf8"));
	for (const [lane, kind] of [
		["measured", "measured"],
		["second", "goal"],
	]) {
		const dir = join(f.root, ".multiloop/active", lane, original.runTag);
		await mkdir(dir, { recursive: true });
		await writeFile(join(dir, "state.json"), JSON.stringify({ ...original, lane, kind, goal: `${lane} objective` }));
		registry.loops.push({ ...registry.loops[0], lane });
	}
	await writeFile(registryPath, JSON.stringify(registry));
	await f.session.prompt("/goal");
	assert.match(notices.at(-1).text, /second objective/);
	assert.doesNotMatch(notices.at(-1).text, /measured objective/);
	assert.match(notices.at(-1).text, /Other runs hidden: 1/);
	await f.session.prompt("/goal resume");
	assert.match(notices.at(-1).text, /Finding the goal to resume/);
	await f.session.waitForIdle();
	for (const operation of ["resume", "pause", "stop"]) {
		await f.session.prompt(`/goal ${operation} measured/${original.runTag}`);
		assert.match(
			notices.at(-1).text,
			operation === "resume" ? /Finding the goal to resume/ : /Could not select a goal/,
		);
		await f.session.waitForIdle();
	}
	const measured = JSON.parse(
		await readFile(join(f.root, ".multiloop/active/measured", original.runTag, "state.json"), "utf8"),
	);
	assert.equal(measured.status, original.status);
	assert.deepEqual(f.errors, []);
})"

"test(`goal resume uses normal delivery: multiple=${multiple}, busy=${busy}`, {
			timeout: 15000,
		}, async (t) => {
			const { assistantToolCalls, deferred } = await import("../../../scripts/fixtures/pi-flow-session.mjs");
			const started = deferred();
			const release = deferred();
			const done = deferred();
			let target;
			let request = 0;
			const f = await assembledSession(t, {
				producerExtensions: await installedProducerExtensions({
					freshMultiloop: true,
				}),
				script: async () => {
					if (busy && request++ === 0) {
						started.resolve();
						await release.promise;
						return { text: "Previous work finished" };
					}
					const index = busy ? request - 2 : request++;
					if (multiple && index === 0)
						return assistantToolCalls({
							name: "multiloop_resume",
							arguments: { target },
						});
					if (index === (multiple ? 1 : 0))
						return assistantToolCalls({
							name: "multiloop_stop",
							arguments: { target },
						});
					done.resolve();
					return { text: "Goal handled" };
				},
			});
			let preparing = true;
			const host = f.ingress.branch().host;
			const gate = host.gate.bind(host);
			t.mock.method(host, "gate", () => ({
				...gate(),
				automatedPaused: preparing,
			}));
			const notices = capturedNotices(f.session);
			await f.session.prompt("/goal Finish the intended objective");
			target = notices.find((n) => n.text.startsWith("Goal started:"))?.text.match(/Goal started: (\S+)/)?.[1];
			assert.ok(target);
			await f.session.prompt("/goal pause");
			if (multiple) {
				const registryPath = join(f.root, ".multiloop/registry.json");
				const registry = JSON.parse(await readFile(registryPath, "utf8"));
				const original = JSON.parse(await readFile(join(f.root, ".multiloop/active", target, "state.json"), "utf8"));
				const dir = join(f.root, ".multiloop/active/another", original.runTag);
				await mkdir(dir, { recursive: true });
				await writeFile(
					join(dir, "state.json"),
					JSON.stringify({
						...original,
						lane: "another",
						goal: "Another objective",
					}),
				);
				registry.loops.push({ ...registry.loops[0], lane: "another" });
				await writeFile(registryPath, JSON.stringify(registry));
			}
			preparing = false;
			const previous = busy ? f.session.prompt("Finish this message first") : undefined;
			if (busy) await started.promise;
			await f.session.prompt("/goal resume");
			if (busy) {
				assert.equal(f.bodies.length, 1, "resume waits for the active turn");
				release.resolve();
				await previous;
			}
			await done.promise;
			await f.session.waitForIdle();
			assert.equal(
				notices.some((notice) => /Finding the goal/.test(notice.text)),
				multiple,
			);
			const prompt = JSON.stringify(f.bodies[busy ? 1 : 0]);
			assert.match(prompt, multiple ? /Resume the user.s saved goal/ : /Resume the selected goal/);
			if (multiple) {
				assert.match(prompt, /Another objective/);
				assert.match(prompt, /Finish the intended objective/);
			}
			assert.ok(prompt.includes(target));
			assert.deepEqual(f.errors, []);
		})"

"test(`${api} payload copies retain live cancellation and isolate request data`, () => {
		const controller = new AbortController();
		const payload = {
			model: "gemini-2.5-flash",
			contents: [{ role: "user", parts: [{ text: "Hello" }] }],
			config: { abortSignal: controller.signal, temperature: 0 },
		};
		const first = copyFlowPayload(payload, api);
		const second = copyFlowPayload(first.owned, api);
		assert.equal(first.serialized, second.serialized);
		assert.equal(JSON.parse(first.serialized).config.abortSignal, undefined);
		assert.equal(second.owned.config.abortSignal, controller.signal);
		second.owned.contents[0].parts[0].text = "Changed";
		assert.equal(payload.contents[0].parts[0].text, "Hello");
		assert.equal(first.owned.contents[0].parts[0].text, "Hello");
		controller.abort("stop");
		assert.equal(second.owned.config.abortSignal.aborted, true);
		assert.equal(second.owned.config.abortSignal.reason, "stop");
	})"

"test("Google cancellation rejects fake signals and transforming parameter objects", () => {
	for (const abortSignal of [{}, Object.create(AbortSignal.prototype), new Proxy(new AbortController().signal, {})])
		assert.throws(() => copyFlowPayload({ config: { abortSignal } }, "google-generative-ai"), /cancellation signal/);
	assert.throws(
		() =>
			copyFlowPayload({ config: { abortSignal: new AbortController().signal }, toJSON: () => ({}) }, "google-vertex"),
		/unsupported runtime values/,
	);
})"

"test(`Google SDK transport through native admission ${cancel ? "receives cancellation" : "completes"}`, async (t) => {
		const model = { ...fixtureModel, api: "google-generative-ai", provider: "google", id: "gemini-2.5-flash" };
		const controller = new AbortController();
		let sent = 0;
		t.mock.method(globalThis, "fetch", async (_url, init) => {
			sent++;
			const body = JSON.parse(init.body);
			assert.equal(body.contents[0].parts[0].text, "Hello");
			assert.equal(body.abortSignal, undefined);
			assert.equal(typeof init.signal.addEventListener, "function");
			if (cancel) {
				return new Promise((_resolve, reject) => {
					init.signal.addEventListener("abort", () => reject(init.signal.reason), { once: true });
					controller.abort(new DOMException("Stopped", "AbortError"));
				});
			}
			return new Response(
				`data: ${JSON.stringify({ candidates: [{ content: { role: "model", parts: [{ text: "Done" }] }, finishReason: "STOP" }] })}\n\n`,
				{ headers: { "Content-Type": "text/event-stream" } },
			);
		});
		const f = await nativeRequests(t, {
			model,
			native: (selected, context, options) =>
				stream(selected, context, { ...options, apiKey: "fixture", signal: controller.signal, maxRetries: 0 }),
		});
		await f.session.prompt("Hello");
		assert.equal(sent, 1);
		assert.equal((await f.store.snapshot())[0].outcome, cancel ? "aborted" : "success");
	})"

"test("174 MiB history verifies in one batch and subsequent host writes scan only the new suffix", async (t) => {
	const { manager, first, path } = await fixture(t);
	const payload = "x".repeat(60 * 1024);
	let last;
	for (let i = 0; i < 3000; i++) last = manager.appendCustomEntry("bounded-state", { payload, i });
	const size = (await stat(path)).size;
	assert.ok(size > 174 * 1024 * 1024);
	const proofs = await verifyPiHistoryEntries(manager, [first, last]);
	assert.equal(proofs.get(first).kind, "persisted");
	assert.equal(proofs.get(last).kind, "persisted");
	assert.equal(piHistoryVerificationStats(manager).scannedBytes, size);
	assert.equal(piHistoryVerificationStats(manager).scans, 1);
	for (let i = 0; i < 100; i++) {
		const id = manager.appendCustomEntry("small", { i });
		assert.equal((await verifyPiHistoryEntry(manager, id)).kind, "persisted");
	}
	const finalSize = (await stat(path)).size;
	assert.equal(piHistoryVerificationStats(manager).scannedBytes, finalSize);
	assert.equal((await verifyPiHistoryEntry(manager, first)).kind, "persisted");
	assert.equal(piHistoryVerificationStats(manager).scannedBytes, finalSize);
	assert.ok(piHistoryVerificationStats(manager).targetBytes > 0);
	const reopened = SessionManager.open(path);
	assert.equal((await verifyPiHistoryEntry(reopened, first)).kind, "persisted");
	assert.equal(piHistoryVerificationStats(reopened).scannedBytes, finalSize);
})"

"test(`a warm index rejects external ${corruption} before and after a host append`, async (t) => {
		for (const hostAppend of [false, true]) {
			const { manager, first, path } = await fixture(t);
			await verifyPiHistoryEntry(manager, first);
			const original = await readFile(path, "utf8");
			if (corruption === "changed") await writeFile(path, original.replace('"first"', '"other"'));
			if (corruption === "duplicate") await appendFile(path, `${JSON.stringify(manager.getEntry(first))}\n`);
			if (corruption === "malformed") await appendFile(path, "{broken}\n");
			if (corruption === "utf8") await appendFile(path, Buffer.from([0xff, 10]));
			if (corruption === "header") await writeFile(path, original.replace(manager.getSessionId(), "foreign"));
			if (hostAppend) manager.appendCustomEntry("after-external-change", {});
			await assert.rejects(verifyPiHistoryEntry(manager, first), /differs|repeated|invalid/);
			assert.equal(piHistoryVerificationStats(manager).indexedEntries, 0);
		}
	})"

