"test("installed multiloop gate-change upgrade replaces only the pinned preceding source", async (t) => {
	const installed = join(packageRoot, "extensions/pi-multiloop/index.ts");
	const source = await readFile(installed, "utf8");
	const previous = multiloopPredecessors(source).previousAfter;
	const lock = JSON.parse(await readFile(join(root, "upstream/multiloop-wait-skill/patch.lock.json"), "utf8"));
	assert.equal(sha256(previous), lock.extension.previousAfter);
	const target = await mkdtemp(join(root, "packages/cli/node_modules/.jouzu-loop-upgrade-"));
	t.after(() => rm(target, { recursive: true, force: true }));
	await mkdir(join(target, "extensions/pi-multiloop"), { recursive: true });
	await writeFile(join(target, "package.json"), JSON.stringify({ name: "pi-multiloop", version: lock.version }));
	for (const path of [
		"skills/multiloop/SKILL.md",
		"extensions/pi-multiloop/index.ts",
		"extensions/pi-multiloop/lanes.ts",
		"extensions/pi-multiloop/jouzu-flow.ts",
	]) {
		await mkdir(join(target, path, ".."), { recursive: true });
		await writeFile(join(target, path), await readFile(join(packageRoot, path)));
	}
	await writeFile(join(target, "extensions/pi-multiloop/index.ts"), previous);
	await applyMultiloopWaitSkill(target);
	assert.equal(await readFile(join(target, "extensions/pi-multiloop/index.ts"), "utf8"), source);
	assert.equal(await applyMultiloopWaitSkill(target, true), 0);
	const preceding = source.replace("      if (flow.retained?.(lane)) continue;\n", "");
	assert.equal(sha256(preceding), lock.extension.retainedPreviousAfter);
	await writeFile(join(target, "extensions/pi-multiloop/index.ts"), preceding);
	await assert.rejects(applyMultiloopWaitSkill(target, true), /hash differs/);
	assert.equal(await applyMultiloopWaitSkill(target), 1);
	assert.equal(await readFile(join(target, "extensions/pi-multiloop/index.ts"), "utf8"), source);
	assert.equal(await applyMultiloopWaitSkill(target, true), 0);
})"

"test(`a goal advances after a pre-settlement retention snapshot: compaction=${compact}`, {
		timeout: 15000,
	}, async (t) => {
		let f;
		let notices;
		let firstEnd = true;
		let observedPhase;
		let compactions = 0;
		const done = deferred();
		f = await assembledSession(t, {
			persist: true,
			settings: { compaction: { enabled: false, keepRecentTokens: 1 } },
			producerExtensions: [
				...(await installedProducerExtensions({ freshMultiloop: true })),
				{
					name: "continuation-retention-order",
					factory(pi) {
						registerCompactionRequest(pi);
						pi.on("session_before_compact", (event) => {
							compactions++;
							return {
								compaction: {
									summary: "The goal is unfinished. Continue the next unit.",
									firstKeptEntryId: event.preparation.firstKeptEntryId,
									tokensBefore: event.preparation.tokensBefore,
								},
							};
						});
						pi.on("agent_end", async () => {
							if (!firstEnd) return;
							firstEnd = false;
							const branch = f.ingress.branch();
							const state = await branch.attachment.ledger.snapshot();
							observedPhase = state.attempts.find((attempt) => attempt.id === state.activeAttemptId)?.phase;
							// The installed loop has submitted its successor, but the host has not settled
							// its current attempt. Retention reads must not freeze the successor's revision.
							await branch.controller.retentionReferences();
						});
					},
				},
			],
			script: (_body, index) => {
				const target = notices
					.find((notice) => notice.text.startsWith("Goal started:"))
					?.text.match(/Goal started: (\S+)/)?.[1];
				assert.ok(target, "the fixture uses the goal identity returned by the installed extension");
				if (index === 0 || index === 2) {
					const calls = [
						{
							name: "multiloop_log",
							arguments: {
								lane: target.split("/")[0],
								action: "log",
								note: `Unit ${index} finished; more remains.`,
							},
						},
					];
					if (compact && index === 0) calls.push({ name: "compact_context", arguments: {} });
					return assistantToolCalls(...calls);
				}
				if (index === 1 || index === 3) return { text: "This unit is finished; the goal remains open." };
				if (index === 4)
					return assistantToolCalls({
						name: "multiloop_stop",
						arguments: { target },
					});
				done.resolve();
				return { text: "Fixture stopped." };
			},
		});
		notices = capturedNotices(f.session);
		await f.session.prompt("/goal Finish the continuation fixture");
		await done.promise;
		await f.session.waitForIdle();
		await f.ingress.joinPendingOperations();
		assert.equal(observedPhase, "running");
		assert.equal(compactions, compact ? 1 : 0);
		assert.equal(f.bodies.length, 6, "successive goal turns run without user input or an explicit wake");
		const results = f.sessionManager
			.getEntries()
			.filter((entry) => entry.type === "message" && entry.message.role === "toolResult")
			.map((entry) => entry.message);
		assert.ok(
			results.every((result) => !result.isError),
			JSON.stringify(results),
		);
		const logs = results.filter((result) => result.toolName === "multiloop_log");
		assert.equal(logs.length, 2);
		assert.ok(logs.every((result) => /Recorded log iteration/.test(JSON.stringify(result.content))));
		const attempts = (await f.ingress.branch().attachment.ledger.snapshot()).attempts;
		const loops = attempts.filter((attempt) => attempt.admission?.choice.intent.producer === "multiloop");
		assert.ok(loops.length >= 2, "compaction cannot be the only continuation after the first goal turn");
		assert.ok(attempts.every((attempt) => attempt.outcome === "success"));
		assert.deepEqual(
			loops.map((attempt) => attempt.admission.choice.intent.revision),
			loops.map((_, index) => String(index + 1)),
		);
		assert.match(JSON.stringify(f.bodies[4]), /Continue the active quick goal/);
		assert.deepEqual(f.errors, []);
	})"

"test("a notification-only acknowledgement does not strand the attached goal", { timeout: 15_000 }, async (t) => {
	const records = [];
	const errors = [];
	const inbox = { current: undefined };
	const acknowledged = { result: undefined, error: undefined };
	const notificationRequests = [];
	const unexpected = [];
	let observed;
	const done = deferred();
	let flow;
	let notices;
	let goalTarget;

	flow = await assembledSession(t, {
		producerExtensions: [
			...(await installedProducerExtensions({ freshMultiloop: true })),
			{
				name: "fixture-retention-order",
				factory(pi) {
					let firstEnd = true;
					pi.on("agent_end", async () => {
						if (!firstEnd) return;
						firstEnd = false;
						const branch = flow.ingress.branch();
						const state = await branch.attachment.ledger.snapshot();
						const attempt = state.attempts.find((item) => item.id === state.activeAttemptId);
						observed = {
							phase: attempt?.phase,
							producer: attempt?.admission?.choice.intent.producer,
							revision: attempt?.admission?.choice.intent.revision,
						};
						// The installed loop has submitted its successor, but the host has not settled
						// its current attempt. Retention reads must not freeze the successor's revision.
						await branch.controller.retentionReferences();
					});
				},
			},
			{
				name: "fixture-notification",
				factory(pi) {
					const created = createNotificationInbox({
						pi,
						customType: "fixture-notification",
						records: () => records,
						save: (id, change) =>
							Object.assign(
								records.find((record) => record.id === id),
								change,
							),
						observed: () => new Set(),
						build: (batchId) => ({ content: `Notification ${batchId}`, display: true, details: {} }),
						reportError: (error) => errors.push(error),
					});
					inbox.current = created;
					pi.on("session_start", (_event, ctx) => created.start(ctx));
					pi.registerTool({
						name: "ack_notification",
						label: "Acknowledge notification",
						description: "Acknowledge the notification batch delivered in this run.",
						parameters: {
							type: "object",
							properties: { batchId: { type: "string" } },
							required: ["batchId"],
						},
						execute: async (_id, params) => {
							try {
								acknowledged.result = created.acknowledge(params.batchId);
							} catch (error) {
								acknowledged.error = error;
							}
							return acknowledged.result ?? { content: [{ type: "text", text: "Acknowledgement failed." }] };
						},
					});
				},
			},
		],
		script: (body, index) => {
			const last = text(body.messages.at(-1));
			const target = notices
				.find((notice) => notice.text.startsWith("Goal started:"))
				?.text.match(/Goal started: (\S+)/)?.[1];
			assert.ok(target, "the fixture uses the goal identity returned by the installed extension");
			goalTarget = target;
			if (index === 0) {
				// The goal's first continuation is running; a notification arrives during that turn.
				records.push({ id: "run-1", revision: "terminal-1", handled: false });
				inbox.current.request();
				return assistantToolCalls({
					name: "multiloop_log",
					arguments: {
						lane: target.split("/")[0],
						action: "log",
						note: `Unit ${index} finished; more remains.`,
					},
				});
			}
			if (index === 1 || index === 4) return { text: "This unit is finished; the goal remains open." };
			if (index === 2) {
				const batch = last.match(/^Notification ([0-9a-f-]{36})$/)?.[1];
				if (batch) {
					notificationRequests.push(index);
					return assistantToolCalls({ name: "ack_notification", arguments: { batchId: batch } });
				}
			}
			if (index === 3) {
				return assistantToolCalls({
					name: "multiloop_log",
					arguments: {
						lane: target.split("/")[0],
						action: "log",
						note: `Unit ${index} finished; more remains.`,
					},
				});
			}
			if (index === 5) return assistantToolCalls({ name: "multiloop_stop", arguments: { target } });
			if (index === 6) {
				done.resolve();
				return { text: "Fixture stopped." };
			}
			unexpected.push({ index, last: last.slice(0, 160) });
			return { text: "Unexpected request." };
		},
	});
	notices = capturedNotices(flow.session);

	await flow.session.prompt("/goal Finish the notification campaign");
	// Pre-fix the successor is pinned to its predecessor's revision and filtered, so the loop
	// never reaches its stop turn and this barrier times out instead of advancing.
	await done.promise;
	await flow.session.waitForIdle();
	await flow.ingress.joinPendingOperations();

	assert.deepEqual(observed, { phase: "running", producer: "multiloop", revision: "1" });
	assert.equal(acknowledged.error, undefined);
	assert.equal(acknowledged.result?.terminate, true, "the production inbox acknowledgement ends that turn");
	assert.equal(records[0].handled, true, "the acknowledged notification is marked handled");
	assert.deepEqual(notificationRequests, [2], "the notification is delivered in its own turn");
	assert.equal(flow.bodies.length, 7, "the goal advances through two continuations and an explicit stop");
	const attempts = (await flow.ingress.branch().attachment.ledger.snapshot()).attempts;
	const loops = attempts.filter((attempt) => attempt.admission?.choice.intent.producer === "multiloop");
	assert.deepEqual(
		loops.map((attempt) => attempt.admission.choice.intent.revision),
		["1", "2", "3"],
		"the continuation after the acknowledged notification keeps the next revision",
	);
	assert.ok(loops.every((attempt) => attempt.phase === "settled" && attempt.outcome === "success"));
	const resumed = JSON.parse(text(flow.bodies[3].messages.at(-1)));
	assert.equal(resumed.kind, "work");
	assert.match(resumed.content, /Continue the active quick goal/);
	assert.ok(resumed.content.includes(goalTarget));
	const results = flow.sessionManager
		.getEntries()
		.filter((entry) => entry.type === "message" && entry.message.role === "toolResult")
		.map((entry) => entry.message);
	assert.ok(
		results.every((result) => !result.isError),
		JSON.stringify(results),
	);
	const logs = results.filter((result) => result.toolName === "multiloop_log");
	assert.equal(logs.length, 2);
	assert.ok(logs.every((result) => /Recorded log iteration/.test(JSON.stringify(result.content))));
	const notificationTurn = flow.session.messages.find(
		(message) => message.role === "custom" && message.customType === "fixture-notification",
	);
	const notificationReply = flow.session.messages[flow.session.messages.indexOf(notificationTurn) + 1];
	assert.equal(
		notificationReply?.content.some((part) => part.type === "text"),
		false,
		"the acknowledgement turn produces no assistant reply",
	);
	assert.equal(
		notificationReply?.content.some((part) => part.type === "toolCall" && part.name === "ack_notification"),
		true,
	);
	assert.deepEqual(unexpected, []);
	assert.deepEqual(errors, []);
	assert.deepEqual(flow.errors, []);
})"

"test(`installed goal continues after pre-settlement retention read: early snapshot=${earlySnapshot}`, {
		timeout: 15000,
	}, async (t) => {
		let f;
		const done = deferred();
		const inspect = {
			name: "inspect-next-continuation",
			factory(pi) {
				pi.on("agent_end", async () => {
					if (earlySnapshot) await f.ingress.branch().controller.retentionReferences();
					if (f.bodies.length === 4) done.resolve();
				});
			},
		};
		f = await assembledSession(t, {
			producerExtensions: [...(await installedProducerExtensions({ freshMultiloop: true })), inspect],
			script: (_body, index) => {
				if (index === 0) return assistantToolCalls({ name: "get_goal", arguments: {} });
				if (index === 2) return assistantToolCalls({ name: "update_goal", arguments: { status: "complete" } });
				return { text: "Goal turn finished" };
			},
		});
		await f.session.prompt("/goal Verify automatic continuation");
		await done.promise;
		await f.session.waitForIdle();
		assert.equal(f.bodies.length, 4, "the installed goal advances and completes without user input");
		const completed = f.session.messages.findLast(
			(message) => message.role === "toolResult" && message.toolName === "update_goal",
		);
		assert.ok(completed);
		assert.match(JSON.stringify(completed.content), /marked complete/);
		assert.deepEqual(f.errors, []);
	})"

"test(`a reopened session resumes a detached loop without continue: command=${command}, disambiguate=${disambiguate}`, {
			timeout: 15000,
		}, async (t) => {
			const first = await assembledSession(t, {
				persist: true,
				producerExtensions: await installedProducerExtensions({
					freshMultiloop: true,
				}),
			});
			first.ingress.pauseAutomated("Hold setup until restart");
			const notices = capturedNotices(first.session);
			await first.session.prompt("/goal Finish the persisted campaign");
			const target = notices
				.find((notice) => notice.text.startsWith("Goal started:"))
				?.text.match(/Goal started: (\S+)/)?.[1];
			assert.ok(target);
			assert.equal(first.bodies.length, 0);
			const history = first.sessionManager.getSessionFile();
			await first.shutdown("resume", history);
			const done = deferred();
			const second = await assembledSession(t, {
				root: first.root,
				persist: true,
				sessionManager: SessionManager.open(history),
				producerExtensions: await installedProducerExtensions({
					freshMultiloop: true,
				}),
				script: (_body, index) => {
					if (disambiguate && index === 0)
						return assistantToolCalls({
							name: "multiloop_resume",
							arguments: { target },
						});
					if (index === (disambiguate ? 1 : 0))
						return assistantToolCalls({
							name: "multiloop_stop",
							arguments: { target },
						});
					done.resolve();
					return { text: "Campaign handled" };
				},
			});
			const resumedNotices = capturedNotices(second.session);
			await second.session.prompt(
				`/${command} resume ${disambiguate ? "<lane/run-tag>" : command === "goal" ? "" : target}`,
			);
			await done.promise;
			await second.session.waitForIdle();
			assert.equal(second.bodies.length, disambiguate ? 3 : 2);
			assert.ok(
				JSON.stringify(second.bodies[0]).includes(disambiguate ? "<lane/run-tag>" : "Finish the persisted campaign"),
			);
			assert.equal(
				resumedNotices.some((notice) => /Could not resolve|Finding the goal/.test(notice.text)),
				disambiguate,
			);
			assert.deepEqual(second.errors, []);
			assert.deepEqual(first.errors, []);
		})"

"test(`a pending multiloop revision advances after settlement: early snapshot=${earlySnapshot}, retire=${retire}`, async (t) => {
			const f = await fixture(t);
			f.submit("first");
			const first = await f.begin("first");
			f.submit("second");
			if (earlySnapshot) {
				const pending = await f.snapshot();
				assert.equal(pending.revision, first.revision);
				assert.equal(f.producer.retained(f.lane), true);
			}
			await f.ledger.settle("first", "success");
			if (retire) assert.equal(await f.ledger.retire(0), 1);
			const next = await f.snapshot();
			assert.equal(next.revision, "2", "an early read must not freeze the predecessor's revision");
			assert.equal(next.runnable, true);
			assert.equal(await f.fenced(next), false);
			assert.equal((await f.producer.build(next, f.signal)).text, "second");
			await assert.rejects(f.producer.build(first, f.signal), { code: "stale" });
			await f.begin("second");
			await f.ledger.settle("second", "success");
			assert.equal((await f.snapshot()).revision, "2", "consumption freezes the revision against replay");
			assert.equal(await f.fenced(await f.snapshot()), true);
			assert.equal(f.producer.retained(f.lane), false);
			assert.deepEqual(f.admitted, ["first", "second"]);
		})"

"test(`a pending multiloop continuation preserves the ${outcome} receipt`, async (t) => {
		const f = await fixture(t);
		f.submit("first");
		await f.begin("first", outcome);
		f.submit("second");
		await f.snapshot();
		await f.ledger.settle("first", outcome);
		const next = await f.snapshot();
		assert.equal(next.revision, "1");
		assert.equal(next.runnable, false);
		assert.equal(await f.fenced(next), true);
		await assert.rejects(f.producer.build(next, f.signal), { code: "stale" });
		assert.equal(await f.ledger.retire(0), 1);
		assert.equal((await f.snapshot()).revision, "1");
		assert.equal(await f.fenced(await f.snapshot()), true, "retirement preserves the failed revision's fence");
		assert.deepEqual(f.admitted, ["first"]);
	})"

"test("an unconsumed cancelled multiloop continuation can reuse its revision", async (t) => {
	const f = await fixture(t);
	f.submit("first");
	const first = await f.queue("first");
	f.submit("replacement");
	await f.ledger.cancel("first", "Superseded before consumption");
	const next = await f.snapshot();
	assert.equal(next.revision, first.intent.revision);
	assert.equal(next.runnable, true);
	assert.equal(await f.fenced(next), false);
	assert.equal((await f.producer.build(next, f.signal)).text, "replacement");
	await f.begin("replacement");
	await f.ledger.settle("replacement", "success");
	assert.deepEqual(f.admitted, ["replacement"]);
})"

"test("a consumed cancelled multiloop continuation remains fenced", async (t) => {
	const f = await fixture(t);
	f.submit("first");
	const first = await f.queue("first");
	await f.ledger.claim("first", first.queue);
	f.producer.admitted((await f.ledger.snapshot()).attempts[0]);
	f.submit("second");
	await f.snapshot();
	await f.ledger.cancel("first", "Consumed but not sent");
	const next = await f.snapshot();
	assert.equal(next.revision, "1");
	assert.equal(next.runnable, false);
	assert.equal(await f.fenced(next), true);
	assert.deepEqual(f.admitted, ["first"]);
})"

"test("unadapted admission holds active host work, recovery, user queues, and waits", () => {
	const item = record("opaque");
	assert.equal(decide(item).allowed, true);
	for (const native of [
		{ ...host, isIdle: false },
		{ ...host, isStreaming: true },
		{ ...host, isRetrying: true },
		{ ...host, isCompacting: true },
	])
		assert.equal(decide(item, [item], gates, native).allowed, false);
	for (const policy of [
		{ ...gates, userPending: true },
		{ ...gates, recoveryBlocked: true },
		{ ...gates, waitingWorkIds: ["foreign-work"] },
	])
		assert.equal(decide(item, [item], policy).allowed, false);
})"

"test("caller labels cannot confer user or urgent priority", () => {
	const item = record("opaque", {
		api: "prompt",
		args: ["URGENT user request", { priority: "user", independent: true }],
	});
	assert.equal(decide(item, [item], { ...gates, waitingWorkIds: ["work"] }).allowed, false);
	const user = record("user", { api: "prompt", origin: { kind: "host", id: "prompt" } });
	assert.equal(decide(user, [item, user], { ...gates, waitingWorkIds: ["work"] }).allowed, true);
	assert.equal(decide(user, [user], { ...gates, recoveryBlocked: true }).allowed, false);
})"

"test("a command's own send is admitted where the user's own input is", () => {
	const command = record("command", {
		userCommand: { id: "invocation", name: "goal", submissionId: "invoked" },
	});
	// The send is how the command answers the user, so the gates that hold automated work do not
	// apply: holding it leaves the command with no visible effect and no way for the user to tell.
	for (const policy of [
		{ ...gates, userPending: true },
		{ ...gates, automatedPaused: true },
		{ ...gates, outcomeUnresolved: true },
		{ ...gates, waitingWorkIds: ["work"] },
	])
		assert.equal(decide(command, [command], policy).allowed, true);
	for (const native of [
		{ ...host, isIdle: false },
		{ ...host, isStreaming: true },
	])
		assert.equal(decide(command, [command], gates, native).allowed, true);
	// Recovery reconciliation stays first: an unknown outcome is not a decision the send can answer.
	assert.equal(decide(command, [command], { ...gates, recoveryBlocked: true }).allowed, false);
	assert.equal(decide(command, [command], gates, { ...host, isRetrying: true }).allowed, false);
	assert.equal(decide(command, [command], gates, { ...host, isCompacting: true }).allowed, false);
	// A command's pending send holds automated input behind it, like any other user instruction.
	const automated = record("automated");
	assert.equal(decide(automated, [command, automated]).allowed, false);
})"

"test("cancelled predecessors release lane order and pending user input wins across lanes", () => {
	const first = record("first"),
		second = record("second");
	assert.equal(decide(second, [first, second]).allowed, false);
	first.status = "cancelled";
	assert.equal(decide(second, [first, second]).allowed, true);
	const user = record("user", { api: "steer", origin: { kind: "host", id: "steer" } });
	assert.equal(decide(second, [second, user]).allowed, false);
	user.dispatch = { phase: "started", promptClaims: [{ inputIndex: 0, messageIndex: 0 }] };
	assert.equal(decide(second, [second, user]).allowed, true);
})"

"test("Pi queue batches preserve native order without blocking on their own preceding member", () => {
	const first = record("first", { api: "followUp" });
	const second = record("second", { api: "followUp" });
	const one = { kind: "followUp", args: ["one"], queue: { id: "one", revision: 1 } };
	const two = { kind: "followUp", args: ["two"], queue: { id: "two", revision: 1 } };
	first.dispatch = { phase: "returned", inputs: [one] };
	second.dispatch = { phase: "returned", inputs: [two] };
	const running = { ...host, isIdle: false, isStreaming: true };
	assert.equal(decide(second, [first, second], gates, running, "queue", two).allowed, true);
	assert.equal(
		decide(second, [first, second], { ...gates, waitingWorkIds: ["work"] }, running, "queue", two).allowed,
		false,
	);
	delete first.dispatch;
	assert.equal(decide(second, [first, second], gates, running, "queue", two).allowed, false);
})"

"test("delivery options cannot split the idle native prompt lane", () => {
	const first = record("first");
	const second = record("second", { args: ["second", { deliverAs: "followUp" }], hostState: { streaming: false } });
	assert.equal(decide(second, [first, second]).allowed, false);
})"

"test("an unresolved outcome holds automated input while verified user input proceeds", () => {
	// The two recovery gates differ in exactly one way: an unresolved outcome never holds the user,
	// because the controls that resolve an interrupted turn arrive as user input. Incomplete
	// reconciliation still holds every origin.
	const automated = record("opaque");
	const user = record("user", { api: "prompt", origin: { kind: "host" } });
	const unresolved = { ...gates, outcomeUnresolved: true };
	const held = decide(automated, [automated], unresolved);
	assert.equal(held.allowed, false);
	assert.match(held.reason, /interrupted turn/);
	assert.equal(decide(user, [user], unresolved).allowed, true);
	assert.equal(decide(user, [user], { ...gates, recoveryBlocked: true }).allowed, false);
	// A caller-supplied label cannot borrow the exemption; origin is host-assigned.
	const labelled = record("labelled", { api: "prompt", origin: { kind: "extension", id: "synthetic" } });
	assert.equal(decide(labelled, [labelled], unresolved).allowed, false);
})"

"test("automated input waits behind a queued user message the host still holds", () => {
	const automated = record("automated");
	const user = queuedUser("user");
	const live = new Set(["queue-user"]);
	// With or without the live-queue evidence, a message the host still holds outranks automation.
	for (const queue of [undefined, live])
		assert.equal(
			reason(
				decideNativeAdmission(automated.submission, [user, automated], gates, host, "submission", undefined, queue),
			),
			"Input is waiting for queued user work.",
		);
})"

"assert.equal(
			reason(
				decideNativeAdmission(automated.submission, [user, automated], gates, host, "submission", undefined, queue),
			),
			"Input is waiting for queued user work.",
		)"

"test("a queued user message the host discarded stops holding automated input", () => {
	const automated = record("automated");
	const user = queuedUser("user");
	// The host no longer holds it and no claim was ever recorded: it was dropped, not delivered.
	// Without this evidence the record reads as pending forever and nothing automated ever runs.
	assert.equal(
		decideNativeAdmission(automated.submission, [user, automated], gates, host, "submission", undefined, new Set())
			.allowed,
		true,
	);
	// A claimed message is already terminal, so it never held anything either way.
	assert.equal(
		decideNativeAdmission(
			automated.submission,
			[queuedUser("user", { claimed: true }), automated],
			gates,
			host,
			"submission",
			undefined,
			new Set(),
		).allowed,
		true,
	);
})"

"test("an undispatched user message holds automated input whatever the queue says", () => {
	// Not yet dispatched means not yet offered to the host, so an empty queue is not evidence of
	// anything. Only a record the host was given and then dropped may stop holding.
	const automated = record("automated");
	const pending = record("pending", { api: "steer", origin: { kind: "host", id: "terminal" }, args: ["typed"] });
	for (const queue of [undefined, new Set()])
		assert.equal(
			reason(
				decideNativeAdmission(automated.submission, [pending, automated], gates, host, "submission", undefined, queue),
			),
			"Input is waiting for queued user work.",
		);
})"

"assert.equal(
			reason(
				decideNativeAdmission(automated.submission, [pending, automated], gates, host, "submission", undefined, queue),
			),
			"Input is waiting for queued user work.",
		)"

"test("user input is admitted regardless of the queue evidence", () => {
	// The user's own input never waits on this gate; only its origin decides that.
	const user = record("typed", { api: "steer", origin: { kind: "host", id: "terminal" }, args: ["typed"] });
	const blocker = queuedUser("other");
	for (const queue of [undefined, new Set(["queue-other"]), new Set()])
		assert.equal(
			decideNativeAdmission(user.submission, [blocker, user], gates, host, "submission", undefined, queue).allowed,
			true,
		);
})"

"test("an interrupt pause holds automated input and never the user's own", () => {
	const automated = record("automated");
	const user = record("typed", { api: "steer", origin: { kind: "host", id: "terminal" }, args: ["typed"] });
	const paused = { ...gates, automatedPaused: true };
	assert.equal(
		reason(decideNativeAdmission(automated.submission, [automated], paused, host, "submission")),
		"Automated input is paused until the next user turn is under way.",
	);
	// The gesture means stop what is happening, not stop the user from speaking.
	assert.equal(decideNativeAdmission(user.submission, [user], paused, host, "submission").allowed, true);
	// And it holds on an idle host, where automated input would otherwise be admitted.
	assert.equal(decideNativeAdmission(automated.submission, [automated], gates, host, "submission").allowed, true);
})"

"test("only an explicit input-free completion releases pending user priority", () => {
	const user = record("user", { api: "prompt", origin: { kind: "host", id: "prompt" } });
	const automated = record("automated");
	for (const phase of ["started", "failed", "returned"]) {
		user.dispatch = { phase };
		assert.equal(decide(automated, [user, automated]).allowed, false);
	}
	user.dispatch = { phase: "returned", noInput: true };
	assert.equal(decide(automated, [user, automated]).allowed, true);
	user.dispatch.inputs = [{ kind: "prompt", args: ["real input"] }];
	assert.equal(decide(automated, [user, automated]).allowed, false);
})"

"test("only a self-contained continuation survives a reattach as replayable", () => {
	const replayable = (overrides) => replayableContinuation(record("replay", overrides).submission);
	// A command's own waking send is the user's instruction, and nothing re-issues it after a restart.
	assert.equal(
		replayable({
			api: "sendUserMessage",
			args: ["Resume the saved goal.", { deliverAs: "followUp" }],
			userCommand: { id: "invocation", name: "resume", submissionId: "invoked" },
		}),
		true,
	);
	assert.equal(replayable({ api: "sendCustomMessage", args: [{ customType: "c" }, { triggerTurn: true }] }), true);
	assert.equal(replayable({ api: "sendUserMessage", args: ["Continue.", { deliverAs: "followUp" }] }), true);
	// Typed input belongs to a user who is present to send it again.
	assert.equal(replayable({ api: "prompt", origin: { kind: "host", id: "prompt" }, args: ["typed"] }), false);
	// A steer belongs to the turn it interrupts, and a non-waking context append carries no turn.
	assert.equal(replayable({ api: "sendUserMessage", args: ["Stop.", { deliverAs: "steer" }] }), false);
	assert.equal(replayable({ api: "sendCustomMessage", args: [{ customType: "c" }, { triggerTurn: false }] }), false);
	// A send a prior lifetime's callback would run is not self-contained.
	assert.equal(
		replayable({
			api: "sendCustomMessage",
			args: [{ customType: "c", details: { waitContextId: "context" } }, { triggerTurn: true }],
		}),
		false,
	);
})"

"assert.equal(
		replayable({
			api: "sendUserMessage",
			args: ["Resume the saved goal.", { deliverAs: "followUp" }],
			userCommand: { id: "invocation", name: "resume", submissionId: "invoked" },
		}),
		true,
	)"

"test("external input is never replayed by a reattach while ordinary continuations still are", () => {
	const external = (overrides) =>
		replayableContinuation(
			record("external", {
				api: "sendUserMessage",
				args: ["Continue.", { deliverAs: "followUp" }],
				externalUser: { version: 1, adapterId: "fixture", messageId: "message" },
				...overrides,
			}).submission,
		);
	assert.equal(
		replayableContinuation(
			record("ordinary", { api: "sendUserMessage", args: ["Continue.", { deliverAs: "followUp" }] }).submission,
		),
		true,
	);
	assert.equal(
		replayableContinuation(
			record("ordinary", {
				api: "sendCustomMessage",
				args: [{ customType: "c" }, { triggerTurn: true }],
			}).submission,
		),
		true,
	);
	// External human input waits for an explicit retry instead of replaying after a restart.
	assert.equal(external(), false);
	assert.equal(external({ api: "sendCustomMessage", args: [{ customType: "c" }, { triggerTurn: true }] }), false);
	assert.equal(external({ api: "prompt", origin: { kind: "host", id: "prompt" }, args: ["typed"] }), false);
	assert.equal(
		external({
			userCommand: { id: "invocation", name: "goal", submissionId: "invoked" },
			args: ["Resume the saved goal.", { deliverAs: "followUp" }],
		}),
		false,
	);
})"

"assert.equal(
		external({
			userCommand: { id: "invocation", name: "goal", submissionId: "invoked" },
			args: ["Resume the saved goal.", { deliverAs: "followUp" }],
		}),
		false,
	)"

"test("only a record whose native call never ran is still issuable", () => {
	assert.equal(undispatchedRecord({}), true);
	assert.equal(undispatchedRecord({ dispatch: { phase: "failed" } }), true);
	assert.equal(undispatchedRecord({ dispatch: { phase: "started" } }), false);
	assert.equal(undispatchedRecord({ dispatch: { phase: "returned" } }), false);
	// A failed dispatch that produced native input may already be in the transcript.
