})"

"test("a request admitted by an older build can settle at the byte limit and reopen", async (t) => {
	const f = await fullStore(t);
	assert.equal(await f.store.handoff("pending", payload), true);
	await f.store.finish("pending", "success");
	assert.ok(bytes(await f.store.snapshot()) > limit);
	const next = await replacedSession(t, f, { reason: "resume", persist: true, sessionManager: f.sessionManager });
	await next.session.prompt("/flow");
	const store = next.ingress.branch().attachment.nativeRequests;
	await store.retireHistory();
	assert.ok(bytes(await store.snapshot()) <= limit / 2);
	await next.session.prompt("Continue after settlement.");
	assert.equal(next.bodies.length, 1, next.session.agent.state.errorMessage);
})"

"test("/flow clear recovers a full legacy store without inventing an outcome or losing history", async (t) => {
	const f = await fullStore(t);
	const notices = capturedNotices(f.session);
	await f.session.prompt("/flow clear");
	assert.equal(f.store.recoveryBlocked, false, JSON.stringify(notices));
	assert.equal(f.bodies.length, 0);
	await f.session.prompt("Continue after clearing the hold.");
	assert.equal(f.bodies.length, 1, f.session.agent.state.errorMessage);
	const requests = await f.store.snapshot();
	const pending =
		requests.find((r) => r.id === "pending") ??
		(await f.attachment.session.getValue(value("jouzu.flow.native-request-history", "pending"), BACKGROUND_CONTEXT))
			?.value;
	assert.equal(pending.reset, true);
	assert.equal(pending.outcome, undefined);
	assert.equal(pending.payload, undefined);
	for (const old of f.records.slice(0, -1)) {
		const kept =
			requests.find((r) => r.id === old.id) ??
			(await f.attachment.session.getValue(value("jouzu.flow.native-request-history", old.id), BACKGROUND_CONTEXT))
				?.value;
		assert.deepEqual(kept, old);
	}
	await assert.rejects(f.store.begin(record("old-0")), { code: "stale" });
})"

"test("new request admission reserves space and leaves a full store unchanged on refusal", async (t) => {
	const f = await fullStore(t);
	await f.store.reset();
	const before = await f.store.snapshot();
	await assert.rejects(f.store.begin(record("too-full")), { code: "capacity" });
	assert.deepEqual(await f.store.snapshot(), before);
})"

"test("continuous tools retire large settled snapshots before the next request without an idle boundary", async (t) => {
	let steps = 0;
	let endings = 0;
	const f = await assembledSession(t, {
		producerExtensions: [
			{
				name: "capacity-history",
				factory(pi) {
					pi.registerTool({
						name: "step",
						label: "Step",
						description: "Advance the fixture.",
						parameters: { type: "object", properties: {} },
						async execute() {
							const attachment = f.ingress.branch().attachment;
							const records = await attachment.nativeRequests.snapshot();
							await seed(attachment, [...records, record(`history-${steps++}`, 80000)]);
							return { content: [{ type: "text", text: "done" }], details: {} };
						},
					});
					pi.on("agent_end", () => {
						endings++;
					});
				},
			},
		],
		script: (_body, index) =>
			index < 20 ? { toolCalls: [{ id: `step-${index}`, name: "step", arguments: {} }] } : { text: "Finished." },
	});
	await f.session.prompt("Run the tool sequence.");
	assert.equal(f.bodies.length, 21, f.session.agent.state.errorMessage);
	assert.equal(steps, 20);
	assert.equal(endings, 1);
	assert.equal(f.ingress.automatedPause(), undefined);
	assert.ok(bytes(await f.ingress.branch().attachment.nativeRequests.snapshot()) < limit);
})"

"test("byte retirement preserves live evidence and retires retry chains together", () => {
	const records = Array.from({ length: 8 }, (_, i) => record(`record-${i}`, 80000));
	const parent = {
		...records[0],
		outcome: "withheld",
		retryAuthorization: { ownerId: "owner", requestId: records[2].id },
	};
	const child = { ...records[2], retryOf: parent.id };
	records[0] = parent;
	records[2] = child;
	const selected = retirableNativeRequests(records, 64, new Set(), new Set([records[1].id]), new Set(), 300000);
	assert.ok(selected.includes(parent.id));
	assert.ok(selected.includes(child.id));
	assert.ok(!selected.includes(records[1].id));
	assert.ok(bytes(records.filter((r) => !selected.includes(r.id))) <= 300000);
	for (const protectedId of [parent.id, child.id]) {
		const protectedSelection = retirableNativeRequests(records, 64, new Set(), new Set([protectedId]), new Set(), 0);
		assert.ok(!protectedSelection.includes(parent.id));
		assert.ok(!protectedSelection.includes(child.id));
	}
})"

"test("only intact and converted sources acknowledge delivery", () => {
	const record = request({ sources: ["intact", "converted", "changed", "unresolved"] });
	assert.equal(nativeSourceDelivered(record, 0), true);
	assert.equal(nativeSourceDelivered(record, 1), true);
	// Pi records `changed` when it replaces content, such as removing an image. Replaced content is
	// not what the controller retained, so it cannot acknowledge that the instruction was delivered.
	assert.equal(nativeSourceDelivered(record, 2), false);
	assert.equal(nativeSourceDelivered(record, 3), false);
	// An index no capture member claims is not delivered by omission.
	assert.equal(nativeSourceDelivered(record, 9), false);
	assert.equal(nativeSourceDelivered(request(), 0), false);
})"

"test("a projection acknowledges delivery only when it converted intact", () => {
	const record = request({ projections: ["converted", "changed", "unresolved"] });
	assert.equal(nativeProjectionDelivered(record, 0), true);
	assert.equal(nativeProjectionDelivered(record, 1), false);
	assert.equal(nativeProjectionDelivered(record, 2), false);
	assert.equal(nativeProjectionDelivered(record, 9), false);
})"

"test("the two layers agree on every request a real campaign produces", async (t) => {
	const background = await controlledBackground(t);
	const wakeEntered = deferred(),
		releaseWake = deferred(),
		wakeSettled = deferred();
	const script = campaignScript({ command: background.command, goal: "Compare inclusion layers" });
	const f = await assembledSession(t, {
		producerExtensions: await installedProducerExtensions(),
		script: async (body, index) => {
			if (index === 4) {
				wakeEntered.resolve();
				await releaseWake.promise;
			}
			return script(body, index);
		},
	});
	afterFlowCleanup(t, () => releaseWake.resolve());
	const store = f.ingress.branch().attachment.nativeRequests;
	const finish = store.finish.bind(store);
	const seen = new Map();
	let wakeId;
	// Capture each terminal receipt before the next request or idle maintenance can retire it.
	t.mock.method(store, "finish", async (...args) => {
		await finish(...args);
		const record = (await store.snapshot()).find((request) => request.id === args[0]);
		assert.ok(record, `finished request ${args[0]} remains available at settlement`);
		seen.set(record.id, record);
		if (record.id === wakeId) wakeSettled.resolve();
	});
	await f.session.prompt("start the sweep and wait");
	assert.equal(f.bodies.length, 4, "the campaign starts its lane, job, and wait before replying");
	const waits = await f.ingress.branch().attachment.waits.snapshot();
	assert.equal(waits.length, 1, "the campaign declares one wait");
	assert.equal(waits[0].state, "waiting", "the dependency remains gated until the wait is recorded");
	await background.release();
	await wakeEntered.promise;
	const pending = (await store.snapshot()).filter((request) => request.outcome === undefined);
	assert.equal(pending.length, 1, "the wake request is waiting for its provider response");
	const inFlight = pending[0];
	wakeId = inFlight.id;
	assert.ok(inFlight.payload, "the wake reached the provider");
	assert.ok(inFlight.sourceCapture?.members.length, "the wake carries retained sources");
	// Model delivery precedes the provider's outcome. A polling collector can retain this snapshot
	// after the request succeeds and is retired, so it cannot infer non-delivery from no outcome.
	for (const member of inFlight.sourceCapture.members)
		assert.equal(nativeSourceDelivered(inFlight, member.index), true, `in-flight source ${member.index}`);
	releaseWake.resolve();
	await wakeSettled.promise;
	await f.session.waitForIdle();
	assert.equal(inFlight.outcome, undefined, "a pre-response snapshot does not acquire the later outcome");
	assert.equal(seen.get(wakeId)?.outcome, "success", "settlement captures the wake's completed receipt");

	const requests = [...seen.values()];
	assert.equal(f.bodies.length, 5, "the dependency produces one composed wake");
	assert.equal(requests.length, f.bodies.length, "every provider request has a captured terminal receipt");
	assert.ok(requests.length >= 2, `the campaign made several provider requests, saw ${requests.length}`);
	assert.ok(
		requests.some((request) => request.sourceCapture?.members.length),
		"at least one request carried retained sources",
	);
	// Projections are composed by the wait-decision context path rather than this campaign, so their
	// real-fixture agreement is proven where that path already runs: the ingress, wait-observation,
	// and background-results suites exercise it once their readers move to the model layer.
	// Every retained source in a successful request reached the adapter as composed.
	for (const request of requests) {
		assert.equal(request.outcome, "success", `request ${request.id} completed successfully`);
		for (const member of request.sourceCapture?.members ?? [])
			assert.equal(
				nativeSourceDelivered(request, member.index),
				request.outcome === "success",
				`request ${request.id} source ${member.index}`,
			);
	}
	assert.deepEqual(f.errors, []);
})"

"test(`native prompt observation follows input handling once: handled=${handled}`, async (t) => {
		let transforms = 0;
		const f = await fixture(t, [
			(pi) => {
				pi.on("input", () => {
					transforms++;
					return handled ? { action: "handled" } : { action: "transform", text: "normalized" };
				});
				pi.on("before_agent_start", () => ({
					message: { customType: "context", content: "native context", display: false, details: { n: 1 } },
				}));
			},
		]);
		const images = [pngImage];
		await f.session.prompt("original", { images });
		const [record] = await f.attachment.submissions.snapshot();
		assert.equal(transforms, 1);
		assert.equal(record.submission.args[0], "original");
		assert.equal(record.dispatch.phase, "returned");
		assert.equal(f.requests.length, handled ? 0 : 1);
		if (handled) {
			assert.equal(record.dispatch.inputs, undefined);
			assert.equal(record.dispatch.promptHistory, undefined);
		} else {
			assert.equal(record.dispatch.inputs.length, 1);
			const input = record.dispatch.inputs[0];
			assert.equal(input.kind, "prompt");
			assert.equal(input.args[0][0].content[0].text, "normalized");
			assert.deepEqual(input.args[0][0].content[1], images[0]);
			assert.equal(input.args[0][1].customType, "context");
			assert.deepEqual(input.args[0][1].details, { n: 1 });
			assert.deepEqual(
				record.dispatch.promptHistory.map(({ inputIndex, messageIndex }) => ({ inputIndex, messageIndex })),
				[
					{ inputIndex: 0, messageIndex: 0 },
					{ inputIndex: 0, messageIndex: 1 },
				],
			);
			assert.notEqual(record.dispatch.promptHistory[0].entryId, record.dispatch.promptHistory[1].entryId);
			await f.native.close();
			await f.attachment.close();
			const reopened = await PiFlowAttachment.open(f.root, f.scope);
			assert.deepEqual((await reopened.submissions.snapshot())[0].dispatch.inputs, record.dispatch.inputs);
			assert.deepEqual(
				(await reopened.submissions.snapshot())[0].dispatch.promptHistory,
				record.dispatch.promptHistory,
			);
			await reopened.close();
		}
	})"

"test("native queue consumption waits for its exact input observation without scanning history", async (t) => {
	const f = await fixture(t);
	const snapshot = f.attachment.submissions.snapshot.bind(f.attachment.submissions);
	t.mock.method(f.attachment.submissions, "snapshot", () => {
		throw new Error("Queue consumption must not scan submission history");
	});
	const queries = [];
	const forOperations = f.attachment.submissions.forOperations.bind(f.attachment.submissions);
	t.mock.method(f.attachment.submissions, "forOperations", (operations) => {
		queries.push([...operations]);
		return forOperations(operations);
	});
	const entered = deferred(),
		release = deferred();
	const dispatch = f.attachment.submissions.dispatch.bind(f.attachment.submissions);
	t.mock.method(f.attachment.submissions, "dispatch", (id, revision, operation, run) =>
		dispatch(id, revision, operation, (observer, submission) =>
			run(
				{
					observe: async (input) => {
						entered.resolve();
						await release.promise;
						return observer.observe(input);
					},
				},
				submission,
			),
		),
	);
	const enqueuing = f.session.followUp("queued");
	await entered.promise;
	const [item] = f.session.agent.inspectQueuedMessages();
	const running = f.session.continueQueued();
	await tick();
	assert.equal(f.requests.length, 0);
	release.resolve();
	await Promise.all([enqueuing, running]);
	assert.equal(f.requests.length, 1);
	const [record] = await snapshot();
	assert.equal(queries.length, 3);
	assert.ok(queries.every((operations) => operations.length === 1 && operations[0] === record.dispatch.operationId));
	assert.deepEqual(record.dispatch.inputs[0].queue, { id: item.id, revision: item.revision });
	assert.equal(record.dispatch.inputs[0].args[0].content[0].text, "queued");
	assert.deepEqual(record.dispatch.queueClaims, [{ id: item.id, revision: item.revision, consumed: true }]);
	const [view] = projectFlowSubmissions([record], await f.attachment.ledger.snapshot());
	assert.equal(view.delivery, "history");
	assert.equal(view.admission, "held");
})"

