			{ id: item.id, revision: 2 },
			{
				kind: "followUp",
				args: [{ role: "user", content: "after consumption", timestamp: 1 }],
				queue: { id: item.id, revision: 3 },
			},
		),
		{ code: "transition" },
	);
})"

