	f.storage.mutate = (update, context) =>
		mutate(
			(mutation, ctx) =>
				update(
					new Proxy(mutation, {
						get(target, key) {
							if (key === "commit")
								return () => {
									throw new Error("injected native commit failure");
								};
							const field = Reflect.get(target, key);
							return typeof field === "function" ? field.bind(target) : field;
						},
					}),
					ctx,
				),
			context,
		);
