	f.storage.mutate = (update, context) =>
		mutate(
			(mutation, ctx) =>
				update(
					new Proxy(mutation, {
						get(target, key) {
							if (key === "scanValues")
								return () => {
									throw new Error("unexpected history scan");
								};
							if (key === "getValue")
								return (address, context) => {
									if (address.namespace === "jouzu.flow.native-source-reconciled") seen.add(address.key);
