"test("native submission join rejects foreign claims and returns owned inspection data", async (t) => {
	const f = await nativeRequests(t, { retainInputs: true });
	await f.session.prompt("source");
	const records = await f.attachment.submissions.snapshot(),
		ledger = await f.attachment.ledger.snapshot();
	const requests = await f.store.snapshot();
	for (const mutate of [
		(request) => {
			request.sourceCapture.members[0].operationId = "foreign";
		},
		(request) => {
			request.sourceCapture.members[0].prompt.messageIndex = 99;
		},
		(request) => {
			request.sourceCapture.model.members[0].sourceIndex = 99;
		},
	]) {
		const changed = structuredClone(requests);
		mutate(changed[0]);
		assert.throws(() => projectFlowSubmissions(records, ledger, changed), { code: "identity" });
	}
	assert.throws(() => projectFlowSubmissions(records, ledger, [...requests, ...requests]), { code: "identity" });
	const [view] = projectFlowSubmissions(records, ledger, requests);
	view.nativeRequests[0].sources[0].identity.operationId = "edited";
	assert.notEqual(requests[0].sourceCapture.members[0].operationId, "edited");
})"

"test("only a run carrying nothing the user is owed an answer about gets permission", () => {
	assert.equal(flowNoReplyPermission(attempt()), flowNoReplyToken("attempt-1"));
	// Requested work and wait decisions are things the model was asked to act on.
	for (const kind of ["work", "wait", "user", "alert"])
		assert.equal(flowNoReplyPermission(attempt({ members: [member(kind)] })), undefined, kind);
	// One result beside requested work does not make the run notification-only.
	assert.equal(flowNoReplyPermission(attempt({ members: [member("result"), member("work")] })), undefined);
	// User input is judged when the tool runs rather than when the offer is composed, so nothing
	// here inspects requests. A run with no members has nothing to notify about, so silence would
	// say nothing about nothing.
	assert.equal(flowNoReplyPermission(attempt({ members: [] })), undefined);
})"

"test("permission is bound to one attempt and refuses user input anywhere in its run", () => {
	const current = attempt();
	const token = flowNoReplyPermission(current);
	assert.deepEqual(checkFlowNoReply(state(current), token), { allowed: true, attemptId: "attempt-1" });

	// Queued user input joining the run appends a request. The offer was already made, so the
	// withdrawal has to happen at call time rather than by changing the token.
	const joined = attempt({ requests: [request("r1"), request("r2", true)] });
	assert.equal(checkFlowNoReply(state(joined), token).reason, "carries-user-input");
	// A user message that joined mid-run stays behind the assistant turns that followed it, so
	// the newest request alone can no longer see it. Every request of the run is owed a reply.
	const trailed = attempt({ requests: [request("r1", true), request("r2"), request("r3")] });
	assert.equal(checkFlowNoReply(state(trailed), token).reason, "carries-user-input");

	// A token from another attempt, or for an attempt that is no longer current, cannot terminate.
	assert.equal(checkFlowNoReply(state(current), flowNoReplyToken("attempt-2")).reason, "stale-run");
	const superseded = { ...state(current), activeAttemptId: "attempt-2" };
	assert.equal(checkFlowNoReply(superseded, token).reason, "unknown-run");
})"

"test("a malformed or absent token is refused rather than trusted", () => {
	const current = attempt();
	for (const token of [undefined, null, "", 0, {}, ["x"], "not-a-token"])
		assert.equal(checkFlowNoReply(state(current), token).allowed, false, JSON.stringify(token) ?? "undefined");
	// The refusal names why, so a model can tell a stale permission from an ineligible run.
	assert.equal(
		checkFlowNoReply(state(attempt({ requests: [request("r1", true)] })), flowNoReplyToken("attempt-1")).reason,
		"carries-user-input",
	);
	assert.equal(
		checkFlowNoReply(state(attempt({ members: [member("work")] })), flowNoReplyToken("attempt-1")).reason,
		"carries-requested-work",
	);
})"

"test("tokens differ across attempts", () => {
	// Binding is what stops a permission being replayed, so distinct runs must not collide.
	const tokens = new Set(["a", "b", "a1", "ab", ""].map((id) => flowNoReplyToken(id)));
	assert.equal(tokens.size, 5, "no two attempts share a token, including ambiguous concatenations");
})"

"test("a projection exposes what a producer needs and nothing of the host's message shape", () => {
	const [projected] = flowObservations([toolResult]);
	assert.deepEqual(projected, {
		index: 0,
		kind: "toolResult",
		failed: false,
		toolCallId: "read",
		toolName: "bg_task",
		contentHash: createHash("sha256").update(JSON.stringify(content)).digest("hex"),
	});
	// Non-tool messages are still offered so indices line up with the host's own list.
	const mixed = flowObservations([{ role: "user", content: "hi" }, toolResult]);
	assert.deepEqual(
		mixed.map((item) => [item.index, item.kind]),
		[
			[0, "other"],
			[1, "toolResult"],
		],
	);
	// A host variant without content still projects, rather than throwing on the union's edge cases.
	assert.equal(flowObservations([{ role: "bashExecution" }])[0].contentHash, flowObservationHash(undefined));
	assert.equal(flowObservations([{ role: "toolResult", isError: true, content }])[0].failed, true);
})"

"test("stored evidence and live context project identically", () => {
	// The reconciliation path compares a retained message against a live one; they must agree.
	const { index, ...live } = flowObservations([toolResult])[0];
	assert.equal(index, 0);
	assert.deepEqual(flowObservationOf(toolResult), live);
})"

"test("a producer cannot name an observation outside the offered context", () => {
	assert.deepEqual(selectedObservations([2, 0, 0], 3), [0, 2], "duplicates collapse and order is stable");
	assert.deepEqual(selectedObservations([], 3), []);
	for (const invalid of [[3], [-1], [1.5], [Number.NaN], ["0"]])
		assert.throws(() => selectedObservations(invalid, 3), RangeError, `${JSON.stringify(invalid)}`);
	// Nothing may be selected from an empty context, which is what a producer sees before any turn.
	assert.throws(() => selectedObservations([0], 0), RangeError);
	assert.throws(() => selectedObservations("all", 3), TypeError);
})"

"test("every flow tool refuses with one message while flow control is off", async () => {
	// The attachment getter throws: a refusal that got as far as reading it would be a different failure.
	const attachment = () => assert.fail("a refused tool must not read its attachment");
	const waits = tools(createFlowWaitExtension({ attachment, maxDurationMs: 5000, enabled: off }));
	await assert.rejects(
		waits
			.get("agent_wait")
			.execute("call", { work: "work", reason: "why", deadline: "5m", on: [] }, undefined, undefined, ctx),
		(error) => refusal(error) === FLOW_OFF_MESSAGE,
	);
	await assert.rejects(
