	]);
	await ledger.cancel("attempt", "Cancelled before queue admission.");
	assert.deepEqual(host.agent.inspectQueuedMessages(), [second]);
	assert.equal(host.agent.cancelQueuedMessage(second.id, second.revision).kind, "cancelled");
	assert.deepEqual(host.agent.inspectQueuedMessages(), []);
})"

"test(`hidden results remain exact after reset, retirement and reopen: preempt=${preempt}`, {
		timeout: 15000,
	}, async (t) => {
		const expected = structuredClone(members).sort((a, b) => a.id.localeCompare(b.id));
		const producers = await installedProducerExtensions();
		const f = await assembledSession(t, {
			persist: true,
			producerExtensions: producers,
			limits: { maxResultBytes: 2400 },
		});
		await f.session.prompt("Keep all results");
		let unblock, entered;
		const ready = new Promise((resolve) => {
			entered = resolve;
		});
		const gate = preempt
			? new Promise((resolve) => {
					unblock = resolve;
				})
			: Promise.resolve();
		const producer = {
			version: 1,
			namespace: "preservation",
			snapshot: async () =>
				members.map((member, sequence) => ({
					id: member.id,
					revision: member.revision,
					producer: member.producer,
					sequence,
					rank: 6,
					independent: true,
					runnable: true,
				})),
			build: () => assert.fail("must retain the complete manifest"),
			describeResult: async (intent) => {
				entered();
				await gate;
				return members.find((member) => member.id === intent.id);
			},
		};
		const registration = f.ingress.registerProducer(producer);
		t.after(() => registration.dispose());
		const delivering = registration.changed();
		if (preempt) {
			await ready;
			const user = f.session.prompt("優先 instruction: preserve every result");
			await new Promise((resolve) => setImmediate(resolve));
			unblock();
			await user;
		}
		await delivering;
		await f.session.waitForIdle();
		const attempts = (await f.ingress.branch().attachment.ledger.snapshot()).attempts;
		const delivered = attempts.find(
			(attempt) => attempt.phase === "settled" && attempt.members.length === members.length,
		);
		assert.ok(delivered, "all members reached a settled provider attempt");
		const envelopes = f.bodies
			.flatMap((body) => body.messages)
			.flatMap((message) => (Array.isArray(message.content) ? message.content : []))
			.flatMap((part) => {
				try {
					const parsed = JSON.parse(part.text);
					return parsed.kind === "result" ? [parsed.content] : [];
				} catch {
					return [];
				}
			});
		const envelope = envelopes.find((value) => value.total === members.length);
		assert.ok(envelope);
		assert.ok(envelope.omitted > 0, "budget really excludes some members from the sample");
		if (preempt) assert.ok(f.bodies.some((body) => text(body).includes("優先 instruction")));
		assert.deepEqual(await pages(f.ingress.branch().attachment.results, envelope.manifest), expected);
		registration.dispose();
		// A newer unrelated manifest makes the delivered manifest eligible by age, but its transcript reference must protect it.
		await f.ingress.branch().attachment.results.retain([{ ...members[0], id: "unrelated", execution: "unrelated" }]);
		await f.session.prompt("/flow clear");
		await f.ingress.retireResultHistory(1);
		assert.deepEqual(await pages(f.ingress.branch().attachment.results, envelope.manifest), expected);
		const file = f.sessionManager.getSessionFile();
		const next = await replacedSession(t, f, {
			reason: "resume",
			producerExtensions: producers,
			persist: true,
			sessionManager: SessionManager.open(file),
		});
		await next.session.prompt("Continue after recovery");
		await next.ingress.retireResultHistory(1);
		assert.deepEqual(await pages(next.ingress.branch().attachment.results, envelope.manifest), expected);
		assert.deepEqual(f.errors, []);
		assert.deepEqual(next.errors, []);
	})"

"test(`a truncated response pauses only if compact-and-retry fails: recovers=${recovers}`, async (t) => {
		const f = await assembledSession(t, {
			persist: true,
			settings: { compaction: { enabled: true, reserveTokens: 512, keepRecentTokens: 1 } },
			producerExtensions: await installedProducerExtensions(),
			script: [
				{ text: "Earlier successful response" },
				truncated(),
				{ text: "Summary of earlier work" },
				{ text: "Summary of the current turn" },
				recovers ? { text: "Recovered" } : truncated(),
			],
		});
		const notices = capturedNotices(f.session);
		await f.session.setModel({ ...f.session.model, contextWindow: 262144 });
		await f.session.prompt("Establish earlier history");
		await f.session.prompt("Continue the work");
		await f.session.waitForIdle();
		assert.equal(
			f.bodies.length,
			5,
			"one truncation, two summaries for the split turn, and one retry after the earlier turn",
		);
		assert.equal(f.sessionManager.getEntries().filter((entry) => entry.type === "compaction").length, 1);
		assert.equal(isProviderPause(f.ingress.automatedPause() ?? ""), !recovers);
		assert.equal(notices.filter((notice) => notice.text.includes("Flow control paused")).length, recovers ? 0 : 1);
		if (!recovers) assert.match(f.ingress.automatedPause(), /response was truncated/i);

		const producer = syntheticProducer();
		const registration = f.ingress.registerProducer(producer.producer);
		t.after(() => registration.dispose());
		producer.offer([{ id: "after-truncation-recovery", revision: "1" }]);
		await registration.changed();
		await f.session.waitForIdle();
		assert.equal(f.bodies.length, recovers ? 6 : 5, "only a successful recovery permits automatic continuation");
		assert.deepEqual(f.errors, []);
	})"

"test("a provider failure that ends a turn holds automated work and reports why", async (t) => {
	const f = await assembledSession(t, {
		producerExtensions: await installedProducerExtensions(),
		script: rejection,
	});
	const notices = capturedNotices(f.session);
	await f.session.prompt("Do the work");
	await settle();
	// The fixture disables retries, so the turn stops after the one request it made.
	assert.equal(f.bodies.length, 1);
	const pause = f.ingress.automatedPause();
	assert.ok(isProviderPause(pause ?? ""), `expected a provider pause, got ${pause}`);
	assert.match(pause, /403 terminated/);
	const reported = notices.filter((notice) => notice.text.includes("Flow control paused"));
	assert.equal(reported.length, 1, JSON.stringify(notices));
	assert.match(reported[0].text, /403 terminated/);
	assert.match(reported[0].text, /\/flow for details/);

	notices.length = 0;
	await f.session.prompt("/flow");
	await settle();
	const listed = notices.map((notice) => notice.text).join("\n");
	assert.match(listed, /Paused: a provider request failed/);
	assert.match(listed, /403 terminated/);
	assert.match(listed, /\/flow resume/);
	assert.doesNotMatch(listed, /\/flow clear/, "a provider rejection is not repaired by releasing a reservation");
})"

