"test(`official Astra keeps prepared request identity with a receipt: ${scenario.name}`, async (t) => {
		const { apiKey } = scenario;
		const f = await fixture(t);
		f.runtime.registerProvider("openai", {
			api: "openai-responses",
			apiKey,
			models: [
				{
					id: "gpt-6-astra",
					name: "Account Astra",
					api: "openai-responses",
					baseUrl: "https://api.openai.com/v1",
					reasoning: false,
					input: ["text"],
					contextWindow: 400000,
					maxTokens: 12000,
					cost: { input: 10, output: 50, cacheRead: 1, cacheWrite: 12.5 },
				},
			],
		});
		const model = f.runtime.getModel("openai", "gpt-6-astra");
		const initialBaseUrl = scenario.baseUrl ?? model.baseUrl;
		let baseUrl = initialBaseUrl;
		let authFailed = false;
		const getAuth = f.runtime.getAuth.bind(f.runtime);
		f.runtime.getAuth = async (...args) => {
			if (authFailed) throw new Error("fixture later auth failure");
			const resolved = await getAuth(...args);
			return resolved
				? {
						...resolved,
						auth: {
							...resolved.auth,
							baseUrl,
							...(scenario.headerOnly
								? { apiKey: undefined, headers: { Authorization: "Bearer fixture-header-credential" } }
								: {}),
						},
					}
				: resolved;
		};
		const snapshots = [];
		const loader = new DefaultResourceLoader({
			cwd: f.root,
			agentDir: f.root,
			noExtensions: true,
			noSkills: true,
			extensionFactories: [
				(pi) => {
					pi.on("before_provider_request", async (event) => {
						snapshots.push(event.request);
						if (scenario.nextKey) await f.runtime.setRuntimeApiKey("openai", scenario.nextKey);
						if (scenario.nextBaseUrl) baseUrl = scenario.nextBaseUrl;
						if (scenario.failLaterAuth) authFailed = true;
						return { ...event.payload, temperature: 0.8 };
					});
				},
				createAstraCompatibilityExtension(),
			],
		});
		await loader.reload();
		const { session } = await createAgentSession({
			cwd: f.root,
			agentDir: f.root,
			modelRuntime: f.runtime,
			resourceLoader: loader,
			sessionManager: SessionManager.inMemory(f.root),
			model,
			thinkingLevel: "off",
			tools: [],
			settingsManager: SettingsManager.inMemory({ retry: { enabled: false }, compaction: { enabled: false } }),
		});
		await session.bindExtensions({
			mode: "rpc",
			onError: (error) => {
				throw error;
			},
		});
		assert.equal(f.runtime.getRegisteredNativeProvider("openai"), undefined);
		assert.equal(f.runtime.getRegisteredProviderConfig("openai")?.streamSimple, undefined);
		assert.equal(session.model.thinkingLevelMap?.max, "max");
		const bodies = [];
		const nativeStream = session.agent.streamFunction;
		const streamFn = (selected, context, options) =>
			nativeStream(selected, context, {
				...options,
				...(scenario.cacheRetention ? { cacheRetention: scenario.cacheRetention } : {}),
				fetch: async (_url, init) => {
					bodies.push(JSON.parse(init.body));
					const item = {
						type: "message",
						id: "msg_done",
						role: "assistant",
						content: [{ type: "output_text", text: "ok", annotations: [] }],
						status: "completed",
					};
					const events = [
						{ type: "response.output_item.done", output_index: 0, item },
						{ type: "response.completed", response: { id: "fixture", status: "completed", output: [item] } },
					];
					return new Response(
						events.map((event) => `event: ${event.type}\ndata: ${JSON.stringify(event)}\n\n`).join(""),
						{ headers: { "content-type": "text/event-stream" } },
					);
				},
			});
		session.agent.streamFunction = streamFn;
		const attachment = await PiFlowAttachment.open(join(f.root, "flow"), {
			sessionId: session.sessionId,
			branchId: "main",
		});
		const bridge = new PiNativeRequests(
			session,
			attachment.nativeRequests,
			100000,
			undefined,
			false,
			undefined,
			undefined,
			streamFn,
		);
		afterCleanup(t, async () => {
			await bridge.close();
			await attachment.close();
			await session.dispose();
		});
		assert.doesNotThrow(() => preparePiProviderRoute(f.runtime, model, () => {}));
		await session.prompt("hello");
		const records = await attachment.nativeRequests.snapshot();
		assert.equal(bodies.length, 1);
		const subscription = initialBaseUrl === "https://api.openai.com/v1" && !apiKey.startsWith("sk-");
		const custom = initialBaseUrl !== "https://api.openai.com/v1";
		assert.deepEqual(
			bodies[0].prompt_cache_options,
			scenario.cacheRetention === "none"
				? { mode: "explicit" }
				: subscription || custom || scenario.headerOnly
					? undefined
					: { ttl: "30m" },
		);
		if (subscription) assert.equal(bodies[0].max_output_tokens, undefined);
		else assert.ok(bodies[0].max_output_tokens > 0);
		if (!custom) assert.equal(bodies[0].reasoning?.effort, "low");
		assert.equal(bodies[0].temperature, custom ? 0.8 : undefined);
		assert.equal(snapshots.length, 1);
		assert.equal(snapshots[0].model.baseUrl, initialBaseUrl);
		assert.equal(snapshots[0].isChatGPTSignIn, subscription);
		assert.equal(snapshots[0].hasApiKey, !scenario.headerOnly);
		assert.deepEqual(Object.keys(snapshots[0]).sort(), ["hasApiKey", "isChatGPTSignIn", "model"]);
		assert.deepEqual(Object.keys(snapshots[0].model).sort(), ["api", "baseUrl", "compat", "id", "provider"]);
		assert.equal(JSON.stringify(snapshots).includes(apiKey), false);
		assert.ok(Object.isFrozen(snapshots[0]));
		assert.ok(Object.isFrozen(snapshots[0].model));
		assert.ok(Object.isFrozen(snapshots[0].model.compat));
		assert.equal(records.length, 1);
		assert.equal(records[0].outcome, "success");
	})"

"test(`legacy API guard rejects ${replacement} and accepts builtin reset`, async (t) => {
		const f = await fixture(t);
		afterCleanup(t, () => resetApiProviders());
		let invoked = 0;
		const stream = () => {
			invoked++;
			throw Error("must not invoke");
		};
		const api = f.model.api;
		assert.equal(isBuiltinApiProvider(api), true);
		if (replacement === "registered") registerApiProvider({ api, stream, streamSimple: stream }, "route-test");
		if (replacement === "mutated-stream") getApiProvider(api).stream = stream;
		if (replacement === "mutated-simple") getApiProvider(api).streamSimple = stream;
		if (replacement === "mutated-api") getApiProvider(api).api = "unqualified-api";
		assert.equal(isBuiltinApiProvider(api), false);
		registerBuiltInApiProviders();
		assert.equal(isBuiltinApiProvider(api), false, "registration refresh cannot qualify an override");
		assert.throws(() => preparePiProviderRoute(f.runtime, f.model, () => {}), { code: "identity" });
		assert.equal(invoked, 0);
		assert.equal(f.requests(), 0);
		resetApiProviders();
		assert.equal(isBuiltinApiProvider(api), true);
		const response = await f.runtime
			.streamSimple(f.model, f.context, {
				flowValidateProvider: preparePiProviderRoute(f.runtime, f.model, () => {}),
			})
			.result();
		assert.notEqual(response.stopReason, "error", response.errorMessage);
		assert.equal(f.requests(), 1);
		assert.equal(invoked, 0);
	})"

