"test(`process kill at ${checkpoint} preserves exact known receipts`, { timeout: 15000 }, async (t) => {
		const { fork } = await import("node:child_process");
		const { once } = await import("node:events");
		const root = await mkdtemp(join(tmpdir(), "jouzu-flow-kill-"));
		t.after(() => rm(root, { recursive: true, force: true }));
		const child = fork(new URL("./fixtures/flow-ledger-crash.mjs", import.meta.url), [root, checkpoint], {
			stdio: ["ignore", "pipe", "pipe", "ipc"],
		});
		t.after(() => {
			if (child.exitCode === null) child.kill("SIGKILL");
		});
		let stderr = "";
		child.stderr.on("data", (data) => {
			stderr += data;
		});
		const metadata = await new Promise((resolve, reject) => {
			child.once("message", (message) => {
				if (message.ready) resolve(message.metadata);
				else reject(new Error("Unexpected crash-fixture message."));
			});
			child.once("error", reject);
			child.once("exit", (status) => reject(new Error(`Crash fixture exited ${status}: ${stderr}`)));
		});
		const exited = once(child, "exit");
		child.kill("SIGKILL");
		await exited;
		const repo = new JsonlSessionRepo({ fileSystem: new NodeExecutionEnv({ cwd: root }), sessionsRoot: root });
		const session = await repo.open(metadata, context);
		t.after(async () => {
			await session.close(context);
			await repo.close(context);
		});
		const ledger = await FlowReceiptLedger.attach(createPiLedgerStore(session), scope);
		const attempt = (await ledger.snapshot()).attempts[0];
		assert.equal(attempt.phase, checkpoint === "after-handoff" ? "uncertain" : "cancelled");
		assert.equal(attempt.history[0].entryId, "history");
		assert.equal(attempt.members[0].revision, "execution-1");
		assert.equal(attempt.requests[0].handedOff, checkpoint === "after-handoff");
		assert.equal(attempt.requests[0].outcome, undefined);
	})"

"test("flow JSONL updates do not rewrite every retained attempt on each transition", async (t) => {
	const { stat } = await import("node:fs/promises");
	const root = await mkdtemp(join(tmpdir(), "jouzu-flow-growth-"));
	t.after(() => rm(root, { recursive: true, force: true }));
	const repo = new JsonlSessionRepo({ fileSystem: new NodeExecutionEnv({ cwd: root }), sessionsRoot: root });
	const session = await repo.create({ cwd: root }, context);
	t.after(async () => {
		await session.close(context);
		await repo.close(context);
	});
	const ledger = await FlowReceiptLedger.attach(createPiLedgerStore(session), scope);
	let firstBytes;
	for (let i = 0; i < 40; i++) {
		await ledger.select(`attempt-${i}`, [member(`result-${i}`)]);
		await ledger.cancel(`attempt-${i}`, "User cancelled queued work.");
		if (i === 19) firstBytes = (await stat(session.metadata.path)).size;
	}
	const finalBytes = (await stat(session.metadata.path)).size;
	assert.equal((await ledger.snapshot()).attempts.length, 40);
	assert.ok(finalBytes < firstBytes * 3, `20 attempts: ${firstBytes} bytes; 40 attempts: ${finalBytes} bytes`);
	t.diagnostic(`Flow JSONL retained receipts: 20 attempts ${firstBytes} bytes; 40 attempts ${finalBytes} bytes.`);
})"

"test(`tool authority survives ${recovery} recovery for ${owner} work`, { timeout: 15000 }, async (t) => {
			const identities = [];
			const compactions = [];
			const f = await assembledSession(t, {
				persist: true,
				settings: {
					compaction: { enabled: true, reserveTokens: 512, keepRecentTokens: recovery === "threshold" ? 7505 : 1 },
					retry: { enabled: true, maxRetries: 1, baseDelayMs: 1 },
				},
				producerExtensions: [
					...(await installedProducerExtensions({ freshMultiloop: true })),
					{
						name: "ownership-probe",
						factory(pi) {
							pi.registerTool({
								name: "ownership_probe",
								label: "Ownership probe",
								description: "Verify the current fixture work authority.",
								parameters: { type: "object", properties: {} },
								async execute() {
									const branch = f.ingress.branch();
									const work = branch.workContext.current();
									assert.ok(work, "every authorized recovery tool must have owning work");
									assert.deepEqual(branch.attachment.waits.captureExecutionWork(work.id, work.revision, "bg"), work);
									identities.push(work);
									return {
										content: [
											{
												type: "text",
												text: recovery === "threshold" && identities.length === 1 ? "data ".repeat(6000) : "verified",
											},
										],
										details: {},
									};
								},
							});
							pi.on("session_before_compact", (event) => {
								compactions.push(event.reason);
								return {
									compaction: {
										summary: "Continue the authorized fixture work.",
										firstKeptEntryId: "",
										tokensBefore: event.preparation.tokensBefore,
									},
								};
							});
						},
					},
				],
				script: (_body, requestIndex) => {
					if (requestIndex === 0) return { text: "Earlier fixture history." };
					const index = requestIndex - 1;
					if (index === 0) return { toolCalls: [{ name: "ownership_probe", arguments: {} }] };
					if (index === 1 && recovery !== "threshold")
						return {
							httpStatus: recovery === "overflow" ? 400 : 503,
							httpBody: {
								error: {
									message:
										recovery === "overflow"
											? "This model's maximum context length is 262144 tokens. However, you requested 87591 output tokens and your prompt contains at least 174554 input tokens, for a total of at least 262145 tokens. Please reduce the length of the input prompt or the number of requested output tokens. (parameter=input_tokens, value=174554)"
											: "Service unavailable",
									type: recovery === "overflow" ? "BadRequestError" : "server_error",
									code: recovery === "overflow" ? 400 : 503,
								},
							},
						};
					if (index === (recovery === "threshold" ? 1 : 2))
						return { toolCalls: [{ name: "ownership_probe", arguments: {} }] };
					if (owner === "goal" && index === (recovery === "threshold" ? 2 : 3))
						return { toolCalls: [{ name: "multiloop_stop", arguments: { target: "verify-ownership" } }] };
					return { text: "Finished." };
				},
			});
			if (recovery !== "threshold") await f.session.setModel({ ...f.session.model, contextWindow: 262144 });
			await f.session.prompt("Establish earlier fixture history.");
			await f.session.prompt(owner === "goal" ? "/goal Verify ownership" : "Verify ownership across recovery.");
			await f.ingress.wakeProducers();
			await f.session.waitForIdle();
			assert.equal(
				identities.length,
				2,
				JSON.stringify(f.session.messages.filter((message) => message.role === "toolResult")),
			);
			assert.deepEqual(identities[1], identities[0]);
			assert.match(identities[0].id, owner === "goal" ? /^multiloop-work:/ : /^user:/);
			assert.equal(f.bodies.length, (recovery === "threshold" ? 4 : 5) + (owner === "goal" ? 1 : 0));
			assert.deepEqual(compactions, recovery === "retry" ? [] : [recovery]);
			assert.equal(f.ingress.automatedPause(), undefined);
			assert.deepEqual(f.errors, []);
		})"

"test("native request joins model admission, handoff, and outcome without settling the run", async (t) => {
	const { session, ledger, sent } = await fixture(t);
	await session.agent.continue();
	const state = await ledger.snapshot();
	assert.equal(sent.length, 1);
	assert.equal(state.activeAttemptId, "attempt");
	assert.equal(state.attempts[0].phase, "running");
	const [request] = state.attempts[0].requests;
	assert.equal(request.handedOff, true);
	assert.equal(request.outcome, "success");
	// One inclusion record, written at model conversion.
	assert.ok(request.inclusion.length > 0);
	assert.ok(request.inclusion.every((item) => item.disposition === "included"));
})"

"test(`AgentSession extension payload filtering after conversion transmits, optional=${optional}`, async (t) => {
