"test("indexed history crosses byte limits with bounded queries and rolls back failed writes", async (t) => {
	const limits = { maxManifests: 100, maxMembers: 20, maxBytes: 1600 };
	const { session, ownership } = await memory(t, limits);
	const observed = { reads: 0, fail: false };
	const store = await FlowResultManifestStore.attach(observedSession(session, observed), ownership, limits);
	const references = [];
	for (let i = 0; i < 40; i++) {
		observed.reads = 0;
		references.push(await store.retain([member(`bytes-${i}`)]));
		assert.ok(observed.reads <= 4, `retaining one member needs bounded reads: ${observed.reads}`);
	}
	const header = (await session.getValue(value("jouzu.flow.result-manifests", "v1"), context)).value;
	assert.ok(header.manifests.length < 40);
	assert.ok(
		Buffer.byteLength(JSON.stringify(header)) + header.manifests.reduce((sum, entry) => sum + entry.bytes, 0) <=
			limits.maxBytes,
	);
	observed.reads = 0;
	assert.equal((await store.page(references[0], pageOptions)).members[0].id, "bytes-0");
	assert.equal(observed.reads, 2);
	await assert.rejects(store.retain([{ ...member("bytes-0"), warnings: [] }]), { code: "identity" });
	observed.fail = true;
	await assert.rejects(store.retain([member("failed")]), /injected commit failure/);
	assert.deepEqual((await session.getValue(value("jouzu.flow.result-manifests", "v1"), context)).value, header);
	observed.fail = false;
	const changed = { ...member("failed"), status: "failure" };
	const saved = await store.retain([changed]);
	assert.deepEqual(
		(await store.page(saved, pageOptions)).members,
		[changed],
		"failed transaction leaves no immutable identity behind",
	);
})"

"test("legacy migration commits metadata indexes atomically and handles a full byte window", async (t) => {
	const { session, ownership } = await memory(t);
	const record = { version: 1, scope, members: [member("legacy")] };
	const id = createHash("sha256").update(JSON.stringify(record)).digest("hex");
	const header = { version: 1, scope, manifests: [{ id, bytes: Buffer.byteLength(JSON.stringify(record)) }] };
	const headerKey = value("jouzu.flow.result-manifests", "v1");
	await session.mutate(
		(mutation, ctx) =>
			mutation.commit([setValue(headerKey, header), setValue(value("jouzu.flow.result-manifest", id), record)], ctx),
		context,
	);
	const limits = {
		maxManifests: 1,
		maxMembers: 20,
		maxBytes: Buffer.byteLength(JSON.stringify(header)) + header.manifests[0].bytes,
	};
	const observed = { reads: 0, fail: true };
	await assert.rejects(
		FlowResultManifestStore.attach(observedSession(session, observed), ownership, limits),
		/injected commit failure/,
	);
	assert.deepEqual((await session.getValue(headerKey, context)).value, header);
	observed.fail = false;
	const store = await FlowResultManifestStore.attach(observedSession(session, observed), ownership, limits);
	assert.equal(
		(await session.getValue(headerKey, context)).value.manifests.length,
		0,
		"migration metadata can evict a full recent index without losing pages",
	);
	assert.deepEqual((await store.page(`flow-results:${id}`, pageOptions)).members, record.members);
	await assert.rejects(store.retain([{ ...member("legacy"), title: "changed" }]), { code: "identity" });
	observed.reads = 0;
	await FlowResultManifestStore.attach(observedSession(session, observed), ownership, limits);
	assert.equal(observed.reads, 1, "reopen does not repeat historical migration");
})"

"test("failed automated instructions stay excluded after retirement and a later user request", async (t) => {
	const root = await mkdtemp(join(tmpdir(), "jouzu-retirement-context-"));
	afterCleanup(t, () => rm(root, { recursive: true, force: true, maxRetries: 10, retryDelay: 50 }));
	const f = await assembledSession(t, {
		root,
		persist: true,
		script: (_body, index) => (index === 0 ? { httpStatus: 400 } : { text: "user answer" }),
	});
	const source = syntheticProducer();
	const registration = f.ingress.registerProducer(source.producer);
	afterCleanup(t, () => registration.dispose());
	source.offer([{ id: "failed-instruction", revision: "1" }]);
	await registration.changed();
	assert.equal(f.bodies.length, 1);
	assert.ok(JSON.stringify(f.bodies[0].messages).includes("work failed-instruction"));
	const before = await f.ingress.branch().attachment.ledger.snapshot();
	assert.equal(before.attempts.length, 1);
	assert.equal(before.attempts[0].phase, "settled");
	assert.notEqual(before.attempts[0].outcome, "success");
	source.offer([]);
	await f.ingress.retireLedgerHistory(0);
	await f.session.prompt("answer only this new user request");
	assert.equal(f.bodies.length, 2);
	assert.ok(JSON.stringify(f.bodies[1].messages).includes("answer only this new user request"));
	assert.equal(
		JSON.stringify(f.bodies[1].messages).includes("work failed-instruction"),
		false,
		"retirement must not restore failed automated instructions to provider context",
	);
	registration.dispose();
	const sessionFile = f.sessionManager.getSessionFile();
	await f.shutdown("resume", sessionFile);
	const reopened = await assembledSession(t, {
		root: f.root,
		persist: true,
		sessionManager: SessionManager.open(sessionFile),
	});
	await reopened.ingress.retireLedgerHistory(0);
	await reopened.session.prompt("answer after reopening");
	assert.equal(reopened.bodies.length, 1);
	assert.equal(
		JSON.stringify(reopened.bodies[0].messages).includes("work failed-instruction"),
		false,
		"reopening must preserve the exclusion after another retirement pass",
	);
})"

"test("only sources at or after the last assistant turn count as this run's input", () => {
	// History replays on every request, so an answered question must not withhold permission.
	const messages = [user, assistant, user];
	assert.equal(flowRunContainsUserInput(messages, capture([{ operation: "old", at: 0 }]), users("old")), false);
	assert.equal(flowRunContainsUserInput(messages, capture([{ operation: "new", at: 2 }]), users("new")), true);
	// With no assistant turn yet, every source is this run's input.
	assert.equal(flowRunContainsUserInput([user], capture([{ operation: "first", at: 0 }]), users("first")), true);
	// A run whose only content is controller-composed carries no retained source at all.
	assert.equal(flowRunContainsUserInput([assistant, user], capture([]), users("any")), false);
})"

"test("a source the host did not mark as user cannot withhold permission", () => {
	const messages = [assistant, user];
	const carried = capture([{ operation: "extension", at: 1 }]);
	// Origin is what the host assigned. An automated send inside this run's block is not instruction,
	// and no label or marker in its content can change that.
	assert.equal(flowRunContainsUserInput(messages, carried, users("someone-else")), false);
	assert.equal(flowRunContainsUserInput(messages, carried, users("extension")), true);
})"

"test("user input joining a composed wake withholds permission from either side", () => {
	const messages = [assistant, user, user, user];
	assert.equal(flowRunContainsUserInput(messages, capture([{ operation: "typed", at: 3 }]), users("typed")), true);
	assert.equal(flowRunContainsUserInput(messages, capture([{ operation: "typed", at: 1 }]), users("typed")), true);
})"

"test("missing or unplaceable evidence withholds permission", () => {
	const messages = [assistant, user];
	// No conversion record: nothing establishes where a source landed.
	assert.equal(flowRunContainsUserInput(messages, { hash, count: 0, members: [] }, users("typed")), true);
	assert.equal(flowRunContainsUserInput(messages, undefined, users("typed")), true);
	// No resolved origins to compare against.
	assert.equal(flowRunContainsUserInput(messages, capture([{ operation: "typed", at: 1 }]), undefined), true);
	// A user source conversion could not place is treated as inside this run.
	assert.equal(flowRunContainsUserInput(messages, capture([{ operation: "typed" }]), users("typed")), true);
	assert.equal(flowRunContainsUserInput(undefined, capture([{ operation: "typed", at: 1 }]), users("typed")), true);
})"

"test("a mismatched conversion position cannot silence a user source", () => {
	const carried = capture([{ operation: "typed", at: 0 }]);
	// The model record must describe the member it sits beside; a mismatch is not evidence of place.
	carried.model.members[0].sourceIndex = 99;
	assert.equal(flowRunContainsUserInput([user, assistant], carried, users("typed")), true);
})"

"test("the assembly registers the controller extensions the launcher passes to Pi", async (t) => {
	const { flow } = await runtime(t);
	assert.deepEqual(
		flow.extensions.map((extension) => extension.name),
		[
