				mutator.commit([setValue(address, { date: new Date(0), number: NaN, missing: undefined })], BACKGROUND_CONTEXT),
			BACKGROUND_CONTEXT,
		);
		assert.deepEqual((await session.getValue(address, BACKGROUND_CONTEXT)).value, {
			date: "1970-01-01T00:00:00.000Z",
			number: null,
