"test(`${operation} is fenced during navigation ${phase} with flow ${enabled ? "on" : "off"}`, async (t) => {
				const entered = deferred(),
					release = deferred();
				let extension;
				const f = await navigationFixture(t, {
					extensions: [
						(pi) => {
							extension = pi;
							if (phase === "preparation")
								pi.on("session_before_tree", async () => {
									entered.resolve();
									await release.promise;
								});
						},
					],
				});
				await f.session.setModel({ ...model, reasoning: true });
				f.session.setThinkingLevel("off");
				if (!enabled) await f.ingress.suspend();
				const branch = f.ingress.branch();
				let gate;
				if (phase !== "preparation") {
					const target = phase === "teardown" ? branch.attachment : Object.getPrototypeOf(branch.workContext);
					const method = phase === "teardown" ? "close" : "attach";
					const original = target[method];
					gate = t.mock.method(target, method, async function (...args) {
						entered.resolve();
						await release.promise;
						return original.apply(this, args);
					});
				}
				const change =
					operation === "extension setThinkingLevel"
						? () => extension.setThinkingLevel("high")
						: operation === "cycleThinkingLevel"
							? () => f.session.cycleThinkingLevel({ persist: true })
							: () => f.session.setThinkingLevel("high", { persist: true });
				const navigating = f.session.prompt("/navigate-local 0");
				await entered.promise;
				try {
					const entries = structuredClone(f.session.sessionManager.getEntries());
					const leaf = f.session.sessionManager.getLeafId();
					const level = f.session.thinkingLevel;
					const defaultLevel = f.session.settingsManager.getDefaultThinkingLevel();
					assert.throws(change, { code: "busy" });
					assert.deepEqual(f.session.sessionManager.getEntries(), entries);
					assert.equal(f.session.sessionManager.getLeafId(), leaf);
					assert.equal(f.session.thinkingLevel, level);
					assert.equal(f.session.settingsManager.getDefaultThinkingLevel(), defaultLevel);
				} finally {
					release.resolve();
					await navigating;
					gate?.mock.restore();
				}
				assert.equal(f.outcomes[0].cancelled, false, String(f.outcomes[0]));
				f.session.setThinkingLevel("off");
				const before = f.session.sessionManager.getEntries().length;
				const result = change();
				assert.notEqual(f.session.thinkingLevel, "off");
				assert.equal(f.session.sessionManager.getEntries().length, before + 1);
				assert.equal(f.session.sessionManager.getLeafEntry().type, "thinking_level_change");
				if (operation === "cycleThinkingLevel") assert.equal(result, f.session.thinkingLevel);
				if (operation !== "extension setThinkingLevel")
					assert.equal(f.session.settingsManager.getDefaultThinkingLevel(), f.session.thinkingLevel);
			})"

