"test("reopening reconciles retained executions before exposing the branch and holds missing producers", async (t) => {
	const first = await fixture(t);
	const attachment = first.service.branch().attachment;
	await attachment.waits.registerWork("work", "lane", 0);
	await attachment.waits.shareWork("work", "lane", 1, "bg", 0);
	await attachment.waits.registerExecution(
		{
			producer: "bg",
			workId: "work",
			handle: "bg-1",
			execution: "exec",
			revision: 1,
			predicates: [{ until: "exit", state: "pending" }],
		},
		2,
		0,
	);
	await first.service.close();
	let failedSourceClosed = 0;
	const sourceErrors = [];
	const unavailable = await PiFlowSessionService.open(first.session, {
		...options(first.root),
		attachWaitSources: async (attachment) => {
			attachment.waitProducers.register(
				{
					version: 1,
					namespace: "bg",
					subscribe: () => () => {},
					snapshot: async () => {
						throw new Error("snapshot unavailable");
					},
					close: () => {
						failedSourceClosed++;
					},
				},
				(error) => sourceErrors.push(error),
			);
		},
	});
	t.after(() => unavailable.close());
	assert.deepEqual(unavailable.branch().waitSourceRecovery, { restored: 0, missing: ["bg"] });
	assert.equal(unavailable.branch().host.gate().recoveryBlocked, true);
	assert.equal(sourceErrors.length, 1);
	assert.match(sourceErrors[0].cause.message, /snapshot unavailable/);
	await unavailable.close();
	assert.equal(failedSourceClosed, 1);
	const manager = () => SessionManager.open(first.session.sessionManager.getSessionFile());
	const missing = await fixture(t, { root: first.root, manager: manager() });
	assert.deepEqual(missing.service.branch().waitSourceRecovery, { restored: 0, missing: ["bg"] });
	assert.equal(missing.service.branch().host.gate().recoveryBlocked, true);
	await missing.service.close();
	const entered = deferred(),
		proceed = deferred();
	const opening = fixture(t, {
		root: first.root,
		manager: manager(),
		attachWaitSources: async (attachment) => {
			attachment.waitProducers.register(
				{
					version: 1,
					namespace: "bg",
					subscribe: () => () => {},
					snapshot: async (identity) => {
						entered.resolve();
						await proceed.promise;
						return { ...identity, revision: 2, predicates: [{ until: "exit", state: "satisfied" }] };
					},
				},
				assert.ifError,
			);
		},
	});
	await entered.promise;
	let opened = false;
	void opening.then(() => {
		opened = true;
	});
	await new Promise((resolve) => setImmediate(resolve));
	assert.equal(opened, false);
	proceed.resolve();
	const restored = await opening;
	assert.deepEqual(restored.service.branch().waitSourceRecovery, { restored: 1, missing: [] });
	assert.equal(restored.service.branch().host.gate().recoveryBlocked, false);
	assert.equal(
		(await restored.service.branch().attachment.waits.authoritySnapshot()).executions[0].predicates[0].state,
		"satisfied",
	);
	assert.deepEqual(restored.requests, []);
})"

"test(`session controller binds ${ownership} selected work through native execution`, async (t) => {
		let branch, observed;
		const f = await fixture(t, {
			host: {
				maxPayloadBytes: 100000,
				containsUserInput: () => false,
			},
			onRequest() {
				observed = branch.workContext.current();
			},
		});
		branch = f.service.branch();
		if (ownership !== "unclassified")
			await branch.attachment.waits.registerWork(
				"selected-work",
				ownership === "foreign" ? "another-owner" : "lane",
				0,
			);
		branch.controller.register({
			version: 1,
			namespace: "lane",
			async snapshot() {
				return [
					{
						id: "instruction",
						revision: "1",
						producer: "lane",
						sequence: 1,
						rank: 4,
						workId: "selected-work",
						workRevision: "producer-revision",
						independent: false,
						runnable: true,
					},
				];
			},
			async build() {
				return { id: "instruction", revision: "1", kind: "work", text: "Perform the selected work" };
			},
		});
		await branch.controller.wake();
		assert.equal(f.requests.length, 1);
		// A registered work is attributed by identity alone; an unregistered one falls back to the branch host.
		assert.equal(observed?.id, ownership === "unclassified" ? automaticWorkId(branch.scope) : "selected-work");
		if (ownership !== "unclassified") assert.equal(observed.revision, 1);
		// Tools stay usable after the turn on the branch host identity.
		assert.equal(branch.workContext.current()?.id, automaticWorkId(branch.scope));
	})"

"test(`consumed ${lane} input reattributes tools to the branch host during the same native run`, async (t) => {
		let branch,
			calls = 0;
		const observed = [];
		const f = await fixture(t, {
			retainInputs: true,
			host: {
				maxPayloadBytes: 100000,
				containsUserInput: () => calls > 0,
			},
			async onRequest() {
				calls++;
				observed.push(branch.workContext.current()?.id);
				if (calls === 1) {
					await f.session.prompt("New user instructions", { streamingBehavior: lane });
					observed.push(branch.workContext.current()?.id);
				}
			},
		});
		branch = f.service.branch();
		await branch.attachment.waits.registerWork("selected-work", "lane", 0);
		branch.controller.register({
			version: 1,
			namespace: "lane",
			async snapshot() {
				return [
					{
						id: "instruction",
						revision: "1",
						producer: "lane",
						sequence: 1,
						rank: 4,
						workId: "selected-work",
						workRevision: "1",
						independent: false,
						runnable: true,
					},
				];
			},
			async build() {
				return { id: "instruction", revision: "1", kind: "work", text: "Perform selected work" };
			},
		});
		await branch.controller.wake();
		assert.equal(calls, 2);
		assert.equal(f.requests.length, 2);
		// The consumed input ends the selected work; the turn keeps a usable attribution.
		assert.equal(observed[0], "selected-work");
		assert.ok(observed.at(-1), "tools keep an attribution after consumption");
		assert.notEqual(observed.at(-1), "selected-work", "the consumed work is no longer selected");
	})"

"test(`compacted undelivered input recovers across clear and reopen: release=${release}`, async (t) => {
		const producers = await installedProducerExtensions();
		const f = await assembledSession(t, { persist: true, producerExtensions: producers });
		const store = f.ingress.branch().attachment.nativeRequests;
		const begin = store.begin.bind(store);
		store.begin = async () => {
			throw new FlowLedgerError("capacity", "Injected full native store");
		};
		await f.session.prompt("Old input that never reached the provider");
		store.begin = begin;
		assert.equal(f.bodies.length, 0);
		const undelivered = (await f.ingress.branch().attachment.submissions.snapshot()).find((record) =>
			JSON.stringify(record.submission).includes("Old input that never reached the provider"),
		);
		assert.ok(undelivered, "failed input remains available for inspection and explicit resubmission");
		assert.match(f.ingress.automatedPause(), /flow admission failed/);
		const manager = f.sessionManager;
		manager.appendCompaction("Earlier request failed before delivery.", manager.getLeafId(), 100);
		manager.flush();
		const file = manager.getSessionFile();
		const next = await replacedSession(t, f, {
			reason: "resume",
			persist: true,
			sessionManager: SessionManager.open(file),
			producerExtensions: producers,
		});
		if (release) await next.session.prompt("/flow clear");
		const recovered = (await next.ingress.branch().attachment.submissions.snapshot()).find(
			(record) => record.id === undelivered.id,
		);
		assert.deepEqual(
			recovered?.submission,
			undelivered.submission,
			"compaction/reset preserves the exact undelivered input",
		);
		await next.session.prompt("Continue with current input");
		await next.session.prompt("Another current input");
		assert.equal(next.bodies.length, 2);
		assert.ok(!JSON.stringify(next.bodies).includes("Old input that never reached the provider"));
		assert.equal((await next.ingress.branch().attachment.nativeRequests.reconciledSources()).size, 1);
		const after = await replacedSession(t, next, {
			reason: "resume",
			persist: true,
			sessionManager: SessionManager.open(file),
			producerExtensions: producers,
		});
		await after.session.prompt("Continue after another reopen");
		assert.equal(after.bodies.length, 1);
		const retained = (await after.ingress.branch().attachment.submissions.snapshot()).find(
			(record) => record.id === undelivered.id,
		);
		assert.deepEqual(
			retained?.submission,
			undelivered.submission,
			"a second reopen does not erase failed input or turn it into successful delivery",
		);
		assert.deepEqual(f.errors, []);
		assert.deepEqual(next.errors, []);
		assert.deepEqual(after.errors, []);
	})"

"test("terminal admission failure holds the next automated input without consuming retries", async (t) => {
	let endings = 0;
	const producers = await installedProducerExtensions();
	const f = await assembledSession(t, {
		producerExtensions: [
			...producers,
			{
				name: "retrying-producer",
				factory(pi) {
					pi.on("agent_end", () => {
						endings++;
						if (endings < 5) pi.sendUserMessage("Retry after failure", { deliverAs: "followUp" });
					});
				},
			},
		],
	});
	const store = f.ingress.branch().attachment.nativeRequests;
	const original = store.begin.bind(store);
	store.begin = async () => {
		throw new FlowLedgerError("capacity", "Injected full store");
	};
	await f.session.prompt("Trigger admission failure");
	await f.session.waitForIdle();
	assert.equal(endings, 1);
	assert.equal(f.bodies.length, 0);
	assert.match(f.ingress.automatedPause(), /flow admission failed/);
	const retained = await f.ingress.branch().attachment.submissions.snapshot();
	assert.ok(retained.some((record) => !record.dispatch?.promptClaims?.length));
	store.begin = original;
})"

