"test(`task context guard preserves input and receipt bytes: ${variant}`, async () => {
		const handlers = new Map(),
			saved = [],
			errors = [];
		let aborted = 0;
		const attempt = {
			id: "attempt",
			admission: { choice: { intent: { producer: "tasks" } } },
			members: [{ kind: "work" }, ...(variant === "results-joined" ? [{ kind: "result" }] : [])],
		};
		installTaskContextGuard(
			{
				on(name, handler) {
					handlers.set(name, handler);
				},
				appendEntry(customType, data) {
					saved.push({ type: "custom", customType, data });
				},
			},
			{
				activeAttempt: async () => attempt,
				valid: async () => variant === "valid",
				onError: (error) => errors.push(error),
			},
		);
		const ctx = {
			sessionManager: { getBranch: () => saved },
			ui: { notify() {} },
			abort() {
				aborted++;
				if (variant === "abort-throws") throw new Error("Cannot abort");
			},
		};
		await handlers.get("session_start")({}, ctx);
		const source = {
			role: "custom",
			customType: "jouzu-flow",
			content: "Exact original task bytes",
			details: { attemptId: "attempt" },
			display: true,
			timestamp: 1,
		};
		const user = { role: "user", content: [{ type: "text", text: JSON.stringify(source) }], timestamp: 2 };
		const messages = variant === "user-text" ? [user] : [source, ...(variant === "user-joined" ? [user] : [])];
		const before = JSON.stringify(messages);
		for (const message of messages) await handlers.get("message_start")({ message }, ctx);
		const result = await handlers.get("context")({ messages }, ctx);
		assert.equal(JSON.stringify(messages), before);
		for (const message of messages) assert.ok(result.messages.includes(message));
		assert.equal(aborted, ["stale-only", "abort-throws"].includes(variant) ? 1 : 0);
		assert.equal(errors.length, variant === "abort-throws" ? 1 : 0);
		if (["valid", "user-text"].includes(variant)) assert.deepEqual(result.messages, messages);
		else {
			assert.ok(result.messages.some((message) => message.customType === "jouzu-task-skipped"));
			assert.equal(saved.length, 1);
			await handlers.get("session_start")({}, ctx);
			const reopened = await handlers.get("context")({ messages }, ctx);
			assert.ok(reopened.messages.some((message) => message.customType === "jouzu-task-skipped"));
		}
	})"

"test(`installed task continuation cancels stale work queued at ${enqueueAt}`, { timeout: 15_000 }, async (t) => {
		const root = await mkdtemp(join(tmpdir(), "jouzu-task-continuation-"));
		afterFlowCleanup(t, () => rm(root, { recursive: true, force: true }));
		await mkdir(join(root, ".pi"));
		await writeFile(
			join(root, ".pi/tasks-config.json"),
			JSON.stringify({ autoMode: "cascade", autoClearCompleted: "never" }),
		);
		const taskFile = join(root, "tasks.json");
		const description = "Preserve this task's original instruction 日本語";
		const captured = deferred(),
			requested = deferred(),
			releaseResponse = deferred(),
			cancelled = deferred();
		let host,
			pending,
			inAgentEnd = false,
			builds = 0,
			consumed = 0;
		const complete = () => {
			const saved = JSON.parse(readFileSync(taskFile, "utf8"));
			assert.equal(saved.tasks.length, 1);
			saved.tasks[0].status = "completed";
			saved.tasks[0].updatedAt++;
			writeFileSync(taskFile, JSON.stringify(saved));
		};
		const enqueueThenComplete = () => {
			host.submit(pending);
			complete();
		};
		const f = await assembledSession(t, {
			root,
			producerExtensions: [
				{
					name: "observe-installed-task-submission",
					factory(pi) {
						pi.on("agent_start", () => {
							inAgentEnd = false;
						});
						pi.on("agent_end", () => {
							inAgentEnd = true;
						});
						pi.events.on("jouzu:task-flow", (request) => {
							const accept = request.accept;
							request.accept = (value) => {
								host = value;
								accept({
									...value,
									submit(input) {
										assert.equal(pending, undefined, "the installed extension submits one continuation");
										assert.equal(inAgentEnd, true, "capture the installed extension's agent_end submission");
										pending = {
											...input,
											build() {
												builds++;
												return input.build();
											},
											consumed() {
												consumed++;
												input.consumed();
											},
											cancelled() {
												input.cancelled();
												cancelled.resolve();
											},
										};
										if (enqueueAt === "agent_end") enqueueThenComplete();
										captured.resolve();
									},
								});
							};
						});
					},
				},
				...(await installedProducerExtensions()),
				await installedTaskExtension(taskFile),
			],
			script: async (_body, index) => {
				if (index === 0)
					return assistantToolCalls({ name: "TaskCreate", arguments: { subject: "A task", description } });
				if (index === 2 && enqueueAt === "streaming") {
					requested.resolve();
					await releaseResponse.promise;
				}
				return { text: "Done" };
			},
		});
		afterFlowCleanup(t, () => releaseResponse.resolve());
		assert.ok(host, "the installed task extension must complete its Jouzu adapter handshake");
		await f.session.prompt("Create the task");
		await captured.promise;
		if (enqueueAt === "streaming") {
			// Delay only delivery of the real installed extension's request until a user response is active.
			const active = f.session.prompt("Answer this separate user request");
			await requested.promise;
			assert.equal(f.session.agent.state.isStreaming, true);
			enqueueThenComplete();
			releaseResponse.resolve();
			await active;
		}
		await cancelled.promise;
		await f.session.waitForIdle();
		const expected = enqueueAt === "streaming" ? 3 : 2;
		assert.equal(f.bodies.length, expected, "stale continuation sends no extra HTTP request");
		assert.equal(builds, 0, "stale work is cancelled before its prompt is built");
		assert.equal(consumed, 0);
		assert.equal(f.ingress.automatedPause(), undefined);
		const task = JSON.parse(readFileSync(taskFile, "utf8")).tasks[0];
		assert.equal(task.status, "completed");
		assert.equal(task.description, description, "cancellation preserves stored source text");
		await f.session.prompt("Explain the completed result");
		assert.equal(f.bodies.length, expected + 1);
		assert.ok(JSON.stringify(f.bodies.at(-1)).includes("Explain the completed result"));
		assert.deepEqual(f.errors, []);
	})"

"test("task live-predicate upgrade replaces only the pinned preceding runtime", async (t) => {
	const root = await mkdtemp(join(tmpdir(), "jouzu-task-upgrade-"));
	t.after(() => rm(root, { recursive: true, force: true }));
	await mkdir(join(root, "src"));
	for (const path of ["package.json", "src/index.ts"])
		await writeFile(join(root, path), await readFile(new URL(path, installed)));
	const runtime = await readFile(new URL("src/jouzu-flow.ts", installed), "utf8");
	// The preceding release routed through the host whenever it was accepted, so its runtime is this
	// one without the live predicate.
	const previous = runtime
		.replace(
			"\t/** Flow control is on for this session. Absent on older hosts, which are treated as live. */\n\tlive?(): boolean;\n",
			"",
		)
		.replace(
			"\t\t\t// While flow control is off the task store drives its own continuations, exactly as it does\n\t\t\t// in a session where flow control was never attached.\n\t\t\tif (!active || active.live?.() === false) return false;",
			"\t\t\tif (!active) return false;",
		)
		.replace(
			"return active && active.live?.() !== false ? active.tool(tool.name, args, invoke) : invoke();",
			"return active ? active.tool(tool.name, args, invoke) : invoke();",
		);
	assert.notEqual(previous, runtime);
	const lock = JSON.parse(
		await readFile(new URL("../../../upstream/task-flow/patch.lock.json", import.meta.url), "utf8"),
	);
	assert.equal(createHash("sha256").update(previous).digest("hex"), lock.previousRuntime);
	await writeFile(join(root, "src/jouzu-flow.ts"), previous);
	await assert.rejects(applyTaskFlow(root, true), /differs/);
	assert.equal(await readFile(join(root, "src/jouzu-flow.ts"), "utf8"), previous);
	assert.equal(await applyTaskFlow(root), 1);
	assert.equal(await readFile(join(root, "src/jouzu-flow.ts"), "utf8"), runtime);
	assert.equal(await applyTaskFlow(root, true), 0);
})"

