"test("continuous tools cross native byte and record quotas after compaction without waiting for idle @endurance", {
	timeout: 120000,
}, async (t) => {
	const turns = 1120;
	let tools = 0;
	let compactions = 0;
	let endings = 0;
	let peak = 0;
	const observed = new Map();
	const producers = await installedProducerExtensions();
	const f = await assembledSession(t, {
		persist: true,
		settings: { compaction: { enabled: true, reserveTokens: 512, keepRecentTokens: 7505 } },
		producerExtensions: [
			...producers,
			{
				name: "tool-retention",
				factory(pi) {
					pi.registerTool({
						name: "step",
						label: "Step",
						description: "Return fixture data.",
						parameters: { type: "object", properties: {} },
						async execute() {
							tools++;
							const records = await f.ingress.branch().attachment.nativeRequests.snapshot();
							peak = Math.max(peak, records.length);
							for (const record of records) observed.set(record.id, record);
							return {
								content: [{ type: "text", text: tools % 20 === 1 ? "data ".repeat(6000) : "done" }],
								details: {},
							};
						},
					});
					pi.on("agent_end", () => {
						endings++;
					});
					pi.on("session_before_compact", (event) => {
						compactions++;
						return {
							compaction: {
								summary: "Continue the tool sequence.",
								firstKeptEntryId: "",
								tokensBefore: event.preparation.tokensBefore,
							},
						};
					});
				},
			},
		],
		script: (_body, index) =>
			index < turns ? { toolCalls: [{ id: `step-${index}`, name: "step", arguments: {} }] } : { text: "Finished." },
	});
	await f.session.prompt("Run the tool sequence.");
	await f.session.waitForIdle();
	assert.equal(f.bodies.length, turns + 1, f.session.agent.state.errorMessage);
	assert.equal(tools, turns);
	assert.equal(endings, 1, "there was no idle turn boundary during the tool sequence");
	assert.ok(compactions > 1);
	const empty = [...observed.values()].filter(
		(r) => !r.sourceCapture?.members.length && !r.projectionCapture?.members.length,
	);
	assert.ok(empty.length > 1024, `crossed record quota: ${empty.length}`);
	assert.ok(Buffer.byteLength(JSON.stringify(empty)) > 1024 * 1024, "crossed the actual byte quota");
	assert.ok(peak <= 70, `request history is bounded before idle cleanup: ${peak}`);
	assert.equal(f.ingress.automatedPause(), undefined);
	assert.deepEqual(f.errors, []);
	const history = f.sessionManager.getSessionFile();
	await f.shutdown("resume", history);
	const reopened = await assembledSession(t, {
		root: f.root,
		persist: true,
		producerExtensions: producers,
		sessionManager: SessionManager.open(history),
	});
	await reopened.session.prompt("Continue after the tool sequence.");
	assert.equal(reopened.bodies.length, 1, reopened.session.agent.state.errorMessage);
	assert.deepEqual(reopened.errors, []);
})"

"test(`tools remain usable after ${transition} with fresh work attribution`, {
		timeout: 15000,
	}, async (t) => {
		let active;
		const observations = [];
		const extensions = [
			...(await installedProducerExtensions()),
			{
				name: "transition-ownership",
				factory(pi) {
					pi.registerTool({
						name: "ownership_probe",
						label: "Ownership probe",
						description: "Capture fixture ownership and its lifetime.",
						parameters: { type: "object", properties: {} },
						async execute() {
							const branch = active.ingress.branch();
							const work = branch.workContext.current();
							assert.ok(work);
							observations.push({ work, scope: branch.scope });
							return { content: [{ type: "text", text: "verified" }], details: {} };
						},
					});
				},
			},
		];
		const script = (_body, index) =>
			index % 2 === 0 ? { toolCalls: [{ name: "ownership_probe", arguments: {} }] } : { text: "Finished." };
		active = await assembledSession(t, { persist: true, producerExtensions: extensions, script });
		await active.session.prompt("Verify fixture ownership.");
		assert.equal(observations.length, 1);
		const first = active;
		const history = first.sessionManager.getSessionFile();
		if (transition === "tree") {
			const user = first.sessionManager
				.getBranch()
				.find((entry) => entry.type === "message" && entry.message.role === "user");
			await first.session.navigateTree(user.id);
		} else {
			const sessionManager =
				transition === "resume"
					? SessionManager.open(history)
					: transition === "fork"
						? SessionManager.forkFrom(history, first.root)
						: undefined;
			active = await replacedSession(t, first, {
				reason: transition,
				sessionManager,
				persist: true,
				producerExtensions: extensions,
				script,
			});
		}
		await active.session.prompt("Verify fixture ownership.");
		assert.equal(
			observations.length,
			2,
			JSON.stringify(active.session.messages.filter((message) => message.role === "toolResult")),
		);
		assert.notEqual(observations[0].work.id, observations[1].work.id);
		assert.equal(
			observations[0].scope.sessionId === observations[1].scope.sessionId,
			transition === "resume" || transition === "tree",
		);
		assert.equal(observations[0].scope.branchId === observations[1].scope.branchId, transition === "resume");
		assert.ok(active.ingress.branch().workContext.current(), "idle tools retain session attribution");
		assert.deepEqual(active.errors, []);
	})"

"test("retrying an interrupted turn makes its work eligible again", async (t) => {
	const { ledger } = await attached(t);
	await interrupted(ledger);
	await ledger.resolveUncertain("attempt", "retry", "Resolved from /flow as undelivered.");
	const [attempt] = (await ledger.snapshot()).attempts;
	// Cancelled rather than settled: this attempt did not succeed, so the work behind it is offered
	// again. The user accepted that the provider may already have answered the first send.
	assert.equal(attempt.phase, "cancelled");
	assert.equal(attempt.outcome, undefined);
	assert.equal(attempt.reason, "Resolved from /flow as undelivered.");
	assert.equal(attempt.requests[0].handedOff, true, "the handed-off request stays on the record");
})"

"test("discarding an interrupted turn settles it so nothing runs again", async (t) => {
	const { ledger } = await attached(t);
	await interrupted(ledger);
	await ledger.resolveUncertain("attempt", "discard", "Resolved from /flow as spent.");
	const [attempt] = (await ledger.snapshot()).attempts;
	assert.equal(attempt.phase, "settled");
	assert.equal(attempt.outcome, "failure");
	assert.equal(attempt.reason, "Resolved from /flow as spent.");
})"

"test("only an uncertain attempt can be resolved, and only into a known resolution", async (t) => {
	const { ledger } = await attached(t);
	await ledger.select("attempt", [member]);
	await assert.rejects(ledger.resolveUncertain("attempt", "retry", "too early"), { code: "transition" });
	await ledger.queued("attempt", { id: "queue", revision: 1 });
	await ledger.claim("attempt", { id: "queue", revision: 1 });
	await ledger.prepare("attempt", "request", included, false);
	await ledger.handoff("attempt", "request");
	await ledger.uncertain("attempt", "unknown outcome");
	assert.throws(() => ledger.resolveUncertain("attempt", "guess", "invalid"), { code: "schema" });
	await assert.rejects(ledger.resolveUncertain("missing", "retry", "unknown attempt"), { code: "identity" });
	await ledger.resolveUncertain("attempt", "discard", "settled by the user");
	// One decision only: a resolved attempt is terminal and cannot be resolved a second way.
	await assert.rejects(ledger.resolveUncertain("attempt", "retry", "again"), { code: "transition" });
})"

"test("a resolved attempt survives reattachment with its decision", async (t) => {
	const root = await mkdtemp(join(tmpdir(), "jouzu-uncertain-reopen-"));
	t.after(() => rm(root, { recursive: true, force: true }));
