"test("a bind failure during rebind withdraws the target and recovers on the next branch change", async () => {
	const f = await harness();
	await f.invoke("session_start", { type: "session_start", reason: "startup" });
	const bind = f.adapter.bind;
	let fail = true;
	f.adapter.bind = async () => {
		if (fail) {
			fail = false;
			throw Object.assign(new Error("Target is not attached"), { code: "target-unavailable" });
		}
		return bind();
	};
	await f.invoke("session_tree", { type: "session_tree", newLeafId: "leaf-2", oldLeafId: "leaf-1" });
	// The withdrawn target is not republished, and the failure is reported to the client and the user.
	assert.deepEqual(f.client.state.bindings, [BINDING, undefined]);
	assert.deepEqual(f.client.state.failures, [{ code: "target-unavailable", text: "Target is not attached" }]);
	assert.equal(f.notifications.length, 1);
	assert.equal(f.notifications[0].level, "error");
	assert.equal(f.calls.subscribe, 1);
	assert.equal(f.calls.unsubscribe, 1);
	await f.invoke("session_tree", { type: "session_tree", newLeafId: "leaf-3", oldLeafId: "leaf-2" });
	// The failed attempt never reached the adapter's own bind, so only the retry increments it.
	assert.equal(f.calls.bind, 2);
	assert.deepEqual(f.client.state.bindings, [BINDING, undefined, BINDING]);
	assert.equal(f.calls.subscribe, 2);
	f.client.deliver(message("after-failure"));
	await until(
		() => f.calls.submit.some((input) => input.messageId === "after-failure"),
		"delivery did not resume after the failed bind was retried",
	);
})"

"test("canonical identity drift cannot authorize an old handle or its retained input", async (t) => {
	let allowed = false;
	const f = await setup(t, { register: false, admit: async () => allowed });
	const other = join(f.agentDir, "other.ts");
	const alias = join(f.agentDir, "alias.ts");
	await writeFile(other, "export default () => {};\n");
	await symlink(f.extensionId, alias);
	f.adapter = await f.register({ extensionId: alias });
	f.binding = await f.adapter.bind();
	assert.equal((await f.adapter.submit(input(f))).state, "held");
	const [record] = await externalRecords(f);
	await unlink(alias);
	await symlink(other, alias);
	await f.writeGrants([{ extensionPath: await realpath(other), adapterId: "fixture" }]);
	await assert.rejects(f.adapter.bind(), { code: "unauthorized" });
	await assert.rejects(lookup(f, "one"), { code: "unauthorized" });
	await assert.rejects(f.adapter.submit(input(f, "two")), { code: "unauthorized" });
	await assert.rejects(
		f.ingress.authorizeExternal(
			record.submission,
			await f.ingress.branch().attachment.submissions.externalTargetEpoch(),
		),
		{ code: "unauthorized" },
	);
	allowed = true;
	assert.equal(await f.ingress.release(record.id, record.revision), false);
	await f.ingress.joinPendingOperations();
	const [cancelled] = await externalRecords(f);
	assert.equal(cancelled.status, "cancelled");
	assert.equal(cancelled.cancellationReason, "unauthorized");
	assert.equal(f.sent.length, 0);
	const replacement = await f.register({ extensionId: alias });
	assert.equal(await replacement.lookup({ target: f.binding.target, messageId: "one" }), undefined);
})"

"test("a first authorization fault records a visible hold without a prior policy hold", async (t) => {
