			gate.resolve();
			finish.resolve();
		});
		const f = await commandFixture(t, {
			admit: async () => !holding,
			extensions: [
				(pi) =>
					pi.registerCommand("park", {
						handler: async () => {
							entered.resolve();
							await finish.promise;
						},
					}),
			],
		});
		const store = f.ingress.branch().attachment.submissions;
		let admitting = false;
		const admit = f.ingress.admit.bind(f.ingress);
		t.mock.method(f.ingress, "admit", async (...args) => {
			admitting = true;
			try {
				return await admit(...args);
			} finally {
				admitting = false;
			}
		});
		let recordId,
			parkedOnce = false;
		const authorize = f.ingress.external.authorize.bind(f.ingress.external);
		t.mock.method(f.ingress.external, "authorize", async (...args) => {
			const granted = await authorize(...args);
			if (!admitting && !parkedOnce && f.ingress.pending.get(recordId)?.running) {
				parkedOnce = true;
				parked.resolve();
				await gate.promise;
			}
			return granted;
		});
		assert.equal((await f.adapter.submit(input(f.binding, "queued"))).state, "held");
		const [record] = await externalRecords(store);
		recordId = record.id;
		holding = false;
		const released = f.ingress.release(record.id, record.revision);
		await parked.promise;
		const competing =
			owner === "command"
				? f.session.prompt("/park")
				: f.ingress.branch().workContext.run(undefined, async () => {
						entered.resolve();
						await finish.promise;
					});
		await entered.promise;
		gate.resolve();
		try {
			assert.equal(await released, owner === "command");
			if (owner === "invocation") {
				const [held] = await externalRecords(store);
				assert.equal(held.status, "retained");
				assert.equal(held.unavailable, undefined);
				assert.equal(held.dispatch, undefined);
				assert.equal(f.ingress.pending.has(record.id), true);
				assert.equal(
					(await f.ingress.branch().attachment.waits.authoritySnapshot()).work.some((work) =>
						work.userInputs?.some((source) => source.id === record.id),
					),
					false,
				);
				assert.equal(f.sent.length, 0);
			} else {
				assert.equal(f.ingress.pending.has(record.id), false);
				assert.equal((await f.adapter.lookup({ target: f.binding.target, messageId: "queued" })).state, "consumed");
				assert.equal(f.sent.length, 1);
			}
		} finally {
			finish.resolve();
			await competing;
		}
		if (owner === "invocation") assert.equal(await f.ingress.release(record.id, record.revision), true);
		await f.ingress.joinPendingOperations();
		assert.equal((await f.adapter.lookup({ target: f.binding.target, messageId: "queued" })).state, "consumed");
		assert.equal((await f.adapter.submit(input(f.binding, "queued"))).state, "consumed");
		await f.ingress.joinPendingOperations();
		assert.equal(f.sent.length, 1);
		assert.equal(
			(await f.ingress.branch().attachment.waits.authoritySnapshot()).work.filter((work) =>
				work.userInputs?.some((source) => source.id === record.id),
			).length,
			1,
			"delivery must create exactly one user-work claim",
		);
	})"

"test("a crash after external retention reopens without replay and retries only on request", {
	timeout: 30000,
}, async (t) => {
	const message = await crash(t, "retained");
	const f = await reopen(t, message);
	// The stable target survives the process death, so the same client identity reattaches.
	assert.equal(f.binding.target, message.target);
	await f.session.waitForIdle();
	await delay(50);
	assert.equal(f.sent.length, 0, "reopening replayed the retained external message");
	const before = await receipt(f, message);
	assert.equal(before.state, "unknown");
	assert.equal(before.reason.code, "callback-ended");
	const [retained] = (await f.ingress.branch().attachment.submissions.snapshot(false)).filter(
		(item) => item.submission.externalUser,
	);
	assert.equal(retained.dispatch, undefined, "the crash left dispatch intent behind");
	assert.equal(retained.unavailable, "callback-ended");
	// The explicit retry is authorized by the same target and reattaches before any intent exists.
	const retried = await f.adapter.submit(retry(f, message));
	assert.notEqual(retried.state, "unknown");
	await f.ingress.joinPendingOperations();
	assert.equal((await receipt(f, message)).state, "consumed");
	assert.equal(f.sent.length, 1, "the explicit retry did not dispatch exactly once");
})"

"test("a crash after external dispatch intent stays unknown and is never resent", { timeout: 30000 }, async (t) => {
	const message = await crash(t, "intent");
	const f = await reopen(t, message);
	assert.equal(f.binding.target, message.target);
	await f.session.waitForIdle();
	await delay(50);
	assert.equal(f.sent.length, 0, "reopening dispatched a prior-intent external message");
	const before = await receipt(f, message);
	assert.equal(before.state, "unknown");
	assert.equal(before.reason.code, "dispatch-unconfirmed");
	const [pending] = (await f.ingress.branch().attachment.submissions.snapshot(false)).filter(
		(item) => item.submission.externalUser,
	);
	assert.equal(pending.dispatch.phase, "started");
	assert.equal(pending.dispatch.inputs, undefined);
	// A retry reports the same unconfirmed receipt and never writes a second intent or dispatches.
	const retried = await f.adapter.submit(retry(f, message));
	assert.equal(retried.state, "unknown");
	assert.equal(retried.reason.code, "dispatch-unconfirmed");
	await f.ingress.joinPendingOperations();
	await delay(50);
	assert.equal(f.sent.length, 0);
	const [unchanged] = (await f.ingress.branch().attachment.submissions.snapshot(false)).filter(
		(item) => item.submission.externalUser,
	);
	assert.equal(unchanged.revision, pending.revision);
	assert.equal(unchanged.dispatch.phase, "started");
})"

