"test("a health scan that overlaps wait declaration reconciles at or after wait creation", async () => {
	const scope = { sessionId: "session", branchId: "branch" };
	const handle = { producer: "bg", handle: "bg-1", execution: "exec-1", until: "exit", health: "health-v1" };
	const waitRequest = {
		token: "wait",
		scope,
		workId: "work",
		reason: "Wait for the process",
		mode: "all",
		on: [handle],
		expiresAt: 200,
	};
	let wait = createFlowWait(waitRequest, [{ ...handle, scope, workId: "work", state: "pending" }], 100, 1_000);
	const execution = {
		producer: "bg",
		workId: "work",
		handle: "bg-1",
		execution: "exec-1",
		revision: 1,
		predicates: [{ until: "exit", state: "pending" }],
		observedAt: 0,
		healthSince: 0,
		healthEvidence: { policy: "health-v1", revision: 1, observedAt: 0, state: "unhealthy", detail: "stopped" },
	};
	let release;
	let start;
	const gate = new Promise((resolve) => (release = resolve));
	const started = new Promise((resolve) => (start = resolve));
	const observedAt = [];
	const store = {
		async snapshot() {
			start();
			await gate;
			return wait.state === "waiting" ? [wait] : [];
		},
		async authoritySnapshot() {
			await gate;
			return { executions: [execution] };
		},
		async observeWaitHealth(_token, _handle, _execution, state, now) {
			observedAt.push(now);
			assert.ok(now >= wait.createdAt, "health reconciliation must not predate wait creation");
			wait = { ...wait, state, endedAt: now };
			return true;
		},
	};
	let clockReads = 0;
	const monitor = new FlowWaitHealthMonitor({
		store,
		policy: () => policy({ name: "health-v1", evidence: "health evidence", freshnessMs: 1, graceMs: 0, cadenceMs: 1 }),
		probe: async () => {},
		clock: {
			now: () => (clockReads++ === 0 ? 99 : 100),
			after: () => {
				throw new Error("unexpected health timer");
			},
		},
		onError: (error) => {
			throw error;
		},
	});
	const running = monitor.refresh();
	await started;
	release();
	await running;
	await monitor.stop();
	assert.deepEqual(observedAt, [100]);
})"

"test("a policy the host cannot act on is rejected at registration", () => {
	assert.deepEqual(validateFlowHealthPolicy(policy()), policy());
	for (const [field, value] of [
		["name", ""],
		["evidence", "   "],
		["freshnessMs", 0],
		["probeTimeoutMs", -1],
		["cadenceMs", 1.5],
		["graceMs", -1],
	])
		assert.throws(() => validateFlowHealthPolicy(policy({ [field]: value })), { code: "schema" }, `${field}`);
	// A cadence past freshness would call every healthy execution stale at its own next check.
	assert.throws(() => validateFlowHealthPolicy(policy({ cadenceMs: 60_001 })), {
		code: "schema",
		message: /cadence must not exceed/,
	});
	assert.doesNotThrow(() => validateFlowHealthPolicy(policy({ cadenceMs: 60_000, graceMs: 0 })));
	// Extra producer fields are dropped rather than retained, so stored policies stay comparable.
	assert.equal(validateFlowHealthPolicy({ ...policy(), extra: "x" }).extra, undefined);
})"

"test("replayed or reordered evidence cannot refresh health", () => {
	const first = retainFlowHealthEvidence(undefined, evidence({ revision: 4, observedAt: 4_000 }));
	assert.equal(first.revision, 4);
	// Equal and lower revisions are replays; the retained observation stands.
	assert.equal(retainFlowHealthEvidence(first, evidence({ revision: 4, observedAt: 9_000 })), first);
	assert.equal(retainFlowHealthEvidence(first, evidence({ revision: 3, observedAt: 9_000 })), first);
	assert.equal(retainFlowHealthEvidence(first, evidence({ revision: 5, observedAt: 5_000 })).revision, 5);
	assert.throws(() => retainFlowHealthEvidence(first, evidence({ policy: "other" })), { code: "identity" });
	for (const invalid of [
		{ revision: -1 },
		{ observedAt: 1.5 },
		{ state: "maybe" },
		{ marker: "" },
		{ detail: "x".repeat(4097) },
	])
		assert.throws(() => retainFlowHealthEvidence(undefined, evidence(invalid)), { code: "schema" });
})"

"test("fresh evidence keeps the wait live and schedules the next check by cadence", () => {
	const verdict = assessFlowHealth(policy(), evidence({ observedAt: 1_000 }), 1_000, 0, 1_000_000);
	assert.equal(verdict.state, "healthy");
	assert.equal(verdict.evidence, "sweep step counter");
	// Cadence first, but never past the moment the evidence itself goes stale.
	assert.equal(verdict.nextCheckAt, 31_000);
	assert.equal(assessFlowHealth(policy({ cadenceMs: 60_000 }), evidence(), 55_000, 0, 1_000_000).nextCheckAt, 61_000);
})"

"test("an explicit producer failure ends the wait without waiting out its grace", () => {
	const verdict = assessFlowHealth(
		policy(),
		evidence({ state: "unhealthy", detail: "step counter went backwards" }),
		1_000,
		0,
		1_000_000,
	);
	assert.deepEqual(verdict, {
		state: "unhealthy",
		evidence: "sweep step counter",
		reason: "step counter went backwards",
	});
	// Without detail the decision still names the evidence it acted on.
	assert.match(assessFlowHealth(policy(), evidence({ state: "unhealthy" }), 1_000, 0, 1_000_000).reason, /unhealthy/);
})"

"test("stale evidence ends the wait only after its bounded probe and grace", () => {
	const stale = evidence({ observedAt: 1_000 });
	// Stale at 61_000; probe 5_000 and grace 10_000 push the decision to 76_000.
	assert.equal(assessFlowHealth(policy(), stale, 60_999, 0, 1_000_000).state, "healthy");
	const probing = assessFlowHealth(policy(), stale, 61_000, 0, 1_000_000);
	assert.equal(probing.state, "healthy", "staleness alone is not a decision");
	assert.equal(probing.nextCheckAt, 76_000, "the next check is when grace runs out");
	assert.equal(assessFlowHealth(policy(), stale, 75_999, 0, 1_000_000).state, "healthy");
	const unknown = assessFlowHealth(policy(), stale, 76_000, 0, 1_000_000);
	assert.equal(unknown.state, "health-unknown");
	assert.match(unknown.reason, /last reported at 1000/);
})"

"test("an execution that never reports is judged from when evidence was first expected", () => {
	// `since` is registration or reattachment, so a restart does not restart the grace from zero.
	const never = assessFlowHealth(policy(), undefined, 76_000, 0, 1_000_000);
	assert.equal(never.state, "health-unknown");
	assert.match(never.reason, /never reported/);
	assert.equal(assessFlowHealth(policy(), undefined, 76_000, 10_000, 1_000_000).state, "healthy");
	// Evidence older than the moment the policy started applying cannot backdate the grace window.
	const backdated = assessFlowHealth(policy(), evidence({ observedAt: 0 }), 80_000, 20_000, 1_000_000);
	assert.equal(backdated.state, "healthy");
})"

"test("health never renews the hard deadline", () => {
	const expiresAt = 20_000;
	const verdict = assessFlowHealth(policy(), evidence({ observedAt: 1_000 }), 1_000, 0, expiresAt);
	assert.equal(verdict.state, "healthy");
	// The check itself is scheduled by cadence, but nothing past expiry is ever scheduled.
	assert.equal(nextFlowHealthCheck(verdict, expiresAt), undefined, "no check is scheduled past the deadline");
	assert.equal(nextFlowHealthCheck(verdict, 40_000), 31_000);
	for (const state of ["unhealthy", "health-unknown"])
		assert.equal(nextFlowHealthCheck({ state, reason: "r", evidence: "e" }, 1_000_000), undefined);
})"

"test("assessment refuses evidence from another policy or an invalid clock", () => {
	assert.throws(() => assessFlowHealth(policy(), evidence({ policy: "other" }), 1, 0, 2), { code: "identity" });
	for (const [now, since, expires] of [
		[-1, 0, 2],
		[1, -1, 2],
		[1, 0, -2],
	])
		assert.throws(() => assessFlowHealth(policy(), undefined, now, since, expires), { code: "schema" });
	assert.throws(() => assessFlowHealth(policy({ freshnessMs: 0 }), undefined, 1, 0, 2), { code: "schema" });
})"

"test(`${api}: successful tool observation absorbs immediate wait resolution without another wake and survives reopening`, async (t) => {
		const f = await fixture(t, { automatic: true, api });
		await f.session.prompt("wait for the finished process");
		await f.ingress.wakeProducers();
		await tick();
		await tick();
		assert.equal(f.sent.length, 2);
		const attachment = f.ingress.branch().attachment;
		assert.equal((await attachment.waits.snapshot())[0].state, "resolved");
		assert.equal((await attachment.waits.toolReceipts()).length, 1);
		const records = await attachment.nativeRequests.snapshot();
		assert.equal(records[1].projectionCapture.members[0].message.role, "toolResult");
		assert.deepEqual(records[1].requiredProjections, []);
		assert.equal(records[1].projectionCapture.model.members[0].status, "converted");
		assert.equal(toolRows(f.sent[1]).length, 1);
		if (api === "openai-codex-responses") {
			assert.equal(f.sent[0].type, "response.create");
			assert.equal(f.sent[1].previous_response_id, "response_1");
		}
		assert.deepEqual(await f.decisions(), []);
		assert.deepEqual(f.errors, []);
		await f.ingress.dispose();
		const next = await fixture(t, {
			root: f.root,
			api,
			manager: SessionManager.open(f.session.sessionManager.getSessionFile()),
			automatic: true,
			issueTool: false,
		});
		await next.ingress.wakeProducers();
		await tick();
		assert.deepEqual(next.sent, []);
		assert.deepEqual(await next.decisions(), []);
		await next.session.prompt("status");
		assert.equal(next.sent.length, 1);
		assert.equal(
			payloadRows(next.sent[0]).filter(
				(message) => message.role === "user" && JSON.stringify(message.content).includes("waitDecisions"),
			).length,
			0,
		);
		await next.ingress.dispose();
	})"

"test(`${api}: a later user prompt observes the pending decision through required wait context`, async (t) => {
		// A failed request delivered nothing, which is what leaves a decision pending. A provider body
		// mutated after model conversion no longer does: the controller trusts conversion from that
		// checkpoint on, so it cannot see the mutation.
		const f = await fixture(t, { api, failure: true });
		await f.session.prompt("wait");
		assert.equal((await f.decisions()).length, 1);
		await f.session.prompt("status");
		assert.equal(f.sent.length, 3);
		assert.ok(
			payloadRows(f.sent[2]).some(
				(message) => message.role === "user" && JSON.stringify(message.content).includes("waitDecisions"),
			),
		);
		assert.deepEqual(await f.decisions(), []);
		assert.deepEqual(f.errors, []);
	})"

"test(`${api}: ${mode} required user content after conversion still transmits`, async (t) => {
			const f = await fixture(t, {
				api,
				issueTool: false,
				change(payload) {
					const row = payloadRows(payload).find((message) => message.role === "user");
					if (mode === "changed")
						row.content = [
							{
								type: ["openai-responses", "openai-codex-responses", "azure-openai-responses"].includes(api)
									? "input_text"
									: "text",
								text: "replaced",
							},
						];
					if (mode === "omitted")
						container(payload)[
							["openai-responses", "openai-codex-responses", "azure-openai-responses"].includes(api)
								? "input"
								: "messages"
						] = payloadRows(payload).filter((message) => message !== row);
					if (mode === "cloned")
						return api === "pi-messages" ? JSON.parse(JSON.stringify(payload)) : structuredClone(payload);
				},
			});
			await f.session.prompt("required user instruction");
			// The mutation happens after model conversion, which the controller trusts, so the request
			// is transmitted and recorded rather than withheld. Required content is judged at
			// conversion instead, where this instruction arrived intact.
			assert.equal(f.sent.length, 1);
			const [record] = await f.ingress.branch().attachment.nativeRequests.snapshot();
			assert.equal(record.outcome, "success");
			assert.ok(record.requiredSources.length > 0);
			assert.equal(record.sourceCapture.model.members[0].status, "intact");
			assert.ok(record.payload.bytes > 0, "the transmitted body is still bounded and identified");
			assert.deepEqual(f.errors, []);
		})"

"test(`${api}: ${mode} tool payload keeps its wait decision pending`, async (t) => {
			const f = await fixture(t, {
				api,
				failure: mode === "failed",
				change:
					mode === "failed"
						? undefined
						: (payload) => {
								const block = toolRows(payload)[0];
								const tool = api === "bedrock-converse-stream" ? block?.toolResult : block;
								if (!tool) return;
								if (mode === "content")
									tool[
										["openai-responses", "openai-codex-responses", "azure-openai-responses"].includes(api)
											? "output"
											: "content"
									] += " altered";
								if (mode === "identity")
									tool[
										api === "bedrock-converse-stream"
											? "toolUseId"
											: api === "anthropic-messages"
												? "tool_use_id"
												: ["openai-responses", "openai-codex-responses", "azure-openai-responses"].includes(api)
													? "call_id"
													: ["mistral-conversations", "pi-messages"].includes(api)
														? "toolCallId"
														: "tool_call_id"
									] += "-other";
								if (mode === "omitted") omitTools(payload);
							},
			});
			await f.session.prompt("wait");
			assert.equal(f.sent.length, 2);
			const record = (await f.ingress.branch().attachment.nativeRequests.snapshot())[1];
			assert.equal(record.outcome, mode === "failed" ? "failure" : "success");
			// Every mode here mutates the provider body after model conversion, so the adapter received
			// the decision intact in each one.
			assert.equal(record.projectionCapture.model.members[0].status, "converted");
			// Only the failed request leaves the decision pending. The other three are the accepted
			// trust boundary: a transform after model conversion is not visible to the controller, so
			// the decision is acknowledged even though the provider never received it as composed.
			assert.equal((await f.decisions()).length, mode === "failed" ? 1 : 0);
			assert.deepEqual(f.errors, []);
		})"

"test("provider maps retained tool results and leaves synthetic orphan results unobserved", () => {
	const call = assistant();
	call.content = [{ type: "toolCall", id: "orphan", name: "agent_wait", arguments: args }];
	call.stopReason = "toolUse";
	const user = { role: "user", content: "continue", timestamp: 2 };
	const observed = [];
	const rows = convertMessages(
		model,
		{ messages: [call, user] },
		{},
		{
			onMessageConverted: (source, output) => observed.push({ source, output }),
		},
	);
	assert.equal(rows.filter((row) => row.role === "tool").length, 1);
	assert.equal(observed.length, 1);
	assert.equal(observed[0].source, user);
	assert.equal(observed[0].output.role, "user");
})"

"test("Anthropic grouped terminal waits retain distinct block receipts through reopening", async (t) => {
	const api = "anthropic-messages";
	const f = await fixture(t, { api, automatic: true, toolCount: 2 });
	await f.session.prompt("wait for both");
	await f.ingress.wakeProducers();
	await tick();
	assert.equal(f.sent.length, 2);
	const [row] = f.sent[1].messages.filter(
		(row) => Array.isArray(row.content) && row.content.some((block) => block.type === "tool_result"),
	);
	assert.equal(row.content.filter((block) => block.type === "tool_result").length, 2);
	assert.ok(
		row.content.every((block) => !block.is_error),
		JSON.stringify(row.content),
	);
	const record = (await f.ingress.branch().attachment.nativeRequests.snapshot())[1];
	// Both grouped decisions converted intact, which is what delivery means, and both are acknowledged.
	assert.deepEqual(
		record.projectionCapture.model.members.map((member) => member.status),
		["converted", "converted"],
	);
	assert.deepEqual(await f.decisions(), []);
	validateNativeProjections(record.projectionCapture, record.transformedHash, record.modelHash);
	await f.ingress.dispose();
	const next = await fixture(t, {
		api,
		root: f.root,
		manager: SessionManager.open(f.session.sessionManager.getSessionFile()),
		automatic: true,
		issueTool: false,
	});
	await next.ingress.wakeProducers();
	await tick();
	assert.deepEqual(next.sent, []);
	assert.deepEqual(await next.decisions(), []);
	assert.deepEqual(f.errors, []);
	assert.deepEqual(next.errors, []);
})"

"test(`${api}: later dependency completion dispatches one retained decision and survives reopening`, async (t) => {
		const f = await fixture(t, { api, automatic: true, pending: true });
		await f.session.prompt("wait until the process exits");
		assert.equal(f.sent.length, 2);
		assert.equal((await f.ingress.branch().attachment.waits.snapshot())[0].state, "waiting");
		await f.ingress.wakeProducers();
		await tick();
		assert.equal(f.sent.length, 2);
		await f.complete(false);
		const deadline = Date.now() + 5000;
		while (
			!(await f.ingress.branch().attachment.ledger.snapshot()).attempts.some((attempt) => attempt.phase === "settled")
		) {
			assert.ok(Date.now() < deadline, "automatic dependency delivery did not settle");
			await new Promise((resolve) => setTimeout(resolve, 10));
		}
		assert.equal(f.sent.length, 3);
		const state = await f.ingress.branch().attachment.ledger.snapshot();
		assert.equal(state.attempts.length, 1);
		assert.equal(state.attempts[0].phase, "settled");
		assert.equal(state.attempts[0].outcome, "success");
		assert.equal(state.attempts[0].members[0].kind, "wait");
		// Inclusion is the prepare-time record from model conversion; the ledger keeps no wire receipt.
		assert.equal(state.attempts[0].requests[0].handedOff, true);
		assert.equal(state.attempts[0].requests[0].inclusion[0].disposition, "included");
		if (api === "openai-codex-responses")
			assert.ok(
				f.codex.requests[2].input.some(
					(row) => row.role === "user" && row.content?.some((part) => part.text?.includes('"kind":"wait"')),
				),
			);
		await f.ingress.wakeProducers();
		await tick();
		assert.equal(f.sent.length, 3);
		await f.ingress.dispose();
		const next = await fixture(t, {
			api,
			root: f.root,
			manager: SessionManager.open(f.session.sessionManager.getSessionFile()),
			automatic: true,
			issueTool: false,
		});
		await next.ingress.wakeProducers();
		await tick();
		assert.deepEqual(next.sent, []);
		await next.session.prompt("status");
		assert.equal(next.sent.length, 1);
		assert.equal((await next.ingress.branch().attachment.ledger.snapshot()).attempts.length, 1);
		assert.deepEqual(f.errors, []);
		assert.deepEqual(next.errors, []);
	})"

"test(`Anthropic ${mode} decision payload after conversion transmits and acknowledges`, async (t) => {
		const f = await fixture(t, {
			api: "anthropic-messages",
			pending: true,
			change(payload) {
				for (const [index, row] of payload.messages.entries()) {
					if (row.role !== "user" || !Array.isArray(row.content)) continue;
					const part = row.content.find(
						(part) => part.type === "text" && part.text.includes('"flowInput"') && part.text.includes('"kind":"wait"'),
					);
					if (!part) continue;
					if (mode === "replaced") {
						const frame = JSON.parse(part.text);
						frame.content = "changed";
						part.text = JSON.stringify(frame);
					}
					if (mode === "omitted") row.content = row.content.filter((candidate) => candidate !== part);
					if (mode === "tool-copy")
						payload.messages.splice(
							index,
							1,
							{ role: "assistant", content: [{ type: "tool_use", id: "copy", name: "read", input: {} }] },
							{ role: "user", content: [{ type: "tool_result", tool_use_id: "copy", content: [part] }, part] },
						);
					if (mode === "tool-gap")
						payload.messages.splice(index, 0, {
							role: "assistant",
							content: [{ type: "tool_use", id: "missing", name: "read", input: {} }],
						});
					break;
				}
			},
		});
		await f.session.prompt("wait");
		await f.complete();
		// The decision turn is transmitted now rather than withheld before transport, so the run makes
		// one more request than it did when the wire check refused it.
		assert.equal(f.sent.length, 3);
		const [attempt] = (await f.ingress.branch().attachment.ledger.snapshot()).attempts;
		// Each mode edits the Anthropic body after model conversion. The composed decision reached the
		// adapter, so the attempt is handed off and the decision is acknowledged; the edit is invisible.
		assert.equal(attempt.phase, "settled");
		assert.equal(attempt.requests[0].handedOff, true);
		assert.equal(attempt.requests[0].inclusion[0].disposition, "included");
		assert.equal((await f.decisions()).length, 0);
		await f.ingress.wakeProducers();
		assert.equal(f.sent.length, 3, "an acknowledged decision creates no further wake");
		assert.deepEqual(f.errors, []);
	})"

"test(`${api} grouped wait tool observation through SDK transport: ${mode}`, async (t) => {
			const f = await fixture(t, {
				api,
				toolCount: 2,
				automatic: mode === "intact",
				failure: mode === "failed",
				change(payload) {
					const row = payload.contents.find((row) => row.parts.some((part) => part.functionResponse));
					if (!row) return;
					if (mode === "content") row.parts[0].functionResponse.response.output += " changed";
					if (mode === "omitted") row.parts.shift();
				},
			});
			await f.session.prompt("wait for the finished process");
			if (mode === "intact") {
				await f.ingress.wakeProducers();
				await tick();
			}
			assert.equal(f.sent.length, 2);
			const attachment = f.ingress.branch().attachment;
			const records = await attachment.nativeRequests.snapshot();
			// Every mode reaches the adapter converted; only the wire body differs, which is no longer read.
			assert.deepEqual(
				records[1].projectionCapture.model.members.map((member) => member.status),
				["converted", "converted"],
			);
			// `content` and `omitted` mutate the SDK payload after model conversion, which the controller
			// trusts, so both acknowledge their decisions. Only the failed request keeps its two pending.
			assert.equal((await f.decisions()).length, mode === "failed" ? 2 : 0);
			assert.deepEqual(f.errors, []);
			if (mode !== "intact") {
				await f.session.prompt("report the wait status");
				assert.deepEqual(await f.decisions(), []);
				return;
			}
			await f.ingress.dispose();
			const next = await fixture(t, {
				root: f.root,
				api,
				automatic: true,
				issueTool: false,
				manager: f.session.sessionManager,
			});
			await next.ingress.wakeProducers();
			assert.deepEqual(next.sent, []);
			assert.deepEqual(await next.decisions(), []);
			await next.session.prompt("continue");
			assert.equal(next.sent.length, 1);
			assert.deepEqual(await next.decisions(), []);
		})"

"test(`${api} ${mode} decision after conversion transmits and acknowledges`, async (t) => {
			const f = await fixture(t, {
				api,
				pending: true,
				change(payload) {
					for (const row of payload.contents) {
						const part = row.parts.find(
							(part) =>
								typeof part.text === "string" &&
								part.text.includes('"flowInput"') &&
								part.text.includes('"kind":"wait"'),
						);
						if (!part) continue;
						if (mode === "replaced") {
							const frame = JSON.parse(part.text);
							frame.content = "changed";
							part.text = JSON.stringify(frame);
						}
						if (mode === "omitted") row.parts = row.parts.filter((candidate) => candidate !== part);
						if (mode === "extra-body") payload.config.httpOptions = { extraBody: { contents: [] } };
					}
				},
			});
			await f.session.prompt("wait");
			await f.complete();
			assert.equal(f.sent.length, 3, "the decision turn is transmitted rather than withheld");
			const [attempt] = (await f.ingress.branch().attachment.ledger.snapshot()).attempts;
			// The SDK payload is edited after model conversion, which the controller trusts.
			assert.equal(attempt.phase, "settled");
			assert.equal(attempt.requests[0].handedOff, true);
			assert.equal(attempt.requests[0].inclusion[0].disposition, "included");
			assert.equal((await f.decisions()).length, 0);
			await f.ingress.wakeProducers();
			assert.equal(f.sent.length, 3, "an acknowledged decision creates no further wake");
		})"

"test(`Codex ${codexMode} ${pending ? "later" : "immediate"} wait delivery`, async (t) => {
			const f = await fixture(t, { api: "openai-codex-responses", codexMode, automatic: true, pending });
			await f.session.prompt("wait");
			if (pending) await f.complete();
			await f.ingress.wakeProducers();
			assert.equal(f.sent.length, pending ? 3 : 2);
			if (!pending) assert.deepEqual(await f.decisions(), []);
			else assert.equal((await f.ingress.branch().attachment.ledger.snapshot()).attempts[0].phase, "settled");
			assert.equal(f.codex.requests[0].transport, codexMode === "sse" ? "sse" : "websocket");
			assert.equal(f.sent[1].previous_response_id, codexMode === "websocket-cached" ? "response_1" : undefined);
			assert.deepEqual(f.errors, []);
		})"

"test(`Codex ${mode} decision after conversion transmits through cached transport`, async (t) => {
		const f = await fixture(t, {
			api: "openai-codex-responses",
			pending: true,
			change(payload) {
				for (const [index, row] of payload.input.entries()) {
					if (row.role !== "user") continue;
					const part = row.content.find(
						(part) => part.text?.includes('"flowInput"') && part.text.includes('"kind":"wait"'),
					);
					if (!part) continue;
					if (mode === "replaced") {
						const frame = JSON.parse(part.text);
						frame.content = "changed";
						part.text = JSON.stringify(frame);
					}
					if (mode === "omitted") row.content = row.content.filter((candidate) => candidate !== part);
					if (mode === "tool-copy")
						payload.input.splice(
							index,
							1,
							{ type: "function_call", name: "read", call_id: "copy", arguments: "{}" },
							{ type: "function_call_output", call_id: "copy", output: part.text },
						);
					if (mode === "tool-gap")
						payload.input.splice(index, 0, {
							type: "function_call",
							name: "read",
							call_id: "missing",
							arguments: "{}",
						});
					break;
				}
			},
		});
		await f.session.prompt("wait");
		await f.complete();
		// The Codex body is edited after model conversion, so the decision turn is transmitted and the
		// composed decision is acknowledged from the ledger.
		assert.equal(f.sent.length, 3);
		const [attempt] = (await f.ingress.branch().attachment.ledger.snapshot()).attempts;
		assert.equal(attempt.phase, "settled");
		assert.equal(attempt.requests[0].handedOff, true);
		assert.equal((await f.decisions()).length, 0);
		await f.ingress.wakeProducers();
		assert.equal(f.sent.length, 3, "an acknowledged decision creates no further wake");
	})"

