	const active = await f.store.registerWork(first.id, "other-owner", 4);
	const second = await f.store.changeWork(
		active.id,
		active.owner,
		active.revision,
		"completed",
		"Second generation",
		5,
	);
	await f.store.retire({ ...empty(), work: [second] });
