		const saved = {
			version: 1,
			jobs: [
				{
					id: "release-review",
					schedule: "0 9 * * *",
					prompt: "Review the release.",
					nextRun: "2026-06-01T09:00:00.000Z",
				},
			],
		};
		writeFileSync(scheduleFile, JSON.stringify(saved));
		const bytes = readFileSync(scheduleFile, "utf8");
