		const snapshot = readLocalizationConfigSnapshot(configDir);
		saveLocalizationConfig({ configDir, stateDir }, "en", snapshot);
		const written = JSON.parse(readFileSync(join(configDir, LOCALIZATION_FILE_NAME), "utf8"));
