"test("the catalog-independent recovery text is used when no catalog can be read", () => {
	withCatalogRoot((localesRoot) => {
		rmSync(join(localesRoot, "en", "cli.ftl"));
		rmSync(join(localesRoot, "ja", "cli.ftl"));
