		assert.equal(requests[0].redirect, "error");
		assert.equal(
			loadActiveModelCatalogs(jouzuPaths, { SHISA_API_KEY: "sk-fixture" })[0]?.document.revision,
			"fixture-1",
		);
	} finally {
		rmSync(temporary, { recursive: true, force: true });
	}
})"

