"test("gap analysis flags offerings that leave thinking levels undeclared", () => {
	const parsed = (document) => parseAndValidateModelCatalog(JSON.stringify(document), { remote: true });
	const document = accountSnapshot();
	assert.deepEqual(
		catalogThinkingLevelGaps(parsed(document)),
		[],
		"an explicit capability list without reasoning rules thinking out",
	);

	delete document.modelOfferings[0].capabilities;
	assert.deepEqual(
		catalogThinkingLevelGaps(parsed(document)),
		[{ providerId: "ai.example.gateway", modelId: "example-model" }],
		"silence is the risky case, so an absent capability list is reported",
	);

	document.modelOfferings[0].capabilities = ["text", "streaming", "tool_calling", "reasoning"];
	assert.deepEqual(catalogThinkingLevelGaps(parsed(document)), [
		{ providerId: "ai.example.gateway", modelId: "example-model" },
	]);

	document.modelOfferings[0].supportedThinkingLevels = ["low", "medium", "high"];
	assert.deepEqual(catalogThinkingLevelGaps(parsed(document)), [], "a declared set closes the gap");
})"

"test("gap analysis flags offerings that cannot become a new model", () => {
	const parsed = (document) => parseAndValidateModelCatalog(JSON.stringify(document), { remote: true });
	const document = accountSnapshot();
	assert.deepEqual(
		catalogRegistrationGaps(parsed(document)),
		[],
		"a complete offering carries a text modality, a context window, and an output limit",
	);

	delete document.modelOfferings[0].modalities;
	delete document.modelOfferings[0].limits.maxOutputTokens;
	const gaps = catalogRegistrationGaps(parsed(document));
	assert.deepEqual(gaps, [
		{ providerId: "ai.example.gateway", modelId: "example-model", missing: ["textModality", "maxOutputTokens"] },
	]);
	assert.equal(describeCatalogRegistrationGap(gaps[0]), "no text input, no maximum output tokens");
	assert.equal(describeCatalogRegistrationGaps(gaps), "1 no text input, 1 no maximum output tokens");

	document.modelOfferings[0].modalities = ["image"];
	assert.deepEqual(
		catalogRegistrationGaps(parsed(document))[0].missing,
		["textModality", "maxOutputTokens"],
		"a modality list without text cannot define a text model",
	);

	document.modelOfferings[0].modalities = ["text", "image"];
	document.modelOfferings[0].limits.maxOutputTokens = 32768;
	assert.deepEqual(catalogRegistrationGaps(parsed(document)), [], "declaring the missing fields closes the gap");
})"

"test("per-model reasoning defaults match the schema and remain optional", () => {
	const schema = JSON.parse(readFileSync(join(catalogRoot, "model-catalog-v1.schema.json"), "utf8"));
	const levels = schema.$defs.offering.properties.defaultThinkingLevel.enum;
	assert.deepEqual(levels, ["off", "minimal", "low", "medium", "high", "xhigh", "max"]);
	for (const level of [...levels, undefined]) {
		const document = accountSnapshot();
		if (level === undefined) delete document.modelOfferings[0].defaultThinkingLevel;
		else document.modelOfferings[0].defaultThinkingLevel = level;
		const parsed = parseAndValidateModelCatalog(JSON.stringify(document), { remote: true });
		assert.equal(parsed.modelOfferings[0].defaultThinkingLevel, level);
		assert.equal(Object.hasOwn(parsed.modelOfferings[0], "defaultThinkingLevel"), level !== undefined);
	}
	for (const level of [null, true, 1, "", {}, ["medium"]]) {
		const document = accountSnapshot();
		document.modelOfferings[0].defaultThinkingLevel = level;
		assert.throws(
			() => parseAndValidateModelCatalog(JSON.stringify(document), { remote: true }),
			(error) =>
				error instanceof ModelCatalogError &&
				error.code === "invalid_record" &&
				error.path === "$.modelOfferings[0].defaultThinkingLevel",
		);
	}
	for (const level of ["auto", "MEDIUM", "ultra"]) {
		const document = accountSnapshot();
		document.modelOfferings[0].defaultThinkingLevel = level;
		const parsed = parseAndValidateModelCatalog(JSON.stringify(document), { remote: true });
		assert.equal(parsed.modelOfferings[0].defaultThinkingLevel, undefined);
		assert.equal(Object.hasOwn(parsed.modelOfferings[0], "defaultThinkingLevel"), false);
	}
})"

