"test("strict parsing rejects duplicate keys, unsafe references, and credential fields", () => {
	const duplicate = fixture("account-snapshot-v1.json").replace(
		'"revision": "fixture-1",',
		'"revision": "fixture-1",\n  "revision": "fixture-2",',
	);
	assert.throws(
		() => parseAndValidateModelCatalog(duplicate, { remote: true }),
		(error) => error instanceof ModelCatalogError && error.code === "duplicate_key",
	);

	const base = accountSnapshot();
	assert.throws(
		() =>
			parseAndValidateModelCatalog(
				invalid(base, (document) => {
					document.modelOfferings[0].routeIds = ["missing-route"];
				}),
				{ remote: true },
			),
		(error) => error instanceof ModelCatalogError && error.code === "unresolved_reference",
	);
	assert.throws(
		() =>
			parseAndValidateModelCatalog(
				invalid(base, (document) => {
					document.extensions = { apiKey: "must-not-appear" };
				}),
				{ remote: true },
			),
		(error) => error instanceof ModelCatalogError && error.code === "credential_material",
	);
	for (const mutate of [
		(document) => {
			document.providers[0].api = { protocol: "openai" };
		},
		(document) => {
			document.modelOfferings[0].name = ["not", "a", "name"];
		},
		(document) => {
			document.modelOfferings[0].api = 7;
		},
		(document) => {
			document.modelOfferings[0].modalities = ["text", 7];
		},
		(document) => {
			document.modelOfferings[0].capabilities = { reasoning: true };
		},
	]) {
		assert.throws(
			() => parseAndValidateModelCatalog(invalid(base, mutate), { remote: true }),
			(error) => error instanceof ModelCatalogError && error.code === "invalid_record",
		);
	}
	const prototypeCredential = fixture("account-snapshot-v1.json").replace(
		'"id": "ai.example.gateway",',
		'"id": "ai.example.gateway",\n      "__proto__": { "apiKey": "must-not-appear" },',
	);
	assert.throws(
		() => parseAndValidateModelCatalog(prototypeCredential, { remote: true }),
		(error) => error instanceof ModelCatalogError && error.code === "credential_material",
	);
	assert.throws(
		() =>
			parseAndValidateModelCatalog(
				invalid(base, (document) => {
					document.modelOfferings.push({ ...document.modelOfferings[0], id: "another-offering" });
				}),
				{ remote: true },
			),
		(error) => error instanceof ModelCatalogError && error.code === "duplicate_identity",
	);
	assert.throws(
		() =>
			parseAndValidateModelCatalog(
				invalid(base, (document) => {
					document.providers[0].id = "unsafe\u001b[31m";
				}),
				{ remote: true },
			),
		(error) => error instanceof ModelCatalogError && error.code === "invalid_record",
	);
})"

"assert.throws(
		() =>
			parseAndValidateModelCatalog(
				invalid(base, (document) => {
					document.modelOfferings[0].routeIds = ["missing-route"];
				}),
				{ remote: true },
			),
		(error) => error instanceof ModelCatalogError && error.code === "unresolved_reference",
	)"

