"test("supported thinking levels filter unknown levels and reject malformed sets and contradictions", () => {
	const schema = JSON.parse(readFileSync(join(catalogRoot, "model-catalog-v1.schema.json"), "utf8"));
	assert.deepEqual(
		schema.$defs.offering.properties.supportedThinkingLevels.items.enum,
		schema.$defs.offering.properties.defaultThinkingLevel.enum,
	);
	for (const [levels, expected] of [
		[undefined, undefined],
		[["off"], ["off"]],
		[
			["low", "high", "xhigh", "max"],
			["low", "high", "xhigh", "max"],
		],
		[["high"], ["high"]],
		[["low", "ultra"], ["low"]],
		[["off", "ultra"], ["off"]],
		[["ultra"], undefined],
		[["HIGH"], undefined],
	]) {
		const document = accountSnapshot();
		delete document.modelOfferings[0].defaultThinkingLevel;
		delete document.modelOfferings[0].capabilities;
		if (levels !== undefined) document.modelOfferings[0].supportedThinkingLevels = levels;
		assert.deepEqual(
			parseAndValidateModelCatalog(JSON.stringify(document)).modelOfferings[0].supportedThinkingLevels,
			expected,
			JSON.stringify(levels),
		);
	}
	for (const levels of [null, [], "high", ["high", "high"], [75], ["off", null]]) {
		const document = accountSnapshot();
		document.modelOfferings[0].supportedThinkingLevels = levels;
		assert.throws(() => parseAndValidateModelCatalog(JSON.stringify(document)), ModelCatalogError);
	}
	const unknownDefault = accountSnapshot();
	unknownDefault.modelOfferings[0].defaultThinkingLevel = "ultra";
	assert.equal(
		parseAndValidateModelCatalog(JSON.stringify(unknownDefault)).modelOfferings[0].defaultThinkingLevel,
		undefined,
	);
	const mixed = accountSnapshot();
	mixed.modelOfferings[0].supportedThinkingLevels = ["low", "ultra"];
	mixed.modelOfferings[0].defaultThinkingLevel = "low";
	const mixedParsed = parseAndValidateModelCatalog(JSON.stringify(mixed));
	assert.deepEqual(mixedParsed.modelOfferings[0].supportedThinkingLevels, ["low"]);
	assert.equal(mixedParsed.modelOfferings[0].defaultThinkingLevel, "low");
	const document = accountSnapshot();
	document.modelOfferings[0].supportedThinkingLevels = ["low", "high"];
	assert.throws(() => parseAndValidateModelCatalog(JSON.stringify(document)), /must include defaultThinkingLevel/);
	delete document.modelOfferings[0].defaultThinkingLevel;
	assert.throws(() => parseAndValidateModelCatalog(JSON.stringify(document)), /must agree with reasoning capability/);
	document.modelOfferings[0].capabilities.push("reasoning");
	assert.doesNotThrow(() => parseAndValidateModelCatalog(JSON.stringify(document)));
})"

"test("Astra guidance follows the selected model on every turn without accumulating", async () => {
	const before = hook();
	const turn = (ctx) => runPromptHook(before, { systemPrompt: base, options: { selectedTools: ["read"] }, ctx });
	const astra = { model: { id: "gpt-6-astra", provider: "configured-provider" } };
	const first = turn(astra);
	assert.match(first.systemPrompt, /carry authorized work through implementation/);
	assert.match(
		first.systemPrompt,
		/Do not stop at acknowledging capability, proposing a plan, or offering to continue/,
	);
	assert.match(first.systemPrompt, /continue without ending the turn to clarify/);
	assert.match(
		first.systemPrompt,
		/diagnose and fix the issues you identify within the requested scope, then verify the fixes/,
	);
	assert.match(first.systemPrompt, /Do not stop at findings or ask whether to implement an authorized fix/);
	assert.match(
		first.systemPrompt,
		/If the user explicitly requests diagnosis only, review only, or otherwise limits changes, respect that boundary/,
	);
	assert.match(first.systemPrompt, /Authorization persists across turns/);
	assertRecoveryGuidance(first.systemPrompt);
	assert.match(first.systemPrompt, /repeat or broaden testing only/);
	assert.match(first.systemPrompt, /overall completion checklist/);
	assert.match(first.systemPrompt, /use them selectively for bounded, coherent work packages/);
	assert.match(first.systemPrompt, /A task list is an execution aid, not proof of completion/);
	assert.doesNotMatch(first.systemPrompt, /Use `subagent`/);
	const other = turn({ model: { id: "gpt-5.6-sol" } });
	assert.doesNotMatch(other.systemPrompt, /carry authorized work through implementation/);
	// Each run starts from fresh options, so guidance is set once per turn and never accumulates.
	assert.deepEqual(turn(astra).sections, first.sections);
	assert.equal(first.systemPrompt.split("carry authorized work through implementation").length, 2);
})"

"test("delegation guidance describes only the active Jouzu tool", () => {
