	catalogState.favorites = catalogModels.map((model, index) => ({
		catalogId: model.catalogId,
		offeringId: model.offeringId,
		provider: model.provider,
		modelId: model.modelId,
		addedAt: `2026-08-23T00:00:0${index}.000Z`,
