"test("CLI preserves explicit reasoning suffixes and distinguishes literal colon IDs", { timeout: 120000 }, () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-thinking-cli-"));
	try {
		const home = join(root, "home");
		const extension = join(root, "provider.mjs");
		writeFileSync(
			extension,
			`export default function(pi) {
			pi.registerProvider('thinking-fixture', {
				baseUrl: 'http://127.0.0.1:1', apiKey: 'fixture-only', api: 'openai-completions',
				models: ['fixture', 'literal:low'].map(id => ({id, name:id, reasoning:true,
					input:['text'], cost:{input:0,output:0,cacheRead:0,cacheWrite:0}, contextWindow:32000,maxTokens:1000}))
			});
		}`,
		);
		const store = new ModelPickerStore(resolveJouzuPaths({ homeOverride: home }));
		for (const modelId of ["fixture", "literal:low"])
			store.setModelThinkingLevel({ provider: "thinking-fixture", modelId }, "high");
		const env = Object.fromEntries(
			Object.entries(process.env).filter(([key]) => !/^(JOUZU_|PI_|SHISA_|AI_AGENT|TEXTGUARD_)/u.test(key)),
		);
		Object.assign(env, { PI_OFFLINE: "1", JOUZU_NO_UPDATE: "1" });
		for (const [args, expected] of [
			[["--model", "thinking-fixture/fixture:low"], "low"],
			[["--provider", "thinking-fixture", "--model", "fixture:off"], "off"],
			[["--model", "thinking-fixture/fixture:low", "--thinking", "medium"], "medium"],
			[["--model", "thinking-fixture/fixture", "--thinking", "low"], "low"],
			[["--model", "thinking-fixture/fixture"], "high"],
			[["--model", "thinking-fixture/literal:low"], "high"],
			[["--model", "thinking-fixture/literal:low:off"], "off"],
		]) {
			const result = spawnSync(
				process.execPath,
				[
					resolve(import.meta.dirname, "../dist/cli.js"),
					"--jouzu-home",
					home,
					"--mode",
					"rpc",
					"--no-session",
					"--no-context-files",
					"--no-extensions",
					"--no-skills",
					"--extension",
					extension,
					...args,
				],
				{
					cwd: root,
					env,
					encoding: "utf8",
					timeout: 15000,
					input: '{"id":"state","type":"get_state"}\n',
				},
			);
			assert.equal(result.status, 0, result.stderr);
			const response = result.stdout
				.split("\n")
				.filter((line) => line.startsWith("{"))
				.map((line) => JSON.parse(line))
				.find((value) => value.id === "state");
			assert.equal(
				response?.data?.thinkingLevel,
				expected,
				JSON.stringify({ args, stdout: result.stdout, stderr: result.stderr }),
			);
			assert.deepEqual(
				store.load().state.thinkingLevels.map((entry) => entry.thinkingLevel),
				["high", "high"],
			);
		}
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test(`${failure} failure remains pending without a settled-event retry loop`, async () => {
		const f = fixture(failure);
		try {
			f.idle(true);
			f.inbox.request();
			await tick();
			assert.equal(f.errors.length, 1);
			assert.equal(f.records[0].handled, false);
			for (let i = 0; i < 3; i++) {
				f.handlers.get("agent_settled")({}, f.ctx);
				await tick();
			}
			assert.equal(f.errors.length, 1);
			assert.equal(f.sent.length, 0);
		} finally {
			f.inbox.shutdown();
		}
	})"

"test("redacted batch cannot establish a receipt or authorize no-reply", async () => {
	const f = fixture();
	try {
		f.idle(true);
		f.inbox.request();
		await tick();
		const changed = { ...f.sent[0], content: "Policy removed result" };
		f.handlers.get("agent_start")();
		f.handlers.get("message_start")({ message: { role: "custom", ...changed } }, f.ctx);
		f.branch.push({ type: "custom_message", ...changed });
		f.handlers.get("turn_end")({}, f.ctx);
		assert.equal(f.records[0].handled, false);
		assert.throws(() => f.inbox.acknowledge(changed.details.inbox.batchId));
	} finally {
		f.inbox.shutdown();
	}
})"

"test(`redacted batch permits later completions without retrying withheld results (message event: ${deliveryEvent})`, async () => {
		const f = fixture();
		try {
			f.idle(true);
			f.inbox.request();
			await tick();
			const changed = { ...f.sent[0], content: "Policy removed result" };
			if (deliveryEvent) f.handlers.get("message_start")({ message: { role: "custom", ...changed } }, f.ctx);
			f.branch.push({ type: "custom_message", ...changed });
			f.handlers.get("turn_end")({}, f.ctx);
			f.records.push({ id: "later", revision: "terminal-2", handled: false });
			f.handlers.get("agent_settled")({}, f.ctx);
			await tick();
			assert.equal(f.sent.length, 2);
			assert.equal(f.records[0].batchId, changed.details.inbox.batchId);
			assert.equal(f.records[1].batchId, f.sent[1].details.inbox.batchId);
			f.branch.push({ type: "custom_message", ...f.sent[1] });
			for (let i = 0; i < 3; i++) {
				f.handlers.get("agent_settled")({}, f.ctx);
				await tick();
			}
			assert.equal(f.errors.length, 1);
			assert.equal(f.sent.length, 2);
			assert.equal(f.records[0].handled, false);
			assert.equal(f.records[1].handled, true);
			f.inbox.start(f.ctx);
			await tick();
			assert.equal(f.sent.length, 3, "reload retries the withheld result");
			assert.equal(f.records[0].batchId, f.sent[2].details.inbox.batchId);
		} finally {
			f.inbox.shutdown();
		}
	})"

"test("subsequent user input invalidates a current-run no-reply choice", async () => {
	const f = fixture();
	try {
		f.idle(true);
		f.inbox.request();
		await tick();
		const message = f.sent[0];
		f.branch.push({ type: "custom_message", ...message });
		f.handlers.get("agent_start")();
		f.handlers.get("message_start")({ message: { role: "custom", ...message } }, f.ctx);
		f.handlers.get("message_start")({ message: { role: "user", content: "New work" } }, f.ctx);
		assert.throws(() => f.inbox.acknowledge(message.details.inbox.batchId));
	} finally {
		f.inbox.shutdown();
	}
})"

"test("inbox waits for idle and queued user work, then reconciles the durable receipt", async () => {
	const f = fixture();
	try {
		await tick();
		assert.equal(f.sent.length, 0);
		f.idle(true);
		f.queued(true);
		f.inbox.request();
		await tick();
		assert.equal(f.sent.length, 0);
		f.queued(false);
		f.inbox.request();
		await tick();
		assert.equal(f.sent.length, 1);
		assert.equal(f.records[0].handled, false);
		f.branch.push({ type: "custom_message", ...f.sent[0] });
		f.handlers.get("turn_end")({}, f.ctx);
		assert.equal(f.records[0].handled, true);
		f.inbox.request();
		await tick();
		assert.equal(f.sent.length, 1);
	} finally {
		f.inbox.shutdown();
	}
})"

"test("no-reply permission requires current-run delivered identity, survives receipt reconciliation, and expires", async () => {
	const f = fixture();
	try {
		f.idle(true);
		f.inbox.request();
		await tick();
		const message = f.sent[0];
		const id = message.details.inbox.batchId;
		assert.throws(() => f.inbox.acknowledge(id));
		f.handlers.get("agent_start")();
		f.handlers.get("message_start")({ message: { role: "custom", ...message } }, f.ctx);
		f.branch.push({ type: "custom_message", ...message });
		f.handlers.get("turn_end")({}, f.ctx);
		assert.throws(() => f.inbox.acknowledge("wrong"));
		assert.equal(f.inbox.acknowledge(id).terminate, true);
		assert.throws(() => f.inbox.acknowledge(id));
	} finally {
		f.inbox.shutdown();
	}
})"

"test("aborted notification runs cannot acknowledge and foreign session events cannot deliver", async () => {
	const f = fixture();
	try {
		f.idle(true);
		f.inbox.request();
		await tick();
		const message = f.sent[0];
		f.branch.push({ type: "custom_message", ...message });
		f.handlers.get("agent_start")();
		f.handlers.get("message_start")(
			{ message: { role: "custom", ...message } },
			{ ...f.ctx, signal: AbortSignal.abort() },
		);
		assert.throws(() => f.inbox.acknowledge(message.details.inbox.batchId));
		f.inbox.shutdown();
		f.records.push({ id: "later", revision: "terminal-2", handled: false });
		f.idle(false);
		f.inbox.start(f.ctx);
		await tick();
		const foreign = {
			...f.ctx,
			isIdle: () => true,
			sessionManager: { getSessionId: () => "other", getBranch: () => [] },
		};
		f.handlers.get("agent_settled")({}, foreign);
		await tick();
		assert.equal(f.sent.length, 1);
	} finally {
		f.inbox.shutdown();
	}
})"

"test("shutdown cancels scheduled delivery and restart uses persisted membership", async () => {
	const f = fixture();
	f.idle(true);
	f.inbox.request();
	f.inbox.shutdown();
	await tick();
	assert.equal(f.sent.length, 0);
	f.inbox.start(f.ctx);
	await tick();
	f.branch.push({ type: "custom_message", ...f.sent[0] });
	f.inbox.shutdown();
	f.inbox.start(f.ctx);
	await tick();
	assert.equal(f.sent.length, 1);
	assert.equal(f.records[0].handled, true);
	f.inbox.shutdown();
})"

"test("the model-facing acknowledge reply and the inbox protocol fields are unchanged", async () => {
	const f = fixture("Externally produced body.");
