"test("reference files are installed exactly and preserve user edits on reapply", () => {
	const fixture = temporary();
	try {
		const profile = loadBundledProfile("core");
		applyProfile(profile, fixture.paths, "0.1.0");
		const references = profile.assets.filter((asset) => asset.target.startsWith("skills/jouzu-reference/"));
		assert.equal(references.length, 5);
		for (const asset of references) {
			assert.deepEqual(readFileSync(join(fixture.paths.agentDir, asset.target)), asset.bytes);
		}
		const target = "skills/jouzu-reference/references/configuration.md";
		const file = join(fixture.paths.agentDir, target);
		writeFileSync(file, "user customization\n");
		assert.equal(
			planProfile(profile, fixture.paths, "0.1.0").actions.find((a) => a.target === target)?.reason,
			"managed-modified",
		);
		assert.throws(() => applyProfile(profile, fixture.paths, "0.1.0"), ProfileConflictError);
		assert.equal(readFileSync(file, "utf8"), "user customization\n");
	} finally {
		cleanup(fixture.root);
	}
})"

"test("unmanaged and modified managed files conflict before any write", () => {
	const fixture = temporary();
	try {
		const profile = loadBundledProfile("ja");
		mkdirSync(fixture.paths.agentDir, { recursive: true });
		const target = join(fixture.paths.agentDir, "APPEND_SYSTEM.md");
		writeFileSync(target, "user-owned\n");
		const plan = planProfile(profile, fixture.paths, "0.1.0");
		assert.equal(plan.actions.find((action) => action.target === "APPEND_SYSTEM.md")?.reason, "unmanaged-different");
		assert.throws(() => applyProfile(profile, fixture.paths, "0.1.0"), ProfileConflictError);
		assert.equal(readFileSync(target, "utf8"), "user-owned\n");
		assert.equal(existsSync(fixture.paths.profileStatePath), false);

		rmSync(target);
		applyProfile(profile, fixture.paths, "0.1.0");
		writeFileSync(target, "locally modified\n");
		assert.equal(
			planProfile(profile, fixture.paths, "0.1.0").actions.find((action) => action.target === "APPEND_SYSTEM.md")
				?.reason,
			"managed-modified",
		);
		assert.throws(() => applyProfile(profile, fixture.paths, "0.1.0"), ProfileConflictError);
		assert.equal(readFileSync(target, "utf8"), "locally modified\n");
	} finally {
		cleanup(fixture.root);
	}
})"

"test("unsupported CP932 content is reported and left byte-identical", () => {
	const fixture = temporary();
	try {
		const bytes = Buffer.from([0x82, 0xa0, 0x82, 0xa2, 0x0d, 0x0a]);
		mkdirSync(fixture.paths.agentDir, { recursive: true });
		const target = join(fixture.paths.agentDir, "APPEND_SYSTEM.md");
		writeFileSync(target, bytes);
		const plan = planProfile(loadBundledProfile("ja"), fixture.paths, "0.1.0");
		assert.equal(plan.actions.find((action) => action.target === "APPEND_SYSTEM.md")?.reason, "unsupported-encoding");
		assert.throws(() => applyProfile(loadBundledProfile("ja"), fixture.paths, "0.1.0"), ProfileConflictError);
		assert.deepEqual(readFileSync(target), bytes);
	} finally {
		cleanup(fixture.root);
	}
})"

"test("matching unmanaged files are adopted without rewriting", () => {
	const fixture = temporary();
	try {
		const profile = loadBundledProfile("core");
		for (const asset of profile.assets) {
			const path = join(fixture.paths.agentDir, ...asset.target.split("/"));
			mkdirSync(join(path, ".."), { recursive: true });
			writeFileSync(path, asset.bytes);
		}
		const before = profile.assets.map((asset) =>
			readFileSync(join(fixture.paths.agentDir, ...asset.target.split("/"))),
		);
		const plan = planProfile(profile, fixture.paths, "0.1.0");
		assert.equal(plan.actions.filter((action) => action.type === "adopt").length, profile.assets.length);
		applyProfile(profile, fixture.paths, "0.1.0");
		const after = profile.assets.map((asset) => readFileSync(join(fixture.paths.agentDir, ...asset.target.split("/"))));
		assert.deepEqual(after, before);
	} finally {
		cleanup(fixture.root);
	}
})"

"test("upgrading Core backs up and retires the prior managed repository skill", () => {
	const fixture = temporary();
	try {
		const core = loadBundledProfile("core");
		const priorBytes = Buffer.from("prior repository skill\n");
		const priorTarget = "skills/jouzu-core/SKILL.md";
		const prior = {
			...core,
			version: 7,
			manifestSha256: "c".repeat(64),
			assets: [...core.assets, { target: priorTarget, sha256: hash(priorBytes), bytes: priorBytes }],
		};
		applyProfile(prior, fixture.paths, "0.1.4");
		const plan = planProfile(core, fixture.paths, "0.1.4");
		assert.equal(plan.actions.find((action) => action.target === priorTarget)?.type, "delete");
		const result = applyProfile(core, fixture.paths, "0.1.4");
		assert.equal(existsSync(join(fixture.paths.agentDir, ...priorTarget.split("/"))), false);
		assert.ok(result.backupDir);
		assert.deepEqual(readFileSync(join(result.backupDir, ...priorTarget.split("/"))), priorBytes);
	} finally {
		cleanup(fixture.root);
	}
})"

"test("switching from JA to Core backs up and retires only managed JA assets", () => {
	const fixture = temporary();
	try {
		const ja = loadBundledProfile("ja");
		const core = loadBundledProfile("core");
		applyProfile(ja, fixture.paths, "0.1.0");
		const userAgents = join(fixture.paths.agentDir, "AGENTS.md");
		writeFileSync(userAgents, "user-owned\n");
		const plan = planProfile(core, fixture.paths, "0.1.0");
		assert.equal(plan.actions.find((action) => action.target === "APPEND_SYSTEM.md")?.type, "delete");
		const result = applyProfile(core, fixture.paths, "0.1.0");
		assert.equal(existsSync(join(fixture.paths.agentDir, "APPEND_SYSTEM.md")), false);
		assert.equal(readFileSync(userAgents, "utf8"), "user-owned\n");
		assert.ok(result.backupDir);
		assert.ok(existsSync(join(result.backupDir, "APPEND_SYSTEM.md")));
		assert.deepEqual(planProfile(core, fixture.paths, "0.1.0").actions, []);
	} finally {
		cleanup(fixture.root);
	}
})"

"test("managed updates are backed up before atomic replacement", () => {
	const fixture = temporary();
	try {
		const core = loadBundledProfile("core");
		applyProfile(core, fixture.paths, "0.1.0");
		const replacement = Buffer.from("updated managed asset\n");
		const updated = {
			...core,
			version: 4,
			manifestSha256: "b".repeat(64),
			assets: core.assets.map((asset, index) =>
				index === 0 ? { ...asset, bytes: replacement, sha256: hash(replacement) } : asset,
			),
		};
		const changed = updated.assets[0];
		const target = join(fixture.paths.agentDir, ...changed.target.split("/"));
		const original = readFileSync(target);
		assert.equal(planProfile(updated, fixture.paths, "0.1.0").actions[1].type, "update");
		const result = applyProfile(updated, fixture.paths, "0.1.0");
		assert.equal(readFileSync(target, "utf8"), "updated managed asset\n");
		assert.deepEqual(readFileSync(join(result.backupDir, ...changed.target.split("/"))), original);
	} finally {
		cleanup(fixture.root);
	}
})"

"test("stale state after an interrupted asset update converges without overwriting", () => {
	const fixture = temporary();
	try {
		const core = loadBundledProfile("core");
		applyProfile(core, fixture.paths, "0.1.0");
		const replacement = Buffer.from("replacement asset\n");
		const updated = {
			...core,
			version: 4,
			manifestSha256: "a".repeat(64),
			assets: core.assets.map((asset, index) =>
				index === 0 ? { ...asset, bytes: replacement, sha256: hash(replacement) } : asset,
			),
		};
		const target = join(fixture.paths.agentDir, ...updated.assets[0].target.split("/"));
		writeFileSync(target, replacement);
		const plan = planProfile(updated, fixture.paths, "0.1.0");
		assert.deepEqual(
			plan.actions.map((action) => action.type),
			["state-update"],
		);
		applyProfile(updated, fixture.paths, "0.1.0");
		assert.equal(readFileSync(target, "utf8"), "replacement asset\n");
		assert.equal(readProfileState(fixture.paths.profileStatePath).profileVersion, 4);
	} finally {
		cleanup(fixture.root);
	}
})"

"test("symlink profile targets conflict without touching the link destination", {
	skip: process.platform === "win32" ? "symlink privileges vary on Windows" : false,
}, () => {
	const fixture = temporary();
	try {
		const outside = join(fixture.root, "outside.md");
		writeFileSync(outside, "outside\n");
		mkdirSync(fixture.paths.agentDir, { recursive: true });
		symlinkSync(outside, join(fixture.paths.agentDir, "APPEND_SYSTEM.md"));
		const plan = planProfile(loadBundledProfile("ja"), fixture.paths, "0.1.0");
		assert.equal(plan.actions.find((action) => action.target === "APPEND_SYSTEM.md")?.reason, "unsafe-target");
		assert.throws(() => applyProfile(loadBundledProfile("ja"), fixture.paths, "0.1.0"), ProfileConflictError);
		assert.equal(readFileSync(outside, "utf8"), "outside\n");
	} finally {
		cleanup(fixture.root);
	}
})"

"test("an existing operation lock is preserved", () => {
	const fixture = temporary();
	try {
		mkdirSync(fixture.paths.stateDir, { recursive: true });
		const lock = join(fixture.paths.stateDir, "profile.lock");
		writeFileSync(lock, "other operation\n");
		assert.throws(() => applyProfile(loadBundledProfile("core"), fixture.paths, "0.1.0"), ProfileStateError);
		assert.equal(readFileSync(lock, "utf8"), "other operation\n");
	} finally {
		cleanup(fixture.root);
	}
})"

"test("the parser accepts plan, apply, and rollback and rejects unknown operations and options", () => {
	assert.deepEqual(parseJouzuArgs(["profile-migration"]), {
		kind: "profile-migration",
		options: {},
		operation: "plan",
		json: false,
		yes: false,
	});
	assert.deepEqual(parseJouzuArgs(["--jouzu-home=/tmp/上手", "profile-migration", "plan", "--json"]), {
		kind: "profile-migration",
		options: { home: "/tmp/上手" },
		operation: "plan",
		json: true,
		yes: false,
	});
	assert.deepEqual(parseJouzuArgs(["--jouzu-profile", "ja", "profile-migration", "apply", "--yes"]), {
		kind: "profile-migration",
		options: { profile: "ja" },
		operation: "apply",
		json: false,
		yes: true,
	});
	assert.deepEqual(parseJouzuArgs(["profile-migration", "rollback"]), {
		kind: "profile-migration",
		options: {},
		operation: "rollback",
		json: false,
		yes: false,
	});
	assert.throws(() => parseJouzuArgs(["profile-migration", "other"]), UsageError);
	assert.throws(() => parseJouzuArgs(["profile-migration", "apply", "--json"]), UsageError);
	assert.throws(() => parseJouzuArgs(["profile-migration", "plan", "--yes"]), UsageError);
	assert.throws(() => parseJouzuArgs(["profile-migration", "plan", "--json", "--json"]), UsageError);
})"

"test("the plan shows the effective profile, the mapping, and the asset diff", async () => {
	const workspace = makeWorkspace();
	try {
		writeChoice(workspace, "ja");
		writeFileSync(appendFile(workspace), `${MANAGED}- My own instruction.\n`);
		const { exitCode, output } = await runCommand(workspace.paths, { operation: "plan", ...managedOptions() });
		assert.equal(exitCode, 0);
		const text = flat(output);
		assert.match(text, /Jouzu profile migration plan/u);
		assert.match(text, /From ja \(saved\)/u);
		assert.match(text, /To response language ja; display language auto/u);
		assert.match(text, /APPEND_SYSTEM\.md/u);
		assert.match(text, /keep the edited file and review the duplicated lines/u);
		assert.match(text, /remove - Reply in Japanese\./u);
		assert.match(text, /keep - My own instruction\./u);
		assert.match(text, /Confirming this plan saves it to the user-wide settings\./u);
	} finally {
		cleanup(workspace);
	}
})"

"test("the plan shows the not-saved notice for a temporary choice", async () => {
	const workspace = makeWorkspace();
	try {
		writeChoice(workspace, "ja");
		const { output } = await runCommand(workspace.paths, {
			operation: "plan",
			...managedOptions({ explicitProfile: "ja" }),
		});
		const text = flat(output);
		assert.match(text, /From ja \(cli\)/u);
		assert.match(text, /The profile choice is temporary; the user-wide settings are not changed\./u);
	} finally {
		cleanup(workspace);
	}
})"

"test("the plan is available as JSON without the human rendering path", async () => {
	const workspace = makeWorkspace();
	try {
		writeChoice(workspace, "ja");
		const { exitCode, output } = await runCommand(workspace.paths, {
			operation: "plan",
			json: true,
			...managedOptions(),
		});
		assert.equal(exitCode, 0);
		const plan = JSON.parse(output);
		assert.deepEqual(plan.from, { profile: "ja", source: "saved" });
		assert.deepEqual(plan.to, { responseLanguage: "ja", uiLocale: "auto" });
		assert.deepEqual(plan.conflicts, []);
	} finally {
		cleanup(workspace);
	}
})"

"test("confirming applies the plan through the module and reports the receipt", async () => {
	const workspace = makeWorkspace();
	try {
		writeChoice(workspace, "ja");
		writeSettings(workspace, { uiLocale: "en", responseLanguage: "en" });
		writeFileSync(appendFile(workspace), MANAGED);
		const { exitCode, output } = await runCommand(workspace.paths, {
			operation: "apply",
			interactive: true,
			input: input("y\n"),
			...managedOptions(),
		});
		assert.equal(exitCode, 0);
		const text = flat(output);
		assert.match(text, /Apply this migration\? \[y\/N\]/u);
		assert.match(text, /Applied profile migration transaction: [0-9a-f-]{36}/u);
		assert.match(text, /Backup: /u);
		assert.match(text, /Changed files: localization\.json, APPEND_SYSTEM\.md/u);

		const saved = JSON.parse(readFileSync(settingsFile(workspace), "utf8"));
		assert.equal(saved.localization.responseLanguage, "ja");
		assert.equal(saved.localization.uiLocale, "en");
		assert.equal(existsSync(appendFile(workspace)), false, "the managed duplicate is removed");

		const stored = readStoredProfileMigrationReceipt(workspace.paths);
		assert.equal(stored.status, "ok");
		assert.deepEqual([...stored.receipt.targets].sort(), ["APPEND_SYSTEM.md", LOCALIZATION_FILE_NAME].sort());
		assert.ok(stored.receipt.backupDir?.includes("profile-migration"));
	} finally {
		cleanup(workspace);
	}
})"

"test("an apply with --yes is the non-interactive confirmation", async () => {
	const workspace = makeWorkspace();
	try {
		writeChoice(workspace, "ja");
		writeSettings(workspace, { uiLocale: "en", responseLanguage: "en" });
		const { exitCode, output } = await runCommand(workspace.paths, {
			operation: "apply",
			yes: true,
			...managedOptions(),
		});
		assert.equal(exitCode, 0);
		assert.match(output, /Applied profile migration transaction:/u);
		assert.equal(JSON.parse(readFileSync(settingsFile(workspace), "utf8")).localization.responseLanguage, "ja");
	} finally {
		cleanup(workspace);
	}
})"

"test("cancelling writes nothing", async () => {
	const workspace = makeWorkspace();
	try {
