		"す。",
		"",
		"次の行で",
		"す。",
	]);
	assert.deepEqual(wrapProseText("first\n\nsecond", 8), ["first", "", "second"]);
	assert.deepEqual(wrapProseText("first\n", 8), ["first", ""]);
