})"

"test("protected spans keep inline code, math, and short URLs intact", () => {
	const code = "これは`コード`です。";
	const codeLines = wrapProseText(code, 8, [{ start: 3, end: 8 }]);
	assert.deepEqual(codeLines, ["これは", "`コード`", "です。"]);

	const math = "これはx² + y²です。";
