	assert.deepEqual(spacedCodeLines, ["これは", "` foo`で", "す。"]);

	const mixed = "hello\nこれは`コード`です。";
	const mixedLines = wrapProseText(mixed, 8, [{ start: 9, end: 14 }]);
	assert.deepEqual(mixedLines, ["hello", "これは", "`コード`", "です。"]);
})"

