"test("literal-heavy protected spans map in one pass", { timeout: 5000 }, () => {
	const count = 100_000;
	const text = "あ".repeat(count);
	const spans = Array.from({ length: count }, (_, index) => ({ start: index, end: index + 1 }));
	const lines = wrapProseText(text, 80, spans);
	assert.equal(plain(lines).join(""), text);
	assert.equal(lines.length, Math.ceil(count / 40));
})"

"test("protected value constructors carry a distinguishing kind", () => {
	const values = {
		command: protectedCommand("doctor"),
		path: protectedPath("/home/user/.config/jouzu"),
		url: protectedUrl("https://example.test/dashboard"),
		"model-id": protectedModelId("shisa/deepseek-v4-flash"),
		"error-code": protectedErrorCode("doctor.pi.lockUnqualified"),
		"source-error": protectedSourceError("Cannot find module 'x'"),
		digest: protectedDigest("a".repeat(64)),
	};
	assert.deepEqual(
		Object.fromEntries(Object.entries(values).map(([kind, value]) => [kind, value.kind])),
		Object.fromEntries(Object.keys(values).map((kind) => [kind, kind])),
	);
	assert.deepEqual(
		Object.values(values).map((value) => value.value),
		[
			"doctor",
			"/home/user/.config/jouzu",
			"https://example.test/dashboard",
			"shisa/deepseek-v4-flash",
			"doctor.pi.lockUnqualified",
			"Cannot find module 'x'",
			"a".repeat(64),
		],
	);
})"

"test("resolveHumanMessage renders a protected value as its text", () => {
	const message = humanMessage(CliMessageId.optionValueRequired, { option: protectedCommand("--jouzu-home") });
	assert.equal(resolveHumanMessage(message), "--jouzu-home requires a value");
})"

"test("a UsageError renders from its descriptor, not its cached text", () => {
	const parserError = new UsageError(
		humanMessage(CliMessageId.optionValueRequired, { option: protectedCommand("--jouzu-home") }),
	);
	// The descriptor is the rendering source, so a stale cached message cannot freeze it.
	parserError.message = "stale cached text";
	assert.equal(usageErrorMessage(parserError), "--jouzu-home requires a value");
	assert.equal(renderMainError(parserError)[0], "Error: --jouzu-home requires a value");

	const plainError = new UsageError("plain parser failure");
	assert.equal(usageErrorMessage(plainError), "plain parser failure");
	assert.equal(renderMainError(plainError)[0], "Error: plain parser failure");
})"

"test("a locale without a table falls back to English", () => {
	const message = humanMessage(CliMessageId.usageHint);
	assert.equal(resolveHumanMessage(message, "en"), resolveHumanMessage(message));
	assert.equal(resolveHumanMessage(message, "ja"), resolveHumanMessage(message));
	assert.equal(resolveHumanMessage(message, "zh-Hant"), resolveHumanMessage(message));
})"

"test("protectedJouzuPaths marks all seven Jouzu paths as protected", () => {
	const paths = {
		configDir: "/home/user/.config/jouzu",
		agentDir: "/home/user/.config/jouzu/agent",
		stateDir: "/home/user/.local/state/jouzu",
		cacheDir: "/home/user/.cache/jouzu",
		sessionDir: "/home/user/.local/state/jouzu/sessions",
		profileStatePath: "/home/user/.local/state/jouzu/profile-state.json",
		backupDir: "/home/user/.local/state/jouzu/backups",
	};
	const protectedPaths = protectedJouzuPaths(paths);
	assert.deepEqual(Object.keys(protectedPaths), Object.keys(paths));
	for (const [key, value] of Object.entries(protectedPaths)) {
		assert.equal(value.kind, "path", `${key} is a protected path`);
		assert.equal(value.value, paths[key], `${key} keeps its value`);
	}
})"

"test("release extensions execute stateful workflows and clean up lifecycle resources", {
	timeout: 120_000,
}, async () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-extension-behavior-"));
	const previousCwd = process.cwd();
	const previousAgentDir = process.env.PI_CODING_AGENT_DIR;
	const previousRuntimeStateDir = process.env.JOUZU_RUNTIME_STATE_DIR;
	const previousTasks = process.env.PI_TASKS;
	const previousVccConfig = process.env.PI_VCC_CONFIG_PATH;
	const forceEarlyFailure = process.env.JOUZU_TEST_EXTENSION_EARLY_FAILURE === "1";
	let extensions = [];
	let harness;
	let backgroundPid;
	try {
		process.chdir(root);
		process.env.PI_CODING_AGENT_DIR = join(root, "agent");
		process.env.JOUZU_RUNTIME_STATE_DIR = join(root, "state");
		process.env.PI_TASKS = "off";
		process.env.PI_VCC_CONFIG_PATH = join(root, "pi-vcc-config.json");
		mkdirSync(process.env.PI_CODING_AGENT_DIR, { recursive: true });
		writeFileSync(
			process.env.PI_VCC_CONFIG_PATH,
			JSON.stringify({ overrideDefaultCompaction: true, continueAfterThresholdCompact: true, debug: false }),
		);

		harness = createHarness(root);
		const status = inspectReleaseExtensions();
		const loaded = await loadExtensions(status.resolvedExtensionPaths, root, createEventBus(), harness.runtime);
		assert.deepEqual(loaded.errors, []);
		extensions = loaded.extensions;
		await invokeHandlers(extensions, "session_start", { type: "session_start", reason: "startup" }, harness.ctx);

		const taskCreate = await execute(
			getTool(extensions, "TaskCreate"),
			{ subject: "Qualify", description: "Exercise task state" },
			harness.ctx,
		);
		assert.match(textOf(taskCreate), /Task #1 created/u);
		await execute(getTool(extensions, "TaskUpdate"), { taskId: "1", status: "in_progress" }, harness.ctx);
		const taskList = await execute(getTool(extensions, "TaskList"), {}, harness.ctx);
		assert.match(textOf(taskList), /Qualify/u);

		const goal = getCommand(extensions, "goal");
		await goal.handler("Complete extension qualification", harness.ctx);
		const goalResult = await execute(getTool(extensions, "get_goal"), {}, harness.ctx);
		assert.match(textOf(goalResult), /Complete extension qualification/u);
		await execute(getTool(extensions, "TaskUpdate"), { taskId: "1", status: "completed" }, harness.ctx);
		const completeGoal = await execute(getTool(extensions, "update_goal"), { status: "complete" }, harness.ctx);
		assert.match(textOf(completeGoal), /complete/u);

		const scheduleTool = getTool(extensions, "schedule_prompt");
		const scheduled = await execute(
			scheduleTool,
			{ action: "add", schedule: "+1h", prompt: "qualification", type: "once", name: "qualification" },
			harness.ctx,
		);
		assert.match(textOf(scheduled), /Created cron job/u);
		const jobId = scheduled.details.jobId;
		assert.ok(jobId);
		assert.match(textOf(await execute(scheduleTool, { action: "list" }, harness.ctx)), /qualification/u);
		assert.match(textOf(await execute(scheduleTool, { action: "remove", jobId }, harness.ctx)), /Removed cron job/u);

		const startLoop = await execute(
			getTool(extensions, "multiloop_start"),
			{
				lane: "qualification",
				mode: "research",
				goal: "Exercise lifecycle",
				verifyCommand: 'node -e "console.log(1)"',
			},
			harness.ctx,
		);
		assert.match(textOf(startLoop), /qualification/u);
		if (forceEarlyFailure) throw new Error("intentional extension lifecycle qualification failure");
		await execute(
			getTool(extensions, "multiloop_iterate"),
			{ lane: "qualification", hypothesis: "state records" },
			harness.ctx,
		);
		await execute(
			getTool(extensions, "multiloop_measure"),
			{ lane: "qualification", measurements: [1], checks: [{ name: "fixture", passed: true, kind: "mechanical" }] },
			harness.ctx,
		);
		assert.match(
			textOf(
				await execute(
					getTool(extensions, "multiloop_log"),
					{ lane: "qualification", action: "log", metric: 1, note: "passed" },
					harness.ctx,
				),
			),
			/logged|recorded|iteration/iu,
		);
		assert.ok(existsSync(join(root, ".multiloop")));

		const recall = await execute(getTool(extensions, "vcc_recall"), { query: "qualification" }, harness.ctx);
		assert.match(textOf(recall), /active lineage|qualification/iu);
		const compactionEntries = [
			{ id: "c1", type: "message", message: { role: "user", content: "first goal" } },
			{ id: "c2", type: "message", message: { role: "assistant", content: "first result" } },
			{ id: "c3", type: "message", message: { role: "user", content: "second goal" } },
			{ id: "c4", type: "message", message: { role: "assistant", content: "second result" } },
		];
		const compactionResults = await invokeHandlers(
			extensions,
			"session_before_compact",
			{
				type: "session_before_compact",
				reason: "threshold",
				willRetry: false,
				branchEntries: compactionEntries,
				preparation: {
					previousSummary: undefined,
					fileOps: { read: [], written: [], edited: [] },
					tokensBefore: 1000,
				},
				signal: new AbortController().signal,
			},
			harness.ctx,
		);
		assert.ok(compactionResults.some((result) => result?.compaction?.summary));

		const skillInput = await invokeHandlers(
			extensions,
			"input",
			{ type: "input", text: "$jouzu-clear-writing check", images: [], source: "rpc" },
			harness.ctx,
		);
		assert.ok(
			skillInput.some((result) => result?.action === "transform" && result.text === "/skill:jouzu-clear-writing check"),
		);
		assert.ok(harness.autocompleteProviders.length > 0);

		const writeTool = getTool(extensions, "write");
		const writePath = join(root, "preview.txt");
		const writeResult = await execute(writeTool, { path: writePath, content: "preview\n" }, harness.ctx);
		assert.equal(readFileSync(writePath, "utf8"), "preview\n");
		const writeComponent = writeTool.renderResult?.(writeResult, { expanded: true }, fakeTheme(), {
			toolCallId: "qualification-write",
			args: { path: writePath, content: "preview\n" },
			state: {},
			isError: false,
			invalidate() {},
		});
		assert.ok(writeComponent?.render(100).length > 0);
		await getCommand(extensions, "code-preview-health").handler("", harness.ctx);
		assert.ok(harness.rendered.some((line) => line.includes("Code preview health")));

		const invalidFetch = await execute(getTool(extensions, "web_fetch"), { url: "ftp://example.com" }, harness.ctx);
		assert.match(textOf(invalidFetch), /Error|invalid|http/iu);
		const invalidBatch = await execute(
			getTool(extensions, "batch_web_fetch"),
			{ requests: [{ url: "ftp://example.com" }] },
			harness.ctx,
		);
		assert.match(textOf(invalidBatch), /error|failed|invalid/iu);

		const bgTool = getTool(extensions, "bg_task");
		if (process.platform === "win32") {
			assert.match(textOf(await execute(bgTool, { action: "list" }, harness.ctx)), /No background tasks/iu);
		} else {
			const spawned = await execute(
				bgTool,
				{
					action: "spawn",
					command: `${process.execPath} -e "setTimeout(() => {}, 5000)"`,
					cwd: root,
					notifyOnExit: true,
				},
				harness.ctx,
			);
			backgroundPid = spawned.details.task.pid;
			assert.ok(backgroundPid > 0);
			assert.match(textOf(await execute(bgTool, { action: "list" }, harness.ctx)), /running/iu);
		}

		await invokeHandlers(extensions, "session_shutdown", { type: "session_shutdown", reason: "reload" }, harness.ctx);
		await sleep(100);
		await invokeHandlers(
			extensions,
			"session_start",
			{ type: "session_start", reason: "reload", previousSessionFile: harness.sessionFile },
			harness.ctx,
		);
		await invokeHandlers(extensions, "session_shutdown", { type: "session_shutdown", reason: "new" }, harness.ctx);
		await invokeHandlers(
			extensions,
			"session_start",
			{ type: "session_start", reason: "new", previousSessionFile: harness.sessionFile },
			harness.ctx,
		);
		await invokeHandlers(extensions, "session_shutdown", { type: "session_shutdown", reason: "quit" }, harness.ctx);
		if (backgroundPid) {
			await sleep(300);
			assert.throws(() => process.kill(backgroundPid, 0), /ESRCH/u);
			backgroundPid = undefined;
		}
	} catch (error) {
		if (!forceEarlyFailure || error?.message !== "intentional extension lifecycle qualification failure") throw error;
	} finally {
		if (extensions.length > 0 && harness) {
			try {
				await invokeHandlers(extensions, "session_shutdown", { type: "session_shutdown", reason: "quit" }, harness.ctx);
			} catch {}
		}
		if (backgroundPid) {
			try {
				process.kill(backgroundPid, "SIGKILL");
			} catch {}
		}
		process.chdir(previousCwd);
		if (previousAgentDir === undefined) delete process.env.PI_CODING_AGENT_DIR;
		else process.env.PI_CODING_AGENT_DIR = previousAgentDir;
		if (previousRuntimeStateDir === undefined) delete process.env.JOUZU_RUNTIME_STATE_DIR;
		else process.env.JOUZU_RUNTIME_STATE_DIR = previousRuntimeStateDir;
		if (previousTasks === undefined) delete process.env.PI_TASKS;
		else process.env.PI_TASKS = previousTasks;
		if (previousVccConfig === undefined) delete process.env.PI_VCC_CONFIG_PATH;
		else process.env.PI_VCC_CONFIG_PATH = previousVccConfig;
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("required web extensions fetch without installing the optional browser runtime", {
	skip: process.env.JOUZU_EXTENSION_NETWORK !== "1",
	timeout: 600_000,
}, async () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-extension-network-"));
	const previousCwd = process.cwd();
	const previousAgentDir = process.env.PI_CODING_AGENT_DIR;
	const previousRuntimeStateDir = process.env.JOUZU_RUNTIME_STATE_DIR;
	let extensions = [];
	let harness;
	try {
		process.chdir(root);
		process.env.PI_CODING_AGENT_DIR = join(root, "agent");
		process.env.JOUZU_RUNTIME_STATE_DIR = join(root, "state");
		mkdirSync(process.env.PI_CODING_AGENT_DIR, { recursive: true });
		harness = createHarness(root);
		const status = inspectReleaseExtensions();
		const loaded = await loadExtensions(status.resolvedExtensionPaths, root, createEventBus(), harness.runtime);
		assert.deepEqual(loaded.errors, []);
		extensions = loaded.extensions;
		await invokeHandlers(extensions, "session_start", { type: "session_start", reason: "startup" }, harness.ctx);

		const fetched = await execute(
			getTool(extensions, "web_fetch"),
			{ url: "https://example.com/", format: "markdown", maxChars: 10_000, timeoutMs: 30_000 },
			harness.ctx,
		);
		assert.match(textOf(fetched), /Example Domain/u);

		const batch = await execute(
			getTool(extensions, "batch_web_fetch"),
			{
				requests: [
					{ url: "https://example.com/", format: "markdown", maxChars: 10_000 },
					{ url: "https://www.iana.org/help/example-domains", format: "markdown", maxChars: 20_000 },
				],
			},
			harness.ctx,
		);
		assert.doesNotMatch(textOf(batch), /Unexpected batch_web_fetch failure/u);
		assert.equal(batch.details.total, 2);
		assert.equal(batch.details.succeeded, 2);
		assert.equal(batch.details.failed, 0);

		// The installed renderer lists each URL with its settled status instead of one summary line.
		const batchComponent = getTool(extensions, "batch_web_fetch").renderResult?.(
			batch,
			{ expanded: false },
			fakeTheme(),
			{ lastComponent: undefined, isError: false, invalidate() {} },
		);
		const batchLines = batchComponent?.render(120) ?? [];
		assert.equal(batchLines.length, 3);
		assert.match(batchLines[0] ?? "", /^Fetched 2\/2 URLs/u);
		assert.equal(batchLines.filter((line) => line.includes("https://example.com/")).length, 1);
		assert.equal(batchLines.filter((line) => line.includes("https://www.iana.org/help/example-domains")).length, 1);
		assert.ok(batchLines.slice(1).every((line) => line.includes("✓")));

		assert.ok(getTool(extensions, "tff-fetch_url"));
		assert.ok(getTool(extensions, "tff-search_web"));
		assert.equal(existsSync(join(root, "state", "camoufox-runtime")), false);
	} finally {
		if (extensions.length > 0 && harness) {
			try {
				await invokeHandlers(extensions, "session_shutdown", { type: "session_shutdown", reason: "quit" }, harness.ctx);
			} catch {}
		}
		process.chdir(previousCwd);
		if (previousAgentDir === undefined) delete process.env.PI_CODING_AGENT_DIR;
		else process.env.PI_CODING_AGENT_DIR = previousAgentDir;
		if (previousRuntimeStateDir === undefined) delete process.env.JOUZU_RUNTIME_STATE_DIR;
		else process.env.JOUZU_RUNTIME_STATE_DIR = previousRuntimeStateDir;
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("the release manifest and bundle list contain the selected extension set", () => {
	assert.equal(manifest.schemaVersion, 1);
	assert.deepEqual(packageNames(manifest.packages), expectedExtensions);
	assert.deepEqual(packageNames(manifest.compatibilityDependencies), expectedCompatibility);
	assert.deepEqual(
		[...packageJson.bundleDependencies].sort(),
		[
			"@agentclientprotocol/sdk",
			"zod",
			"@earendil-works/pi-agent-core",
			"@earendil-works/pi-ai",
			"@earendil-works/pi-codemode",
			"@earendil-works/pi-coding-agent",
			"@earendil-works/pi-mcp",
			"@earendil-works/pi-telemetry",
			"@earendil-works/pi-tui",
			"@picovoice/pvrecorder-node",
			"get-east-asian-width",
			"marked",
			"partial-json",
			"ws",
			...expectedExtensions.filter((name) => name !== "jouzu-camoufox-adapter"),
			"typebox",
		].sort(),
	);
	const piTasksExtension = manifest.packages.find((record) => record.name === "@lhl/pi-tasks");
	assert.deepEqual({ version: piTasksExtension?.version, commit: piTasksExtension?.commit }, expectedPiTasks);
	for (const record of manifest.compatibilityDependencies) {
		assert.equal(record.bundled, record.name === "typebox" ? undefined : false);
	}
	const webaioExtension = manifest.packages.find((record) => record.name === "pi-webaio");
	assert.equal(webaioExtension.optional, undefined);
	assert.deepEqual(webaioExtension.tools, ["web_fetch", "batch_web_fetch"]);
	assert.deepEqual(webaioExtension.extensions, ["dist/src/jouzu-extension.js"]);
	assert.deepEqual(webaioExtension.dependencyRemovals, ["playwright", "wreq-js", "@modelcontextprotocol/sdk"]);
	assert.deepEqual(manifest.runtimeDependencyRedirects, []);
	const camoufoxAdapter = manifest.packages.find((record) => record.name === "jouzu-camoufox-adapter");
	assert.equal(camoufoxAdapter.optional, true);
	assert.equal(camoufoxAdapter.adapter, "jouzu-lazy-camoufox");
	assert.deepEqual(camoufoxAdapter.tools, ["tff-fetch_url", "tff-search_web"]);
	assert.deepEqual(camoufoxAdapter.extensions, ["dist/camoufox-adapter.js"]);
	for (const record of [...manifest.packages, ...manifest.compatibilityDependencies]) {
		if (!record.adapter)
			assert.equal(packageJson.dependencies[record.name], record.commit ? record.source : record.version);
		assert.match(record.repository, /^https:\/\//u);
		assert.ok(record.license);
		assert.ok(record.licenseEvidence);
		if (record.integrity) assert.match(record.integrity, /^sha512-[A-Za-z0-9+/]+={0,2}$/u);
		if (!record.adapter) {
			const noticePin = record.commit ? `\`${record.commit}\`` : record.version;
			assert.ok(
				thirdPartyNotices.includes(`| \`${record.name}\` | ${noticePin}`),
				`${record.name} notice does not identify ${noticePin}`,
			);
		}
	}
})"

