"test("corrupt and symlinked profile state raise a strict ProfileStateError", () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-runtime-strict-"));
	try {
		const resolved = paths(root);
		mkdirSync(resolved.stateDir, { recursive: true });
		writeFileSync(resolved.profileStatePath, "{ not valid json");
		assert.throws(() => resolveProfileSelection(resolved, { env: {} }), ProfileStateError);
		assert.match(
			(() => {
				try {
					resolveProfileSelection(resolved, { env: {} });
					return "";
				} catch (error) {
					return error.message;
				}
			})(),
			/profile-state\.json/,
		);

		rmSync(resolved.profileStatePath, { force: true });
		const outside = join(root, "outside");
		writeFileSync(outside, JSON.stringify(validState("ja", "b".repeat(64))));
		symlinkSync(outside, resolved.profileStatePath);
		assert.throws(() => resolveProfileSelection(resolved, { env: {} }), ProfileStateError);
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("scrollback observes live shell activity and clears only its own attachment", async () => {
	const observer = createScrollbackSessionObserver();
	const first = observer.wrap();
	const second = observer.wrap();
	const session = { isBashRunning: true };
	assert.equal(observer.isShellBusy(), false);
	await first.attach(session);
	assert.equal(observer.isShellBusy(), true);
	session.isBashRunning = false;
	assert.equal(observer.isShellBusy(), false);
	await second.attach({ isBashRunning: true });
	await first.dispose();
	assert.equal(observer.isShellBusy(), true);
	await second.dispose();
	assert.equal(observer.isShellBusy(), false);
})"

"test("scrollback wrapper preserves delegate methods, receivers, and dispatch ownership", async () => {
	const observer = createScrollbackSessionObserver();
	const calls = [];
	const delegate = {
		version: 1,
		async attach(value) {
			assert.equal(this, delegate);
			calls.push(["attach", value]);
		},
		async dispose() {
			assert.equal(this, delegate);
			calls.push(["dispose"]);
		},
		async beforeBranchChange(value) {
			assert.equal(this, delegate);
			calls.push(["before", value]);
		},
		async branchChanged(value) {
			assert.equal(this, delegate);
			calls.push(["after", value]);
		},
		async runCommand(value, run) {
			assert.equal(this, delegate);
			calls.push(["command", value]);
			await run();
		},
		async submit(value) {
			assert.equal(this, delegate);
			calls.push(["submit", value]);
		},
	};
	const wrapped = observer.wrap(delegate);
	const session = { isBashRunning: false };
	const scope = {};
	const submission = {};
	await wrapped.attach(session);
	await wrapped.beforeBranchChange(scope);
	await wrapped.branchChanged(scope);
	let commands = 0;
	await wrapped.runCommand(submission, async () => {
		commands++;
	});
	assert.equal(commands, 1);
	await wrapped.submit(submission, () => {
		throw Error("delegate owns dispatch");
	});
	await wrapped.dispose();
	assert.deepEqual(calls, [
		["attach", session],
		["before", scope],
		["after", scope],
		["command", submission],
		["submit", submission],
		["dispose"],
	]);
	let dispatched = 0;
	await observer.wrap().submit(submission, async () => {
		dispatched++;
	});
	assert.equal(dispatched, 1);
	await observer.wrap().runCommand(submission, async () => {
		commands++;
	});
	assert.equal(commands, 2);
})"

"test("scrollback wrapper forwards adapter registration and dispatch authorization with their receiver", async () => {
	const observer = createScrollbackSessionObserver();
	const calls = [];
	const adapter = {};
	const delegate = {
		version: 1,
		submit() {},
		async registerUserInputAdapter(...args) {
			assert.equal(this, delegate);
			calls.push(["register", ...args]);
			return adapter;
		},
		async authorizeExternal(...args) {
			assert.equal(this, delegate);
			calls.push(["authorize", ...args]);
			if (args[1] === "expired") throw Error("expired target");
		},
	};
	const wrapped = observer.wrap(delegate);
	const host = {};
	const options = { id: "fixture", label: "Fixture" };
	const submission = {};
	assert.equal(await wrapped.registerUserInputAdapter(host, options), adapter);
	await wrapped.authorizeExternal(submission, "epoch");
	await assert.rejects(wrapped.authorizeExternal(submission, "expired"), /expired target/);
	assert.deepEqual(calls, [
		["register", host, options],
		["authorize", submission, "epoch"],
		["authorize", submission, "expired"],
	]);
	assert.equal(observer.wrap().registerUserInputAdapter, undefined);
	assert.equal(observer.wrap().authorizeExternal, undefined);
})"

"test("host shell activity stays busy through executeBash while the agent is idle", async (t) => {
	const observer = createScrollbackSessionObserver();
	const { session } = await createFlowSession(t, { ingress: observer.wrap() });
	const entered = deferred();
	const release = deferred();
	const running = session.executeBash("fixture", undefined, {
		operations: {
			async exec() {
				entered.resolve();
				await release.promise;
				return { exitCode: 0 };
			},
		},
	});
	try {
		await entered.promise;
		assert.equal(session.isIdle, true);
		assert.equal(observer.isShellBusy(), true);
	} finally {
		release.resolve();
		await running;
	}
	assert.equal(observer.isShellBusy(), false);
	await session.dispose();
	assert.equal(observer.isShellBusy(), false);
})"

"test("failed attachment does not replace the observed session", async () => {
	const observer = createScrollbackSessionObserver();
	await observer.wrap().attach({ isBashRunning: true });
	const wrapped = observer.wrap({
		version: 1,
		attach() {
			throw Error("attach failed");
		},
		submit() {},
	});
	await assert.rejects(wrapped.attach({ isBashRunning: false }), /attach failed/);
	assert.equal(observer.isShellBusy(), true);
	await wrapped.dispose();
	assert.equal(observer.isShellBusy(), true);
})"

"test("exports the active branch through the real fullscreen renderer and returns", async () => {
	const branch = [
		message("system", { content: "SECRET SYSTEM PROMPT" }),
		message("user", {
			content: [
				{ type: "text", text: "hello 日本語" },
				{ type: "image", data: "QUJD", mimeType: "image/png" },
			],
		}),
		message("assistant", {
			content: [
				{ type: "text", text: "answer" },
				{ type: "thinking", thinking: "plan" },
				{ type: "toolCall", id: "t1", name: "bash", arguments: { command: "ls" } },
			],
			stopReason: "toolUse",
		}),
		message("toolResult", {
			toolCallId: "t1",
			toolName: "bash",
			content: [{ type: "text", text: "file.txt" }],
			isError: false,
		}),
		entry("custom_message", { customType: "note", content: "custom note", display: true }),
		entry("compaction", { summary: "older context", firstKeptEntryId: "entry-1", tokensBefore: 1234 }),
		entry("branch_summary", { summary: "other branch", fromId: "abc" }),
		message("bashExecution", {
			command: "echo hi",
			output: "hi",
			exitCode: 0,
			cancelled: false,
			truncated: false,
		}),
		entry("model_change", { provider: "provider", modelId: "model" }),
		message("user", { content: "after compaction" }),
	];
	const harness = await createHarness({ branch });
	try {
		assert.equal(harness.tui.constructor.name, "TuiAltScreen");
		assert.equal(harness.tui.mode, "fullscreen");
		const { promise } = await beginExport(harness);

		const altExit = harness.terminal.output.indexOf("\u001b[?1049l");
		const transcriptStart = harness.terminal.output.indexOf("Jouzu transcript export");
		assert.ok(altExit >= 0, "the export leaves the alternate screen");
		assert.ok(transcriptStart > altExit, "the transcript is written after leaving the alternate screen");
		assert.equal(harness.terminal.output.slice(0, altExit).includes("Jouzu transcript export"), false);

		const body = transcriptText(harness.terminal);
		for (const expected of [
			"Jouzu transcript export",
			"Session: session-1",
			"Exported: 2026-01-01T00:00:00.000Z",
			"Scope: stored entries on the active branch",
			"Limits: system prompts, tool details, and raw image data are not included",
			"User",
			"hello 日本語",
			"[image: image/png, 3 B]",
			"Assistant",
			"answer",
			"Thinking",
			"plan",
			"Tool call: bash",
			'"command": "ls"',
			"Tool result: bash",
			"file.txt",
			"Custom message (note)",
			"custom note",
			"Compaction summary",
			"older context",
			"1234 tokens before",
			"Branch summary",
			"other branch",
			"[from abc]",
			"Bash",
			"$ echo hi",
			"hi",
			"[exit code 0]",
			"after compaction",
			HINT,
		]) {
			assert.ok(body.includes(expected), `the transcript includes ${JSON.stringify(expected)}`);
		}
		assert.equal(body.includes("SECRET SYSTEM PROMPT"), false, "the system prompt is omitted");
		assert.equal(body.includes("QUJD"), false, "raw image data is not exported");
		assert.equal(body.includes("OFF BRANCH SECRET"), false, "only the supplied active branch is read");
		assert.equal(harness.state.getBranchCalls, 1, "the export reads the active branch");
		assertPlainText(body, "the transcript");

		assert.equal(harness.tui.hasOverlay(), true, "the custom screen is mounted as an overlay");
		assert.equal(harness.ui.surfaces[0].options.overlay, true, "the overlay preserves the editor container");
		assert.equal(harness.editor.getText(), DRAFT, "the draft is unchanged while the export is open");
		assert.equal(harness.terminal.titles.length, 0, "the export does not change the terminal title");

		const beforeReturn = harness.terminal.output.length;
		harness.tui.requestRender(true);
		await tick();
		assert.equal(harness.terminal.output.length, beforeReturn, "the stopped renderer does not redraw over the export");

		await returnFromExport(harness, promise, "\r");
		assert.ok(harness.terminal.output.lastIndexOf("\u001b[?1049h") > transcriptStart, "the TUI re-enters fullscreen");
		assert.equal(harness.tui.hasOverlay(), false, "return closes the overlay");
		assert.equal(harness.tui.getFocusedComponent(), harness.editor, "focus returns to the prompt");
		assert.equal(harness.editor.getText(), DRAFT, "the draft survives the export");
		assert.equal(harness.editor.setTextCalls, 0, "the export never rewrites the editor");
		assert.equal(harness.state.editorTextCalls.length, 0, "the export never sets editor text");
		assert.equal(harness.tui.mode, "fullscreen", "the TUI mode is unchanged");
		assert.equal(harness.terminal.titles.length, 0, "the terminal title is still unchanged");
		assert.equal(harness.state.notifications.length, 0, "a successful return needs no notification");
	} finally {
		harness.cleanup();
	}
})"

