	await settle();
	await f.command("");
	assert.match(f.notifications.at(-1), /revisit after 2 more completed/);
	await f.finish();
	await f.finish();
	assert.equal(f.calls.length, 1);
	await f.input("The auth API");
	assert.equal(f.calls.length, 1);
	await f.input("Fix login validation");
