			const bar = renderStatusBar(snapshot, width, plainStyles, text[locale]);
			assert.equal(line, SESSION_LINE_GOLDEN[key], `line ${key}`);
			assert.equal(bar, STATUS_BAR_GOLDEN[key], `status bar ${key}`);
