"test(`${operation} failures leave an existing lock busy rather than free or recoverable`, (t) => {
		const { root, stateDir } = makeStateDir();
		const path = join(stateDir, "lock");
		writeAged(path, "", STATE_LOCK_STALE_MS + 1000);
		const original = fs[operation];
		t.mock.method(fs, operation, (target, ...args) => {
			if (target === path || typeof target === "number")
				throw Object.assign(new Error("inspection failed"), { code: "EIO" });
			return original(target, ...args);
		});
		syncBuiltinESMExports();
		try {
			assert.deepEqual(inspectStateLock(path, new Date()), { exists: true, status: "unreadable", ageMs: null });
			assert.throws(() => acquireStateLock({ path, describe: "test", onBusy: busyError }), /domain busy/);
			assert.ok(existsSync(path), "inspection failure must not remove the lock");
		} finally {
			t.mock.restoreAll();
			syncBuiltinESMExports();
			rmSync(root, { recursive: true, force: true });
		}
	})"

"test("oversized lock records stay busy and token release leaves them untouched", (t) => {
	const { root, stateDir } = makeStateDir();
	t.after(() => rmSync(root, { recursive: true, force: true }));
	const path = join(stateDir, "lock");
	const release = acquireStateLock({ path, describe: "test", onBusy: busyError });
	const record = readFileSync(path, "utf8").trim();
	writeAged(path, record.padEnd(STATE_LOCK_MAX_BYTES + 1), STATE_LOCK_STALE_MS + 1000);
	assert.equal(inspectStateLock(path, new Date()).status, "unreadable");
	assert.throws(() => acquireStateLock({ path, describe: "test", onBusy: busyError }), /domain busy/);
	release();
	assert.ok(existsSync(path));
	// Even if a file grows after fstat, the read itself must remain bounded.
	const original = fs.fstatSync;
	t.mock.method(fs, "fstatSync", (...args) => Object.assign(original(...args), { size: 0 }));
	syncBuiltinESMExports();
	try {
		assert.equal(inspectStateLock(path, new Date()).status, "unreadable");
		release();
		assert.ok(existsSync(path));
	} finally {
		t.mock.restoreAll();
		syncBuiltinESMExports();
	}
	writeFileSync(path, record.padEnd(STATE_LOCK_MAX_BYTES));
	assert.equal(inspectStateLock(path, new Date()).status, "held-live");
	release();
	assert.equal(existsSync(path), false);
})"

"test("inspectStateLock reports free, dead, and owner-unknown states", async () => {
	const { root, stateDir } = makeStateDir();
	try {
		const path = join(stateDir, "lock");
		assert.equal(inspectStateLock(path, new Date()).status, "free");

		writeFileSync(
			path,
			`${JSON.stringify({ pid: await deadPid(), startedAt: new Date().toISOString(), token: "x" })}\n`,
		);
		assert.equal(inspectStateLock(path, new Date()).status, "held-dead");

		writeAged(path, "", 5000);
		assert.equal(inspectStateLock(path, new Date()).status, "owner-unknown");
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("real reviewer reads a sibling file with role-limited tools", { timeout: 20_000 }, async () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-child-access-"));
	const cwd = join(root, "workspace");
	mkdirSync(cwd);
	const outside = join(root, "reference.txt");
	writeFileSync(outside, "SIBLING_REFERENCE_EVIDENCE");
	const requests = [];
	const server = createServer(async (req, res) => {
		const chunks = [];
		for await (const chunk of req) chunks.push(chunk);
		requests.push(JSON.parse(Buffer.concat(chunks).toString()));
		res.writeHead(200, { "Content-Type": "text/event-stream" });
		const first = requests.length === 1;
		const delta = first
			? {
					role: "assistant",
					tool_calls: [
						{
							index: 0,
							id: "read-sibling",
							type: "function",
							function: { name: "read", arguments: JSON.stringify({ path: outside }) },
						},
					],
				}
			: { role: "assistant", content: "Sibling read completed." };
		res.write(`data: ${JSON.stringify({ id: "fixture", choices: [{ index: 0, delta, finish_reason: null }] })}\n\n`);
		res.write(
			`data: ${JSON.stringify({ id: "fixture", choices: [{ index: 0, delta: {}, finish_reason: first ? "tool_calls" : "stop" }], usage: { prompt_tokens: 10, completion_tokens: 5, total_tokens: 15 } })}\n\n`,
		);
		res.end("data: [DONE]\n\n");
	});
	server.listen(0, "127.0.0.1");
	await once(server, "listening");
	let resolveRun;
	const done = new Promise((resolve) => {
		resolveRun = resolve;
	});
	const manager = new SubagentManager(
		{ configDir: join(root, "config"), stateDir: join(root, "state") },
		"parent",
		1,
		undefined,
		resolveRun,
	);
	try {
		manager.launch({
			cwd,
			role: { ...defaultAgentConfig().roles[2], thinking: "off" },
			task: "Read the sibling reference",
			auth: { apiKey: "fixture" },
			model: {
				provider: "fixture",
				id: "test",
				name: "Fixture",
				api: "openai-completions",
				baseUrl: `http://127.0.0.1:${server.address().port}/v1`,
				reasoning: false,
				input: ["text"],
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
				contextWindow: 32000,
				maxTokens: 512,
			},
		});
		const result = await done;
		assert.equal(result.status, "completed", result.result);
		assert.equal(requests.length, 2);
		assert.ok(JSON.stringify(requests[1].messages).includes("SIBLING_REFERENCE_EVIDENCE"));
		assert.ok(requests[0].tools.some((tool) => tool.function.name === "vcc_recall"));
		assert.ok(requests[0].tools.every((tool) => !["bash", "powershell", "write", "edit"].includes(tool.function.name)));
		assert.match(readFileSync(result.sessionFile, "utf8"), /SIBLING_REFERENCE_EVIDENCE/);
	} finally {
		await manager.dispose();
		server.closeAllConnections();
		await new Promise((resolve) => server.close(resolve));
		rmSync(root, { recursive: true, force: true });
	}
})"

"test(`child warming usage and configured mode stay isolated: ${mode ?? "default"}`, { timeout: 20_000 }, async () => {
		const root = mkdtempSync(join(tmpdir(), "jouzu-child-warming-"));
		const requests = [];
		const server = createServer(async (req, res) => {
			const chunks = [];
			for await (const chunk of req) chunks.push(chunk);
			const body = JSON.parse(Buffer.concat(chunks).toString());
			requests.push(body);
			const first = requests.length === 1;
			const warm = body.max_tokens === 1 || body.max_completion_tokens === 1;
			const delta = first
				? {
						role: "assistant",
						tool_calls: [
							{
								index: 0,
								id: "hold",
								type: "function",
								function: {
									name: "bash",
									arguments: JSON.stringify({
										command: `${JSON.stringify(process.execPath)} -e 'setTimeout(() => {}, 2500)'`,
									}),
								},
							},
						],
					}
				: { role: "assistant", content: warm ? "WARM_ONLY" : "Completed." };
			res.writeHead(200, { "Content-Type": "text/event-stream" });
			res.write(`data: ${JSON.stringify({ id: "fixture", choices: [{ index: 0, delta, finish_reason: null }] })}\n\n`);
			res.write(
				`data: ${JSON.stringify({ id: "fixture", choices: [{ index: 0, delta: {}, finish_reason: first ? "tool_calls" : "stop" }], usage: { prompt_tokens: 10, completion_tokens: warm ? 1 : 5, total_tokens: warm ? 11 : 15 } })}\n\n`,
			);
			res.end("data: [DONE]\n\n");
		});
		server.listen(0, "127.0.0.1");
		await once(server, "listening");
		let resolveRun;
		const done = new Promise((resolve) => {
			resolveRun = resolve;
		});
		const manager = new SubagentManager(
			{ configDir: join(root, "config"), stateDir: join(root, "state") },
			"parent",
			1,
			undefined,
			resolveRun,
		);
		try {
			manager.launch({
				...(mode ? { cacheWarming: mode } : {}),
				cwd: root,
				role: { ...defaultAgentConfig().roles[1], thinking: "off", maxTurns: 3 },
				task: "Run the tool and finish.",
				auth: { apiKey: "fixture" },
				model: {
					provider: "fixture",
					id: "test",
					name: "Fixture",
					api: "openai-completions",
					baseUrl: `http://127.0.0.1:${server.address().port}/v1`,
					reasoning: false,
					input: ["text"],
					// Synthetic prices make the automatic decision eligible; all requests stay on loopback.
					cost: { input: 10000, output: 1, cacheRead: 1, cacheWrite: 0 },
					promptCache: { short: 11 },
					contextWindow: 32000,
					maxTokens: 512,
				},
			});
			const result = await done;
			assert.equal(result.status, "completed", result.result);
			const readEntries = (file) => readFileSync(file, "utf8").trim().split("\n").map(JSON.parse);
			// Parent totals are fixed when the child reports its result, so read the usage the
			// parent could have received before stopping the child.
			const reported = readEntries(result.sessionFile);
			// The refresh ledger is final only after the child stops: a refresh still in flight
			// when the child finishes is aborted during shutdown and settles then.
			await manager.dispose();
			const entries = readEntries(result.sessionFile);
			const warms = entries.filter((entry) => entry.type === "usage" && entry.kind === "cache_warm");
			const reportedWarms = reported.filter((entry) => entry.type === "usage" && entry.kind === "cache_warm");
			// A refresh still in flight when the warming run is replaced is aborted, so the provider
			// can serve a refresh whose usage is never recorded. Correlate served traffic with the
			// child's own admission ledger instead of assuming every served refresh completes.
			const warmRequests = requests.filter((body) => body.max_tokens === 1 || body.max_completion_tokens === 1);
			const admissions = entries.filter(
				(entry) => entry.type === "custom" && entry.customType === "jouzu-cache-warm-request",
			);
			const handoffs = admissions.filter((entry) => entry.data?.phase === "handoff");
			const settled = admissions.filter((entry) => entry.data?.phase === "settled");
			const completed = settled.filter((entry) => entry.data?.outcome === "stop");
			const aborted = settled.filter((entry) => entry.data?.outcome === "aborted");
			const handoffIds = handoffs.map((entry) => entry.data.id);
			const settledIds = settled.map((entry) => entry.data.id);
			const handoffIdSet = new Set(handoffIds);
			assert.equal(new Set(handoffIds).size, handoffIds.length, "each refresh is admitted once");
			assert.equal(new Set(settledIds).size, settledIds.length, "each refresh settles once");
			assert.ok(
				settledIds.every((id) => handoffIdSet.has(id)),
				"every refresh outcome must belong to an admitted refresh",
			);
			assert.equal(completed.length + aborted.length, settled.length, "refresh outcomes must be stop or aborted");
			assert.equal(settled.length, handoffs.length, "every admitted refresh must settle before the child stops");
			if (mode === undefined || mode === "off") {
				assert.equal(warms.length, 0, "default and disabled children must not refresh");
				assert.equal(handoffs.length, 0, "default and disabled children must not admit a refresh");
			} else assert.ok(warms.length > 0, "worker should perform at least one automatic refresh during the tool");
			assert.equal(
				requests.length - warmRequests.length,
				2,
				"the child makes only its first and final conversational requests",
			);
			assert.ok(
				handoffs.length >= warmRequests.length,
				"every refresh the provider served must be admitted by the child",
			);
			assert.ok(
				warmRequests.length >= completed.length && warmRequests.length <= completed.length + aborted.length,
				`served refreshes must be completed or aborted: ${warmRequests.length} served, ${completed.length} completed, ${aborted.length} aborted`,
			);
			assert.equal(
				completed.length,
				warms.length,
				"each completed refresh must persist exactly one cache-warm usage entry",
			);
			for (const warm of warms) {
				assert.equal(warm.usage.input, 10);
				assert.equal(warm.usage.output, 1);
			}
			for (const warm of requests.slice(1, -1)) {
				assert.deepEqual(warm.messages, requests[0].messages);
				assert.deepEqual(warm.tools, requests[0].tools);
				assert.equal(warm.model, requests[0].model);
				assert.ok(warm.max_tokens === 1 || warm.max_completion_tokens === 1);
			}
			assert.equal(
				result.usage.input,
				(2 + reportedWarms.length) * 10,
				"parent totals must include cache-warming input",
			);
			assert.equal(result.usage.output, 10 + reportedWarms.length);
			assert.equal(result.result, "Completed.");
			assert.ok(!JSON.stringify(requests.at(-1).messages).includes("WARM_ONLY"));
			assert.equal(entries.filter((entry) => entry.type === "message" && entry.message.role === "assistant").length, 2);
			const usage = reported.flatMap((entry) =>
				entry.type === "usage"
					? [entry.usage]
					: entry.type === "message" && entry.message.role === "assistant"
						? [entry.message.usage]
						: [],
			);
			assert.ok(Math.abs(result.usage.cost - usage.reduce((sum, item) => sum + item.cost.total, 0)) < 1e-9);
		} finally {
			await manager.dispose();
			server.closeAllConnections();
			await new Promise((resolve) => server.close(resolve));
			rmSync(root, { recursive: true, force: true });
		}
	})"

"test("context inheritance is explicit reference material, strips thinking/state, and bounds injected text", () => {
	const branch = [
		entry("u", "Requirement"),
		{
			...entry("a", []),
			message: {
				role: "assistant",
				content: [
					{ type: "thinking", thinking: "PRIVATE_THINKING" },
					{ type: "image", data: "BINARY_IMAGE" },
					{
						type: "toolCall",
						name: "bash",
						id: "call",
						arguments: {
							command: "echo evidence",
							content: ["ARGUMENT_CONTENT"],
							details: { name: "ARGUMENT_DETAILS" },
						},
					},
				],
			},
		},
		{ type: "custom", customType: "task-state", data: "PARENT_TASKS", id: "state" },
	];
	const fresh = captureChildContext({}, false, "parent", branch, "a");
	assert.equal(inheritedContextText(fresh), undefined);
	const fork = captureChildContext({ context: "fork" }, false, "parent", branch, "a");
	const text = inheritedContextText(fork);
	assert.match(text, /Reference context.*parent/);
	assert.match(text, /echo evidence/);
	assert.match(text, /ARGUMENT_CONTENT/);
	assert.match(text, /ARGUMENT_DETAILS/);
	assert.doesNotMatch(JSON.stringify(fork), /PRIVATE_THINKING|BINARY_IMAGE|PARENT_TASKS/);
	const splice = captureChildContext({ context: "splice", entryIds: ["u"] }, false, "parent", branch, "a");
	assert.match(inheritedContextText(splice), /Requirement/);
	assert.doesNotMatch(inheritedContextText(splice), /echo evidence/);
	assert.throws(() => captureChildContext({ context: "fresh", entryIds: ["u"] }, false, "p", branch), /only valid/);
	const large = captureChildContext(
		{ context: "fork" },
		false,
		"p",
		Array.from({ length: 100 }, (_, index) => entry(String(index), "日".repeat(10000))),
	);
	assert.ok(inheritedContextText(large).length < 65000);
	assert.match(inheritedContextText(large), /truncated/);
})"

"test("real children can read outside cwd, use skills/recall/web/tasks, consult parent context, and retain local tasks on resume", {
	timeout: 120000,
}, async () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-child-capabilities-"));
	const workspace = join(root, "workspace");
	mkdirSync(workspace);
	writeFileSync(join(root, "reference.txt"), "EXTERNAL_REFERENCE_EVIDENCE");
	writeFileSync(join(workspace, "AGENTS.md"), "PROJECT_GUIDANCE_EVIDENCE");
	mkdirSync(join(workspace, ".pi"));
	writeFileSync(
		join(workspace, ".pi", "tasks-config.json"),
		JSON.stringify({ taskScope: "project", autoMode: "cascade" }),
	);
	writeFileSync(join(workspace, ".pi", "tasks.json"), "PARENT_TASK_FILE_UNCHANGED");
	const requests = [];
	const steps = [];
	const server = createServer(async (req, res) => {
		if (req.url === "/page") {
			res.writeHead(200, { "Content-Type": "text/html" });
			res.end(
				"<html><body><article><h1>Local evidence</h1><p>WEB_FIXTURE_EVIDENCE from a deterministic local source.</p></article></body></html>",
			);
			return;
		}
		const chunks = [];
		for await (const chunk of req) chunks.push(chunk);
		const body = JSON.parse(Buffer.concat(chunks).toString());
		requests.push(body);
		const step = steps.shift();
		if (!step) {
			respond(res, { role: "assistant", content: "DONE" }, "stop");
			return;
		}
		const [name, suppliedArgs] = step;
		let args = suppliedArgs;
		if (name === "agent_wait" && suppliedArgs === "background") {
			const result = [...body.messages]
				.reverse()
				.find(
					(message) =>
						message.role === "tool" &&
						typeof message.content === "string" &&
						message.content.includes("Wait dependency: "),
				);
			const dependency = JSON.parse(result.content.split("Wait dependency: ")[1].split("\n")[0]);
			args = { on: [dependency], mode: "all", deadline: "10s", reason: "Wait for the child fixture execution." };
		}
		if (name === "reply") {
			respond(res, { role: "assistant", content: args }, "stop");
			return;
		}
		respond(res, {
			role: "assistant",
			tool_calls: [
				{
					index: 0,
					id: `call_${requests.length}`,
					type: "function",
					function: { name, arguments: JSON.stringify(args) },
				},
			],
		});
	});
	server.listen(0, "127.0.0.1");
	await once(server, "listening");
	const model = {
		id: "test",
		provider: "fixture",
		name: "Fixture",
		api: "openai-completions",
		baseUrl: `http://127.0.0.1:${server.address().port}/v1`,
		reasoning: false,
		input: ["text"],
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
		contextWindow: 128000,
		maxTokens: 512,
	};
	let complete;
	const manager = new SubagentManager(
		{ configDir: join(root, "config"), stateDir: join(root, "state") },
		"parent",
		2,
		undefined,
		(run) => complete(run),
	);
	// Bounds a hung child. A loaded 3-CPU runner can spend 9 s starting the child before its first turn.
	const role = { ...defaultAgentConfig().roles[1], thinking: "off", timeoutSeconds: 45 };
	const launch = {
		role,
		model,
		auth: { apiKey: "fixture-key" },
		cwd: workspace,
		task: "Use the assigned tools and report DONE.",
		context: captureChildContext({}, false, "parent", [entry("requirement", "PARENT_PROJECT_DECISION")], "requirement"),
	};
	try {
		steps.push(
			["read", { path: join(root, "reference.txt") }],
			["TaskCreate", { subject: "Child work", description: "Keep this task for resume" }],
			["TaskUpdate", { taskId: "1", status: "in_progress" }],
			["TaskList", {}],
			["parent_context", { query: "PARENT_PROJECT_DECISION" }],
			["vcc_recall", { query: "EXTERNAL_REFERENCE_EVIDENCE" }],
			["web_fetch", { url: `http://127.0.0.1:${server.address().port}/page`, format: "text", timeoutMs: 5000 }],
		);
		const done = new Promise((resolve) => {
			complete = resolve;
		});
		const started = manager.launch(launch);
		steps.splice(1, 0, [
			"read",
			{ path: join(dirname(started.parentContextFile), "skills", "jouzu-clear-writing", "SKILL.md") },
		]);
		const run = await done;
		assert.equal(run.status, "completed", manager.read(started.id).text);
		assert.equal(run.result, "DONE");
		const allTools = requests[0].tools.map((tool) => tool.function.name);
		for (const name of ["vcc_recall", "compact_context", "TaskCreate", "web_fetch", "tff-search_web", "parent_context"])
			assert.ok(allTools.includes(name), `${name}: ${JSON.stringify(allTools)}`);
		assert.ok(allTools.includes("TaskExecute"));
		assert.ok(allTools.includes("bg_task"));
		assert.ok(!allTools.includes("schedule_prompt"));
		assert.ok(!allTools.includes("subagent"));
		assert.ok(allTools.includes("multiloop_start"));
		assert.ok(allTools.includes("agent_wait"));
		const prompt = JSON.stringify(requests[0].messages);
		assert.match(prompt, /PROJECT_GUIDANCE_EVIDENCE/);
		assert.match(prompt, /jouzu-clear-writing/);
		assert.match(prompt, /Jouzu capability routing/);
		const saved = readFileSync(run.sessionFile, "utf8").trim().split("\n").map(JSON.parse);
		const results = saved
			.filter((item) => item.type === "message" && item.message.role === "toolResult")
			.map((item) => item.message);
		for (const result of results) assert.equal(result.isError, false, JSON.stringify(result));
		assert.match(JSON.stringify(results.find((result) => result.toolName === "read")), /EXTERNAL_REFERENCE_EVIDENCE/);
		assert.match(
			JSON.stringify(results.find((result) => result.toolName === "parent_context")),
			/PARENT_PROJECT_DECISION/,
		);
		assert.match(
			JSON.stringify(results.find((result) => result.toolName === "vcc_recall")),
			/EXTERNAL_REFERENCE_EVIDENCE/,
		);
		// The bundled web tool deliberately blocks private addresses. Exercise its real validation without external network access.
		assert.match(JSON.stringify(results.find((result) => result.toolName === "web_fetch")), /blocked_ssrf/);
		assert.equal(readFileSync(join(workspace, ".pi", "tasks.json"), "utf8"), "PARENT_TASK_FILE_UNCHANGED");
		assert.equal(requests.length, 9, "project task auto-mode must not start extra work");
		assert.ok(
			results.some(
				(result) => result.toolName === "read" && JSON.stringify(result.content).includes("Clear Technical Writing"),
			),
		);
		const schedulePath = join(dirname(run.sessionFile), ".pi", "schedule-prompts.json");
		mkdirSync(dirname(schedulePath), { recursive: true });
		writeFileSync(
			schedulePath,
			JSON.stringify({
				version: 1,
				jobs: [
					{
						id: "legacy",
						name: "legacy",
						type: "interval",
						schedule: "1s",
						prompt: "LEGACY_CHILD_SCHEDULE",
						enabled: true,
						createdAt: "2026-01-01T00:00:00Z",
						runCount: 0,
					},
				],
			}),
		);
		const continuation = new Promise((resolve) => {
			complete = resolve;
		});
		steps.push(["TaskList", {}]);
		manager.launch(
			{ ...launch, context: undefined, task: "List your saved tasks and report DONE." },
			undefined,
			run.id,
		);
		const resumed = await continuation;
		assert.equal(resumed.status, "completed", resumed.result);
		assert.equal(resumed.childSessionId, run.childSessionId);
		assert.equal(JSON.parse(readFileSync(schedulePath, "utf8")).jobs[0].enabled, false);
		assert.match(resumed.result, /1 pending child schedule cancelled/);
		assert.equal(resumed.cancelledSchedules, 1);
		assert.equal(requests.length, 11, "resume must not run a saved child schedule");
		assert.match(
			JSON.stringify(
				requests
					.at(-1)
					.messages.filter((message) => message.role === "tool")
					.at(-1),
			),
			/Child work/,
		);
		assert.match(
			JSON.stringify(
				requests
					.at(-1)
					.messages.filter((message) => message.role === "tool")
					.at(-1),
			),
			/in_progress/,
		);
		writeFileSync(schedulePath, "{invalid");
		const recovery = new Promise((resolve) => {
			complete = resolve;
		});
		steps.push(["reply", "RECOVERED"]);
		manager.launch({ ...launch, context: undefined, task: "Report recovery." }, undefined, resumed.id);
		const recovered = await recovery;
		assert.equal(recovered.status, "completed", recovered.result);
		assert.match(recovered.result, /Saved child schedules could not be read/);
		assert.match(recovered.result, /RECOVERED/);
		assert.match(recovered.scheduleWarning, /Preserved at .*\.invalid-/);
		for (const [label, automation] of [
			[
				"task execution",
				[
					["TaskCreate", { subject: "Scheduled child work", description: "Finish after the first response" }],
					["TaskExecute", { task_ids: ["1"] }],
					["reply", "TASK_QUEUED"],
					["TaskUpdate", { taskId: "1", status: "completed" }],
					["reply", "AUTOMATION_DONE"],
				],
			],
			[
				"background completion",
				[
					[
						"bg_task",
						{
							action: "spawn",
							command: "node -e 'setTimeout(() => console.log(42), 400)'",
							notifyOnExit: true,
							timeoutSeconds: 5,
						},
					],
					["reply", "BACKGROUND_PENDING"],
					["reply", "AUTOMATION_DONE"],
				],
			],
			[
				"quiet background completion",
				[
					[
						"bg_task",
						{
							action: "spawn",
							command: "node -e 'setTimeout(() => console.log(42), 400)'",
							notifyOnExit: false,
							timeoutSeconds: 5,
						},
					],
					["reply", "AUTOMATION_DONE"],
				],
			],
			[
				"multiloop gate recovery",
				[
					[
						"multiloop_start",
						{
							lane: "child-fixture",
							runTag: "gate",
							mode: "research",
							goal: "Wait for the job and then stop the lane.",
						},
					],
					[
						"bg_task",
						{
							action: "spawn",
							command: "node -e 'setTimeout(() => console.log(42), 400)'",
							notifyOnExit: false,
							timeoutSeconds: 5,
						},
					],
					["agent_wait", "background"],
					["reply", "LOOP_WAITING"],
					["multiloop_stop", { target: "child-fixture/gate" }],
					["reply", "AUTOMATION_DONE"],
				],
			],
			[
				"rejected child scheduling",
				[
					[
						"schedule_prompt",
						{ action: "add", type: "once", schedule: "+1d", model: "fixture/test", prompt: "Launch another agent." },
					],
					["subagent", { op: "launch", role: "coder", task: "Recursive work" }],
					["reply", "AUTOMATION_DONE"],
				],
			],
		]) {
			steps.push(...automation);
			const finished = new Promise((resolve) => {
				complete = resolve;
			});
			const automated = manager.launch({
				...launch,
				context: undefined,
				task: `Exercise ${label} and finish the admitted follow-up.`,
			});
			const terminal = await finished;
			assert.equal(terminal.status, "completed", manager.read(automated.id).text);
			assert.equal(
				terminal.result,
				"AUTOMATION_DONE",
				`${label} must drain before reporting completion: ${manager.read(automated.id).text}`,
			);
			assert.equal(steps.length, 0, label);
			if (label === "multiloop gate recovery") {
				const messages = readFileSync(terminal.sessionFile, "utf8").trim().split("\n").map(JSON.parse);
				for (const result of messages.filter((entry) => entry.message?.role === "toolResult"))
					assert.equal(result.message.isError, false, JSON.stringify(result.message));
				const waitResult = messages.find((entry) => entry.message?.toolName === "agent_wait");
				assert.match(JSON.stringify(waitResult?.message.content), /agent_wait waiting/);
				assert.ok(messages.some((entry) => JSON.stringify(entry).includes("LOOP_WAITING")));
			}
			if (label === "rejected child scheduling") {
				const messages = readFileSync(terminal.sessionFile, "utf8").trim().split("\n").map(JSON.parse);
				for (const tool of ["schedule_prompt", "subagent"]) {
					assert.equal(messages.find((entry) => entry.message?.toolName === tool)?.message.isError, true);
				}
			}
			if (label.includes("background")) {
				const messages = readFileSync(terminal.sessionFile, "utf8").trim().split("\n").map(JSON.parse);
				const task = messages.find((entry) => entry.message?.toolName === "bg_task").message.details.task;
				assert.match(readFileSync(task.logFile, "utf8"), /42/, "background work must finish before the worker closes");
			}
		}
		steps.push(
			["TaskCreate", { subject: "Bounded work", description: "Exercise the total turn limit" }],
			["TaskExecute", { task_ids: ["1"] }],
			["reply", "LIMIT_PENDING"],
		);
		const requestCount = requests.length;
		const limited = new Promise((resolve) => {
			complete = resolve;
		});
		manager.launch({
			...launch,
			context: undefined,
			role: { ...role, maxTurns: 3 },
			task: "Schedule work within the turn limit.",
		});
		const limitResult = await limited;
		assert.equal(limitResult.status, "failed", limitResult.result);
		assert.match(limitResult.result, /Agent limit reached/);
		assert.equal(requests.length - requestCount, 3, "automatic continuations share the original turn limit");
	} finally {
		await manager.dispose();
		server.closeAllConnections();
		await new Promise((resolve) => server.close(resolve));
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("terminal observation requires exact revision, session, contiguous pages and unchanged content", () => {
	const item = run();
	const first = page(item, 0, 10, 20);
	const last = page(item, 10, 20, 20);
	assert.deepEqual([...observedSubagentResults([item], [last, first])], [item.id]);
	for (const entries of [
		[first],
		[last],
		[first, page(item, 11, 20, 20)],
		[first, page(item, 10, 20, 21)],
		[first, page({ ...item, parentSessionId: "other" }, 10, 20, 20)],
		[first, page({ ...item, completion: { revision: "new" } }, 10, 20, 20)],
		[first, page(item, 10, 20, 20, { isError: true })],
		[first, page(item, 10, 20, 20, { content: [{ type: "text", text: "Removed by policy" }] })],
		[first, page({ ...item, status: "running" }, 10, 20, 20)],
	]) {
		assert.equal(observedSubagentResults([item], entries).size, 0);
	}
	assert.equal(terminalReadObservation({ ...item, completion: undefined }, 0, { totalBytes: 20 }, []), undefined);
})"

"test("batch bounds the whole envelope, counts omitted failures and keeps review warnings", () => {
	const runs = Array.from({ length: 100 }, (_, i) => ({
		...run(`run-${i}`),
		status: i < 50 ? "completed" : "failed",
		role: { id: "日本語".repeat(100) },
		result: "結果✅".repeat(5000),
	}));
	runs[0].review = { status: "changed" };
	const records = runs.map((item) => ({ id: item.id, ...item.completion }));
	const message = subagentCompletionBatch("parent", "batch", records, runs);
	const envelope = {
		...message,
		customType: "jouzu-subagent-result",
		details: { ...message.details, inbox: { version: 1, sessionId: "parent", batchId: "batch" } },
	};
	assert.ok(Buffer.byteLength(JSON.stringify(envelope)) <= 4096);
	assert.match(message.content, /completed 50, failed 50/);
	assert.equal(message.details.omitted, 100 - message.details.runs.length);
	assert.ok(message.details.omitted > 0);
	assert.match(message.content, /subagent list/);
	assert.match(message.content, /Review candidate changed/);
	assert.ok(message.details.runs.every((item) => item.status === "failed" || item.reviewWarning));
	const component = subagentComponent(message.details, { fg: (_role, text) => text }, true);
	for (const width of [48, 80]) {
		const lines = component.render(width);
		assert.ok(lines.every((line) => visibleWidth(line) <= width));
		assert.match(lines.join("\n"), /omitted/);
		assert.match(lines.join("\n"), /Review candidate/);
	}
})"

