"test("tree navigation releases unread child completions without blocking later results", {
	timeout: 30000,
}, async (t) => {
	const root = await mkdtemp(join(tmpdir(), "flow-child-tree-"));
	afterFlowCleanup(t, () => rm(root, { recursive: true, force: true }));
	const workers = [];
	const integration = createWorkflowIntegration(
		{ agentDir: join(root, "agent"), configDir: join(root, "config"), stateDir: join(root, "state") },
		(launch, emit, exit) => {
			const w = {
				launch,
				emit,
				exit,
				send() {},
				async stop() {
					exit(false);
				},
			};
			workers.push(w);
			return w;
		},
	);
	const roles = integration.service.roles();
	roles.config.maxConcurrent = 2;
	roles.config.roles = roles.config.roles.map((r) => ({ ...r, model: "fixture/fixture", tools: ["read"] }));
	integration.service.save(roles);
	const f = await assembledSession(t, {
		root,
		producerExtensions: [
			{
				name: "fixture-subagents",
				factory(pi) {
					integration.register(pi, async () => false);
				},
			},
		],
		script: async (_body, i) =>
			i === 0
				? {
						toolCalls: [0, 1].map((n) => ({
							id: `launch${n}`,
							name: "subagent",
							arguments: { op: "launch", role: "coder", task: `child ${n}` },
						})),
					}
				: { text: "Done" },
	});
	await f.session.prompt("Launch two children.");
	assert.equal(workers.length, 2);
	f.ingress.pauseAutomated("navigation hold");
	const entered = deferred(),
		release = deferred();
	const submit = f.ingress.submit;
	const send = f.session.sendCustomMessage;
	let delivery;
	// The inbox saves a batch identifier before its asynchronous host send finishes.
	// Hold that send explicitly: a saved batch alone does not establish host idleness.
	f.ingress.submit = async function (input, dispatch) {
		if (input.api === "sendCustomMessage" && input.args[0]?.customType === "jouzu-subagent-result") {
			entered.resolve();
			await release.promise;
		}
		return submit.call(this, input, dispatch);
	};
	f.session.sendCustomMessage = function (...args) {
		const pending = send.apply(this, args);
		if (args[0]?.customType === "jouzu-subagent-result") delivery = pending;
		return pending;
	};
	const user = f.sessionManager.getBranch().find((e) => e.type === "message" && e.message.role === "user");
	try {
		workers[0].emit({ type: "result", status: "completed", text: "First evidence" });
		workers[0].exit(true);
		await entered.promise;
		const before = integration.service.runs();
		assert.ok(before.find((r) => r.completion)?.completion.batchId);
		assert.equal(before.find((r) => r.completion)?.completion.handled, false);
		assert.equal(f.bodies.length, 2, "the first completion is still held before navigation");
		const leaf = f.sessionManager.getLeafId();
		await assert.rejects(f.session.navigateTree(user.id), { code: "busy" });
		assert.equal(f.sessionManager.getLeafId(), leaf, "an unfinished host send prevents branch mutation");
		release.resolve();
		assert.ok(delivery, "capture the actual host send, not only its batch identifier");
		await delivery;
	} finally {
		release.resolve();
		f.ingress.submit = submit;
		f.session.sendCustomMessage = send;
	}
	await f.session.navigateTree(user.id);
	await f.session.prompt("Continue on the new branch.");
	assert.equal(f.ingress.automatedPause(), undefined, "new user turn must release the navigation hold");
	workers[1].emit({ type: "result", status: "completed", text: "Second evidence" });
	workers[1].exit(true);
	// Wait for both completions to be handled and carry a batch identifier, which the assertions below
	// both count, rather than for a fixed interval to elapse.
	const settledCount = async () =>
		integration.service.runs().filter((r) => r.completion?.handled && r.completion?.batchId).length;
	for (let i = 0; i < 400 && (await settledCount()) < 2; i++) await new Promise((r) => setTimeout(r, 25));
	await f.session.agent.waitForIdle();
	const runs = integration.service.runs();

	assert.equal(runs.filter((r) => r.completion?.handled).length, 2);
	assert.equal(runs.filter((r) => r.completion?.batchId).length, 2);
	assert.ok(f.bodies.length > 3, "unread completions reach the provider on the new branch");
	assert.ok(JSON.stringify(f.bodies.slice(2)).includes("First evidence"));
	assert.ok(JSON.stringify(f.bodies.slice(2)).includes("Second evidence"));
})"

"test(`terminal read observation requires final-input inclusion: ${transform}`, { timeout: 30000 }, async (t) => {
		const root = await mkdtemp(join(tmpdir(), "flow-child-real-"));
		afterFlowCleanup(t, () => rm(root, { recursive: true, force: true }));
		const workers = [];
		const integration = createWorkflowIntegration(
			{ agentDir: join(root, "agent"), configDir: join(root, "config"), stateDir: join(root, "state") },
			(launch, emit, exit) => {
				const w = {
					launch,
					emit,
					exit,
					send() {},
					async stop() {
						exit(false);
					},
				};
				workers.push(w);
				return w;
			},
		);
		const roles = integration.service.roles();
		roles.config.roles = roles.config.roles.map((r) => ({ ...r, model: "fixture/fixture", tools: ["read"] }));
		integration.service.save(roles);
		const fixture = await assembledSession(t, {
			root,
			producerExtensions: [
				{
					name: "fixture-subagents",
					factory(pi) {
						integration.register(pi, async () => false);
						pi.on("context", (event) => ({
							messages: event.messages.flatMap((m) =>
								m.role === "toolResult" && m.details?.terminalRead
									? transform === "omitted"
										? []
										: transform === "replaced"
											? [{ ...m, content: [{ type: "text", text: "TERMINAL OUTPUT WITHHELD" }] }]
											: [m]
									: [m],
							),
						}));
					},
				},
			],
			script: async (body, index) => {
				if (index === 0)
					return {
						toolCalls: [
							{ name: "subagent", arguments: { op: "launch", role: "coder", task: "fixture child" }, id: "launch" },
						],
					};
				if (index === 1) {
					assert.equal(workers.length, 1, JSON.stringify(body));
					workers[0].emit({ type: "result", status: "completed", text: "SECRET_CHILD_EVIDENCE" });
					workers[0].exit(true);
					return {
						toolCalls: [
							{ name: "subagent", arguments: { op: "read", id: integration.service.runs()[0].id }, id: "read" },
						],
					};
				}
				return { text: "Finished" };
			},
		});
		await fixture.session.prompt("Run the fixture child and read its evidence.");
		// The completion is handled asynchronously, and the request bodies that follow depend on it.
		// Poll for the handled completion instead of racing it with a fixed sleep.
		for (let i = 0; i < 400; i++) {
			if (integration.service.runs()[0]?.completion?.handled) break;
			await new Promise((r) => setTimeout(r, 25));
		}
		await fixture.session.agent.waitForIdle();
		const runs = integration.service.runs();
		assert.ok(JSON.stringify(fixture.session.sessionManager.getBranch()).includes("SECRET_CHILD_EVIDENCE"));
		assert.equal(fixture.bodies.length, transform === "included" ? 3 : 4);
		if (transform === "replaced") assert.ok(JSON.stringify(fixture.bodies[2]).includes("TERMINAL OUTPUT WITHHELD"));
		assert.equal(JSON.stringify(fixture.bodies[2]).includes("SECRET_CHILD_EVIDENCE"), transform === "included");
		assert.equal(runs[0].completion.handled, true);
		const batches = fixture.sessionManager
			.getBranch()
			.filter((e) => e.type === "custom_message" && e.customType === "jouzu-subagent-result");
		assert.equal(batches.length, transform === "included" ? 0 : 1);
	})"

"test(`real Pi subagent inbox request count: ${scenario}`, { timeout: 15000 }, async (t) => {
		t.mock.method(globalThis, "fetch", async () => {
			throw new Error("Network disabled in inbox fixture");
		});
		const root = await mkdtemp(join(tmpdir(), "jouzu-subagent-inbox-"));
		const workers = [];
		const integration = createWorkflowIntegration(
			{ agentDir: join(root, "agent"), configDir: join(root, "config"), stateDir: join(root, "state") },
			(launch, emit, exit) => {
				const worker = {
					launch,
					emit,
					exit,
					send() {},
					async stop() {
						exit(false);
					},
				};
				workers.push(worker);
				return worker;
			},
		);
		const roles = integration.service.roles();
		roles.config.maxConcurrent = 8;
		roles.config.roles = roles.config.roles.map((role) => ({ ...role, model: "child/test", tools: ["read"] }));
		integration.service.save(roles);
		const model = {
			id: "test",
			name: "Fixture",
			provider: "fixture",
			api: "openai-completions",
			baseUrl: "http://127.0.0.1:1",
			reasoning: false,
			input: ["text"],
			contextWindow: 128000,
			maxTokens: 4096,
			cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
		};
		const modelRuntime = await ModelRuntime.create({
			credentials: {
				read: async () => undefined,
				list: async () => [],
				modify: async () => undefined,
				delete: async () => {},
			},
			modelsPath: null,
			modelsStorePath: join(root, "models.json"),
			refreshOnCreate: false,
			allowModelNetwork: false,
		});
		modelRuntime.registerProvider("child", {
			api: model.api,
			baseUrl: model.baseUrl,
			apiKey: "fixture",
			models: [{ ...model, provider: "child" }],
		});
		let session;
		let requests = 0;
		let scriptFailure;
		let rejectedBatch;
		const errors = [];
		const text = (value) => ({ type: "text", text: value });
		const tool = (name, args, id) => ({ type: "toolCall", name, arguments: args, id });
		async function response() {
			requests++;
			assert.ok(requests <= 8, "must not loop on completion");
			if (requests === 1)
				return Array.from({ length: 3 }, (_, i) =>
					tool("subagent", { op: "launch", role: "coder", task: `Fixture ${i}` }, `launch-${i}`),
				);
			if (requests === 2) {
				assert.equal(workers.length, 3);
				for (let i = 0; i < workers.length; i++) {
					workers[i].emit({ type: "result", status: i === 0 ? "failed" : "completed", text: `Result ${i}` });
					workers[i].exit(true);
				}
				// Busy longer than the preceding debounce: completions must remain retractable.
				await new Promise((resolve) => setTimeout(resolve, 150));
				return ["history-only", "redacted-read"].includes(scenario)
					? integration.service.runs().map((run, i) => tool("subagent", { op: "read", id: run.id }, `read-${i}`))
					: [text("Initial work finished.")];
			}
			if (["history-only", "redacted-read"].includes(scenario)) return [text("Read tools finished.")];
			if (scenario === "redacted-metadata" && requests === 3) {
				return [tool("subagent", { op: "launch", role: "coder", task: "Later result" }, "later")];
			}
			if (scenario === "redacted-metadata" && requests === 4) {
				workers[3].emit({ type: "result", status: "completed", text: "Later success" });
				workers[3].exit(true);
				return [text("Later child finished.")];
			}
			if (requests === 3 || (scenario === "redacted-metadata" && requests === 5)) {
				const entry = [...session.sessionManager.getBranch()]
					.reverse()
					.find((item) => item.type === "custom_message" && item.customType === "jouzu-subagent-result");
				assert.ok(entry, "receipt must precede the notification provider request");
				if (scenario === "reply") return [text("The failed child needs attention.")];
				if (scenario === "queued") await session.followUp("User work must survive");
				const calls = [
					tool(
						"subagent",
						{ op: "acknowledge", batchId: scenario === "stale" ? "stale" : entry.details.inbox.batchId },
						"ack",
					),
				];
				if (scenario === "mixed") calls.push(tool("fixture_aux", {}, "aux"));
				return calls;
			}
			return [text(scenario === "queued" ? "User work handled." : "Additional work handled.")];
		}
		modelRuntime.registerProvider("fixture", {
			api: model.api,
			baseUrl: model.baseUrl,
			apiKey: "fixture",
			models: [model],
			streamSimple() {
				const stream = createAssistantMessageEventStream();
				void (async () => {
					try {
						const content = await response();
						const message = {
							role: "assistant",
							content,
							api: model.api,
							provider: model.provider,
							model: model.id,
							stopReason: content.some((part) => part.type === "toolCall") ? "toolUse" : "stop",
							timestamp: Date.now(),
							usage: {
								input: 0,
								output: 0,
								cacheRead: 0,
								cacheWrite: 0,
								totalTokens: 0,
								cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
							},
						};
						stream.push({ type: "done", reason: message.stopReason, message });
						stream.end(message);
					} catch (error) {
						scriptFailure = error;
						stream.end();
					}
				})();
				return stream;
			},
		});
		try {
			const loader = new DefaultResourceLoader({
				cwd: root,
				agentDir: root,
				noExtensions: true,
				noSkills: true,
				noPromptTemplates: true,
				noContextFiles: true,
				contentPolicy:
					scenario === "redacted-metadata"
						? {
								filterSkills: async (skills) => skills,
								shouldInspectTool: () => false,
								filterToolResult: async ({ result }) => result,
								filterContext: async (messages) =>
									messages.map((message) => {
										if (message.role !== "custom" || message.customType !== "jouzu-subagent-result") return message;
										const id = message.details?.inbox?.batchId;
										if (id) rejectedBatch ??= id;
										return id === rejectedBatch
											? { ...message, content: [text("Policy withheld the notification")], details: {} }
											: message;
									}),
							}
						: undefined,
				extensionFactories: [
					(pi) => {
						integration.register(pi, async () => false);
						if (scenario === "redacted-read")
							pi.on("tool_result", (event) =>
								event.toolName === "subagent" && event.details?.terminalRead
									? { content: [text("Read content removed by policy")] }
									: undefined,
							);
						pi.registerTool({
							name: "fixture_aux",
							label: "Auxiliary",
							description: "Non-terminating sibling",
							parameters: { type: "object", properties: {} },
							execute: async () => ({ content: [text("Auxiliary complete")], details: {} }),
						});
					},
				],
			});
			await loader.reload();
			({ session } = await createAgentSession({
				cwd: root,
				agentDir: root,
				modelRuntime,
				model,
				resourceLoader: loader,
				sessionManager: SessionManager.inMemory(root),
				settingsManager: SettingsManager.inMemory({
					retry: { enabled: false },
					compaction: { enabled: false },
					followUpMode: "one-at-a-time",
				}),
				tools: ["subagent", "fixture_aux"],
			}));
			await session.bindExtensions({ mode: "json", onError: (error) => errors.push(error) });
			await session.prompt("Run child fixtures.");
			await new Promise((resolve) => setTimeout(resolve, 20));
			await session.agent.waitForIdle();
			await new Promise((resolve) => setTimeout(resolve, 20));
			if (scriptFailure) throw scriptFailure;
			assert.deepEqual(errors, []);
			assert.equal(
				requests,
				scenario === "redacted-metadata"
					? 5
					: ["mixed", "stale", "queued", "redacted-read", "history-only"].includes(scenario)
						? 4
						: 3,
			);
			const batches = session.sessionManager
				.getBranch()
				.filter((entry) => entry.type === "custom_message" && entry.customType === "jouzu-subagent-result");
			assert.equal(batches.length, scenario === "redacted-metadata" ? 2 : 1);
			if (scenario === "redacted-metadata") {
				assert.deepEqual(batches[0].details, {});
				assert.equal(integration.service.runs().filter((run) => !run.completion.handled).length, 3);
			}
			const prose = session.messages
				.filter((message) => message.role === "assistant")
				.flatMap((message) => message.content.filter((part) => part.type === "text").map((part) => part.text));
			if (scenario === "acknowledge") assert.deepEqual(prose, ["Initial work finished."]);
			if (scenario === "reply") assert.ok(prose.includes("The failed child needs attention."));
			if (scenario === "queued") assert.ok(prose.includes("User work handled."));
		} finally {
			await session?.extensionRunner.emit({ type: "session_shutdown", reason: "quit" });
			session?.dispose();
			await rm(root, { recursive: true, force: true });
		}
	})"

"test("shared dashboard takeover suppresses child widget and routes visibility without launching work", async () => {
	const visibility = [];
	const f = fixture(false, { dashboardVisibility: (visible) => visibility.push(visible) });
	const widgets = [];
	f.ctx.ui.setWidget = (...args) => widgets.push(args);
	try {
		await f.handlers.get("session_start")({}, f.ctx);
		await f.commands.get("subagents").handler("hide", f.ctx);
		await f.commands.get("subagents").handler("show", f.ctx);
		await f.commands.get("subagents").handler("", f.ctx);
		assert.deepEqual(visibility, [false, true]);
		assert.deepEqual(f.opened, ["runs"]);
		assert.equal(f.workers.length, 0);
		assert.ok(widgets.every(([, content]) => content === undefined));
	} finally {
		await f.handlers.get("session_shutdown")({}, f.ctx);
	}
})"

