"test("subagent provider schemas allow omission without fabricated arguments", async () => {
	const f = fixture();
	try {
		const tool = f.tool;
		assert.deepEqual(tool.parameters.required, ["op"]);
		for (const [key, property] of Object.entries(tool.parameters.properties)) {
			if (key !== "op") assert.ok(property.type.includes("null"), `${key} is nullable at registration`);
		}
		assert.deepEqual(tool.constrainedSampling, { type: "json_schema", strict: "prefer" });
		for (const supportsStrictMode of [false, true]) {
			const converted = convertResponsesTools([tool], { supportsStrictMode })[0];
			assert.deepEqual(
				converted.parameters.required,
				supportsStrictMode ? Object.keys(tool.parameters.properties) : ["op"],
			);
			assert.equal(converted.strict, supportsStrictMode ? true : undefined);
			for (const key of Object.keys(tool.parameters.properties).filter((key) => key !== "op")) {
				if (supportsStrictMode) assert.ok(converted.parameters.properties[key].type.includes("null"), key);
				else assert.deepEqual(converted.parameters.properties[key], tool.parameters.properties[key]);
			}
			assert.deepEqual(converted.parameters.properties.op, tool.parameters.properties.op);
		}
		const nullable = Object.fromEntries(
			Object.keys(tool.parameters.properties)
				.filter((key) => key !== "op")
				.map((key) => [key, null]),
		);
		for (const minimal of [
			{ op: "roles" },
			{ op: "list" },
			{ op: "launch", role: "coder", task: "Inspect" },
			{ op: "read", id: "returned-run-id" },
			{ op: "trace" },
			{ op: "steer", id: "returned-run-id", task: "Report findings" },
			{ op: "stop", id: "returned-run-id" },
			{ op: "resume", id: "returned-run-id", task: "Continue" },
			{ op: "acknowledge", batchId: "delivered-batch-id" },
		]) {
			for (const args of [minimal, { ...nullable, ...minimal }])
				assert.deepEqual(validateToolArguments(tool, { name: "subagent", arguments: args }), args);
		}
		assert.match(tool.description, /\{"op":"roles"\}/);
		assert.match(tool.description, /Omit unused fields; use null only if required by the interface/);
		assert.match(tool.parameters.properties.op.description, /resume\/steer: id, task/);
	} finally {
		await f.shutdown();
	}
})"

"test("discovery ignores unrelated launch fields and accepts nullable optional arguments", async () => {
	const f = fixture();
	try {
		await f.handlers.get("session_start")({}, f.ctx);
		const parentFile = join(f.root, "parent.jsonl");
		writeFileSync(parentFile, "");
		f.ctx.sessionManager.getSessionFile = () => parentFile;
		const padding = {
			batchId: "",
			context: "fresh",
			entryId: "",
			entryIds: ["unused"],
			id: "",
			kind: "all",
			limit: 10,
			offset: 0,
			parentContext: false,
			query: "",
			role: "",
			task: "",
			workspace: "",
		};
		const nullable = Object.fromEntries(
			Object.keys(f.tool.parameters.properties)
				.filter((key) => key !== "op")
				.map((key) => [key, null]),
		);
		for (const op of ["roles", "list", "trace"]) {
			const expected = await f.invoke({ op });
			assert.deepEqual(await f.invoke({ ...padding, op }), expected);
			assert.deepEqual(await f.invoke({ ...nullable, op }), expected);
		}
		assert.equal(f.workers.length, 0);
		const started = await f.invoke(
			validateToolArguments(f.tool, {
				name: "subagent",
				arguments: { ...nullable, op: "launch", role: "coder", task: "Inspect" },
			}),
		);
		assert.equal(started.context.mode, "fresh");
		assert.equal(f.workers.length, 1);
	} finally {
		await f.shutdown();
	}
})"

"test("Codex request preserves subagent omission and nullable optional fields", async () => {
	const { stream } = await import("@earendil-works/pi-ai/api/openai-codex-responses");
	const f = fixture();
	try {
		for (const supportsStrictMode of [false, true]) {
			let payload;
			const token = `fixture.${Buffer.from(JSON.stringify({ "https://api.openai.com/auth": { chatgpt_account_id: "fixture" } })).toString("base64url")}.fixture`;
			const response = await stream(
				{
					id: "fixture",
					input: ["text"],
					api: "openai-codex-responses",
					provider: "fixture",
					baseUrl: "https://fixture.invalid",
					compat: { supportsStrictMode },
				},
				{
					messages: [
						{ role: "system", content: "Test", timestamp: 0, toolsAdded: [f.tool] },
						{ role: "user", content: "Test", timestamp: 1 },
					],
				},
				{
					apiKey: token,
					onPayload(value) {
						payload = value;
