			task: "Test parallel writers",
		});
		assert.equal(starts, 1, "the default policy does not wait for the cross-session workspace lock");
		assert.equal(manager.get(run.id).status, "starting");
	} finally {
		await manager.dispose();
		held.child.kill("SIGKILL");
		// Wait for the holder to exit before removing the fixture: Windows refuses
		// to unlink the SQLite file while the child still holds it open.
		await held.exited;
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("a failed writer-lock release fails completed and queued runs and rejects further work", async (t) => {
	const root = realpathSync(mkdtempSync(join(tmpdir(), "jouzu-lock-release-")));
	const paths = { cwd: root, stateDir: join(root, "state") };
	let emit;
	let exit;
	let starts = 0;
	const completions = [];
	const manager = new SubagentManager(
		paths,
		"parent",
		1,
		(_launch, onEvent, onExit) => {
			starts++;
			emit = onEvent;
			exit = onExit;
			return {
				send() {},
				async stop() {
					onExit(false);
				},
			};
		},
		(run) => completions.push(run),
	);
	manager.setWorkspaceWriters("serialize");
	const launch = {
		role: defaultAgentConfig().roles[1],
		model: { provider: "fixture", id: "test" },
		auth: {},
		cwd: root,
		task: "Test release failure",
	};
	const first = manager.launch(launch);
	const queued = manager.launch(launch);
	const lock = manager.releases.get(first.id);
	const failure = t.mock.method(lock, "release", () => {
		throw new Error("Injected release failure");
	});
	try {
		emit({ type: "result", status: "completed", text: "Work finished" });
		exit(true);
		assert.equal(starts, 1);
		for (const run of [first, queued]) {
			const finished = manager.get(run.id);
			assert.equal(finished.status, "failed");
			assert.match(finished.result, /Process lock release failed; restart Jouzu/);
			assert.match(finished.result, /Injected release failure/);
			const saved = JSON.parse(
				readFileSync(join(paths.stateDir, "subagents", pathDigest("parent"), run.id, "run.json"), "utf8"),
			);
			assert.equal(saved.status, "failed");
		}
		assert.equal(completions.length, 2);
		assert.throws(() => manager.launch(launch), /Process lock release failed/);
		assert.throws(() => acquireProcessLock(join(paths.stateDir, "subagent-writers", `${pathDigest(root)}.sqlite`)), {
			reason: "busy",
		});
		await assert.rejects(manager.dispose(), /Process lock release failed/);
		await assert.rejects(manager.dispose(), /Process lock release failed/);
	} finally {
		failure.mock.restore();
		lock.release();
		await manager.dispose().catch(() => {});
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("a failed owner-lock release rejects disposal and retains ownership", async (t) => {
	const root = realpathSync(mkdtempSync(join(tmpdir(), "jouzu-owner-release-")));
	const paths = { cwd: root, stateDir: join(root, "state") };
	const manager = new SubagentManager(paths, "parent", 1);
	manager.attach();
	const lock = manager.releaseOwner;
	const failure = t.mock.method(lock, "release", () => {
		throw new Error("Injected owner close failure");
	});
	try {
		await assert.rejects(manager.dispose(), /Injected owner close failure/);
		await assert.rejects(manager.dispose(), /Injected owner close failure/);
		assert.throws(() => acquireProcessLock(join(paths.stateDir, "subagents", pathDigest("parent"), "owner.sqlite")), {
			reason: "busy",
		});
	} finally {
		failure.mock.restore();
		lock.release();
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("a leftover lock file from an earlier protocol does not block subagent ownership", async () => {
	const root = realpathSync(mkdtempSync(join(tmpdir(), "jouzu-lock-leftover-")));
	const paths = { cwd: root, stateDir: join(root, "state") };
	const directory = join(paths.stateDir, "subagents", pathDigest("parent"));
	mkdirSync(directory, { recursive: true });
	writeFileSync(join(directory, "owner.sqlite"), "");
	writeFileSync(
		join(directory, "owner.lock"),
		`${JSON.stringify({ pid: 1, startedAt: new Date().toISOString(), token: "earlier-protocol" })}\n`,
	);
	const manager = new SubagentManager(paths, "parent", 1);
	try {
		manager.attach();
	} finally {
		await manager.dispose();
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("a child's flow storage path stays inside the Windows SQLite limit", () => {
	// SQLite on Windows fails with SQLITE_CANTOPEN once a path reaches roughly
	// 250 characters, even though node:fs reaches longer paths through \\?\.
	// The default Windows state root is %LOCALAPPDATA%\Jouzu\state, and a child
	// nests its flow storage several digests below it.
	const stateDir = "C:\\Users\\example\\AppData\\Local\\Jouzu\\state";
	const childDirectory = join(
		stateDir,
		"subagents",
		pathDigest("parent-session"),
		"3f0f2b1c-9d4e-4a5b-8c6d-7e8f9a0b1c2d",
	);
	const lockPath = join(
		childDirectory,
		"flow",
		"session-registry-v1",
		pathDigest(["parent", "branch"]),
		"owner.sqlite",
	);
	assert.ok(lockPath.length < 250, `child flow lock path is ${lockPath.length} characters: ${lockPath}`);
})"

"test(`child read receipt requires success and exact inclusion: ${outcome}/${status}`, async () => {
			const f = fixture();
			const marker = { id: "child", revision: "terminal", start: 0, end: 4, total: 4 };
			const message = {
				role: "toolResult",
				toolCallId: "read",
				toolName: "subagent",
				isError: false,
				content: [{ type: "text", text: "data" }],
				details: { terminalRead: marker },
			};
			f.setRequests([
				{
					outcome,
					projectionCapture: { members: [{ index: 0, message }], model: { members: [{ sourceIndex: 0, status }] } },
				},
			]);
			const expected =
				outcome === "success" && status === "converted"
					? [
							{
								toolCallId: "read",
								contentHash: notificationHash(message.content),
								markerHash: notificationHash(marker),
							},
						]
					: [];
			assert.deepEqual(await f.read(), expected);
			assert.deepEqual(await f.producer.snapshot(), []);
			await assert.rejects(f.producer.build(), /cannot schedule work/);
		})"

"test("child observations reject foreign and replaced branches and detach on shutdown", async () => {
	const f = fixture();
	await assert.rejects(f.read("other"), /another session/);
	let finish;
	f.original.attachment.nativeRequests.snapshot = () =>
		new Promise((resolve) => {
			finish = resolve;
		});
	const reading = f.read();
	f.replaceBranch();
	finish([]);
	await assert.rejects(reading, /branch changed/);
	f.handlers.get("session_tree")({}, f.context);
	assert.equal(f.disposed, 1);
	f.handlers.get("session_shutdown")();
	assert.equal(f.disposed, 2);
	assert.equal(f.unsubscribed, true);
})"

"test("only unreceipted terminal reads retain observation projections", () => {
	const f = fixture();
	const content = [{ type: "text", text: "read output" }];
	const marker = { contentHash: notificationHash(content) };
	const message = {
		role: "toolResult",
		toolCallId: "read",
		toolName: "subagent",
		isError: false,
		content,
		details: { terminalRead: marker },
	};
	f.entries.push({ type: "message", message });
	const observations = [
		{
			index: 0,
			kind: "toolResult",
			toolCallId: "launch",
			toolName: "subagent",
			failed: false,
			contentHash: notificationHash(content),
		},
		{
			index: 1,
			kind: "toolResult",
			toolCallId: "read",
			toolName: "subagent",
			failed: false,
			contentHash: notificationHash(content),
		},
	];
	assert.deepEqual(f.producer.observationProjections(observations), [1]);
	f.entries.push({
		type: "custom",
		customType: "jouzu-subagent-read-receipt",
		data: { markerHash: notificationHash(marker), contentHash: notificationHash(content), toolCallId: "read" },
	});
	assert.deepEqual(f.producer.observationProjections(observations), []);
})"

