"test("status labels move onto the catalog while the state value stays the contract", () => {
	const ja = resolveCatalog("ja").bundle;
	const words = {
		queued: "待機中",
		starting: "開始中",
		running: "実行中",
		completed: "完了",
		failed: "失敗",
		cancelled: "キャンセル",
		interrupted: "中断",
	};
	for (const [state, word] of Object.entries(words)) {
		const output = subagentComponent({ ...run, status: state }, plain, false, "", ja)
			.render(80)
			.join("\n");
		assert.match(output, new RegExp(word, "u"), `the ${state} label renders in Japanese`);
		// The machine-readable snapshot keeps the internal state value; only the
		// display word moved onto the catalog.
		assert.equal(runPresentation({ ...run, status: state, role: { id: "coder" } }).status, state);
	}
	// A state the table does not know is shown as-is, never silently relabeled.
	assert.match(
		subagentComponent({ ...run, status: "waiting" }, plain, false, "", ja)
			.render(80)
			.join("\n"),
		/waiting/u,
	);
	// The English default is unchanged for a resolved catalog of `en`.
	assert.match(
		subagentComponent({ ...run, status: "completed" }, plain, false, "", resolveCatalog("en").bundle)
			.render(80)
			.join("\n"),
		/Completed/u,
	);
})"

"test("invalid child schedule state is preserved with a warning and cannot block restored waits", async (t) => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-child-schedule-recovery-"));
	const previous = { ...process.env };
	t.after(() => {
		for (const key of Object.keys(process.env)) if (!(key in previous)) delete process.env[key];
		Object.assign(process.env, previous);
		rmSync(root, { recursive: true, force: true });
	});
	const unsafe = join(root, "unsafe");
	mkdirSync(unsafe);
	writeFileSync(join(unsafe, ".pi"), "PRESERVE");
	assert.throws(() => configureChildResources({ directory: unsafe }), /must be a real directory/);
	assert.equal(readFileSync(join(unsafe, ".pi"), "utf8"), "PRESERVE");
	for (const [name, data] of [
		["json", "{"],
		["format", '{"version":2,"jobs":[]}'],
		["job", '{"version":1,"jobs":[{"enabled":true}]}'],
		["large", "x".repeat(4 * 1024 * 1024 + 1)],
		["directory", null],
	]) {
		const directory = join(root, name);
		const state = join(directory, ".pi");
		mkdirSync(state, { recursive: true });
		const file = join(state, "schedule-prompts.json");
		if (data === null) mkdirSync(file);
		else writeFileSync(file, data);
		const warnings = [];
		assert.equal(
			configureChildResources({ directory }, (text) => warnings.push(text)),
			0,
		);
		assert.equal(warnings.length, 1);
		assert.match(warnings[0], /Preserved at .*\.invalid-/);
		assert.equal(existsSync(file), false);
		const backup = join(
			state,
			readdirSync(state).find((name) => name.startsWith("schedule-prompts.json.invalid-")),
		);
		if (data === null) assert.ok(lstatSync(backup).isDirectory());
		else assert.equal(readFileSync(backup, "utf8"), data);
		const identity = {
			scope: { sessionId: "child", branchId: "branch" },
			workId: "work",
			handle: "old",
			execution: "old@date",
		};
		const source = createScheduleWaitSource({
			cwd: directory,
			events: {},
			attachment: {
				waits: { authoritySnapshot: async () => ({ executions: [{ producer: "schedule", ...identity }] }) },
			},
			onError(error) {
				throw error;
			},
		});
		assert.deepEqual((await source.snapshot(identity, new AbortController().signal)).predicates, [
			{ until: "first-trigger", state: "cancelled" },
		]);
		assert.equal(
			configureChildResources({ directory }, (text) => warnings.push(text)),
			0,
		);
		assert.equal(warnings.length, 1, "resume does not process quarantined data again");
	}
})"

"test("child resources retain released tools and skills without reopening project automation", async (t) => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-child-resources-"));
	const cwd = join(root, "workspace");
	const directory = join(root, "child");
	const userAgentDir = join(root, "user-agent");
	for (const path of [cwd, directory, userAgentDir]) mkdirSync(path);
	writeFileSync(join(cwd, "AGENTS.md"), "CHILD_PROJECT_GUIDANCE");
	mkdirSync(join(cwd, ".pi"));
	writeFileSync(join(cwd, ".pi", "tasks.json"), "PARENT_TASKS_UNCHANGED");
	mkdirSync(join(userAgentDir, "skills", "local-skill"), { recursive: true });
	writeFileSync(
		join(userAgentDir, "skills", "local-skill", "SKILL.md"),
		"---\nname: local-skill\ndescription: Local fixture skill\n---\nLOCAL_SKILL_EVIDENCE\n",
	);
	const previous = { ...process.env };
	t.after(() => {
		for (const key of Object.keys(process.env)) if (!(key in previous)) delete process.env[key];
		Object.assign(process.env, previous);
		rmSync(root, { recursive: true, force: true });
	});
	const launch = {
		cwd,
		directory,
		userAgentDir,
		role: { ...defaultAgentConfig().roles[1], judging: false },
		model: { id: "fixture" },
	};
	mkdirSync(join(directory, ".pi"));
	const savedSchedules = {
		version: 1,
		jobs: [
			{ id: "future", createdAt: "2026-01-01T00:00:00Z", enabled: true, schedule: "2099-01-01T00:00:00Z", runCount: 0 },
			{ id: "disabled", createdAt: "2026-01-01T00:00:00Z", enabled: false, runCount: 2 },
		],
	};
	writeFileSync(join(directory, ".pi", "schedule-prompts.json"), JSON.stringify(savedSchedules));
	assert.equal(configureChildResources(launch), 1);
	const stoppedSchedules = JSON.parse(readFileSync(join(directory, ".pi", "schedule-prompts.json"), "utf8"));
	assert.deepEqual(
		stoppedSchedules.jobs,
		savedSchedules.jobs.map((job) => ({ ...job, enabled: false })),
	);
	const stored = readFileSync(join(directory, ".pi", "schedule-prompts.json"), "utf8");
	assert.equal(configureChildResources(launch), 0);
	assert.equal(readFileSync(join(directory, ".pi", "schedule-prompts.json"), "utf8"), stored);
	const scheduleSource = createScheduleWaitSource({
		cwd: directory,
		events: {},
		attachment: {},
		onError(error) {
			throw error;
		},
	});
	const evidence = await scheduleSource.snapshot(
		{
			scope: { sessionId: "child", branchId: "branch" },
			workId: "work",
			handle: "future",
			execution: "future@2026-01-01T00:00:00Z",
		},
		new AbortController().signal,
	);
	assert.deepEqual(evidence.predicates, [{ until: "first-trigger", state: "cancelled" }]);
	assert.equal(process.env.PI_CODING_AGENT_DIR, directory);
	assert.equal(process.env.PI_TASKS, join(directory, "tasks.json"));
	assert.equal(JSON.parse(readFileSync(join(directory, "tasks-config.json"))).taskScope, "session");
	assert.equal(JSON.parse(readFileSync(join(directory, "pi-vcc-config.json"))).continueAfterThresholdCompact, false);
	const policy = { filterSkills: async (skills) => skills };
	const scopes = [];
	const loader = await expandedChildResourceLoader(launch, policy, [
		{
			name: "jouzu-task-controller",
			factory(pi) {
				pi.on("session_start", (_event, ctx) => {
					scopes.push(["event", ctx.cwd]);
				});
				pi.registerCommand("scope-probe", {
					handler: async (_args, ctx) => {
						scopes.push(["command", ctx.cwd]);
					},
				});
				pi.registerTool({
					name: "scope_probe",
					label: "Scope probe",
					description: "Fixture scope probe",
					parameters: { type: "object", properties: {} },
					execute: async (_id, _args, _signal, _update, ctx) => {
						scopes.push(["tool", ctx.cwd]);
						return { content: [], details: {} };
					},
				});
			},
		},
	]);
	const scoped = loader
		.getExtensions()
		.extensions.find((extension) => extension.path === "<inline:jouzu-task-controller>");
	const context = { cwd };
	await scoped.handlers.get("session_start")[0]({}, context);
	await scoped.commands.get("scope-probe").handler("", context);
	await scoped.tools.get("scope_probe").definition.execute("probe", {}, undefined, undefined, context);
	assert.deepEqual(scopes, [
		["event", directory],
		["command", directory],
		["tool", directory],
	]);
	assert.equal(context.cwd, cwd);
	assert.equal(loader.contentPolicy, policy);
	const schemaAdapter = loader
		.getExtensions()
		.extensions.find((extension) => extension.path === "<inline:jouzu-responses-tool-schema>");
	assert.ok(schemaAdapter, "children normalize restored Responses tool declarations");
	const schema = {
		type: "object",
		properties: { delay: { anyOf: [{ type: "integer" }, { type: "null" }], format: "int32" } },
	};
	const payload = { tools: [{ type: "function", name: "device", parameters: schema }] };
	const adapted = await schemaAdapter.handlers.get("before_provider_request")[0](
		{ payload, request: { model: { api: "openai-responses" } } },
		context,
	);
	assert.equal(adapted.tools[0].parameters.properties.delay.format, undefined);
	assert.equal(schema.properties.delay.format, "int32");
	const tools = loader.getExtensions().extensions.flatMap((extension) => [...extension.tools.keys()]);
	for (const name of [
		"web_fetch",
		"tff-search_web",
		"vcc_recall",
		"compact_context",
		"TaskCreate",
		"TaskExecute",
		"bg_task",
		"multiloop_start",
	])
		assert.ok(tools.includes(name), `missing released tool: ${name}`);
	assert.ok(!tools.includes("schedule_prompt"));
	assert.ok(!tools.includes("subagent"));
	assert.ok(loader.getExtensions().extensions.every((extension) => !extension.commands.has("schedule-prompt")));
	const skills = loader.getSkills().skills.map((skill) => skill.name);
	assert.ok(skills.includes("local-skill"));
	assert.ok(skills.includes("jouzu-clear-writing"));
	assert.ok(skills.includes("multiloop"));
	assert.match(JSON.stringify(loader.getAgentsFiles()), /CHILD_PROJECT_GUIDANCE/);
	assert.match(loader.getAppendSystemPrompt().join("\n"), /not a filesystem sandbox/);
	assert.equal(readFileSync(join(cwd, ".pi", "tasks.json"), "utf8"), "PARENT_TASKS_UNCHANGED");
	assert.deepEqual(readdirSync(join(cwd, ".pi")), ["tasks.json"]);
	assert.match(loader.getAppendSystemPrompt().join("\n"), /Scheduling and delegation belong to the parent/);
	const review = await expandedChildResourceLoader({ ...launch, role: { ...launch.role, judging: true } }, policy);
	assert.deepEqual(review.getAgentsFiles().agentsFiles, []);
	assert.ok(
		review
			.getExtensions()
			.extensions.every((extension) => !extension.tools.has("schedule_prompt") && !extension.tools.has("subagent")),
	);
})"

"test("a child joins admitted continuations, not unfinished task inventory", async () => {
	const f = fixture();
	await f.settle();
	assert.equal(f.wakes, 1);
	assert.equal(f.idle, 2);
	assert.equal(f.listenerCount(), 0);
})"

"test("a child waits for owned executions even without an explicit dependency wait", async () => {
	const f = fixture();
	f.executions = [{ predicates: [{ until: "exit", state: "pending" }] }];
	let finished = false;
	const result = f.settle().then(() => {
		finished = true;
	});
	await tick();
	assert.equal(finished, false);
	f.executions[0].predicates[0].state = "satisfied";
	f.changed();
	await result;
	assert.equal(finished, true);
	assert.equal(f.listenerCount(), 0);
})"

"test("a dependency terminal transition cannot be lost during the first read", async () => {
	const f = fixture();
	f.waits = [{ state: "waiting" }];
	const branch = f.ingress.branch();
	branch.attachment.waits.snapshot = async () => {
		if (f.waits[0].state === "waiting") {
			f.waits[0].state = "resolved";
			f.changed();
		}
		return f.waits;
	};
	await f.settle();
	assert.equal(f.wakes, 2);
	assert.equal(f.listenerCount(), 0);
})"

"test("cancellation while a child is idle releases all subscriptions", async () => {
	const f = fixture();
	f.waits = [{ state: "waiting" }];
	const result = f.settle();
	await tick();
	f.cancel.abort(new Error("fixture cancelled"));
	await assert.rejects(result, /fixture cancelled/);
	assert.equal(f.listenerCount(), 0);
})"

"test("a child does not close during a requested compaction", async () => {
	const f = fixture();
	f.compaction.request();
	let finished = false;
	const result = f.settle().then(() => {
		finished = true;
	});
	await tick();
	assert.equal(finished, false);
	f.compaction.beginDispatch();
	await tick();
	assert.equal(finished, false);
	f.compaction.settle();
	await result;
	assert.equal(finished, true);
	assert.equal(f.listenerCount(), 0);
})"

"test("an admission error fails the child and releases subscriptions", async () => {
	const f = fixture();
	f.ingress.wakeProducers = async () => {
		throw new Error("fixture admission error");
	};
	await assert.rejects(f.settle(), /fixture admission error/);
	assert.equal(f.listenerCount(), 0);
})"

"test(`child ${roleId} preserves idle withholding and activates iteration tools only for a loop`, {
		timeout: 30_000,
	}, async () => {
		const root = mkdtempSync(join(tmpdir(), "jouzu-child-tool-exposure-"));
		const cwd = join(root, "workspace");
		const directory = join(root, "child");
		const userAgentDir = join(root, "user-agent");
		for (const path of [cwd, directory, userAgentDir]) mkdirSync(path);
		const previous = { ...process.env };
		const requests = [];
		let session;
		let startup;
		const server = createServer(async (req, res) => {
			const chunks = [];
			for await (const chunk of req) chunks.push(chunk);
			requests.push({
				body: JSON.parse(Buffer.concat(chunks).toString()),
				active: session.getActiveToolNames(),
				registered: session.getAllTools().map((tool) => tool.name),
			});
			const call = [
				["multiloop_start", { lane: "fixture", runTag: "run", mode: "research", goal: "Check child tool exposure" }],
				["multiloop_stop", { target: "fixture/run" }],
			][requests.length - 1];
			const delta = call
				? {
						role: "assistant",
						tool_calls: [
							{
								index: 0,
								id: `call_${requests.length}`,
								type: "function",
								function: { name: call[0], arguments: JSON.stringify(call[1]) },
							},
						],
					}
				: { role: "assistant", content: "Done." };
			res.writeHead(200, { "Content-Type": "text/event-stream" });
			res.write(`data: ${JSON.stringify({ id: "fixture", choices: [{ index: 0, delta, finish_reason: null }] })}\n\n`);
			res.write(
				`data: ${JSON.stringify({ id: "fixture", choices: [{ index: 0, delta: {}, finish_reason: call ? "tool_calls" : "stop" }], usage: { prompt_tokens: 10, completion_tokens: 5, total_tokens: 15 } })}\n\n`,
			);
			res.end("data: [DONE]\n\n");
		});
		server.listen(0, "127.0.0.1");
		await once(server, "listening");
		const role = { ...defaultAgentConfig().roles.find((role) => role.id === roleId), thinking: "off", maxTurns: 5 };
		try {
			await runWorker(
				{
					cwd,
					directory,
					userAgentDir,
					role,
					task: "Start the fixture loop, stop it, and report Done.",
					auth: { apiKey: "fixture" },
					model: {
						provider: "fixture",
						id: "test",
						name: "Fixture",
						api: "openai-completions",
						baseUrl: `http://127.0.0.1:${server.address().port}/v1`,
						reasoning: false,
						input: ["text"],
						cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
						contextWindow: 128000,
						maxTokens: 512,
					},
				},
				(value) => {
					session = value;
					startup = session.getActiveToolNames();
				},
			);
			assert.equal(requests.length, 3, "one idle request, one active loop request, then one stopped request");
			assert.deepEqual(startup, requests[0].active);
			for (const [index, { body, active, registered }] of requests.entries()) {
				const visible = body.tools.map((tool) => tool.function.name);
				assert.deepEqual([...visible].sort(), [...active].sort(), "provider receives the live active tool set");
				for (const name of iterationTools) {
					assert.ok(registered.includes(name), `${name} stays registered at request ${index}`);
					assert.equal(active.includes(name), index === 1, `${name} active at request ${index}`);
					assert.equal(visible.includes(name), index === 1, `${name} model-visible at request ${index}`);
				}
				for (const name of extensionTools) assert.ok(visible.includes(name), `${name} remains available`);
				for (const name of AGENT_TOOLS) {
					assert.equal(visible.includes(name), role.tools.includes(name), `${name} follows the ${roleId} role`);
					assert.equal(registered.includes(name), role.tools.includes(name), `${name} registration is role-limited`);
				}
				for (const name of ["subagent", "schedule_prompt"]) assert.ok(!registered.includes(name), name);
			}
			const entries = readFileSync(session.sessionFile, "utf8").trim().split("\n").map(JSON.parse);
			const results = entries.filter((entry) => entry.type === "message" && entry.message.role === "toolResult");
			assert.deepEqual(
				results.map((entry) => entry.message.toolName),
				["multiloop_start", "multiloop_stop"],
			);
			for (const { message } of results) assert.equal(message.isError, false, JSON.stringify(message));
		} finally {
			server.closeAllConnections();
			await new Promise((resolve) => server.close(resolve));
			for (const key of Object.keys(process.env)) if (!(key in previous)) delete process.env[key];
			Object.assign(process.env, previous);
			rmSync(root, { recursive: true, force: true });
		}
	})"

"test("trace exposes arguments and linked results, filters evidence, and never rewrites the session", async () => {
	await fixture(entries, async (path, content) => {
		const all = await readSessionTrace(path);
		assert.equal(all.records.length, 5);
		assert.doesNotMatch(JSON.stringify(all), /THINKING_EXCLUDED|IMAGE_EXCLUDED|PRIVATE/);
