						executions++;
						return result();
					}),
				);
			},
		],
	});
	for (let index = 0; index < 2; index++) {
		scriptedCall(session, "read");
		await session.prompt("fixture");
	}
	assert.equal(executions, 1);
	assert.equal(exhausted, 1);
})"

"test("a deferred callable tool cannot bypass the child's active-tool permission check", async (t) => {
	let executions = 0;
	let nested;
	const { session } = await createFlowSession(t, {
		tools: ["caller", "hidden"],
		extensions: [
			createChildToolPolicy({ maxCalls: 10, onExhausted: () => assert.fail("unexpected exhaustion") }),
			(pi) => {
				pi.registerTool(
					definition(
						"hidden",
						async () => {
							executions++;
							return result();
						},
						{ exposure: "deferred" },
					),
				);
				pi.registerTool(
					definition("caller", async (_id, _args, signal, _update, ctx) => {
						nested = await ctx.executeTool("hidden", {}, { signal });
						return result();
					}),
				);
			},
		],
	});
	session.setActiveToolsByName(["caller"]);
	assert.ok(session.getCallableToolNames().includes("hidden"), "the fixture must expose the upstream nested-call path");
	scriptedCall(session, "caller");
	await session.prompt("fixture");
	assert.equal(executions, 0);
	assert.equal(nested.isError, true);
	assert.match(nested.result.content[0].text, /not enabled for this child session/);
})"

"test("notification handling notifies idle subscribers without changing completion time", async () => {
	const f = fixture();
	try {
		const run = f.launch();
		f.children[0].emit({ type: "result", status: "completed", text: "Done" });
		f.children[0].exit(true);
		const before = f.manager.get(run.id);
		assert.equal(before.completion.handled, false);
		let observed;
		const unsubscribe = f.manager.subscribe(() => {
			observed = f.manager.get(run.id);
		});
		f.manager.saveNotification(run.id, { handled: true });
		assert.equal(observed.completion.handled, true);
		assert.equal(observed.updatedAt, before.updatedAt);
		unsubscribe();
	} finally {
		await f.manager.dispose();
		rmSync(f.p.cwd, { recursive: true, force: true });
	}
})"

