"test("real child cancellation aborts a running shell and its process", { timeout: 60000 }, async () => {
	const { createServer } = await import("node:http");
	const { once } = await import("node:events");
	const p = paths();
	const server = createServer(async (req, res) => {
		for await (const _chunk of req) {
		}
		res.writeHead(200, { "Content-Type": "text/event-stream" });
		const delta = {
			role: "assistant",
			tool_calls: [
				{
					index: 0,
					id: "call_fixture",
					type: "function",
					function: {
						name: "bash",
						arguments: JSON.stringify({
							command: `node -e 'require("node:fs").writeFileSync("worker-shell.pid", String(process.pid)); setInterval(() => {}, 1000)'`,
						}),
					},
				},
			],
		};
		res.write(`data: ${JSON.stringify({ id: "test", choices: [{ index: 0, delta, finish_reason: null }] })}\n\n`);
		res.write(
			`data: ${JSON.stringify({ id: "test", choices: [{ index: 0, delta: {}, finish_reason: "tool_calls" }] })}\n\n`,
		);
		res.end("data: [DONE]\n\n");
	});
	server.listen(0, "127.0.0.1");
	await once(server, "listening");
	const manager = new SubagentManager(p, "cancel-parent", 1);
	try {
		const selectedModel = {
			...model,
			provider: "fixture",
			name: "Fixture",
			baseUrl: `http://127.0.0.1:${server.address().port}/v1`,
			reasoning: false,
			input: ["text"],
			cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
			contextWindow: 32000,
			maxTokens: 512,
		};
		const run = manager.launch({
			role: { ...defaultAgentConfig().roles[1], thinking: "off" },
			model: selectedModel,
			auth: { apiKey: "fixture-key" },
			cwd: p.cwd,
			task: "Run the assigned command",
		});
		let pid;
		// A cold runner needs to start the child, complete its model round trip, and start the shell,
		// which takes several times what a warm machine needs. Poll to a deadline rather than assuming
		// a fixed budget: the assertion below still fails if the file never appears. The file is also
		// visible before its contents land, so a read that yields no positive integer keeps polling
		// instead of ending the loop with an unparsed value.
		for (let i = 0; i < 1200; i++) {
			try {
				const candidate = Number(readFileSync(join(p.cwd, "worker-shell.pid"), "utf8"));
				if (Number.isInteger(candidate) && candidate > 0) {
					pid = candidate;
					break;
				}
			} catch {}
			await new Promise((resolve) => setTimeout(resolve, 25));
		}
		assert.ok(pid, manager.read(run.id).text);
		await manager.stop(run.id);
		assert.equal(manager.get(run.id).status, "cancelled");
		assert.throws(() => process.kill(pid, 0), /ESRCH/);
	} finally {
		await manager.dispose();
		server.closeAllConnections();
		server.close();
	}
})"

