"test(`real child admission and restored expansion: ${variant}`, { timeout: 30000 }, async () => {
		const root = mkdtempSync(join(tmpdir(), "jouzu-child-textguard-"));
		const cwd = join(root, "workspace");
		mkdirSync(cwd);
		const path = join(cwd, variant.startsWith("ordinary-file") ? "reference.txt" : "SKILL.md");
		const body = `CHILD_SOURCE_MARKER${variant === "clear-skill" ? "" : "\u202e"}`;
		writeFileSync(path, body);
		const requests = [];
		const server = createServer(async (req, res) => {
			const chunks = [];
			for await (const chunk of req) chunks.push(chunk);
			requests.push(JSON.parse(Buffer.concat(chunks).toString()));
			const first = requests.length === 1;
			const delta = first
				? {
						role: "assistant",
						tool_calls: [
							{
								index: 0,
								id: "read-skill",
								type: "function",
								function: { name: "read", arguments: JSON.stringify({ path }) },
							},
						],
					}
				: { role: "assistant", content: "Finished." };
			res.writeHead(200, { "Content-Type": "text/event-stream" });
			res.write(`data: ${JSON.stringify({ id: "fixture", choices: [{ index: 0, delta, finish_reason: null }] })}\n\n`);
			res.write(
				`data: ${JSON.stringify({ id: "fixture", choices: [{ index: 0, delta: {}, finish_reason: first ? "tool_calls" : "stop" }], usage: { prompt_tokens: 10, completion_tokens: 5, total_tokens: 15 } })}\n\n`,
			);
			res.end("data: [DONE]\n\n");
		});
		server.listen(0, "127.0.0.1");
		await once(server, "listening");
		let complete;
		const wait = () =>
			new Promise((resolve) => {
				complete = resolve;
			});
		const manager = new SubagentManager(
			{ configDir: join(root, "config"), stateDir: join(root, "state") },
			"parent",
			1,
			undefined,
			(result) => complete(result),
		);
		const launch = {
			cwd,
			textguardFiles: variant === "ordinary-file-opt-in",
			role: { ...defaultAgentConfig().roles[2], thinking: "off" },
			task: "Read the file",
			auth: { apiKey: "fixture" },
			model: {
				provider: "fixture",
				id: "test",
				name: "Fixture",
				api: "openai-completions",
				baseUrl: `http://127.0.0.1:${server.address().port}/v1`,
				reasoning: false,
				input: ["text"],
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
				contextWindow: 32000,
				maxTokens: 512,
			},
		};
		try {
			const done = wait();
			manager.launch(launch);
			const result = await done;
			assert.equal(result.status, "completed", result.result);
			assert.equal(requests.length, 2);
			const visible = JSON.stringify(requests[1].messages);
			// A skill is an instruction the child would follow, so it is withheld. An ordinary file is
			// data: the child reads it with the findings attached instead of losing the read.
			const blocked = variant === "major-skill";
			assert.equal(visible.includes("CHILD_SOURCE_MARKER"), !blocked);
			if (blocked) {
				assert.match(visible, /TextGuard withheld/);
				assert.doesNotMatch(readFileSync(result.sessionFile, "utf8"), /CHILD_SOURCE_MARKER/);
			}
			if (variant === "ordinary-file-opt-in") assert.match(visible, /TextGuard advisory:/);
			assert.ok(requests[0].tools.some((tool) => tool.function.name === "vcc_recall"));
			assert.ok(
				requests[0].tools.every((tool) => !["bash", "powershell", "write", "edit"].includes(tool.function.name)),
			);
			// Simulate history written before admission: resume must scan persisted expansions.
			const saved = SessionManager.open(result.sessionFile);
			saved.appendMessage({
				role: "user",
				content: '<skill name="restored">RESTORED_SECRET\u202e</skill>',
				timestamp: Date.now(),
			});
			assert.match(readFileSync(result.sessionFile, "utf8"), /RESTORED_SECRET/);
			const resumed = wait();
			manager.launch({ ...launch, task: "Continue" }, undefined, result.id);
			const followup = await resumed;
			assert.equal(followup.status, "completed", followup.result);
			assert.equal(requests.length, 3);
			assert.doesNotMatch(JSON.stringify(requests[2].messages), /RESTORED_SECRET/);
			assert.match(JSON.stringify(requests[2].messages), /TextGuard withheld/);
		} finally {
			await manager.dispose();
			server.closeAllConnections();
			await new Promise((resolve) => server.close(resolve));
			rmSync(root, { recursive: true, force: true });
		}
	})"

"test(`CLI default native policy checks skill metadata and complete web payloads: ${variant}`, {
		timeout: 30000,
	}, async () => {
		const dir = await mkdtemp(join(tmpdir(), "jouzu-native-cli-"));
		try {
			const skill = join(dir, "SKILL.md"),
				extension = join(dir, "fixture.mjs"),
				captured = join(dir, "contexts.json"),
				home = join(dir, "home");
			const marker = variant === "major" ? "\u202e" : "";
			await writeFile(
				skill,
				`---\nname: native-fixture\ndescription: UNIQUE_SKILL_DESCRIPTION${marker}\n---\nUNIQUE_SKILL_BODY${marker}\n`,
			);
			const web = {
				content: [{ type: "text", text: `UNIQUE_WEB_BODY${marker}` }],
				details: { nested: { markdown: `UNIQUE_WEB_DETAILS${marker}` } },
			};
			if (variant === "image") web.content.push({ type: "image", mimeType: "image/png", data: "UNIQUE_IMAGE_BYTES" });
			await writeFile(
				extension,
				`
import { createAssistantMessageEventStream } from ${JSON.stringify(import.meta.resolve("@earendil-works/pi-ai/utils/event-stream"))};
import { writeFileSync } from 'node:fs';
export default function(pi) {
 const contexts=[];
 pi.registerTool({name:'aio-webfetch',label:'Fixture fetch',description:'Fixture',parameters:{type:'object',properties:{}},
  async execute(){return ${JSON.stringify(web)}}});
 pi.registerProvider('native-fixture',{
  baseUrl:'http://127.0.0.1:1',apiKey:'fixture-only',api:'openai-completions',
  models:[{id:'fixture',name:'Fixture',reasoning:false,input:['text','image'],cost:{input:0,output:0,cacheRead:0,cacheWrite:0},contextWindow:32000,maxTokens:1000}],
  streamSimple(model,context){
   contexts.push(context);writeFileSync(${JSON.stringify(captured)},JSON.stringify(contexts));
   const tool=contexts.length===1;
   const message={role:'assistant',content:tool?[{type:'toolCall',id:'fixture-web',name:'aio-webfetch',arguments:{}}]:[{type:'text',text:'Done.'}],
    api:model.api,provider:model.provider,model:model.id,usage:{input:1,output:1,cacheRead:0,cacheWrite:0,totalTokens:2,cost:{input:0,output:0,cacheRead:0,cacheWrite:0,total:0}},stopReason:tool?'toolUse':'stop',timestamp:Date.now()};
   const stream=createAssistantMessageEventStream();queueMicrotask(()=>{stream.push({type:'done',reason:message.stopReason,message});stream.end(message)});return stream;
  }
 });
}
`,
			);
			const env = Object.fromEntries(
				Object.entries(process.env).filter(
					([key]) => !/^(JOUZU_|PI_|SHISA_|AI_AGENT|TEXTGUARD_|OPENAI_|ANTHROPIC_)/u.test(key),
				),
			);
			// The fixture provider supplies its own streamSimple, which flow control refuses to wrap.
			// These tests exercise the content policy, not request routing.
			env.JOUZU_FLOW_CONTROL = "0";
			env.PI_OFFLINE = "1";
			const args = [
				fileURLToPath(new URL("../dist/cli.js", import.meta.url)),
				"--jouzu-home",
				home,
				"--no-extensions",
				"--no-skills",
				"--no-context-files",
				"--no-prompt-templates",
				"--extension",
				extension,
				"--skill",
				skill,
				"--provider",
				"native-fixture",
				"--model",
				"fixture",
				"--mode",
				"json",
				"-p",
				"/skill:native-fixture",
			];
			const execution = promisify(execFile)(process.execPath, args, {
				cwd: dir,
				env,
				timeout: 20000,
				maxBuffer: 2 * 1024 * 1024,
			});
			execution.child.stdin.end();
			const { stderr } = await execution;
			const contexts = JSON.parse(await readFile(captured, "utf8"));
			assert.equal(contexts.length, 2);
			const first = JSON.stringify(contexts[0]);
			assert.equal(first.includes("UNIQUE_SKILL_DESCRIPTION"), variant !== "major");
			assert.equal(first.includes("UNIQUE_SKILL_BODY"), variant !== "major");
			const result = contexts[1].messages.find(
				(item) => item.role === "toolResult" && item.toolCallId === "fixture-web",
			);
			assert.ok(result);
			if (variant === "clear") {
				assert.equal(result.content[0].text, web.content[0].text);
				assert.equal(result.isError, false);
			} else {
				// A web result is data: it reaches the model with the findings attached rather than
				// being dropped, while the flagged skill above stays withheld.
				assert.equal(result.isError, false);
				assert.match(result.content[0].text, /^TextGuard advisory:/);
				assert.match(JSON.stringify(contexts), /UNIQUE_WEB_BODY/);
				assert.match(stderr, /TextGuard flagged/);
				assert.match(stderr, /untrusted data/);
			}
			if (variant === "major") {
				assert.match(stderr, /TextGuard withheld "skill:.*\d+ error-level findings? \(bidi_control/);
				assert.match(stderr, /interactive session/);
			}
			const cache = JSON.parse(await readFile(join(home, "cache", "textguard", "scans.json"), "utf8"));
			assert.ok(cache.records.length > 0);
			assert.doesNotMatch(JSON.stringify(cache), /UNIQUE_SKILL_BODY|UNIQUE_WEB_BODY|example.com|approvals/);
		} finally {
			await rm(dir, { recursive: true, force: true });
		}
	})"

