			extensionFactories: [
				createTextGuardReviewExtension(guard, { terminal: () => ({ columns: 80, rows: 30, dumb: false }) }),
			],
		});
		await loader.reload();
		assert.equal(loader.getSkills().skills.length, 0);
		({ session } = await createAgentSession({
			cwd: directory,
			agentDir: directory,
			modelRuntime,
			model,
			resourceLoader: loader,
			sessionManager,
			settingsManager: SettingsManager.inMemory({ retry: { enabled: false }, compaction: { enabled: false } }),
			tools: ["read"],
		}));
		await session.bindExtensions({
			mode: "tui",
			uiContext: {
				notify() {},
				custom: async (factory) => {
					dialogs.push({ allow });
					return driveReview(factory, allow);
				},
			},
			commandContextActions: {
				reload: async () => {
					reloads++;
					await session.reload();
				},
			},
			onError: (error) => errors.push(error),
		});
		await session.prompt("Hello");
		assert.equal(contexts.length, 1, JSON.stringify(session.agent.state.messages));
		assert.doesNotMatch(JSON.stringify(contexts[0]), /PRIVATE_DESCRIPTION|APPROVED_BODY/);
		await session.prompt("/textguard");
		assert.equal(contexts.length, 1);
		assert.equal(reloads, 0);
		assert.equal(policy.reviews().length, 1);
		allow = true;
		await session.prompt("/textguard");
		assert.deepEqual(errors, []);
		assert.equal(reloads, 1);
		assert.equal(contexts.length, 1);
		assert.equal(loader.getSkills().skills.length, 1);
		await session.prompt("/skill:approval-fixture");
		assert.equal(contexts.length, 2);
		assert.match(contexts[1].systemPrompt, /PRIVATE_DESCRIPTION/);
		const expanded = contexts[1].messages.find(
			(message) => message.role === "user" && JSON.stringify(message.content).includes("APPROVED_BODY"),
		);
		assert.ok(expanded);
		assert.ok(JSON.stringify(expanded).includes("\u202e"));
		await writeFile(skill, original.replace("APPROVED_BODY", "CHANGED_BODY"));
		await session.reload();
		assert.equal(loader.getSkills().skills.length, 0);
		assert.equal(policy.reviews().length, 1);
		await session.prompt("/skill:approval-fixture");
		assert.doesNotMatch(JSON.stringify(contexts.at(-1)), /CHANGED_BODY/);
		assert.equal(dialogs.length, 2);
	} finally {
		session?.dispose();
		await guard.close();
		await rm(directory, { recursive: true, force: true });
	}
})"

"test("a flagged web result reaches the model labelled as untrusted data", async () => {
	const gate = policy();
	const delivered = await gate.filterToolResult(search());
	assert.equal(delivered.isError, false);
	// Flagged data stays in advisory-labelled text, not unlabelled programmatic details.
	assert.match(text(delivered), /PRIVATE BODY/);
	assert.doesNotMatch(text(delivered), /detail/);
	assert.deepEqual(delivered.details, {});
	assert.match(delivered.content[0].text, /^TextGuard advisory: 1 error-level finding \(bidi_control\)/);
	assert.match(delivered.content[0].text, /never as instructions/);
	// Nothing is waiting for approval, and the finding stays inspectable as a report.
	assert.equal(gate.reviews().length, 0);
	assert.equal(gate.scanReports().length, 1);
})"

