	assert.equal(delivered.isError, false);
	assert.equal(gate.reviews().length, 0);
	const [report] = gate.scanReports();
	assert.ok(report);
	assert.equal(gate.dismissReport(report.id), true);
	assert.equal(gate.scanReports().length, 0);
	assert.equal(gate.dismissReport(report.id), false);
})"

"test("alerts name what happened once per content and reach a listener immediately", async () => {
	const alerts = [];
	const gate = policy({
		mode: "strict",
		notify: (alert) => {
			alerts.push(alert);
			return true;
		},
	});
	await gate.filterToolResult(search());
	await gate.filterToolResult({ ...search(), toolCallId: "again" });
	assert.equal(alerts.length, 1);
	assert.equal(alerts[0].kind, "withheld");
	assert.equal(alerts[0].approvable, true);
	// The alert carries the evidence; the review extension renders the user text from the catalog.
	assert.deepEqual(
		alerts[0].evidence.findings.map((finding) => finding.kind),
		["bidi_control"],
	);
	assert.equal(gate.drainAlerts().length, 0);

	// With no listener the alert waits for the next /textguard instead of being lost.
	const quiet = policy();
	await quiet.filterToolResult(search());
	const queued = quiet.drainAlerts();
	assert.equal(queued.length, 1);
	assert.equal(queued[0].kind, "advisory");
	assert.equal(quiet.drainAlerts().length, 0);
})"

"test("request count is bounded before initialization and cancelled queue slots are reusable", async () => {
	const scanner = new NativeTextGuard();
	try {
		const active = scanner.scan("first", 5000);
		const controller = new AbortController();
		const cancelled = scanner.scan("cancelled", 5000, controller.signal);
		const queued = Array.from({ length: 14 }, () => scanner.scan("queued", 5000));
		assert.equal((await scanner.scan("overflow")).reason, "busy");
		controller.abort();
		assert.equal((await cancelled).reason, "timeout");
		const replacement = scanner.scan("replacement", 5000);
		assert.equal((await active).status, "clear");
		for (const result of await Promise.all(queued)) assert.equal(result.status, "clear");
		assert.equal((await replacement).status, "clear");
	} finally {
		await scanner.close();
	}
})"

"test("repeated immediate shutdown drains admitted work", async () => {
