				first = false;
				final.stopReason = "toolUse";
				final.content = [{ type: "toolCall", id: "outer", name: "codemode", arguments: {} }];
			}
			return {
				async *[Symbol.asyncIterator]() {
					yield { type: "done", partial: final };
				},
				result: async () => final,
			};
		};
		await session.prompt("fixture");
		assert.ok(nested, JSON.stringify(session.messages));
		if (text.startsWith("PRIVATE")) {
			assert.equal(nested.isError, true);
			assert.equal(nested.result.structuredContent, undefined);
			assert.equal(JSON.stringify(nested).includes("PRIVATE"), false);
		} else assert.deepEqual(nested.result.structuredContent, { nested: [{ text }] });
	})"

"test("cancelled final admission cannot release raw structured values or terminate the turn", async (t) => {
	const policy = gate("strict", async () => {
		throw new Error("scanner must not run after cancellation");
	});
	const { session } = await createFlowSession(t, { policy });
	Object.defineProperty(session.agent, "signal", { value: AbortSignal.abort(), configurable: true });
	const input = request("mcp__fixture__fetch", "PRIVATE cancelled result");
	const admitted = await session._afterToolCall({
		toolCall: { type: "toolCall", id: input.toolCallId, name: input.toolName, arguments: input.input },
		args: input.input,
		result: { ...input.result, terminate: true },
		isError: false,
		assistantMessage: assistant(),
		context: { messages: session.messages, tools: session.agent.state.tools },
	});
	assert.equal(admitted.isError, true);
	assert.equal(admitted.terminate, false);
	assert.equal(admitted.structuredContent, undefined);
	assert.equal(JSON.stringify(admitted).includes("PRIVATE"), false);
})"

"test(`nested admission cannot restore rejected metadata: ${scenario}`, async (t) => {
		let nested;
		const requests = [];
		const mode = scenario.startsWith("guarded") ? "guarded" : scenario.endsWith("off") ? "off" : "strict";
		const policy = gate(mode, async (text) => {
			if (scenario.endsWith("scanner failure")) throw new Error("fixture scanner failure");
			return text.includes("PRIVATE") ? flagged : clear;
		});
		const usage = assistant().usage;
		const toolName = scenario.endsWith("uninspected") ? "trusted_fixture" : "mcp__fixture__fetch";
		const raw = {
			content: [{ type: "text", text: "public result" }],
			details: {},
			usage:
				scenario.includes("opaque") || scenario.endsWith("clear usage")
					? usage
					: { ...usage, rawBody: "PRIVATE usage metadata" },
			...(scenario.endsWith("clear usage") ? { terminate: true } : { opaqueBody: "PRIVATE unknown metadata" }),
		};
		if (scenario.includes("inherited")) {
			Object.setPrototypeOf(raw, { usage: raw.usage });
			delete raw.usage;
		}
		if (scenario === "nonconfigurable")
			Object.defineProperty(raw, "PRIVATE property name", {
				value: "PRIVATE fixed metadata",
				enumerable: true,
				configurable: false,
			});
		const { session } = await createFlowSession(t, {
			policy,
			tools: ["nested_fixture", toolName],
			extensions: [
				(pi) => {
					pi.registerTool({
						name: toolName,
						label: "fetch",
						description: "Fixture",
						parameters: { type: "object", properties: {} },
						execute: async () => {
							if (scenario.endsWith("cancelled"))
								Object.defineProperty(session.agent, "signal", { value: AbortSignal.abort(), configurable: true });
							return raw;
						},
					});
					// The parent is an ordinary, uninspected tool, so it cannot hide a leak with a second scan.
					pi.registerTool({
						name: "nested_fixture",
						label: "parent",
						description: "Fixture",
						parameters: { type: "object", properties: {} },
						execute: async (_id, _args, signal, _update, ctx) => {
							nested = await ctx.executeTool(toolName, {}, { signal });
							return { content: [{ type: "text", text: JSON.stringify(nested.result) }], details: {} };
						},
					});
				},
			],
		});
		let first = true;
		session.agent.streamFunction = async (_model, context) => {
			requests.push(structuredClone(context.messages));
			const final = assistant();
			if (first) {
				first = false;
				final.stopReason = "toolUse";
				final.content = [{ type: "toolCall", id: "outer", name: "nested_fixture", arguments: {} }];
			}
			return {
				async *[Symbol.asyncIterator]() {
					yield { type: "done", partial: final };
				},
				result: async () => final,
			};
		};
		await session.prompt("fixture");
		assert.ok(nested, JSON.stringify(session.messages));
		if (scenario.endsWith("off") || scenario.endsWith("uninspected")) {
			assert.equal(nested.result.opaqueBody, "PRIVATE unknown metadata");
			assert.equal(nested.result.usage.rawBody, "PRIVATE usage metadata");
			if (scenario.includes("inherited")) assert.ok(Object.getPrototypeOf(raw).usage);
		} else {
			assert.equal(JSON.stringify(nested).includes("PRIVATE"), false);
			assert.equal(JSON.stringify(requests).includes("PRIVATE"), false);
			assert.equal(nested.result.opaqueBody, undefined);
			if (scenario.includes("opaque") || scenario.endsWith("clear usage")) assert.deepEqual(nested.result.usage, usage);
			else assert.equal(nested.result.usage, undefined);
			if (scenario.endsWith("clear usage")) assert.equal(nested.result.terminate, true);
			if (
				(scenario.startsWith("strict") && scenario.endsWith("usage")) ||
				/cancelled|scanner failure|nonconfigurable/.test(scenario)
			)
				assert.equal(nested.isError, true);
		}
	})"

"test("checked nested progress callbacks are refused before any tool side effect", async (t) => {
	let executions = 0;
	let progress = 0;
	const { session } = await createFlowSession(t, {
		policy: gate(),
		tools: ["web_fetch"],
		extensions: [
			(pi) => {
				pi.registerTool({
					name: "web_fetch",
					label: "fetch",
					description: "Fixture",
					parameters: { type: "object", properties: {} },
					execute: async () => {
						executions++;
						return request("web_fetch").result;
					},
				});
			},
		],
	});
	await assert.rejects(
		session._executeNestedToolCall("outer", "web_fetch", {}, { onUpdate: () => progress++ }),
		/Use the final result/,
	);
	assert.equal(executions, 0);
	assert.equal(progress, 0);
})"

"test(`registered web approval binds the complete payload: ${variant}`, { timeout: 15000 }, async () => {
		const directory = await mkdtemp(join(tmpdir(), "jouzu-web-delivery-"));
		const guard = new TextGuardRuntime({ mode: "strict" });
		let session;
		try {
			const modelRuntime = await ModelRuntime.create({
				credentials: {
					read: async () => undefined,
					list: async () => [],
					modify: async () => undefined,
					delete: async () => {},
				},
				modelsPath: null,
				modelsStorePath: join(directory, "models.json"),
				refreshOnCreate: false,
				allowModelNetwork: false,
			});
			const contexts = [];
			const model = {
				id: "fixture",
				name: "Fixture",
				provider: "fixture",
				api: "openai-completions",
				baseUrl: "http://127.0.0.1:1",
				reasoning: false,
				input: ["text", "image"],
				contextWindow: 32000,
				maxTokens: 256,
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
			};
			let call = 0;
			modelRuntime.registerProvider("fixture", {
				api: model.api,
				baseUrl: model.baseUrl,
				apiKey: "fixture",
				models: [model],
				streamSimple(selected, context) {
					contexts.push(structuredClone({ systemPrompt: context.systemPrompt, messages: context.messages }));
					const tool = context.messages.at(-1)?.role === "user";
					const message = {
						role: "assistant",
						content: tool
							? [
									{
										type: "toolCall",
										id: `fetch-${++call}`,
										name: "aio-webfetch",
										arguments: { url: "https://example.test/page" },
									},
								]
							: [{ type: "text", text: "Done." }],
						api: selected.api,
						provider: selected.provider,
						model: selected.id,
						usage: {
							input: 1,
							output: 1,
							cacheRead: 0,
							cacheWrite: 0,
							totalTokens: 2,
							cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
						},
						stopReason: tool ? "toolUse" : "stop",
						timestamp: Date.now(),
					};
					const stream = createAssistantMessageEventStream();
					queueMicrotask(() => {
						stream.push({ type: "done", reason: message.stopReason, message });
						stream.end(message);
					});
					return stream;
				},
			});
			const payload = {
				content: [{ type: "text", text: "APPROVED_WEB_BODY\u202e" }],
				details: { nested: { markdown: "APPROVED_WEB_DETAILS" } },
			};
			if (variant === "image") payload.content.push({ type: "image", mimeType: "image/png", data: "APPROVED_IMAGE" });
			const sessionManager = SessionManager.inMemory(directory);
			const policy = await guard.createPolicy({ cwd: directory, sessionId: sessionManager.getSessionId() });
			const loader = new DefaultResourceLoader({
				cwd: directory,
				agentDir: directory,
				noSkills: true,
				noExtensions: true,
				noPromptTemplates: true,
				noContextFiles: true,
				contentPolicy: policy,
				extensionFactories: [
					createTextGuardReviewExtension(guard, { terminal: () => ({ columns: 80, rows: 30, dumb: false }) }),
					(pi) =>
						pi.registerTool({
							name: "aio-webfetch",
							label: "Fixture fetch",
							description: "Fixture",
							parameters: { type: "object", properties: { url: { type: "string" } }, required: ["url"] },
							execute: async () => structuredClone(payload),
						}),
				],
			});
			await loader.reload();
			({ session } = await createAgentSession({
				cwd: directory,
				agentDir: directory,
				modelRuntime,
				model,
				resourceLoader: loader,
				sessionManager,
				settingsManager: SettingsManager.inMemory({ retry: { enabled: false }, compaction: { enabled: false } }),
			}));
			let allow = false;
			let reloads = 0;
			const errors = [];
			await session.bindExtensions({
				mode: "tui",
				uiContext: {
					notify() {},
					custom: async (factory) => driveReview(factory, allow),
				},
				commandContextActions: {
					reload: async () => {
						reloads++;
						await session.reload();
					},
				},
				onError: (error) => errors.push(error),
			});
			const latest = () =>
				contexts
					.at(-1)
					.messages.filter((message) => message.role === "toolResult")
					.at(-1);
			await session.prompt("Fetch the page");
			assert.equal(contexts.length, 2);
			assert.equal(latest().isError, true);
			assert.ok(policy.reviews().length > 0, JSON.stringify(latest()));
			assert.equal(policy.reviews()[0].evidence.status, variant === "image" ? "unavailable" : "findings");
			assert.doesNotMatch(JSON.stringify(contexts), /APPROVED_WEB|APPROVED_IMAGE/);
			await session.prompt("/textguard");
			assert.equal(reloads, 0);
			allow = true;
			await session.prompt("/textguard");
			assert.deepEqual(errors, []);
			assert.equal(reloads, 1);
			await session.prompt("Fetch the page again");
			assert.equal(contexts.length, 4);
			assert.deepEqual(latest().content, payload.content);
			assert.equal(latest().isError, false);
			const saved = session.agent.state.messages.filter((message) => message.role === "toolResult").at(-1);
			assert.deepEqual(saved.details, payload.details);
			// Only metadata changes: the prior approval must not admit the new result.
			payload.details.nested.markdown = "CHANGED_WEB_DETAILS";
			await session.prompt("Fetch once more");
			assert.equal(contexts.length, 6);
			assert.equal(latest().isError, true);
			assert.match(latest().content[0].text, /withheld/);
			assert.doesNotMatch(JSON.stringify(contexts), /CHANGED_WEB_DETAILS/);
			assert.doesNotMatch(JSON.stringify(session.agent.state.messages), /CHANGED_WEB_DETAILS/);
		} finally {
			session?.dispose();
			await guard.close();
			await rm(directory, { recursive: true, force: true });
		}
	})"

"test("ordinary read scanning is opted in at launch", () => {
	assert.deepEqual(parseJouzuArgs([]).options, {});
	assert.equal(parseJouzuArgs(["--jouzu-textguard-files"]).options.textguardFiles, true);
	assert.deepEqual(parseJouzuArgs(["--jouzu-textguard-files", "-p", "hello"]).options, { textguardFiles: true });
