"test("the save-lock diagnostics keep their English bytes and localize", () => {
	const ja = resolveCatalog("ja").bundle;
	const { root, configDir, stateDir } = makeLocation();
	try {
		const snapshot = readLocalizationConfigSnapshot(configDir);
