				() => saveLocalizationConfig({ configDir, stateDir }, "ja", snapshot, ja),
				/別の言語設定の保存が進行中です/u,
			);
		} finally {
			release();
		}
		// A lock that is not a regular file reports the other cause.
		rmSync(join(stateDir, LOCALIZATION_LOCK_FILE_NAME), { force: true });
