		writeFileSync(lockTarget, "{}\n");
		symlinkSync(lockTarget, join(stateDir, LOCALIZATION_LOCK_FILE_NAME));
		assert.throws(
			() => saveLocalizationConfig({ configDir, stateDir }, "ja", snapshot),
			/localization\.lock is not a regular lock file/u,
