"test("browse scrolls past the last row to trailing empty-run text and back", () => {
	const f = fixture();
	const config = structuredClone(f.config);
	config.roles = Array.from({ length: 30 }, (_, index) => ({ ...config.roles[0], id: `agent-${index}` }));
