	assert.equal(renderTerminalRgb("x", cyan, "none"), "x");
})"

"test("publishes snapshots and preserves idle start until activity", () => {
	let now = 100;
	const controller = new SessionStatusController({
		run: async () => ({ stdout: "", stderr: "", code: 1, killed: false }),
		clock: { now: () => now },
	});
	const observed = [];
	controller.subscribe((snapshot) => observed.push(snapshot));
	assert.equal(controller.sync(context("/one")).activity.idleSince, 100);
	now = 200;
	assert.equal(controller.sync(context("/one")).activity.idleSince, 100);
	assert.deepEqual(controller.sync(context("/one", false)).activity, { idle: false });
	now = 300;
	assert.equal(controller.sync(context("/one")).activity.idleSince, 300);
	assert.equal(observed.length, 4);
	controller.dispose();
	controller.sync(context("/one"));
	assert.equal(observed.length, 4);
})"

"test("coalesces project refreshes and publishes only typed source outcomes", async () => {
	let now = 1000;
	const gitCalls = [];
	const runtimeCalls = [];
	const controller = new SessionStatusController({
		run: async () => ({ stdout: "", stderr: "", code: 0, killed: false }),
		clock: { now: () => now++ },
		readGit: async (cwd) => {
			gitCalls.push(cwd);
			await Promise.resolve();
			return {
				branch: cwd.slice(1),
				dirty: false,
				ahead: 0,
				behind: 0,
				conflicted: 0,
				untracked: 0,
				stashed: 0,
				modified: 0,
				staged: 0,
				renamed: 0,
				deleted: 0,
				typeChanged: 0,
			};
		},
		readRuntime: async (cwd) => {
			runtimeCalls.push(cwd);
			await Promise.resolve();
			return { id: "node", version: `v${cwd.length}` };
		},
	});
	controller.sync(context("/first"));
	const first = controller.refreshProject(context("/first"));
	const second = controller.refreshProject(context("/second"));
	assert.equal(first, second);
	await first;
	assert.deepEqual(gitCalls, ["/first", "/second"]);
	assert.deepEqual(runtimeCalls, ["/first", "/second"]);
	assert.equal(controller.getSnapshot().workspace.label, "second");
	assert.equal(controller.getSnapshot().git.value.branch, "second");
	assert.equal(controller.getSnapshot().runtime.value.id, "node");
	await controller.refreshGit(context("/third"));
	assert.deepEqual(gitCalls, ["/first", "/second", "/third"]);
	assert.deepEqual(runtimeCalls, ["/first", "/second"]);
})"

"test("aborts source work and suppresses updates after disposal", async () => {
	let observedSignal;
	const controller = new SessionStatusController({
		run: async () => ({ stdout: "", stderr: "", code: 0, killed: false }),
		readGit: async (_cwd, _run, signal) => {
			observedSignal = signal;
			await new Promise((resolve) => signal.addEventListener("abort", resolve, { once: true }));
			return undefined;
		},
		readRuntime: async () => undefined,
	});
	controller.sync(context("/repo"));
	const refresh = controller.refreshProject(context("/repo"));
	controller.dispose();
	await refresh;
	assert.equal(observedSignal.aborted, true);
})"

"test("installs one editor, Session Line, and Status Bar owner and cleans up", async () => {
	const root = mkdtempSync(join(tmpdir(), "jouzu-session-ui-extension-"));
	try {
		writeFileSync(join(root, "package.json"), "{}");
		const handlers = new Map();
		const execCalls = [];
		const modelQueries = [];
		const modelCycles = [];
		let scopedCommandCalls = 0;
		const extension = createSessionUiExtension({
			catalog,
			colorEnabled: false,
			getFastMode: ({ extensionStatuses }) => extensionStatuses.get("jouzu-fast-mode") === "on",
			getHints: () => [{ id: "palette", text: "/model choose", priority: 10, role: "muted" }],
			getActivity: ({ extensionStatuses }) => {
				const loop = extensionStatuses.get("multiloop");
				return loop ? { text: loop, active: /\brunning\b/.test(loop) } : undefined;
			},
			onModelPicker: async (query) => {
				modelQueries.push(query);
				return true;
			},
			onModelCycle: async (direction) => {
				modelCycles.push(direction);
				return true;
			},
			onScopedModelsCommand: async () => {
				scopedCommandCalls += 1;
				return true;
			},
		});
		extension.factory({
			on(name, handler) {
				handlers.set(name, handler);
			},
			async exec(command, args, options) {
				execCalls.push({ command, args, options });
				if (command === "git") return { stdout: "# branch.head main\n", stderr: "", code: 0, killed: false };
				return { stdout: "v24.16.0\n", stderr: "", code: 0, killed: false };
			},
		});
		const calls = { widgets: [], footers: [], editors: [] };
		const ctx = context(root, calls);
		await handlers.get("session_start")({}, ctx);
		const runtimeDeadline = Date.now() + 2000;
		while (!execCalls.some(({ command }) => command === "node") && Date.now() < runtimeDeadline) {
			await new Promise((resolve) => setTimeout(resolve, 10));
		}
		assert.equal(extension.name, SESSION_UI_RUNTIME_IDS.extension);
		// The Session Line is the prompt editor's first line, not a widget Pi can reorder.
		assert.deepEqual(calls.widgets, []);
		assert.equal(typeof calls.footers[0], "function");
		assert.equal(typeof calls.editors[0], "function");
		await handlers.get("session_start")({}, ctx);
		assert.equal(calls.editors.length, 1);
		assert.deepEqual(execCalls.map(({ command }) => command).sort(), ["git", "git", "node"]);

		const tui = { requestRender() {}, terminal: { rows: 40, columns: 80 } };
		const keybindings = {
			matches(data, action) {
				return (
					(data === "model-key" && action === "app.model.select") ||
					(data === "cycle-key" && action === "app.model.cycleForward") ||
					(data === "enter" && action === "tui.input.submit")
				);
			},
		};
		const editor = calls.editors[0](tui, theme, keybindings);
		let builtInModelPickerCalls = 0;
		editor.onAction("app.model.select", () => {
			builtInModelPickerCalls += 1;
		});
		editor.handleInput("model-key");
		editor.handleInput("cycle-key");
		editor.setText("/model codex/gpt-test");
		editor.handleInput("enter");
		editor.setText("/scoped-models");
		editor.handleInput("enter");
		await new Promise((resolve) => setImmediate(resolve));
		assert.deepEqual(modelQueries, [undefined, "codex/gpt-test"]);
		assert.deepEqual(modelCycles, ["forward"]);
		assert.equal(scopedCommandCalls, 1);
		assert.equal(builtInModelPickerCalls, 0);

		const lineComponent = { render: (width) => [editor.render(width)[0]] };
		const line = lineComponent.render(60)[0];
		assert.equal(terminalTextWidth(line), 60);
		assert.match(line, /\/model choose/);
		assert.match(line, /Codex gpt-test \(high\)/);
		ctx.model = { provider: "anthropic", id: "claude-new", name: "Claude New", contextWindow: 200_000 };
		ctx.thinkingLevel = "low";
		await handlers.get("model_select")({}, ctx);
		assert.match(lineComponent.render(60)[0], /Anthropic claude-new \(low\)/);
		let branchChanged;
		let branchUnsubscribed = false;
		const statuses = new Map();
		const footer = calls.footers.at(-1)(tui, theme, {
			getExtensionStatuses: () => statuses,
			onBranchChange(handler) {
				branchChanged = handler;
				return () => {
					branchUnsubscribed = true;
				};
			},
		});
		assert.equal(terminalTextWidth(footer.render(80)[0]), 80);
		statuses.set("jouzu-fast-mode", "on");
		assert.match(lineComponent.render(60)[0], /\(low · fast\)/);
		statuses.delete("jouzu-fast-mode");
		assert.doesNotMatch(lineComponent.render(60)[0], /fast/);
		for (const [state, marker] of [
			["running", "⠋"],
			["paused", "○"],
			["stopped", "○"],
		]) {
			statuses.set("multiloop", `multiloop: 1 ${state}`);
			const line = lineComponent.render(64)[0];
			assert.match(line, new RegExp(`^${marker} multiloop: 1 ${state}`));
			assert.equal(terminalTextWidth(line), 64);
			assert.doesNotMatch(line, /\/model choose/);
			assert.doesNotMatch(footer.render(48)[0], /multiloop/);
		}
		statuses.delete("multiloop");
		assert.doesNotMatch(lineComponent.render(64)[0], /multiloop|stopped/);
		assert.match(lineComponent.render(64)[0], /\/model choose/);
		branchChanged();
		await Promise.resolve();
		footer.dispose();
		assert.equal(branchUnsubscribed, true);

		await handlers.get("session_shutdown")({}, ctx);
		assert.deepEqual(calls.widgets, []);
		assert.equal(lineComponent.render(60)[0].includes("/model choose"), false, "the line leaves with its session");
		assert.equal(calls.footers.at(-1), undefined);
		assert.equal(calls.editors.at(-1), undefined);
	} finally {
		rmSync(root, { recursive: true, force: true });
	}
})"

"test("maps an exact /exit submission unless another command owns the name", async () => {
	const install = async (commands) => {
		const handlers = new Map();
		const calls = { widgets: [], footers: [], editors: [] };
		createSessionUiExtension({ catalog, colorEnabled: false }).factory({
			on(name, handler) {
				handlers.set(name, handler);
			},
			getCommands: () => commands,
			exec: async () => ({ stdout: "", stderr: "", code: 0, killed: false }),
		});
		await handlers.get("session_start")({}, context("/tmp", calls));
		const keybindings = { matches: (data, action) => data === "\r" && action === "tui.input.submit" };
		return calls.editors[0]({ requestRender() {}, terminal: { rows: 30, columns: 80 } }, theme, keybindings);
	};

	const free = await install([]);
	const freeSubmissions = [];
	free.onSubmit = (value) => freeSubmissions.push(value);
	free.setText("/exit");
	free.handleInput("\r");
	assert.deepEqual(freeSubmissions, ["/quit"]);

	const owned = await install([{ name: "exit", description: "My own exit command", source: "prompt" }]);
	const ownedSubmissions = [];
	owned.onSubmit = (value) => ownedSubmissions.push(value);
	owned.setText("/exit");
	owned.handleInput("\r");
	assert.deepEqual(ownedSubmissions, ["/exit"]);
})"

