"test("dashboard registers once per attachment above the editor-hosted Session Line and tree changes do not move it", async () => {
	const handlers = new Map();
	const widgets = [];
	const attachments = [];
	const controller = new WorkDashboardController();
	const extension = createSessionUiExtension({
		catalog,
		dashboard: {
			controller,
			mode: () => "hidden",
			attach: (_ctx, reset) => {
				attachments.push(reset);
				controller.attach({ sessionId: "s", branchId: "b" }, []);
			},
		},
	});
	extension.factory({
		on: (name, handler) => handlers.set(name, handler),
		exec: async () => ({ stdout: "", stderr: "", code: 0 }),
	});
	const ctx = {
		mode: "tui",
		cwd: process.cwd(),
		scopedModels: [],
		isIdle: () => true,
		sessionManager: { getBranch: () => [] },
		getContextUsage: () => undefined,
		ui: {
			theme: { fg: (_color, text) => text, bg: (_color, text) => text, bold: (text) => text },
			setWidget: (...args) => widgets.push(args),
			setFooter() {},
			setEditorComponent() {},
		},
	};
	try {
		await handlers.get("session_start")({}, ctx);
		assert.deepEqual(
			widgets.map(([key]) => key),
			["jouzu-work-dashboard"],
		);
		await handlers.get("session_tree")({}, ctx);
		assert.equal(widgets.length, 1);
		assert.deepEqual(attachments, [true, false]);
		await handlers.get("session_shutdown")({}, ctx);
		assert.equal(controller.getSnapshot(), undefined);
		assert.deepEqual(widgets.at(-1), ["jouzu-work-dashboard", undefined]);
		await handlers.get("session_start")({}, { ...ctx, mode: "rpc" });
		assert.equal(attachments.length, 2);
	} finally {
		await handlers.get("session_shutdown")({}, ctx);
	}
})"

"test("same-session navigation retains stale session members but not branch members", async () => {
	const controller = new WorkDashboardController();
	let fail = false;
	let disposed = 0;
	const source = (id, membership) => ({
		id,
		membership,
		subscribe: () => () => {
			disposed++;
			throw new Error("cleanup");
		},
		read: () => {
			if (fail) throw new Error("offline");
			return { availability: "available", complete: true, units: [{ id, attention: [{ id: "r", type: "result" }] }] };
		},
	});
	const sources = [source("child", "session"), source("flow", "branch")];
	controller.subscribe(() => {
		throw new Error("observer");
	});
	let observed = 0;
	controller.subscribe(() => {
		observed++;
	});
	controller.attach({ sessionId: "s", branchId: "a" }, sources);
	await tick();
	fail = true;
	controller.attach({ sessionId: "s", branchId: "b" }, sources);
	await tick();
	const snapshot = controller.getSnapshot();
	assert.equal(snapshot.sources.child.units.length, 1);
	assert.equal(snapshot.sources.child.availability, "stale");
	assert.equal(snapshot.sources.flow.units.length, 0);
	assert.equal(disposed, 2);
	assert.ok(observed > 2);
	controller.dispose();
	assert.equal(disposed, 4);
})"

"test("slow poll reads publish and detach clears the timer and aborts reads", async (t) => {
	t.mock.timers.enable({ apis: ["setInterval"] });
	const controller = new WorkDashboardController();
	t.after(() => controller.dispose());
	let calls = 0;
	let resolve;
	let signal;
	controller.attach({ sessionId: "s", branchId: "b" }, [
		{
			id: "flow",
			pollIntervalMs: 1000,
			subscribe: () => () => {},
			read: (_scope, abort) => {
				calls++;
				signal = abort;
				return new Promise((done) => {
					resolve = done;
				});
			},
		},
	]);
	t.mock.timers.tick(5000);
	assert.equal(calls, 1);
	resolve({ availability: "available", complete: true, units: [] });
	await tick();
	assert.equal(controller.getSnapshot().sources.flow.availability, "available");
	t.mock.timers.tick(1000);
	assert.equal(calls, 2);
	controller.detach();
	assert.equal(signal.aborted, true);
	t.mock.timers.tick(5000);
	assert.equal(calls, 2);
	resolve({ availability: "available", complete: true, units: [] });
	await tick();
	assert.equal(controller.getSnapshot(), undefined);
})"

"test("subscription failure falls back to polling and incomplete reads retain attention", async (t) => {
	t.mock.timers.enable({ apis: ["setInterval"] });
