  helper(space, 'git', "Write-Output 'Git fixture prepared'; exit 0");
  assert.equal(run().status, 0);
  assert.equal(report(space, 'git').status, 'ready');
  assert.equal(report(space, 'git', true).exitCode, 7);
})"

