		t,
		`import assert from 'node:assert/strict';
assert.equal(process.env.PI_OFFLINE, '1');
assert.equal(process.env.JOUZU_NO_UPDATE, '1');
assert.ok(process.env.JOUZU_HOME.endsWith('Jouzu 上手'));
