		JSON.stringify({
			id: "dev-build",
			type: "response",
			command: "get_state",
			success: true,
			data: { isStreaming: false, sessionFile: "saved" },
		}),
	]) {
		assert.throws(
			() => smokeDevelopmentRuntime(fixture(t, `console.log(${JSON.stringify(response)})`)),
			/invalid output/,
		);
	}
})"

