"test("WebAIO pruning rejects shared static and dynamic MCP imports", async () => {
	const { assertStandaloneMcpBoundary } = await import("./webaio-package-boundary.mjs");
	const root = mkdtempSync(join(tmpdir(), "jouzu-mcp-boundary-"));
