"test("skill expansion injects checked bytes and awaits both queued paths", async () => {
	const policy = passthrough();
	policy.readSkill = async () => "CHECKED BODY";
	const loader = {
		contentPolicy: policy,
		getSkills: () => ({ skills: [{ name: "fixture", filePath: "nonexistent", baseDir: "/fixture" }] }),
	};
	const received = [];
	const fake = {
		resourceLoader: loader,
		promptTemplates: [],
		_throwIfExtensionCommand() {},
		_expandSkillCommand: AgentSession.prototype._expandSkillCommand,
		_queueUserInput: AgentSession.prototype._queueUserInput,
		async _runInputHandlers(text, images) {
			return { text, images };
		},
		async _queueSteer(text) {
			received.push(text);
		},
		async _queueFollowUp(text) {
			received.push(text);
		},
	};
	await AgentSession.prototype.steer.call(fake, "/skill:fixture");
	await AgentSession.prototype.followUp.call(fake, "/skill:fixture");
	assert.equal(received.length, 2);
	for (const text of received) assert.match(text, /CHECKED BODY/);
	policy.readSkill = async () => {
		throw new Error("PRIVATE BODY");
	};
	const rejected = await fake._expandSkillCommand("/skill:fixture");
	assert.equal(rejected.includes("PRIVATE BODY"), false);
	assert.match(rejected, /withheld/);
})"

"test("final tool policy sees extension output and errors remove text and structured details", async () => {
	const policy = passthrough();
	let seen;
	policy.filterToolResult = async (event) => {
		seen = event;
		throw new Error("PRIVATE BODY");
	};
	const fake = {
		_afterToolCall: AgentSession.prototype._afterToolCall,
		_limitsModel: () => undefined,
		agent: {},
		resourceLoader: { contentPolicy: policy },
		settingsManager: { getImageAutoResize: () => false },
		_extensionRunner: {
			hasHandlers: () => true,
			async emitToolResult() {
				return {
					content: [{ type: "text", text: "EXTENSION BODY" }],
					details: { secret: "EXTENSION DETAIL" },
					structuredContent: { secret: "EXTENSION STRUCTURED" },
				};
			},
		},
	};
	AgentSession.prototype._installAgentToolHooks.call(fake);
	const result = await fake.agent.afterToolCall({
		toolCall: { name: "web_fetch", id: "1" },
		args: { url: "https://example.com" },
		result: { content: [{ type: "text", text: "PRIVATE BODY" }], details: { secret: "PRIVATE DETAIL" } },
		isError: false,
	});
	assert.equal(seen.result.content[0].text, "EXTENSION BODY");
	assert.equal(seen.result.details.secret, "EXTENSION DETAIL");
	assert.equal(seen.result.structuredContent.secret, "EXTENSION STRUCTURED");
	assert.deepEqual(result.details, {});
	assert.equal(result.isError, true);
	assert.equal(JSON.stringify(result).includes("PRIVATE"), false);
	// A tool the policy does not inspect keeps its output rather than reporting a failed check.
	policy.shouldInspectTool = () => false;
	const kept = await fake.agent.afterToolCall({
		toolCall: { name: "bash", id: "2" },
		args: { command: "echo hi" },
		result: { content: [{ type: "text", text: "PRIVATE SHELL OUTPUT" }], details: { secret: "PRIVATE DETAIL" } },
		isError: false,
	});
	assert.equal(kept.content[0].text, "EXTENSION BODY");
	assert.equal(kept.details.secret, "EXTENSION DETAIL");
	assert.equal(kept.isError, false);
	assert.equal(JSON.stringify(kept).includes("could not check"), false);
	policy.shouldInspectTool = () => true;
	fake.agent.signal = AbortSignal.abort();
	seen = undefined;
	const cancelled = await fake.agent.afterToolCall({
		toolCall: { name: "web_fetch", id: "3" },
		args: { url: "https://example.com" },
		result: { content: [{ type: "text", text: "PRIVATE WEB BODY" }] },
		isError: false,
	});
	assert.equal(seen, undefined, "cancelled checks must not invoke the policy");
	assert.match(cancelled.content[0].text, /withheld after cancellation/);
	assert.deepEqual(cancelled.details, {});
	assert.equal(cancelled.structuredContent, undefined);
	assert.equal(cancelled.isError, true);
	assert.equal(cancelled.terminate, false);
})"

