"test("session listing skips a session a forced flush persisted before any message", async (t) => {
	const directory = await mkdtemp(join(tmpdir(), "jouzu-policy-session-list-"));
	const sessionDir = join(directory, "sessions");
	t.after(() => rm(directory, { recursive: true, force: true }));
	await mkdir(sessionDir, { recursive: true });
	// Flow control persists a marker with flush() before any message exists, which creates the file.
	const markerOnly = SessionManager.create(directory, sessionDir, { id: "recovery-marker-only-session" });
	markerOnly.appendCustomEntry("jouzu-flow-branch", { marker: true });
	markerOnly.flush();
	// A session with one user message is resumable and must stay listed.
	const withMessage = SessionManager.create(directory, sessionDir);
	withMessage.appendMessage({ role: "user", content: [{ type: "text", text: "hello" }], timestamp: Date.now() });
	withMessage.flush();
	assert.equal((await readdir(sessionDir)).filter((name) => name.endsWith(".jsonl")).length, 2);
	const listed = await SessionManager.list(directory, sessionDir);
	assert.deepEqual(
		listed.map((session) => session.id),
		[withMessage.getSessionId()],
	);
	assert.equal(listed[0].firstMessage, "hello");
	assert.equal((await SessionManager.list(directory, sessionDir, undefined, undefined, true)).length, 2);
	assert.equal((await SessionManager.listAll(sessionDir, undefined, undefined, true)).length, 2);
	// includeEmpty is this patch's own parameter, re-added after 0.87.1 dropped it. The picker keeps
	// the default, so the metadata-only session stays listed only for a caller that asks for it.
	const included = await SessionManager.list(directory, sessionDir, undefined, undefined, true);
	assert.deepEqual(
		included.map((session) => session.id).sort(),
		[markerOnly.getSessionId(), withMessage.getSessionId()].sort(),
	);
	assert.equal(included.find((session) => session.id === markerOnly.getSessionId()).messageCount, 0);
	const partials = [];
	const progress = (_loaded, _total, sessions) => partials.push(...(sessions ?? []));
	await SessionManager.list(directory, sessionDir, progress);
	await SessionManager.listAll(sessionDir, progress);
	assert.ok(partials.length > 0);
	assert.ok(partials.every((session) => session.id === withMessage.getSessionId()));
	const aborted = AbortSignal.abort();
	await assert.rejects(SessionManager.list(directory, sessionDir, undefined, aborted), { name: "AbortError" });
	await assert.rejects(SessionManager.listAll(sessionDir, undefined, aborted), { name: "AbortError" });

	const main = await readFile(new URL("main.js", import.meta.resolve("@earendil-works/pi-coding-agent")), "utf8");
	const start = main.indexOf("function findLocalSessionByExactId(");
	const end = main.indexOf("/** Prompt user for yes/no confirmation */", start);
	assert.ok(start >= 0 && end > start);
	const { resolveSessionPath, findLocalSessionByExactId } = new Function(
		"SessionManager",
		`${main.slice(start, end)}; return { resolveSessionPath, findLocalSessionByExactId };`,
	)(SessionManager);
	const expected = { type: "local", path: markerOnly.getSessionFile() };
	assert.deepEqual(await resolveSessionPath(markerOnly.getSessionId(), directory, sessionDir), expected);
	assert.deepEqual(await resolveSessionPath(markerOnly.getSessionId().slice(0, 20), directory, sessionDir), expected);
	assert.deepEqual(await findLocalSessionByExactId(markerOnly.getSessionId(), directory, sessionDir), expected);
	assert.deepEqual(await resolveSessionPath(markerOnly.getSessionId(), join(directory, "other"), sessionDir), {
		type: "global",
		path: markerOnly.getSessionFile(),
		cwd: directory,
	});
	assert.equal((await SessionManager.listAll(sessionDir)).length, 1);

	const withContext = SessionManager.create(directory, sessionDir);
	withContext.appendCustomMessageEntry("wait-context", "Pending work", false);
	withContext.flush();
	const withTool = SessionManager.create(directory, sessionDir);
	withTool.appendMessage({
		role: "toolResult",
		toolCallId: "call",
		toolName: "read",
		content: [{ type: "text", text: "result" }],
		isError: false,
		timestamp: Date.now(),
	});
	withTool.flush();
	assert.deepEqual(
		new Set((await SessionManager.list(directory, sessionDir)).map((item) => item.id)),
		new Set([withMessage.getSessionId(), withContext.getSessionId(), withTool.getSessionId()]),
	);
})"

"test("flow deviation locks exact bytes and both installed host trees are idempotent", async () => {
	const pin = JSON.parse(await readFile(new URL("../upstream/pi.lock.json", import.meta.url)));
	const bytes = await readFile(new URL("../upstream/pi-flow-control/patch.lock.json", import.meta.url));
