		{ ...jobs[0], run_id: 11 },
	])
		assert.throws(() => qualificationManifest(manifest, run, [bad, jobs[1]]));
	assert.throws(() => qualificationManifest(manifest, run, [jobs[0], job("consumer", 3)]));
	assert.throws(() => qualificationManifest(manifest, { ...run, id: 11 }, jobs));
})"

