"test("phase reports failure and preserves the error", async () => {
	const failure = new Error("fixture failure");
	for (const action of [
		() => {
			throw failure;
		},
		async () => {
			throw failure;
		},
	]) {
		const logs = [];
		await assert.rejects(
			smokePhase("rollback", action, (line) => logs.push(line)),
			(error) => error === failure,
